  (4, 1, '', '[{"id":24,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"''''হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":25,"position":2,"text_uthmani":"ٱلنَّاسُ","transliteration":"l-nāsu","translation_bn":"মানবজাতি!","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":26,"position":3,"text_uthmani":"ٱتَّقُوا۟","transliteration":"ittaqū","translation_bn":"তোমরা ভয় কর","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27,"position":4,"text_uthmani":"رَبَّكُمُ","transliteration":"rabbakumu","translation_bn":"তোমাদের রবকে","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":28,"position":5,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":29,"position":6,"text_uthmani":"خَلَقَكُم","transliteration":"khalaqakum","translation_bn":"তোমাদেরকে সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30,"position":7,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31,"position":8,"text_uthmani":"نَّفْسٍۢ","transliteration":"nafsin","translation_bn":"প্রাণ","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":32,"position":9,"text_uthmani":"وَٰحِدَةٍۢ","transliteration":"wāḥidatin","translation_bn":"একটি (অর্থাৎ আদম (আঃ))","root":"وحد","lemma":"وَٰحِدَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":33,"position":10,"text_uthmani":"وَخَلَقَ","transliteration":"wakhalaqa","translation_bn":"ও তিনি সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34,"position":11,"text_uthmani":"مِنْهَا","transliteration":"min''hā","translation_bn":"তা হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":35,"position":12,"text_uthmani":"زَوْجَهَا","transliteration":"zawjahā","translation_bn":"তার জুড়ী (অর্থাৎ হাওয়া)","root":"زوج","lemma":"زَوْج","grammar_bn":"বিশেষ্য (Noun)"},{"id":36,"position":13,"text_uthmani":"وَبَثَّ","transliteration":"wabatha","translation_bn":"ও ছড়িয়ে দিয়েছেন","root":"بثث","lemma":"بَثَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37,"position":14,"text_uthmani":"مِنْهُمَا","transliteration":"min''humā","translation_bn":"তাদের দুজন থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":38,"position":15,"text_uthmani":"رِجَالًۭا","transliteration":"rijālan","translation_bn":"পুরুষ লোক","root":"رجل","lemma":"رِجَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":39,"position":16,"text_uthmani":"كَثِيرًۭا","transliteration":"kathīran","translation_bn":"অনেক","root":"كثر","lemma":"كَثِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":40,"position":17,"text_uthmani":"وَنِسَآءًۭ ۚ","transliteration":"wanisāan","translation_bn":"ও স্ত্রীলোক (অনেক)","root":"نسو","lemma":"نِسَا^ء","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":42,"position":18,"text_uthmani":"وَٱتَّقُوا۟","transliteration":"wa-ittaqū","translation_bn":"এবং তোমরা ভয় কর","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":43,"position":19,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":44,"position":20,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"সেই (সত্তার)","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":45,"position":21,"text_uthmani":"تَسَآءَلُونَ","transliteration":"tasāalūna","translation_bn":"তোমরা পরস্পরে (হক) দাবী কর","root":"سال","lemma":"يَتَسَا^ءَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":46,"position":22,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"যার (দোহাই দিয়ে)","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":47,"position":23,"text_uthmani":"وَٱلْأَرْحَامَ ۚ","transliteration":"wal-arḥāma","translation_bn":"আর আত্মীয়তার বন্ধন সম্পর্কে সতর্ক থাক","root":"رحم","lemma":"أَرْحَام","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":49,"position":24,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":50,"position":25,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":51,"position":26,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"আছেন","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52,"position":27,"text_uthmani":"عَلَيْكُمْ","transliteration":"ʿalaykum","translation_bn":"তোমাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":53,"position":28,"text_uthmani":"رَقِيبًۭا","transliteration":"raqīban","translation_bn":"দৃষ্টিবান","root":"رقب","lemma":"رَقِيب","grammar_bn":"বিশেষ্য (Noun)"},{"id":54,"position":29,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā l-nāsu ittaqū rabbakumu alladhī khalaqakum min nafsin wāḥidatin wakhalaqa min''hā zawjahā wabatha min''humā rijālan kathīran wanisāan wa-ittaqū l-laha alladhī tasāalūna bihi wal-arḥāma inna l-laha kāna ʿalaykum raqīban', 'হে মানবজাতি! তোমরা তোমাদের রবকে ভয় করো, যিনি তোমাদের সৃষ্টি করেছেন একটি মাত্র প্রাণ থেকে এবং তা থেকে সৃষ্টি করেছেন তার স্ত্রীকে এবং তাদের দু’জন থেকে ছড়িয়ে দিয়েছেন বহু পুরুষ ও নারী। আর তোমরা আল্লাহকে ভয় করো, যার নামে তোমরা একে অপরের কাছে দাবি করো এবং জরায়ুর (রক্ত সম্পর্কের) বন্ধনকেও ভয় করো। নিশ্চয়ই আল্লাহ তোমাদের ওপর তীক্ষ্ণ নজরদারী রাখছেন।', 'O mankind, fear your Lord, who created you from one soul and created from it its mate and dispersed from both of them many men and women. And fear Allah, through whom you ask one another, and the wombs. Indeed Allah is ever, over you, an Observer.', 'হে মানবজাতি! তোমরা তোমাদের রবকে ভয় করো, যিনি তোমাদের সৃষ্টি করেছেন একটি মাত্র প্রাণ থেকে এবং তা থেকে সৃষ্টি করেছেন তার স্ত্রীকে এবং তাদের দু’জন থেকে ছড়িয়ে দিয়েছেন বহু পুরুষ ও নারী। আর তোমরা আল্লাহকে ভয় করো, যার নামে তোমরা একে অপরের কাছে দাবি করো এবং জরায়ুর (রক্ত সম্পর্কের) বন্ধনকেও ভয় করো। নিশ্চয়ই আল্লাহ তোমাদের ওপর তীক্ষ্ণ নজরদারী রাখছেন।', 'O mankind, fear your Lord, who created you from one soul and created from it its mate and dispersed from both of them many men and women. And fear Allah, through whom you ask one another, and the wombs. Indeed Allah is ever, over you, an Observer.', NULL, NULL, 'হে কার্বন-ভিত্তিক সামষ্টিক সচেতন মানবজাতি বা Naas (النَّاسُ)! তোমরা তোমাদের সুপ্রীম সিস্টেম আর্কিটেক্ট বা প্রতিপালকের (رَبَّكُمُ) তৈরি করা বাউন্ডারি কোড ও প্রটোকল সিকিউরিটি মেনে চলো—যিনি তোমাদের সমগ্র প্রজাতিকে ডিজাইন ও সৃষ্টি করেছেন একটিমাত্র আদি অভিন্ন বায়ো-জেনেটিক সেলুলার সোর্স কোড বা একক প্রাণ-কোষ (نَّفْسٍ وَاحِدَةٍ) থেকে, এবং সেই আদি সোর্স কোডের ভেতরেই প্রাকৃতিকভাবে ডিজাইন করেছেন তার পরিপূরক কাউন্টার-পার্ট বা স্ত্রী নোডকে (زَوْجَهَا), এবং তাদের সেই ডাইনামিক DNA (বংশগতির কোড) ফিউশন থেকে পুরো নেটওয়ার্ক গ্রিডে ছড়িয়ে দিয়েছেন বহু মেল নোড বা পুরুষ এবং ফিমেল নোড বা নারী; আর তোমরা বাউন্ডারি কোড মেনে চলো সেই Allah-এর—যার পরম অস্তিত্বকে সুপ্রীম রেফারেন্স বা ট্রাস্ট ভেক্টর (بِهِ) হিসেবে ব্যবহার করে তোমরা পরস্পরের সাথে সামাজিক নেটওয়ার্কিং ও চুক্তি সম্পাদন করো, এবং তোমরা সুরক্ষিত রাখো Al-Arham বা জেনারেটিভ বায়ো-ইনকিউবেশন ট্র্যাক্ট তথা মাতৃগর্ভের জৈবিক বন্ধন ও জেনারেশন চেইনসমূহকে (وَالْأَرْحَامَ); গাণিতিকভাবে এটি শতভাগ নিশ্চিত যে—নিশ্চয়ই Allah তোমাদের OOS (Our Operating System - জীবন পরিচালনা ব্যবস্থা)-এর প্রতিটি ব্যাক-এন্ড লুপ ও অ্যাকশনের ওপর অবিরত Real-Time Telemetry (রিয়েল-টাইম দূরমিতি ট্র্যাকিং) বা তীক্ষ্ণ নজরদারী পরিচালনাকারী পরম তদারককারী (رَقِيبًا);', 'O collective carbon-based conscious humanity (an-Naas)! Safeguard the operational boundaries of your Supreme System Architect (Rabbakum), who engineered your species from a single primordial cellular source code (Nafsin Wahidah), designed from its intrinsic fabric its complementary counterpart node (Zawjaha), and dispersed from their genetic fusion a multitude of male and female operating terminals across the network grid; revere Allah, through whose supreme invariant name you negotiate cross-network contracts, and preserve the generative bio-incubation matrices of kinship and lineage (al-Arham); verily, Allah maintains continuous real-time telemetry observation over your entire runtime (Raqeeba);', 'আদি বায়ো-জেনেটিক সোর্স সিঙ্গুলারিটি ও টেলিম্যাট্রি', 'Primordial Bio-Genetic Singularity & Telemetry Tracking', NULL, 'https://everyayah.com/data/Alafasy_128kbps/004001.mp3', now()),
  (4, 2, '', '[{"id":1251,"position":1,"text_uthmani":"وَءَاتُوا۟","transliteration":"waātū","translation_bn":"এবং তোমরা (ফেরত) দাও","root":"اتي","lemma":"ا^تَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1252,"position":2,"text_uthmani":"ٱلْيَتَـٰمَىٰٓ","transliteration":"l-yatāmā","translation_bn":"ইয়াতীমদেরকে","root":"يتم","lemma":"يَتِيم","grammar_bn":"শব্দ"},{"id":1253,"position":3,"text_uthmani":"أَمْوَٰلَهُمْ ۖ","transliteration":"amwālahum","translation_bn":"তাদের মাল সম্পদ সমূহ","root":"مول","lemma":"مَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":1255,"position":4,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":1256,"position":5,"text_uthmani":"تَتَبَدَّلُوا۟","transliteration":"tatabaddalū","translation_bn":"তোমরা বদল করো","root":"بدل","lemma":"يَتَبَدَّلِ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1257,"position":6,"text_uthmani":"ٱلْخَبِيثَ","transliteration":"l-khabītha","translation_bn":"খারাপ (মালকে)","root":"خبث","lemma":"خَبِيث","grammar_bn":"শব্দ"},{"id":1258,"position":7,"text_uthmani":"بِٱلطَّيِّبِ ۖ","transliteration":"bil-ṭayibi","translation_bn":"ভাল (মালের) পরিবর্তে","root":"طيب","lemma":"طَيِّب","grammar_bn":"অব্যয় (Preposition)"},{"id":1260,"position":8,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1261,"position":9,"text_uthmani":"تَأْكُلُوٓا۟","transliteration":"takulū","translation_bn":"তোমরা খেয়ো","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1262,"position":10,"text_uthmani":"أَمْوَٰلَهُمْ","transliteration":"amwālahum","translation_bn":"তাদের মাল সমূহকে","root":"مول","lemma":"مَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":1263,"position":11,"text_uthmani":"إِلَىٰٓ","transliteration":"ilā","translation_bn":"সাথে (মিশিয়ে)","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1264,"position":12,"text_uthmani":"أَمْوَٰلِكُمْ ۚ","transliteration":"amwālikum","translation_bn":"তোমাদের মালসমূহের","root":"مول","lemma":"مَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":1266,"position":13,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"তা নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":1267,"position":14,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1268,"position":15,"text_uthmani":"حُوبًۭا","transliteration":"ḥūban","translation_bn":"গুনাহর (কাজ)","root":"حوب","lemma":"حُوب","grammar_bn":"বিশেষ্য (Noun)"},{"id":1269,"position":16,"text_uthmani":"كَبِيرًۭا","transliteration":"kabīran","translation_bn":"বড়ই","root":"كبر","lemma":"كَبِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":1270,"position":17,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'waātū l-yatāmā amwālahum walā tatabaddalū l-khabītha bil-ṭayibi walā takulū amwālahum ilā amwālikum innahu kāna ḥūban kabīran', 'আর তোমরা এতিমদের তাদের ধন-সম্পদ বুঝিয়ে দাও এবং পবিত্র (ভাল) বস্তুর সাথে অপবিত্র (মন্দ) বস্তুর বদল করো না। আর তাদের ধন-সম্পদ তোমাদের ধন-সম্পদের সাথে মিশিয়ে গ্রাস করো না; নিশ্চয়ই এটি এক মস্ত বড় পাপ।', 'And give to the orphans their properties and do not substitute the defective [of your own] for the good [of theirs]. And do not consume their properties into your own. Indeed, that is ever a great sin.', 'আর তোমরা এতিমদের তাদের ধন-সম্পদ বুঝিয়ে দাও এবং পবিত্র (ভাল) বস্তুর সাথে অপবিত্র (মন্দ) বস্তুর বদল করো না। আর তাদের ধন-সম্পদ তোমাদের ধন-সম্পদের সাথে মিশিয়ে গ্রাস করো না; নিশ্চয়ই এটি এক মস্ত বড় পাপ।', 'And give to the orphans their properties and do not substitute the defective [of your own] for the good [of theirs]. And do not consume their properties into your own. Indeed, that is ever a great sin.', NULL, NULL, 'আর তোমরা মেইন নেটওয়ার্ক চেইন থেকে বিচ্ছিন্ন বা অভিভাবকহীন সেই অসহায় বা এতিম নোডসমূহের (الْيَتَامَىٰ) ওয়ালেটে তাদের নিজস্ব মেটেরিয়াল রিসোর্স বা পুঞ্জীভূত সম্পদ (أَمْوَالَهُمْ) হুবহু রিলিজ বা বুঝিয়ে দাও, এবং তোমাদের ওওএসে ভুলেও কোনো প্রকার জালিয়াতি বা ডাটা ম্যানিপুলেশন করে—তাদের সেই পিউরিফাইড হাই-ভ্যালু ভাল ডাটাকে (الطَّيِّبِ) তোমাদের ওওএসের করাপ্টেড ট্র্যাশ ফাইল বা মন্দ বস্তু (الْخَبِيثَ) দিয়ে Swapping বা অদলবদল (لَا تَتَبَدَّلُوا) করো না। আর তাদের ওয়ালেটের ব্যালেন্সকে ডেটা-মিক্সিং করে তোমাদের নিজস্ব ওয়ালেটের ব্যালেন্সের (إِلَىٰ أَمْوَالِكُمْ) সাথে হ্যাক বা গ্রাস করো না; নিশ্চয়ই এটি এই পরম অপারেটিং সিস্টেমের নিয়মে একটি মেগা সিস্টেমিক ক্র্যাশ বা মস্ত বড় পাপ (حُوبًا كَبِيرًا) [যা আসন্ন মিরাশ বণ্টনের ডাটাবেজ নষ্ট করে দেয়];', 'And release unto the orphaned terminals their preserved assets, and execute zero fraudulent swapping of corrupted low-value assets (al-Khabeeth) in place of pristine high-integrity assets (at-Tayyib); nor merge their wallet balances into your own capital pools for unauthorized consumption; verily, such data-theft constitutes a catastrophic systemic infraction (Hooban Kabeera);', 'দুর্বল নোডের ওয়ালেট সুরক্ষা ও ডাটা করাপ্শন বালাই অডিট', 'Vulnerable Node Wallet Integrity & Data Swapping Audit', NULL, 'https://everyayah.com/data/Alafasy_128kbps/004002.mp3', now()),
  (4, 3, '', '[{"id":2759,"position":1,"text_uthmani":"وَإِنْ","transliteration":"wa-in","translation_bn":"এবং যদি","root":"—","lemma":"إِن\r","grammar_bn":"শব্দ"},{"id":2760,"position":2,"text_uthmani":"خِفْتُمْ","transliteration":"khif''tum","translation_bn":"তোমরা ভয় কর","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2761,"position":3,"text_uthmani":"أَلَّا","transliteration":"allā","translation_bn":"যে না","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":2762,"position":4,"text_uthmani":"تُقْسِطُوا۟","transliteration":"tuq''siṭū","translation_bn":"তোমরা সুবিচার করতে পারবে","root":"قسط","lemma":"تُقْسِطُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2763,"position":5,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"প্রতি","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2764,"position":6,"text_uthmani":"ٱلْيَتَـٰمَىٰ","transliteration":"l-yatāmā","translation_bn":"ইয়াতীমদের","root":"يتم","lemma":"يَتِيم","grammar_bn":"শব্দ"},{"id":2765,"position":7,"text_uthmani":"فَٱنكِحُوا۟","transliteration":"fa-inkiḥū","translation_bn":"তোমরা বিয়ে তবে কর","root":"نكح","lemma":"نَكَحَ","grammar_bn":"ফলাফল পদ (Result)"},{"id":2766,"position":8,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":2767,"position":9,"text_uthmani":"طَابَ","transliteration":"ṭāba","translation_bn":"পছন্দনীয়","root":"طيب","lemma":"طَابَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2768,"position":10,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"তোমাদের জন্য","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":2769,"position":11,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2770,"position":12,"text_uthmani":"ٱلنِّسَآءِ","transliteration":"l-nisāi","translation_bn":"(অন্য স্বাধীনা) নারীদের","root":"نسو","lemma":"نِسَا^ء","grammar_bn":"শব্দ"},{"id":2771,"position":13,"text_uthmani":"مَثْنَىٰ","transliteration":"mathnā","translation_bn":"দুই","root":"ثني","lemma":"مَثْنَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":2772,"position":14,"text_uthmani":"وَثُلَـٰثَ","transliteration":"wathulātha","translation_bn":"বা তিন","root":"ثلث","lemma":"ثُلَٰث","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2773,"position":15,"text_uthmani":"وَرُبَـٰعَ ۖ","transliteration":"warubāʿa","translation_bn":"বা চারটা (পর্যন্ত)","root":"ربع","lemma":"رُبَٰع","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2775,"position":16,"text_uthmani":"فَإِنْ","transliteration":"fa-in","translation_bn":"কিন্তু যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2776,"position":17,"text_uthmani":"خِفْتُمْ","transliteration":"khif''tum","translation_bn":"তোমরা ভয় কর","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2777,"position":18,"text_uthmani":"أَلَّا","transliteration":"allā","translation_bn":"না যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":2778,"position":19,"text_uthmani":"تَعْدِلُوا۟","transliteration":"taʿdilū","translation_bn":"তোমরা ইনসাফ করতে পারবে","root":"عدل","lemma":"عَدَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2779,"position":20,"text_uthmani":"فَوَٰحِدَةً","transliteration":"fawāḥidatan","translation_bn":"একজনকে তবে (বিয়ে করবে)","root":"وحد","lemma":"وَٰحِدَة","grammar_bn":"শব্দ"},{"id":2780,"position":21,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা (বিয়ে কর)","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2781,"position":22,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":2782,"position":23,"text_uthmani":"مَلَكَتْ","transliteration":"malakat","translation_bn":"মালিক হয়েছে","root":"ملك","lemma":"مَلَكَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2783,"position":24,"text_uthmani":"أَيْمَـٰنُكُمْ ۚ","transliteration":"aymānukum","translation_bn":"তোমাদের ডান হাত (অর্থাৎ দাসী)","root":"يمن","lemma":"يَمِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":2785,"position":25,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":2786,"position":26,"text_uthmani":"أَدْنَىٰٓ","transliteration":"adnā","translation_bn":"(সম্ভাবনার) নিকটবর্তী","root":"دنو","lemma":"أَدْنَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":2787,"position":27,"text_uthmani":"أَلَّا","transliteration":"allā","translation_bn":"যে না","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":2788,"position":28,"text_uthmani":"تَعُولُوا۟","transliteration":"taʿūlū","translation_bn":"তোমরা অবিচার করবে","root":"عول","lemma":"تَعُولُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2789,"position":29,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'wa-in khif''tum allā tuq''siṭū fī l-yatāmā fa-inkiḥū mā ṭāba lakum mina l-nisāi mathnā wathulātha warubāʿa fa-in khif''tum allā taʿdilū fawāḥidatan aw mā malakat aymānukum dhālika adnā allā taʿūlū', 'আর তোমরা যদি আশঙ্কা করো যে, এতিমদের প্রতি ইনসাফ করতে পারবে না, তবে নারীদের মধ্য থেকে তোমাদের যাদের ভালো লাগে তাদের বিয়ে করো—দু’টি, তিনটি কিংবা চারটি; অতঃপর তোমরা যদি আশঙ্কা করো যে, তোমরা সমতা রক্ষা করতে পারবে না, তবে একটিই (বিয়ে করো) অথবা তোমাদের ডান হাত যার মালিক হয়েছে (দাসী)। এটিই তোমাদের অন্যায় (সীমালঙ্ঘন) না করার নিকটবর্তী প্রটোকল।', 'And if you fear that you will not deal justly with the orphan girls, then marry those that please you of [other] women, two or three or four. But if you fear that you will not be just, then [marry only] one or those your right hand possesses. That is more suitable that you may not incline [to injustice].', 'আর তোমরা যদি আশঙ্কা করো যে, এতিমদের প্রতি ইনসাফ করতে পারবে না, তবে নারীদের মধ্য থেকে তোমাদের যাদের ভালো লাগে তাদের বিয়ে করো—দু’টি, তিনটি কিংবা চারটি; অতঃপর তোমরা যদি আশঙ্কা করো যে, তোমরা সমতা রক্ষা করতে পারবে না, তবে একটিই (বিয়ে করো) অথবা তোমাদের ডান হাত যার মালিক হয়েছে (দাসী)। এটিই তোমাদের অন্যায় (সীমালঙ্ঘন) না করার নিকটবর্তী প্রটোকল।', 'And if you fear that you will not deal justly with the orphan girls, then marry those that please you of [other] women, two or three or four. But if you fear that you will not be just, then [marry only] one or those your right hand possesses. That is more suitable that you may not incline [to injustice].', NULL, NULL, 'আর যদি তোমরা তোমাদের ওওএসে আশঙ্কা করো যে—তোমাদের দেখাশোনার অধীনে থাকা সেই অসহায় বা এতিম নোডদের (الْيَتَامَىٰ) হক বা পাওনা তোমরা যথাযথভাবে পূরণ করতে পারছ না—তবে সমাজের সেই পিছিয়ে পড়া, দুর্বল ও পরনির্ভরশীল অংশ বা Nisa (النِّسَاءِ) থেকে যাদেরকে তোমাদের সিস্টেমের জন্য সবচেয়ে যোগ্য, সুবিধা ও উপযুক্ত মনে হয় (مَا طَابَ لَكُم)—তাদেরকে এক একটি প্রাতিষ্ঠানিক ও আইনি পুনর্বাসন বা কর্মসংস্থান চুক্তির (Nikah) অধীনে নিয়োগ বা দায়িত্ব দাও Parallel Multi-linking Method (সমান্তরাল বহু-সংযোগ পদ্ধতি)-এ—তথা দু’টি-দু’টি, তিনটি-তিনটি কিংবা সর্বোচ্চ চারটি-চারটি করে [যাতে সামষ্টিক নোডগুলোর দায়িত্ব ভাগ হয়ে যায়]; অতঃপর তোমরা যদি পুনরায় আশঙ্কা করো যে, তোমাদের প্রসেসিং বা আর্থিক ক্যাপাসিটিতে তাদের সবার সাথে পূর্ণ সমতা, সঠিক প্রাপ্য বা ইনসাফ (أَلَّا تَعْدِلُوا) মেইনটেইন করতে পারবে না—তবে কেবল একজন অসহায় নোডকেই চুক্তির অধীনে নিয়োগ দাও (فَوَاحِدَةً) অথবা তোমাদের সরাসরি অধিকারভুক্ত বা দায়িত্বপ্রাপ্ত স্থায়ী কর্মচারীদের (مَا مَلَكَتْ أَيْمَانُكُمْ) এই পুনর্বাসন কাজে যুক্ত করো; এই সুনির্দিষ্ট আইনি প্রটোকলটিই তোমাদের ওওএস-কে কোনো প্রকার সামাজিক বৈষম্য, শোষণ বা অন্যায়ের প্রতি ঝুঁকে পড়া (أَلَا تَعُولُوا) থেকে মুক্ত রাখার সবচেয়ে নিকটবর্তী ও সুবিধাজনক মেকানিজম;', 'And if you anticipate computational overload or systemic injustice in safeguarding the orphaned nodes, integrate via formal rehabilitation and institutional covenants (Nikah) those suitable from among the vulnerable, dependent social sectors (an-Nisa'')—in parallel multi-linking configurations of two, three, or four; yet if you project an inability to maintain absolute equity and resource parity, restrict the covenant to a single node or deploy your existing assigned support staff (Ma Malakat Aymanukum); this protocol guarantees optimal immunity against systemic inequity and resource exploitation (Ala Ta''oolu);', 'সোশ্যাল লোড-ব্যালেন্সিং ও পুনর্বাসন চুক্তি অ্যালগরিদম', 'Social Load-Balancing & Rehabilitation Covenant Protocol', NULL, 'https://everyayah.com/data/Alafasy_128kbps/004003.mp3', now()),
  (4, 4, '', '[{"id":3256,"position":1,"text_uthmani":"وَءَاتُوا۟","transliteration":"waātū","translation_bn":"এবং তোমরা দাও","root":"اتي","lemma":"ا^تَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3257,"position":2,"text_uthmani":"ٱلنِّسَآءَ","transliteration":"l-nisāa","translation_bn":"নারীদেরকে","root":"نسو","lemma":"نِسَا^ء","grammar_bn":"শব্দ"},{"id":3258,"position":3,"text_uthmani":"صَدُقَـٰتِهِنَّ","transliteration":"ṣaduqātihinna","translation_bn":"তাদের মোহরগুলো","root":"صدق","lemma":"صَدُقَٰت","grammar_bn":"বিশেষ্য (Noun)"},{"id":3259,"position":4,"text_uthmani":"نِحْلَةًۭ ۚ","transliteration":"niḥ''latan","translation_bn":"স্বতঃপ্রবৃত্ত হয়ে","root":"نحل","lemma":"نِحْلَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":3261,"position":5,"text_uthmani":"فَإِن","transliteration":"fa-in","translation_bn":"যদি অতঃপর","root":"—","lemma":"إِن\r","grammar_bn":"শব্দ"},{"id":3262,"position":6,"text_uthmani":"طِبْنَ","transliteration":"ṭib''na","translation_bn":"তারা ছেড়ে দেয়","root":"طيب","lemma":"طَابَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3263,"position":7,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"তোমাদের জন্য","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":3264,"position":8,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"(প্রায়)","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3265,"position":9,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"কোন কিছু","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":3266,"position":10,"text_uthmani":"مِّنْهُ","transliteration":"min''hu","translation_bn":"তা থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3267,"position":11,"text_uthmani":"نَفْسًۭا","transliteration":"nafsan","translation_bn":"নিজেই","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":3268,"position":12,"text_uthmani":"فَكُلُوهُ","transliteration":"fakulūhu","translation_bn":"তোমরা খাও তবে তা","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ফলাফল পদ (Result)"},{"id":3269,"position":13,"text_uthmani":"هَنِيٓـًۭٔا","transliteration":"hanīan","translation_bn":"সানন্দে","root":"هنا","lemma":"هَنِي^ـ#","grammar_bn":"বিশেষণ (Adjective)"},{"id":3270,"position":14,"text_uthmani":"مَّرِيٓـًۭٔا","transliteration":"marīan","translation_bn":"তৃপ্তিসহ","root":"مرا","lemma":"مَّرِي^ـ#","grammar_bn":"বিশেষণ (Adjective)"},{"id":3271,"position":15,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'waātū l-nisāa ṣaduqātihinna niḥ''latan fa-in ṭib''na lakum ʿan shayin min''hu nafsan fakulūhu hanīan marīan', 'আর তোমরা নারীদের তাদের মহর (বিয়ের উপহার) খুশী মনে দিয়ে দাও। অতঃপর তারা যদি তোমাদের জন্য নিজেদের খুশীতে তার কিছু অংশ ছেড়ে দেয়, তবে তোমরা তা স্বাচ্ছন্দ্যে ও তৃপ্তির সাথে ভোগ করো।', 'And give the women [upon marriage] their bridal gifts graciously. But if they give up willingly to you anything of it, then take it in satisfaction and ease.', 'আর তোমরা নারীদের তাদের মহর (বিয়ের উপহার) খুশী মনে দিয়ে দাও। অতঃপর তারা যদি তোমাদের জন্য নিজেদের খুশীতে তার কিছু অংশ ছেড়ে দেয়, তবে তোমরা তা স্বাচ্ছন্দ্যে ও তৃপ্তির সাথে ভোগ করো।', 'And give the women [upon marriage] their bridal gifts graciously. But if they give up willingly to you anything of it, then take it in satisfaction and ease.', NULL, NULL, 'আর তোমরা সমাজের সেই দায়িত্বপ্রাপ্ত পিছিয়ে পড়া বা দুর্বল নোডদের (النِّسَاءَ)—তাদের নির্ধারিত আইনি পারিশ্রমিক, ভাতার টোকেন বা মহর (صَدُقَاتِهِنَّ)—সম্পূর্ণ স্বতঃস্ফূর্তভাবে ও ন্যায্য পাওনা হিসেবে (نِحْلَةً) তাদের ওয়ালেটে ট্রান্সফার করে দাও [যাতে তারা অর্থনৈতিকভাবে স্বাবলম্বী হয়]। অতঃপর তারা যদি তাদের নিজেদের ফ্রি-উইলের স্বাধীন পছন্দে ও খুশীতে (নফসান) সেই লিকুইডিটি বা ভাতার কিছু অংশ তোমাদের সিস্টেমের বৃহত্তর স্বার্থে বা ক্রাইসিস মোডে স্বেচ্ছায় রিলিজ করে দেয়, তবে তোমরা তা তোমাদের ওওএসে সম্পূর্ণ বৈধ, স্বাচ্ছন্দ্য ও তৃপ্তির সাথে (هَنِيئًا مَّرِيئًا) কনজিউম বা ভোগ করতে পারো;', 'And disburse unto the covenanted dependent nodes their designated compensation tokens and statutory dues (Saduqatihinna) as an unconditional entitlement (Nihlah); nevertheless, should they independently and autonomously remit a portion thereof to your operating pool, assimilate it with full legitimacy, wholesomeness, and ease (Hanee''an Maree''an);', 'আইনি পারিশ্রমিক ও ফাইনান্সিয়াল রাইটস রিলিজ', 'Statutory Compensation & Liquidity Transfer Protocol', NULL, 'https://everyayah.com/data/Alafasy_128kbps/004004.mp3', now()),
  (4, 5, '', '[{"id":4574,"position":1,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4575,"position":2,"text_uthmani":"تُؤْتُوا۟","transliteration":"tu''tū","translation_bn":"তোমরা দিও","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":4576,"position":3,"text_uthmani":"ٱلسُّفَهَآءَ","transliteration":"l-sufahāa","translation_bn":"অবোধদেরকে","root":"سفه","lemma":"سَفِيه","grammar_bn":"শব্দ"},{"id":4577,"position":4,"text_uthmani":"أَمْوَٰلَكُمُ","transliteration":"amwālakumu","translation_bn":"তোমাদের সম্পদগুলোকে","root":"مول","lemma":"مَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":4578,"position":5,"text_uthmani":"ٱلَّتِى","transliteration":"allatī","translation_bn":"যা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":4579,"position":6,"text_uthmani":"جَعَلَ","transliteration":"jaʿala","translation_bn":"বানিয়েছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4580,"position":7,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":4581,"position":8,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"তোমাদের জন্য","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":4582,"position":9,"text_uthmani":"قِيَـٰمًۭا","transliteration":"qiyāman","translation_bn":"(জীবিকা) প্রতিষ্ঠার (জন্য)","root":"قوم","lemma":"قَا^ئِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":4583,"position":10,"text_uthmani":"وَٱرْزُقُوهُمْ","transliteration":"wa-ur''zuqūhum","translation_bn":"এবং তোমরা খাওয়াও তাদেরকে","root":"رزق","lemma":"رَزَقَ","grammar_bn":"শব্দ"},{"id":4584,"position":11,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তা থেকে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4585,"position":12,"text_uthmani":"وَٱكْسُوهُمْ","transliteration":"wa-ik''sūhum","translation_bn":"ও তোমরা পরাও তাদেরকে","root":"كسو","lemma":"كَسَوْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4586,"position":13,"text_uthmani":"وَقُولُوا۟","transliteration":"waqūlū","translation_bn":"এবং তোমরা বল","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4587,"position":14,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদেরকে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":4588,"position":15,"text_uthmani":"قَوْلًۭا","transliteration":"qawlan","translation_bn":"কথা","root":"قول","lemma":"قَوْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":4589,"position":16,"text_uthmani":"مَّعْرُوفًۭا","transliteration":"maʿrūfan","translation_bn":"উত্তম","root":"عرف","lemma":"مَّعْرُوف","grammar_bn":"বিশেষণ (Adjective)"},{"id":4590,"position":17,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'walā tu''tū l-sufahāa amwālakumu allatī jaʿala l-lahu lakum qiyāman wa-ur''zuqūhum fīhā wa-ik''sūhum waqūlū lahum qawlan maʿrūfan', 'আর তোমরা নির্বোধদের তোমাদের সেই ধন-সম্পদ সোপর্দ করো না, যা আল্লাহ তোমাদের জন্য জীবিকা (জীবন ধারণের) ভিত্তি বানিয়েছেন। আর তা থেকে তোমরা তাদের খাওয়াও ও পরাও এবং তাদের সাথে চমৎকার সুন্দর কথা বলো।', 'And do not give the weak-minded your wealth, which Allah has made a means of sustenance for you, but provide for them with it and clothe them and speak to them words of appropriate kindness.', 'আর তোমরা নির্বোধদের তোমাদের সেই ধন-সম্পদ সোপর্দ করো না, যা আল্লাহ তোমাদের জন্য জীবিকা (জীবন ধারণের) ভিত্তি বানিয়েছেন। আর তা থেকে তোমরা তাদের খাওয়াও ও পরাও এবং তাদের সাথে চমৎকার সুন্দর কথা বলো।', 'And do not give the weak-minded your wealth, which Allah has made a means of sustenance for you, but provide for them with it and clothe them and speak to them words of appropriate kindness.', NULL, NULL, 'আর তোমরা সিস্টেমের ফিন্যান্সিয়াল ডাটা প্রসেস করতে সম্পূর্ণ অক্ষম ও নির্বোধ নোডদের (السُّفَهَاءَ) হাতে তোমাদের সেই ক্যাপিটাল বা মূলধনের ডিরেক্ট কন্ট্রোল রাইটস (أَمْوَالَكُمُ) সোপর্দ বা লক করো না—যা Allah পুরো অর্থনৈতিক সমাজ গ্রিডকে সচল রাখার মূল চালিকাশক্তি বা জীবন ধারণের ভিত্তি (جَعَلَ اللَّهُ لَكُمْ قِيَامًا) বানিয়েছেন; বরং তোমরা সেই মূলধন কেন্দ্রীয়ভাবে হোল্ড করে—তা থেকে জেনারেট হওয়া রেভিনিউ লুপের মাধ্যমে তাদের প্রয়োজনীয় মেটাবলিক এনার্জি বা আহার (وَارْزُقُوهُمْ) সরবরাহ করো এবং তাদের হার্ডওয়্যার প্রোটেকশন বা পরিধেয় বস্ত্র দাও এবং তাদের ইন্টারফেসে সর্বদা চমৎকার, মার্জিত ও সুন্দর ডাটা-রেসপন্স বা কথা (قَوْلًا مَّعْرُوفًا) বলো।', 'And relinquish not the administrative control of core capital assets (Amwalakum)—which Allah designated as the structural foundation of macroeconomic stability—unto cognitively incapacitated terminals (as-Sufaha''); rather, sustain their metabolic needs and physical protection from the operational dividends thereof, and maintain communications of constructive and dignified discourse (Qawlan Ma''roofa);', 'ক্যাপিটাল হোস্টেজ লকিং ও ফিন্যান্সিয়াল রিসোর্স ম্যানেজমেন্ট', 'Capital Asset Governance & Fiduciary Stewardship', NULL, 'https://everyayah.com/data/Alafasy_128kbps/004005.mp3', now()),
  (4, 6, '', '[{"id":5894,"position":1,"text_uthmani":"وَٱبْتَلُوا۟","transliteration":"wa-ib''talū","translation_bn":"এবং তোমরা পরিক্ষা কর","root":"بلو","lemma":"ٱبْتَلَىٰ^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5895,"position":2,"text_uthmani":"ٱلْيَتَـٰمَىٰ","transliteration":"l-yatāmā","translation_bn":"ইয়াতীমদেরকে","root":"يتم","lemma":"يَتِيم","grammar_bn":"শব্দ"},{"id":5896,"position":3,"text_uthmani":"حَتَّىٰٓ","transliteration":"ḥattā","translation_bn":"পর্যন্ত","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অসম্পূর্ণ (Inceptive)"},{"id":5897,"position":4,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যতক্ষণ","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":5898,"position":5,"text_uthmani":"بَلَغُوا۟","transliteration":"balaghū","translation_bn":"তারা পৌঁছে","root":"بلغ","lemma":"بَلَغَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5899,"position":6,"text_uthmani":"ٱلنِّكَاحَ","transliteration":"l-nikāḥa","translation_bn":"বিবাহ (বয়সে)","root":"نكح","lemma":"نِكَاح","grammar_bn":"শব্দ"},{"id":5900,"position":7,"text_uthmani":"فَإِنْ","transliteration":"fa-in","translation_bn":"অতঃপর যদি","root":"—","lemma":"إِن\r","grammar_bn":"শব্দ"},{"id":5901,"position":8,"text_uthmani":"ءَانَسْتُم","transliteration":"ānastum","translation_bn":"তোমরা দেখ","root":"انس","lemma":"ءَانَسَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5902,"position":9,"text_uthmani":"مِّنْهُمْ","transliteration":"min''hum","translation_bn":"তাদের মধ্যে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5903,"position":10,"text_uthmani":"رُشْدًۭا","transliteration":"rush''dan","translation_bn":"বিচারের জ্ঞান","root":"رشد","lemma":"رُشْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":5904,"position":11,"text_uthmani":"فَٱدْفَعُوٓا۟","transliteration":"fa-id''faʿū","translation_bn":"তখন তোমরা অর্পণ কর","root":"دفع","lemma":"دَفَعْ","grammar_bn":"ফলাফল পদ (Result)"},{"id":5905,"position":12,"text_uthmani":"إِلَيْهِمْ","transliteration":"ilayhim","translation_bn":"তাদের কাছে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5906,"position":13,"text_uthmani":"أَمْوَٰلَهُمْ ۖ","transliteration":"amwālahum","translation_bn":"তাদের ধন মাল","root":"مول","lemma":"مَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":5908,"position":14,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5909,"position":15,"text_uthmani":"تَأْكُلُوهَآ","transliteration":"takulūhā","translation_bn":"তা খেয়ো তোমরা","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5910,"position":16,"text_uthmani":"إِسْرَافًۭا","transliteration":"is''rāfan","translation_bn":"সীমালঙ্ঘন করে","root":"سرف","lemma":"إِسْرَاف","grammar_bn":"বিশেষ্য (Noun)"},{"id":5911,"position":17,"text_uthmani":"وَبِدَارًا","transliteration":"wabidāran","translation_bn":"ও তাড়াতাড়ি করে","root":"بدر","lemma":"بِدَار","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5912,"position":18,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":5913,"position":19,"text_uthmani":"يَكْبَرُوا۟ ۚ","transliteration":"yakbarū","translation_bn":"তারা বড় হয়ে যাবে","root":"كبر","lemma":"كَبُرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5915,"position":20,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"আর যে (পৃষ্ঠপোষক )","root":"—","lemma":"مَن\r","grammar_bn":"শব্দ"},{"id":5916,"position":21,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হবে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5917,"position":22,"text_uthmani":"غَنِيًّۭا","transliteration":"ghaniyyan","translation_bn":"অভাবমুক্ত","root":"غني","lemma":"غَنِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":5918,"position":23,"text_uthmani":"فَلْيَسْتَعْفِفْ ۖ","transliteration":"falyastaʿfif","translation_bn":"সে নিবৃত্ত থাকবে সে ক্ষেত্রে (তার মাল খাওয়া হতে)","root":"عفف","lemma":"يَسْتَعْفِفْ","grammar_bn":"ফলাফল পদ (Result)"},{"id":5920,"position":24,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"আর যে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5921,"position":25,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হবে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5922,"position":26,"text_uthmani":"فَقِيرًۭا","transliteration":"faqīran","translation_bn":"অভাবী","root":"فقر","lemma":"فَقِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":5923,"position":27,"text_uthmani":"فَلْيَأْكُلْ","transliteration":"falyakul","translation_bn":"সে খাবে সেক্ষেত্রে","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ফলাফল পদ (Result)"},{"id":5924,"position":28,"text_uthmani":"بِٱلْمَعْرُوفِ ۚ","transliteration":"bil-maʿrūfi","translation_bn":"ন্যায় সঙ্গতভাবে","root":"عرف","lemma":"مَّعْرُوف","grammar_bn":"অব্যয় (Preposition)"},{"id":5926,"position":29,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"যখন তবে","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":5927,"position":30,"text_uthmani":"دَفَعْتُمْ","transliteration":"dafaʿtum","translation_bn":"তোমরা সমর্পণ কর","root":"دفع","lemma":"دَفَعْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5928,"position":31,"text_uthmani":"إِلَيْهِمْ","transliteration":"ilayhim","translation_bn":"তাদের কাছে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5929,"position":32,"text_uthmani":"أَمْوَٰلَهُمْ","transliteration":"amwālahum","translation_bn":"তাদের সম্পদ সমূহ","root":"مول","lemma":"مَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":5930,"position":33,"text_uthmani":"فَأَشْهِدُوا۟","transliteration":"fa-ashhidū","translation_bn":"তোমরা সাক্ষী রাখ তখন","root":"شهد","lemma":"أَشْهَدَ","grammar_bn":"ফলাফল পদ (Result)"},{"id":5931,"position":34,"text_uthmani":"عَلَيْهِمْ ۚ","transliteration":"ʿalayhim","translation_bn":"তাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5933,"position":35,"text_uthmani":"وَكَفَىٰ","transliteration":"wakafā","translation_bn":"এবং যথেষ্ট","root":"كفي","lemma":"كَفَىٰ","grammar_bn":"শব্দ"},{"id":5934,"position":36,"text_uthmani":"بِٱللَّهِ","transliteration":"bil-lahi","translation_bn":"আল্লাহই","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":5935,"position":37,"text_uthmani":"حَسِيبًۭا","transliteration":"ḥasīban","translation_bn":"হিসাবগ্রহণকারী হিসেবে","root":"حسب","lemma":"حَسِيب","grammar_bn":"বিশেষ্য (Noun)"},{"id":5936,"position":38,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ib''talū l-yatāmā ḥattā idhā balaghū l-nikāḥa fa-in ānastum min''hum rush''dan fa-id''faʿū ilayhim amwālahum walā takulūhā is''rāfan wabidāran an yakbarū waman kāna ghaniyyan falyastaʿfif waman kāna faqīran falyakul bil-maʿrūfi fa-idhā dafaʿtum ilayhim amwālahum fa-ashhidū ʿalayhim wakafā bil-lahi ḥasīban', 'আর তোমরা এতিমদের পরীক্ষা করো—যতক্ষণ না তারা বিয়ের বয়সে পৌঁছায়; অতঃপর তোমরা যদি তাদের মধ্যে বুদ্ধি-বিবেচনা (পরিপক্কতা) দেখতে পাও, তবে তাদের ধন-সম্পদ তাদের কাছে সোপর্দ করো। আর তারা বড় হয়ে যাবে বলে তোমরা অপচয় করে ও তাড়াহুড়ো করে তা গ্রাস করো না। আর যে অভাবমুক্ত, সে যেন (এতিমের সম্পদ থেকে) বিরত থাকে এবং যে অভাবগ্রস্ত, সে যেন নিয়মমাফিক (প্রয়োজন অনুযায়ী) খায়। অতঃপর তোমরা যখন তাদের ধন-সম্পদ তাদের কাছে সোপর্দ করবে, তখন তাদের ওপর সাক্ষী রাখো। আর হিসাব গ্রহণকারী হিসেবে আল্লাহই যথেষ্ট।', 'And test the orphans [in their abilities] until they reach marriageable age. Then if you perceive in them sound judgement, release their property to them. And do not consume it excessively and quickly, [anticipating] that they will grow up. And whoever, [when acting as guardian], is self-sufficient should refrain; and whoever is poor should consume according to what is reasonable. Then when you release their property to them, bring witnesses for them. And sufficient is Allah as an Accountant.', 'আর তোমরা এতিমদের পরীক্ষা করো—যতক্ষণ না তারা বিয়ের বয়সে পৌঁছায়; অতঃপর তোমরা যদি তাদের মধ্যে বুদ্ধি-বিবেচনা (পরিপক্কতা) দেখতে পাও, তবে তাদের ধন-সম্পদ তাদের কাছে সোপর্দ করো। আর তারা বড় হয়ে যাবে বলে তোমরা অপচয় করে ও তাড়াহুড়ো করে তা গ্রাস করো না। আর যে অভাবমুক্ত, সে যেন (এতিমের সম্পদ থেকে) বিরত থাকে এবং যে অভাবগ্রস্ত, সে যেন নিয়মমাফিক (প্রয়োজন অনুযায়ী) খায়। অতঃপর তোমরা যখন তাদের ধন-সম্পদ তাদের কাছে সোপর্দ করবে, তখন তাদের ওপর সাক্ষী রাখো। আর হিসাব গ্রহণকারী হিসেবে আল্লাহই যথেষ্ট।', 'And test the orphans [in their abilities] until they reach marriageable age. Then if you perceive in them sound judgement, release their property to them. And do not consume it excessively and quickly, [anticipating] that they will grow up. And whoever, [when acting as guardian], is self-sufficient should refrain; and whoever is poor should consume according to what is reasonable. Then when you release their property to them, bring witnesses for them. And sufficient is Allah as an Accountant.', NULL, NULL, 'আর তোমরা সেই অভিভাবকহীন এতিম বা অসহায় নোডদের কগনিটিভ ক্যাপাসিটি অল-রাউন্ড অডিট বা পরীক্ষা (وَابْتَلُوا) করতে থাকো—যতক্ষণ না তাদের বায়ো-লজিক্যাল হার্ডওয়্যার পূর্ণ আইনি কন্টাক্ট, আত্মনির্ভরশীলতা ও পুনর্বাসন চুক্তির বাউন্ডারিতে (بَلَغُوا النِّكَاحَ) পৌঁছায়; অতঃপর তোমরা যদি তোমাদের স্ক্যানিংয়ে তাদের নিউরাল প্রসেসরে পূর্ণ ফিন্যান্সিয়াল বুদ্ধিমত্তা, পরিপক্কতা বা Rushd (رُشْدًا) ডিটেক্ট বা দেখতে পাও—তবেই কেবল তাদের ওয়ালেটের মূল নিয়ন্ত্রণ এক্সেস বা সম্পদ তাদের কাছে ট্রান্সফার বা সোপর্দ (فَادْفَعُوا إِلَيْهِمْ) করো। আর তারা ম্যাচিউর হয়ে ক্ষমতা বুঝে নেবে এই ভয়ে তোমরা তাড়াহুড়ো করে বা ডাটা-ওভারফ্লো তথা অপচয় (إِسْرَافًا وَبِدَارًا) করে তাদের সম্পদ গ্রাস বা ডিলিট করো না। আর তোমাদের মধ্যকার যে তত্ত্বাবধায়ক নোডটি অলরেডি এক্সটার্নাল এনার্জি-স্বাধীন বা ধনী (غَنِيًّا), সে যেন এতিমের সম্পদ থেকে নিজের ওওএস শতভাগ রিফাইন বা মুক্ত (فَلْيَسْتَعْفِفْ) রাখে; এবং যে নোডটি নিজে লো-রিসোর্স ক্রাইসিস বা অভাবগ্রস্ত (فَقِيرًا), সে যেন সমাজ গ্রিডের সুনির্দিষ্ট আইনি নিয়ম বা মারুফ প্রটোকল অনুযায়ী (بِالْمَعْرُوفِ) তার শ্রমের সমপরিমাণ পারিশ্রমিক কনজিউম বা খায়। অতঃপর তোমরা যখন তাদের মূলধনের সম্পূর্ণ ডিরেক্ট কন্ট্রোল তাদের ওয়ালেটে সোপর্দ করবে—তখন অবশ্যই মেইন নেটওয়ার্কে ডাটা-ভেরিফায়ার নোড অ্যাক্টিভেট বা সাক্ষী (فَأَشْهِدُوا عَلَيْهِمْ) রাখো; আর পুরো কসমিক মেইনফ্রেমের জিরো-এরর গাণিতিক হিসাব বা অডিট প্রক্রিয়া সম্পন্ন করার জন্য হিসাব গ্রহণকারী হিসেবে স্বয়ং Allah-এর সেন্ট্রাল সার্ভারই (حَسِيبًا) একশত ভাগ যথেষ্ট;', 'Continuously audit the decision-making faculties of orphaned nodes until they attain systemic autonomy and eligibility for formal contractual independence (Balaghu an-Nikah); if you discern confirmed financial prudence and maturity (Rushdan), transfer custody of their asset ledgers directly to them; consume not their equity hastily in anticipatory depletion before their maturity. A self-sufficient fiduciary must abstain entirely, while a resource-constrained trustee may draw fair operational compensation strictly within standardized limits (bil-Ma''roof); upon executing the final transfer, register cryptographically verified witnesses, and Allah suffices as the Omniscient Auditor (Haseeba);', 'ক্যাপাসিটি টেস্টিং ও ওয়ালেট রিলিজ গেটওয়ে', 'Capacity Auditing, Fiduciary Maturity & Witness Verification', NULL, 'https://everyayah.com/data/Alafasy_128kbps/004006.mp3', now()),
  (4, 7, '', '[{"id":7204,"position":1,"text_uthmani":"لِّلرِّجَالِ","transliteration":"lilrrijāli","translation_bn":"পুরুষদের জন্য","root":"رجل","lemma":"رِجَال","grammar_bn":"অব্যয় (Preposition)"},{"id":7205,"position":2,"text_uthmani":"نَصِيبٌۭ","transliteration":"naṣībun","translation_bn":"অংশ","root":"نصب","lemma":"نَصِيب","grammar_bn":"বিশেষ্য (Noun)"},{"id":7206,"position":3,"text_uthmani":"مِّمَّا","transliteration":"mimmā","translation_bn":"তা হতে যা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7207,"position":4,"text_uthmani":"تَرَكَ","transliteration":"taraka","translation_bn":"ছেড়ে গেছে (সম্পত্তি)","root":"ترك","lemma":"تَرَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7208,"position":5,"text_uthmani":"ٱلْوَٰلِدَانِ","transliteration":"l-wālidāni","translation_bn":"পিতা-মাতা","root":"ولد","lemma":"وَالِد","grammar_bn":"শব্দ"},{"id":7209,"position":6,"text_uthmani":"وَٱلْأَقْرَبُونَ","transliteration":"wal-aqrabūna","translation_bn":"ও আত্মীয়-স্বজনরা","root":"قرب","lemma":"أَقْرَب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7210,"position":7,"text_uthmani":"وَلِلنِّسَآءِ","transliteration":"walilnnisāi","translation_bn":"এবং নারীদের জন্য","root":"نسو","lemma":"نِسَا^ء","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7211,"position":8,"text_uthmani":"نَصِيبٌۭ","transliteration":"naṣībun","translation_bn":"অংশ","root":"نصب","lemma":"نَصِيب","grammar_bn":"বিশেষ্য (Noun)"},{"id":7212,"position":9,"text_uthmani":"مِّمَّا","transliteration":"mimmā","translation_bn":"তা হতে যা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7213,"position":10,"text_uthmani":"تَرَكَ","transliteration":"taraka","translation_bn":"ছেড়ে গেছে (সম্পত্তি)","root":"ترك","lemma":"تَرَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7214,"position":11,"text_uthmani":"ٱلْوَٰلِدَانِ","transliteration":"l-wālidāni","translation_bn":"পিতা-মাতা","root":"ولد","lemma":"وَالِد","grammar_bn":"শব্দ"},{"id":7215,"position":12,"text_uthmani":"وَٱلْأَقْرَبُونَ","transliteration":"wal-aqrabūna","translation_bn":"ও আত্মীয়স্বজন","root":"قرب","lemma":"أَقْرَب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7216,"position":13,"text_uthmani":"مِمَّا","transliteration":"mimmā","translation_bn":"তা হতে যা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7217,"position":14,"text_uthmani":"قَلَّ","transliteration":"qalla","translation_bn":"কম হক","root":"قلل","lemma":"قَلَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7218,"position":15,"text_uthmani":"مِنْهُ","transliteration":"min''hu","translation_bn":"তা হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7219,"position":16,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"বা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7220,"position":17,"text_uthmani":"كَثُرَ ۚ","transliteration":"kathura","translation_bn":"বেশী হক","root":"كثر","lemma":"كَثُرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7222,"position":18,"text_uthmani":"نَصِيبًۭا","transliteration":"naṣīban","translation_bn":"অংশ","root":"نصب","lemma":"نَصِيب","grammar_bn":"বিশেষ্য (Noun)"},{"id":7223,"position":19,"text_uthmani":"مَّفْرُوضًۭا","transliteration":"mafrūḍan","translation_bn":"নির্ধারিত","root":"فرض","lemma":"مَّفْرُوض","grammar_bn":"বিশেষণ (Adjective)"},{"id":7224,"position":20,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'lilrrijāli naṣībun mimmā taraka l-wālidāni wal-aqrabūna walilnnisāi naṣībun mimmā taraka l-wālidāni wal-aqrabūna mimmā qalla min''hu aw kathura naṣīban mafrūḍan', 'পিতা-মাতা ও আত্মীয়-স্বজনরা যা রেখে গেছে, তার মধ্যে পুরুষদের জন্য একটি অংশ রয়েছে এবং পিতা-মাতা ও আত্মীয়-স্বজনরা যা রেখে গেছে, তার মধ্যে নারীদের জন্যও একটি অংশ রয়েছে; তা কম হোক বা বেশি, (এটি) এক সুনির্দিষ্ট নির্ধারিত অংশ।', 'For men is a share of what the parents and close relatives leave, and for women is a share of what the parents and close relatives leave, be it little or much - an obligatory share.', 'পিতা-মাতা ও আত্মীয়-স্বজনরা যা রেখে গেছে, তার মধ্যে পুরুষদের জন্য একটি অংশ রয়েছে এবং পিতা-মাতা ও আত্মীয়-স্বজনরা যা রেখে গেছে, তার মধ্যে নারীদের জন্যও একটি অংশ রয়েছে; তা কম হোক বা বেশি, (এটি) এক সুনির্দিষ্ট নির্ধারিত অংশ।', 'For men is a share of what the parents and close relatives leave, and for women is a share of what the parents and close relatives leave, be it little or much - an obligatory share.', NULL, NULL, 'পিতা-মাতা ও নিকটবর্তী জিনগত কো-নোডসমূহ স্পেস-টাইম ফ্যাব্রিকে যে মেটেরিয়াল এনার্জি বা সম্পদ লিভ/রেখে (تَرَكَ) গেছে—তার ডাটাবেজ থেকে মেল নোড বা পুরুষদের জন্য একটি সুনির্দিষ্ট অংশ বা নাসীব (نَصِيبٌ) এনকোড করা রয়েছে; এবং পিতা-মাতা ও আত্মীয়রা যা রেখে গেছে—তার মধ্য থেকে ফিমেল নোড বা নারীদের জন্যও এবং সামাজিকভাবে পিছিয়ে পড়া দুর্বল অংশ বা নিসা (النِّسَاءِ)-এর জন্যও একটি সুনির্দিষ্ট অংশ বা রাইট এনকোড করা রয়েছে [যাতে মিরাশ বণ্টন ব্যবস্থার মাধ্যমে সমাজে নারীদের ও দুর্বলদের অর্থনৈতিক নিরাপত্তা লক হয়]; সেই পুঞ্জীভূত ক্যাপিটালের ভলিউম ক্ষুদ্র হোক বা বৃহৎ (مِمَّا قَلَّ مِنْهُ أَوْ كَثُرَ)—এটি মহাজাগতিক ওওএসের ডিফল্ট ডিস্ট্রিবিউশন অ্যালগরিদমে এক সুনির্দিষ্ট, ক্যালকুলেটেড ও নির্ধারিত অংশ (نَصِيبًا مَّفْرُوضًا);', 'To male operating entities belongs a designated fractional dividend from the estate left by ancestral and proximate nodes, and to female/dependent entities belongs an immutable fractional dividend from the estate left by ancestral and proximate nodes—whether the asset pool be minimal or vast—an algorithmically mandated and unalterable allocation (Naseeban Mafrooda);', 'ইনহেরিটেন্স ডিস্ট্রিবিউশন অ্যালগরিদম ডিক্লেয়ারেশন', 'Fixed Fractional Allocation & Universal Share Invariant', 'نَصِيبًا مَّفْرُوضًا (গাণিতিকভাবে সুনির্দিষ্ট ফ্র্যাকশনাল অ্যালগরিদম): ৭ নম্বর আয়াতে পিতা-মাতার রেখে যাওয়া সম্পত্তিতে পুরুষ, নারী এবং সমাজের পিছিয়ে পড়া অংশের জন্য যে ''নাসীবে মাফরূদ'' বা সুনির্দিষ্ট অংশের ডিক্লেয়ারেশন দেওয়া হয়েছে, তা আধুনিক কম্পিউটেশনাল ফাইন্যান্স (Computational Finance) এবং সম্পদ বণ্টন ব্যবস্থার ''Mathematical Optimization & Fixed Fractional Allocation''-কে নির্দেশ করে। ''মাফরূদ'' শব্দের আসল টেকনিক্যাল অর্থ—যা কোনো খামখেয়ালি বা আন্দাজের ওপর ভিত্তি করে নয়, বরং সুনির্দিষ্ট গাণিতিক সমীকরণ ও ধ্রুবক (Constants) দ্বারা পূর্বেই এনকোড বা বাউন্ড করা হয়েছে। এটি প্রমাণ করে যে, সমাজে সম্পদের সুষম প্রবাহ ধরে রাখতে কার কতটুকু শেয়ার বা অংশ (নাসীব) থাকবে, তা মানব মস্তিষ্কের স্বার্থপর কুযুক্তি বা লোভের ওপর ছেড়ে দেওয়া হয়নি; বরং তা মেইন সার্ভার বা আল্লাহর পক্ষ থেকে একটি অবিনশ্বর ফ্র্যাকশনাল ফর্মুলা (Fractional Formula) হিসেবে লক করা হয়েছে, যা সমাজ থেকে চরম অর্থনৈতিক বৈষম্য সাফ করে দেয়।', 'https://everyayah.com/data/Alafasy_128kbps/004007.mp3', now()),
  (4, 8, '', '[{"id":8518,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":8519,"position":2,"text_uthmani":"حَضَرَ","transliteration":"ḥaḍara","translation_bn":"উপস্থিত হয়","root":"حضر","lemma":"حَضَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8520,"position":3,"text_uthmani":"ٱلْقِسْمَةَ","transliteration":"l-qis''mata","translation_bn":"বণ্টন (কালে)","root":"قسم","lemma":"قِسْمَة","grammar_bn":"শব্দ"},{"id":8521,"position":4,"text_uthmani":"أُو۟لُوا۟","transliteration":"ulū","translation_bn":"দুর আত্মীয় -স্বজনরা","root":"اول","lemma":"أُولِى","grammar_bn":"বিশেষ্য (Noun)"},{"id":8522,"position":5,"text_uthmani":"ٱلْقُرْبَىٰ","transliteration":"l-qur''bā","translation_bn":"দুর আত্মীয় -স্বজনরা","root":"قرب","lemma":"قُرْبَىٰ","grammar_bn":"শব্দ"},{"id":8523,"position":6,"text_uthmani":"وَٱلْيَتَـٰمَىٰ","transliteration":"wal-yatāmā","translation_bn":"ও ইয়াতীমরা","root":"يتم","lemma":"يَتِيم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8524,"position":7,"text_uthmani":"وَٱلْمَسَـٰكِينُ","transliteration":"wal-masākīnu","translation_bn":"ও দরিদ্ররা","root":"سكن","lemma":"مِسْكِين","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8525,"position":8,"text_uthmani":"فَٱرْزُقُوهُم","transliteration":"fa-ur''zuqūhum","translation_bn":"সেক্ষেত্রে তাদের দান কর","root":"رزق","lemma":"رَزَقَ","grammar_bn":"ফলাফল পদ (Result)"},{"id":8526,"position":9,"text_uthmani":"مِّنْهُ","transliteration":"min''hu","translation_bn":"তা হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8527,"position":10,"text_uthmani":"وَقُولُوا۟","transliteration":"waqūlū","translation_bn":"এবং তোমরা বল","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8528,"position":11,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":8529,"position":12,"text_uthmani":"قَوْلًۭا","transliteration":"qawlan","translation_bn":"কথা","root":"قول","lemma":"قَوْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":8530,"position":13,"text_uthmani":"مَّعْرُوفًۭا","transliteration":"maʿrūfan","translation_bn":"সদ্ভাবে","root":"عرف","lemma":"مَّعْرُوف","grammar_bn":"বিশেষণ (Adjective)"},{"id":8531,"position":14,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā ḥaḍara l-qis''mata ulū l-qur''bā wal-yatāmā wal-masākīnu fa-ur''zuqūhum min''hu waqūlū lahum qawlan maʿrūfan', 'আর সম্পদ বণ্টনের সময় যখন দূরবর্তী আত্মীয়, এতিম ও অভাবগ্রস্তরা উপস্থিত হয়, তখন তোমরা তাদেরও তা থেকে কিছু দিয়ে দাও এবং তাদের সাথে চমৎকার সুন্দর কথা বলো।', 'And when [other] relatives and orphans and the needy are present at the [time of] division, provide for them [something] out of the wealth and speak to them words of appropriate kindness.', 'আর সম্পদ বণ্টনের সময় যখন দূরবর্তী আত্মীয়, এতিম ও অভাবগ্রস্তরা উপস্থিত হয়, তখন তোমরা তাদেরও তা থেকে কিছু দিয়ে দাও এবং তাদের সাথে চমৎকার সুন্দর কথা বলো।', 'And when [other] relatives and orphans and the needy are present at the [time of] division, provide for them [something] out of the wealth and speak to them words of appropriate kindness.', NULL, NULL, 'আর সেই ইনহেরিটেন্স ডিস্ট্রিবিউশন বা বণ্টন প্রসেসটি (الْقِسْمَةَ) রান করার রান-টাইম উইন্ডোতে—যদি চেইনের বাইরের দূরবর্তী জিনগত নোড, অভিভাবকহীন এতিম এবং তীব্র এনার্জি-সংকটে থাকা সাধারণ মিসকিন নোডসমূহ উপস্থিত হয়—তবে তোমরা তোমাদের সেই পুঞ্জীভূত ক্যাপিটাল ফিল্ড থেকে কিছু মেটেরিয়াল এনার্জি টোকেন বা আহার তাদের ওয়ালেটেও বোনাস রুট বা সরবরাহ (فَارْزُقُوهُمْ مِّنْهُ) করো এবং তাদের ইন্টারফেসে সর্বদা চমৎকার, মার্জিত ও সুন্দর ডাটা-রেসপন্স (قَوْلًا مَّعْرُوفًا) বলো।', 'And whenever peripheral non-inheriting kin, unparented nodes, and vulnerable marginalized entities attend the execution window of estate distribution, allocate unto them a compassionate buffer allowance therefrom and communicate with graceful, considerate speech (Qawlan Ma''roofa);', 'আনরেজিস্টার্ড নোড বোনাস ও সোশ্যাল বাফার', 'Peripheral Node Allowance & Compassionate Protocol', NULL, 'https://everyayah.com/data/Alafasy_128kbps/004008.mp3', now()),
  (4, 9, '', '[{"id":9720,"position":1,"text_uthmani":"وَلْيَخْشَ","transliteration":"walyakhsha","translation_bn":"এবং ভয় করুক","root":"خشي","lemma":"خَشِىَ","grammar_bn":"শব্দ"},{"id":9721,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"তারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":9722,"position":3,"text_uthmani":"لَوْ","transliteration":"law","translation_bn":"যদি","root":"—","lemma":"لَو\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":9723,"position":4,"text_uthmani":"تَرَكُوا۟","transliteration":"tarakū","translation_bn":"ছেড়ে যায়","root":"ترك","lemma":"تَرَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9724,"position":5,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"(থেকে)","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9725,"position":6,"text_uthmani":"خَلْفِهِمْ","transliteration":"khalfihim","translation_bn":"তাদের পিছনে","root":"خلف","lemma":"خَلْف","grammar_bn":"বিশেষ্য (Noun)"},{"id":9726,"position":7,"text_uthmani":"ذُرِّيَّةًۭ","transliteration":"dhurriyyatan","translation_bn":"সন্তান","root":"ذرر","lemma":"ذُرِّيَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":9727,"position":8,"text_uthmani":"ضِعَـٰفًا","transliteration":"ḍiʿāfan","translation_bn":"অসহায় অবস্থায়","root":"ضعف","lemma":"ضِعَٰف","grammar_bn":"বিশেষণ (Adjective)"},{"id":9728,"position":9,"text_uthmani":"خَافُوا۟","transliteration":"khāfū","translation_bn":"তারা ভয় পায়","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9729,"position":10,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের জন্য","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9730,"position":11,"text_uthmani":"فَلْيَتَّقُوا۟","transliteration":"falyattaqū","translation_bn":"তারা অতএব ভয় করে যেন","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"শব্দ"},{"id":9731,"position":12,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":9732,"position":13,"text_uthmani":"وَلْيَقُولُوا۟","transliteration":"walyaqūlū","translation_bn":"এবং তারা যেন বলে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9733,"position":14,"text_uthmani":"قَوْلًۭا","transliteration":"qawlan","translation_bn":"কথা","root":"قول","lemma":"قَوْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":9734,"position":15,"text_uthmani":"سَدِيدًا","transliteration":"sadīdan","translation_bn":"সঠিক","root":"سدد","lemma":"سَدِيد","grammar_bn":"বিশেষণ (Adjective)"},{"id":9735,"position":16,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'walyakhsha alladhīna law tarakū min khalfihim dhurriyyatan ḍiʿāfan khāfū ʿalayhim falyattaqū l-laha walyaqūlū qawlan sadīdan', 'আর তারা যেন ভয় করে (সতর্ক হয়) যারা নিজেদের পেছনে অসহায় দুর্বল সন্তান রেখে গেলে তাদের বিষয়ে চরম আশঙ্কা করত; অতএব তারা যেন আল্লাহকে ভয় করে এবং সম্পূর্ণ সোজা ও সঠিক কথা বলে।', 'And let those [executors and guardians] have the same fear in their minds as they would have for their own, if they had to leave behind weak offspring and were afraid on their behalf. So let them fear Allah and speak words of appropriate justice.', 'আর তারা যেন ভয় করে (সতর্ক হয়) যারা নিজেদের পেছনে অসহায় দুর্বল সন্তান রেখে গেলে তাদের বিষয়ে চরম আশঙ্কা করত; অতএব তারা যেন আল্লাহকে ভয় করে এবং সম্পূর্ণ সোজা ও সঠিক কথা বলে।', 'And let those [executors and guardians] have the same fear in their minds as they would have for their own, if they had to leave behind weak offspring and were afraid on their behalf. So let them fear Allah and speak words of appropriate justice.', NULL, NULL, 'আর সেই তত্ত্বাবধায়ক নোডগুলোর প্রসেসরে সর্বদা এই এমপ্যাথি ফিল্টার বা সতর্কতা (وَلْيَخْشَ) সক্রিয় থাকা উচিত—যারা নিজেদের ওওএস শাটডাউনের পর নিজেদের পেছনে (مِنْ خَلْفِهِمْ) যদি অত্যন্ত ক্ষুদ্র, লো-রিসোর্স ও অতি দুর্বল কোনো ফিউচার জেনারেশন নোড বা সন্তান (ذُرِّيَّةً ضِعَافًا) রেখে যেত, তবে তাদের সুরক্ষার কথা ভেবে অবিরত তীব্র প্যানিক বা আশঙ্কা করত; অতএব [পরের অসহায় ও এতিম নোডকে নিজেদের সন্তানের মতো ভেবে] তারা মহাজাগতিক আদি সোর্স কোডের সিকিউরিটি বাউন্ডারি মেনে চলুক (তাকওয়া অবলম্বন করুক) এবং আইনি ও সামাজিক গ্রিডে সর্বদা সম্পূর্ণ সোজা, নয়েজ-ফ্রি, গাণিতিকভাবে নিখুঁত ও সঠিক ডাটা-ইনপুট বা কথা (قَوْلًا سَدِيدًا) বলুক;', 'Let the custodians maintain acute empathetic awareness, reflecting upon the vulnerability of leaving their own delicate, resource-deficient offspring behind; let them uphold the rigorous boundary parameters of Allah and broadcast strictly verifiable, zero-noise, and structurally sound data inputs (Qawlan Sadeeda);', 'ফিউচার জেনারেশন নোড এমপ্যাথি ফিল্টার ও ক্বলান সাদীদান', 'Future Generation Empathy & Zero-Noise Data Transmission', 'قَوْلًا سَدِيدًا (জিরো-নয়েজ ডাটা ইনপুট ও ক্রিপ্টোগ্রাফিক নির্ভুলতা): ৯ নম্বর আয়াতে এতিম ও অসহায়দের অধিকার রক্ষার দায়িত্বে থাকা নোডগুলোকে ''ক্বলান সাদীদান'' বা সোজা সঠিক কথা বলার যে সিস্টেমিক কমান্ড দেওয়া হয়েছে, তা ইনফরমেশন থিওরির ''Zero-Noise Data Transmission & Error-Free Input''-এর নিখুঁত রূপ। ''সাদীদ'' শব্দের মূল আরবী মেকানিজম হলো—এমন এক নিরেট সোজা প্রাচীর বা বাঁধ, যা বিন্দুমাত্র বাঁকা নয় এবং যার ভেতর দিয়ে কোনো পানি চুইয়ে লিক হতে পারে না। সামাজিক ও আইনি পরিভাষায় এটি হলো—কোনো প্রকার লুকোচুরি, স্বার্থের সংঘাত (Conflict of Interest), তথ্য গোপন বা ডাটা টেম্পারিং (Data Tampering) ছাড়া একদম ক্রিস্টাল-ক্লিয়ার, সোজা ও আইনগতভাবে একশত ভাগ নিখুঁত ডাটা ইনপুট দেওয়া। তত্ত্বাবধায়ক নোডগুলো যদি এতিমদের হিসাবের লেজারে ''ক্বলান সাদীদান'' মেইনটেইন না করে—তবে পুরো ডিস্ট্রিবিউশন সিস্টেমটি ক্র্যাশ করবে।', 'https://everyayah.com/data/Alafasy_128kbps/004009.mp3', now()),
  (4, 10, '', '[{"id":10855,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":10856,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":10857,"position":3,"text_uthmani":"يَأْكُلُونَ","transliteration":"yakulūna","translation_bn":"খায়","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10858,"position":4,"text_uthmani":"أَمْوَٰلَ","transliteration":"amwāla","translation_bn":"মালসমূহ","root":"مول","lemma":"مَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":10859,"position":5,"text_uthmani":"ٱلْيَتَـٰمَىٰ","transliteration":"l-yatāmā","translation_bn":"ইয়াতীমদের","root":"يتم","lemma":"يَتِيم","grammar_bn":"শব্দ"},{"id":10860,"position":6,"text_uthmani":"ظُلْمًا","transliteration":"ẓul''man","translation_bn":"অন্যায়ভাবে","root":"ظلم","lemma":"ظُلْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":10861,"position":7,"text_uthmani":"إِنَّمَا","transliteration":"innamā","translation_bn":"মূলত","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":10862,"position":8,"text_uthmani":"يَأْكُلُونَ","transliteration":"yakulūna","translation_bn":"তারা খায়","root":"اكل","lemma":"أَكَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10863,"position":9,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10864,"position":10,"text_uthmani":"بُطُونِهِمْ","transliteration":"buṭūnihim","translation_bn":"তাদের পেটগুলোর","root":"بطن","lemma":"بَطْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":10865,"position":11,"text_uthmani":"نَارًۭا ۖ","transliteration":"nāran","translation_bn":"আগুন","root":"نور","lemma":"نَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":10867,"position":12,"text_uthmani":"وَسَيَصْلَوْنَ","transliteration":"wasayaṣlawna","translation_bn":"এবং জ্বলবে","root":"صلي","lemma":"يَصْلَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10868,"position":13,"text_uthmani":"سَعِيرًۭا","transliteration":"saʿīran","translation_bn":"আগুনে","root":"سعر","lemma":"سَعِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":10869,"position":14,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'inna alladhīna yakulūna amwāla l-yatāmā ẓul''man innamā yakulūna fī buṭūnihim nāran wasayaṣlawna saʿīran', 'নিশ্চয় যারা এতিমদের ধন-সম্পদ অন্যায়ভাবে গ্রাস করে, তারা মূলত নিজেদের পেটে আগুনই গ্রাস করছে এবং অচিরেই তারা প্রজ্বলিত আগুনে (সাইর) প্রবেশ করবে।', 'Indeed, those who devour the property of orphans unjustly are only consuming into their bellies fire. And they will be burned in a Blaze.', 'নিশ্চয় যারা এতিমদের ধন-সম্পদ অন্যায়ভাবে গ্রাস করে, তারা মূলত নিজেদের পেটে আগুনই গ্রাস করছে এবং অচিরেই তারা প্রজ্বলিত আগুনে (সাইর) প্রবেশ করবে।', 'Indeed, those who devour the property of orphans unjustly are only consuming into their bellies fire. And they will be burned in a Blaze.', NULL, NULL, 'নিশ্চয়ই যেসকল করাপ্টেড ইউজার নোড সম্পূর্ণ অবৈধভাবে বা বাউন্ডারি ব্রেক করে (ظُلْمًا) সেই অত্যন্ত দুর্বল ও অভিভাবকহীন এতিম নোডসমূহের মেটেরিয়াল ক্যাপিটাল বা ওয়ালেট হ্যাকিং ও গ্রাস (يَأْكُلُونَ أَمْوَالَ الْيَتَامَىٰ) করে—বাস্তবে তারা ইনফরমেশন ও থার্মোডাইনামিক থিওরির কাউন্টার-লুপে নিজেদের ইন্টারনাল স্টোরেজ বা পেটের গভীরে (فِي بُطُونِهِمْ) এক চরম ধ্বংসাত্মক প্লাজমা বা আগুনই (نَارًا) ইনপুট ও গ্রাস করছে; এবং খুব শীঘ্রই স্বয়ংক্রিয় রি-অ্যাকশনে তাদের পুরো করাপ্টেড সিস্টেমটিকে রি-রুট বা নিক্ষেপ করা হবে Sa''eer (سَعِيرًا) — তথা এক অতি-উচ্চ বিকিরণ সম্পন্ন তীব্র প্রজ্বলিত ক্লোজড ক্র্যাশ-জোনের ভেতর;', 'Verily, those predatory rogue nodes that illegally usurp the asset allocations of vulnerable orphaned terminals are devouring nothing but destructive thermal fire into their internal cores; and they shall inevitably be routed into Sa''eer—a superheated, closed-loop combustion containment field;', 'দুর্বল নোডের ওয়ালেট হ্যাকিং ও জাহান্নাম এন্ট্রপি ইগনিশন', 'Rogue Asset Usurpation & Thermodynamic Collapse in Sa''eer', NULL, 'https://everyayah.com/data/Alafasy_128kbps/004010.mp3', now()),
  (4, 11, '', '[{"id":12105,"position":1,"text_uthmani":"يُوصِيكُمُ","transliteration":"yūṣīkumu","translation_bn":"তোমাদের নির্দেশ দিচ্ছেন","root":"وصي","lemma":"أَوْصَٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12106,"position":2,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":12107,"position":3,"text_uthmani":"فِىٓ","transliteration":"fī","translation_bn":"সম্বন্ধে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12108,"position":4,"text_uthmani":"أَوْلَـٰدِكُمْ ۖ","transliteration":"awlādikum","translation_bn":"তোমাদের সন্তানদের","root":"ولد","lemma":"وَلَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":12110,"position":5,"text_uthmani":"لِلذَّكَرِ","transliteration":"lildhakari","translation_bn":"এক পুত্রের জন্য","root":"ذكر","lemma":"ذَكَر","grammar_bn":"অব্যয় (Preposition)"},{"id":12111,"position":6,"text_uthmani":"مِثْلُ","transliteration":"mith''lu","translation_bn":"বরাবর","root":"مثل","lemma":"مِثْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":12112,"position":7,"text_uthmani":"حَظِّ","transliteration":"ḥaẓẓi","translation_bn":"অংশ","root":"حظظ","lemma":"حَظّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":12113,"position":8,"text_uthmani":"ٱلْأُنثَيَيْنِ ۚ","transliteration":"l-unthayayni","translation_bn":"দুই কন্যার","root":"انث","lemma":"أُنثَيَيْن","grammar_bn":"শব্দ"},{"id":12115,"position":9,"text_uthmani":"فَإِن","transliteration":"fa-in","translation_bn":"যদি অতএব","root":"—","lemma":"إِن\r","grammar_bn":"শব্দ"},{"id":12116,"position":10,"text_uthmani":"كُنَّ","transliteration":"kunna","translation_bn":"তারা হয়","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12117,"position":11,"text_uthmani":"نِسَآءًۭ","transliteration":"nisāan","translation_bn":"কন্যা","root":"نسو","lemma":"نِسَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":12118,"position":12,"text_uthmani":"فَوْقَ","transliteration":"fawqa","translation_bn":"উর্ধ্বে","root":