  (5, 15, '', '[{"id":17546,"position":1,"text_uthmani":"يَـٰٓأَهْلَ","transliteration":"yāahla","translation_bn":"হে অধিকারীরা","root":"اهل","lemma":"أَهْل","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":17547,"position":2,"text_uthmani":"ٱلْكِتَـٰبِ","transliteration":"l-kitābi","translation_bn":"কিতাবের","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":17548,"position":3,"text_uthmani":"قَدْ","transliteration":"qad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":17549,"position":4,"text_uthmani":"جَآءَكُمْ","transliteration":"jāakum","translation_bn":"কাছে এসেছে তোমাদের","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17550,"position":5,"text_uthmani":"رَسُولُنَا","transliteration":"rasūlunā","translation_bn":"আমাদের রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":17551,"position":6,"text_uthmani":"يُبَيِّنُ","transliteration":"yubayyinu","translation_bn":"সে প্রকাশ করে","root":"بين","lemma":"بَيَّنُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17552,"position":7,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"কাছে তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":17553,"position":8,"text_uthmani":"كَثِيرًۭا","transliteration":"kathīran","translation_bn":"অনেক (কথা)","root":"كثر","lemma":"كَثِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":17554,"position":9,"text_uthmani":"مِّمَّا","transliteration":"mimmā","translation_bn":"(তা) হতে যা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17555,"position":10,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা ছিলে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17556,"position":11,"text_uthmani":"تُخْفُونَ","transliteration":"tukh''fūna","translation_bn":"তোমরা গোপন করতে","root":"خفي","lemma":"أُخْفِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17557,"position":12,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17558,"position":13,"text_uthmani":"ٱلْكِتَـٰبِ","transliteration":"l-kitābi","translation_bn":"কিতাবের","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":17559,"position":14,"text_uthmani":"وَيَعْفُوا۟","transliteration":"wayaʿfū","translation_bn":"ও সে উপেক্ষা করে","root":"عفو","lemma":"عَفَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17560,"position":15,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17561,"position":16,"text_uthmani":"كَثِيرٍۢ ۚ","transliteration":"kathīrin","translation_bn":"অনেক কিছু","root":"كثر","lemma":"كَثِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":17563,"position":17,"text_uthmani":"قَدْ","transliteration":"qad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":17564,"position":18,"text_uthmani":"جَآءَكُم","transliteration":"jāakum","translation_bn":"কাছে এসেছে তোমাদের","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17565,"position":19,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"পক্ষ হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17566,"position":20,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":17567,"position":21,"text_uthmani":"نُورٌۭ","transliteration":"nūrun","translation_bn":"আলো","root":"نور","lemma":"نُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":17568,"position":22,"text_uthmani":"وَكِتَـٰبٌۭ","transliteration":"wakitābun","translation_bn":"ও কিতাব","root":"كتب","lemma":"كِتَٰب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17569,"position":23,"text_uthmani":"مُّبِينٌۭ","transliteration":"mubīnun","translation_bn":"উজ্জ্বল","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":17570,"position":24,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'yāahla l-kitābi qad jāakum rasūlunā yubayyinu lakum kathīran mimmā kuntum tukh''fūna mina l-kitābi wayaʿfū ʿan kathīrin qad jāakum mina l-lahi nūrun wakitābun mubīnun', 'হে কিতাবধারীগণ! তোমাদের কাছে আমার রসূল এসে গেছে, সে তোমাদেরকে অনেক বিষয় বর্ণনা করে কিতাব থেকে যা তোমরা গোপন করতে আর অনেক বিষয় উপেক্ষা করে। তোমাদের নিকট আল্লাহর পক্ষ হতে জ্যোতি ও স্পষ্ট কিতাব এসেছে।', 'O People of the Scripture, there has come to you Our Messenger making clear to you much of what you used to conceal of the Scripture and overlooking much. There has come to you from Allah a light and a clear Book.', 'হে কিতাবধারীগণ! তোমাদের কাছে আমার রসূল এসে গেছে, সে তোমাদেরকে অনেক বিষয় বর্ণনা করে কিতাব থেকে যা তোমরা গোপন করতে আর অনেক বিষয় উপেক্ষা করে। তোমাদের নিকট আল্লাহর পক্ষ হতে জ্যোতি ও স্পষ্ট কিতাব এসেছে।', 'O People of the Scripture, there has come to you Our Messenger making clear to you much of what you used to conceal of the Scripture and overlooking much. There has come to you from Allah a light and a clear Book.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/005015.mp3', now()),
  (5, 16, '', '[{"id":18587,"position":1,"text_uthmani":"يَهْدِى","transliteration":"yahdī","translation_bn":"পরিচালিত করেন","root":"هدي","lemma":"هَدَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":18588,"position":2,"text_uthmani":"بِهِ","transliteration":"bihi","translation_bn":"দিয়ে তা","root":"—","lemma":"بِهِ","grammar_bn":"অব্যয় (Preposition)"},{"id":18589,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":18590,"position":4,"text_uthmani":"مَنِ","transliteration":"mani","translation_bn":"(তাকে) যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":18591,"position":5,"text_uthmani":"ٱتَّبَعَ","transliteration":"ittabaʿa","translation_bn":"অনুসরণ করে","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18592,"position":6,"text_uthmani":"رِضْوَٰنَهُۥ","transliteration":"riḍ''wānahu","translation_bn":"সন্তুষ্টির তাঁর","root":"رضو","lemma":"رِضْوَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":18593,"position":7,"text_uthmani":"سُبُلَ","transliteration":"subula","translation_bn":"পথে","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":18594,"position":8,"text_uthmani":"ٱلسَّلَـٰمِ","transliteration":"l-salāmi","translation_bn":"শান্তির","root":"سلم","lemma":"سَلَٰم","grammar_bn":"শব্দ"},{"id":18595,"position":9,"text_uthmani":"وَيُخْرِجُهُم","transliteration":"wayukh''rijuhum","translation_bn":"ও বের করেন তাদের","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18596,"position":10,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18597,"position":11,"text_uthmani":"ٱلظُّلُمَـٰتِ","transliteration":"l-ẓulumāti","translation_bn":"অন্ধকারসমূহ","root":"ظلم","lemma":"ظُلُمَٰت","grammar_bn":"শব্দ"},{"id":18598,"position":12,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18599,"position":13,"text_uthmani":"ٱلنُّورِ","transliteration":"l-nūri","translation_bn":"আলোর","root":"نور","lemma":"نُور","grammar_bn":"শব্দ"},{"id":18600,"position":14,"text_uthmani":"بِإِذْنِهِۦ","transliteration":"bi-idh''nihi","translation_bn":"অনুমতিক্রমে তাঁর","root":"اذن","lemma":"إِذْن","grammar_bn":"অব্যয় (Preposition)"},{"id":18601,"position":15,"text_uthmani":"وَيَهْدِيهِمْ","transliteration":"wayahdīhim","translation_bn":"এবং পরিচালিত করেন তাদের","root":"هدي","lemma":"هَدَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18602,"position":16,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18603,"position":17,"text_uthmani":"صِرَٰطٍۢ","transliteration":"ṣirāṭin","translation_bn":"পথের","root":"صرط","lemma":"صِرَٰط","grammar_bn":"বিশেষ্য (Noun)"},{"id":18604,"position":18,"text_uthmani":"مُّسْتَقِيمٍۢ","transliteration":"mus''taqīmin","translation_bn":"সরল সঠিক","root":"قوم","lemma":"مُّسْتَقِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":18605,"position":19,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'yahdī bihi l-lahu mani ittabaʿa riḍ''wānahu subula l-salāmi wayukh''rijuhum mina l-ẓulumāti ilā l-nūri bi-idh''nihi wayahdīhim ilā ṣirāṭin mus''taqīmin', 'আল্লাহ তদ্বারা তাদেরকে শান্তি ও নিরাপত্তার পথে পরিচালিত করেন যারা তাঁর সন্তুষ্টি অনুসন্ধান করে এবং নিজ অনুমতিক্রমে তিনি তাদেরকে অন্ধকার হতে বের করে আলোর দিকে নিয়ে আসেন আর তাদেরকে সরল সঠিক পথে পরিচালিত করেন।', 'By which Allah guides those who pursue His pleasure to the ways of peace and brings them out from darknesses into the light, by His permission, and guides them to a straight path.', 'আল্লাহ তদ্বারা তাদেরকে শান্তি ও নিরাপত্তার পথে পরিচালিত করেন যারা তাঁর সন্তুষ্টি অনুসন্ধান করে এবং নিজ অনুমতিক্রমে তিনি তাদেরকে অন্ধকার হতে বের করে আলোর দিকে নিয়ে আসেন আর তাদেরকে সরল সঠিক পথে পরিচালিত করেন।', 'By which Allah guides those who pursue His pleasure to the ways of peace and brings them out from darknesses into the light, by His permission, and guides them to a straight path.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/005016.mp3', now()),
  (5, 17, '', '[{"id":19603,"position":1,"text_uthmani":"لَّقَدْ","transliteration":"laqad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":19604,"position":2,"text_uthmani":"كَفَرَ","transliteration":"kafara","translation_bn":"অবিশ্বাস করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19605,"position":3,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":19606,"position":4,"text_uthmani":"قَالُوٓا۟","transliteration":"qālū","translation_bn":"বলেছে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19607,"position":5,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"\"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":19608,"position":6,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19609,"position":7,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনি","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":19610,"position":8,"text_uthmani":"ٱلْمَسِيحُ","transliteration":"l-masīḥu","translation_bn":"মসীহই","root":"—","lemma":"مَسِيح","grammar_bn":"শব্দ"},{"id":19611,"position":9,"text_uthmani":"ٱبْنُ","transliteration":"ub''nu","translation_bn":"পুত্র","root":"بني","lemma":"ٱبْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":19612,"position":10,"text_uthmani":"مَرْيَمَ ۚ","transliteration":"maryama","translation_bn":"মারইয়ামের\"","root":"—","lemma":"مَرْيَم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19614,"position":11,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19615,"position":12,"text_uthmani":"فَمَن","transliteration":"faman","translation_bn":"\"অত:পর কে","root":"—","lemma":"مَن\r","grammar_bn":"সম্পূরক পদ (Supplemental)"},{"id":19616,"position":13,"text_uthmani":"يَمْلِكُ","transliteration":"yamliku","translation_bn":"ক্ষমতা রাখে (বাঁচাতে)","root":"ملك","lemma":"مَلَكَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19617,"position":14,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19618,"position":15,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19619,"position":16,"text_uthmani":"شَيْـًٔا","transliteration":"shayan","translation_bn":"কিছু মাত্র","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":19620,"position":17,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":19621,"position":18,"text_uthmani":"أَرَادَ","transliteration":"arāda","translation_bn":"তিনি চান","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19622,"position":19,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":19623,"position":20,"text_uthmani":"يُهْلِكَ","transliteration":"yuh''lika","translation_bn":"ধ্বংস করতে","root":"هلك","lemma":"أَهْلَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19624,"position":21,"text_uthmani":"ٱلْمَسِيحَ","transliteration":"l-masīḥa","translation_bn":"মসীহকে","root":"—","lemma":"مَسِيح","grammar_bn":"শব্দ"},{"id":19625,"position":22,"text_uthmani":"ٱبْنَ","transliteration":"ib''na","translation_bn":"পুত্র","root":"بني","lemma":"ٱبْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":19626,"position":23,"text_uthmani":"مَرْيَمَ","transliteration":"maryama","translation_bn":"মারইয়ামের","root":"—","lemma":"مَرْيَم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19627,"position":24,"text_uthmani":"وَأُمَّهُۥ","transliteration":"wa-ummahu","translation_bn":"ও মাকে তার","root":"امم","lemma":"أُمّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19628,"position":25,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"ও যা কিছু","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19629,"position":26,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19630,"position":27,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":19631,"position":28,"text_uthmani":"جَمِيعًۭا ۗ","transliteration":"jamīʿan","translation_bn":"সমস্তই\"","root":"جمع","lemma":"جَمِيع","grammar_bn":"বিশেষ্য (Noun)"},{"id":19633,"position":29,"text_uthmani":"وَلِلَّهِ","transliteration":"walillahi","translation_bn":"এবং জন্যে আল্লাহরই","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":19634,"position":30,"text_uthmani":"مُلْكُ","transliteration":"mul''ku","translation_bn":"সার্বভৌমত্ব","root":"ملك","lemma":"مُلْك","grammar_bn":"বিশেষ্য (Noun)"},{"id":19635,"position":31,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশসমূহের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":19636,"position":32,"text_uthmani":"وَٱلْأَرْضِ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19637,"position":33,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"ও যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19638,"position":34,"text_uthmani":"بَيْنَهُمَا ۚ","transliteration":"baynahumā","translation_bn":"উভয়ের মাঝে (আছে)","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":19640,"position":35,"text_uthmani":"يَخْلُقُ","transliteration":"yakhluqu","translation_bn":"তিনি সৃষ্টি করেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19641,"position":36,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":19642,"position":37,"text_uthmani":"يَشَآءُ ۚ","transliteration":"yashāu","translation_bn":"তিনি ইচ্ছে করেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19644,"position":38,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":19645,"position":39,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19646,"position":40,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"সব","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":19647,"position":41,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"কিছুুর","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":19648,"position":42,"text_uthmani":"قَدِيرٌۭ","transliteration":"qadīrun","translation_bn":"শক্তিশালী","root":"قدر","lemma":"قَدِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":19649,"position":43,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'laqad kafara alladhīna qālū inna l-laha huwa l-masīḥu ub''nu maryama qul faman yamliku mina l-lahi shayan in arāda an yuh''lika l-masīḥa ib''na maryama wa-ummahu waman fī l-arḍi jamīʿan walillahi mul''ku l-samāwāti wal-arḍi wamā baynahumā yakhluqu mā yashāu wal-lahu ʿalā kulli shayin qadīrun', 'তারা কুফরী করেছে যারা বলে মাসীহ্ ইবনে মারইয়ামই আল্লাহ। বল, মাসীহ ইবনে মারইয়াম, আর তার মা এবং পৃথিবীতে যারা আছে সকলকে ধ্বংস করতে চাইলে আল্লাহর বিরুদ্ধে কারো এতটুকু ক্ষমতা আছে কি? আসমানসমূহে আর পৃথিবীতে ও এদের মধ্যে যা কিছু আছে সব আল্লাহরই মালিকানাধীন। তিনি যা ইচ্ছে সৃষ্টি করেন। আল্লাহ্ সকল বিষয়ে সর্বশক্তিমান।', 'They have certainly disbelieved who say that Allah is Christ, the son of Mary. Say, "Then who could prevent Allah at all if He had intended to destroy Christ, the son of Mary, or his mother or everyone on the earth?" And to Allah belongs the dominion of the heavens and the earth and whatever is between them. He creates what He wills, and Allah is over all things competent.', 'তারা কুফরী করেছে যারা বলে মাসীহ্ ইবনে মারইয়ামই আল্লাহ। বল, মাসীহ ইবনে মারইয়াম, আর তার মা এবং পৃথিবীতে যারা আছে সকলকে ধ্বংস করতে চাইলে আল্লাহর বিরুদ্ধে কারো এতটুকু ক্ষমতা আছে কি? আসমানসমূহে আর পৃথিবীতে ও এদের মধ্যে যা কিছু আছে সব আল্লাহরই মালিকানাধীন। তিনি যা ইচ্ছে সৃষ্টি করেন। আল্লাহ্ সকল বিষয়ে সর্বশক্তিমান।', 'They have certainly disbelieved who say that Allah is Christ, the son of Mary. Say, "Then who could prevent Allah at all if He had intended to destroy Christ, the son of Mary, or his mother or everyone on the earth?" And to Allah belongs the dominion of the heavens and the earth and whatever is between them. He creates what He wills, and Allah is over all things competent.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/005017.mp3', now()),
  (5, 18, '', '[{"id":20702,"position":1,"text_uthmani":"وَقَالَتِ","transliteration":"waqālati","translation_bn":"এবং বলে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20703,"position":2,"text_uthmani":"ٱلْيَهُودُ","transliteration":"l-yahūdu","translation_bn":"ইয়াহুদীরা","root":"—","lemma":"يَهُودِيّ","grammar_bn":"শব্দ"},{"id":20704,"position":3,"text_uthmani":"وَٱلنَّصَـٰرَىٰ","transliteration":"wal-naṣārā","translation_bn":"ও খ্রিষ্টানরা","root":"نصر","lemma":"نَصْرَانِيّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20705,"position":4,"text_uthmani":"نَحْنُ","transliteration":"naḥnu","translation_bn":"\"আমরা","root":"—","lemma":"نَحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":20706,"position":5,"text_uthmani":"أَبْنَـٰٓؤُا۟","transliteration":"abnāu","translation_bn":"সন্তানগণ","root":"بني","lemma":"ٱبْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":20707,"position":6,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":20708,"position":7,"text_uthmani":"وَأَحِبَّـٰٓؤُهُۥ ۚ","transliteration":"wa-aḥibbāuhu","translation_bn":"ও প্রিয় পাত্র তাঁর\"","root":"حبب","lemma":"أَحِبَّٰ^ؤ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20710,"position":8,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20711,"position":9,"text_uthmani":"فَلِمَ","transliteration":"falima","translation_bn":"\"তবে কেন (আল্লাহ)","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":20712,"position":10,"text_uthmani":"يُعَذِّبُكُم","transliteration":"yuʿadhibukum","translation_bn":"শাস্তি দিবেন তোমাদের","root":"عذب","lemma":"عَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20713,"position":11,"text_uthmani":"بِذُنُوبِكُم ۖ","transliteration":"bidhunūbikum","translation_bn":"পাপগুলোর কারণে তোমাদের\"","root":"ذنب","lemma":"ذَنب","grammar_bn":"অব্যয় (Preposition)"},{"id":20715,"position":12,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"অসম্পূর্ণ (Inceptive)"},{"id":20716,"position":13,"text_uthmani":"أَنتُم","transliteration":"antum","translation_bn":"তোমরাও","root":"—","lemma":"أَنتُم","grammar_bn":"সর্বনাম (Pronoun)"},{"id":20717,"position":14,"text_uthmani":"بَشَرٌۭ","transliteration":"basharun","translation_bn":"মানুষ","root":"بشر","lemma":"بَشَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":20718,"position":15,"text_uthmani":"مِّمَّنْ","transliteration":"mimman","translation_bn":"অন্তর্ভুক্ত তাদের যাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20719,"position":16,"text_uthmani":"خَلَقَ ۚ","transliteration":"khalaqa","translation_bn":"তিনি সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20721,"position":17,"text_uthmani":"يَغْفِرُ","transliteration":"yaghfiru","translation_bn":"ক্ষমা করেন","root":"غفر","lemma":"غَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20722,"position":18,"text_uthmani":"لِمَن","transliteration":"liman","translation_bn":"যাকে","root":"—","lemma":"مَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20723,"position":19,"text_uthmani":"يَشَآءُ","transliteration":"yashāu","translation_bn":"তিনি ইচ্ছে করেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20724,"position":20,"text_uthmani":"وَيُعَذِّبُ","transliteration":"wayuʿadhibu","translation_bn":"ও তিনি শাস্তি দেন","root":"عذب","lemma":"عَذَّبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20725,"position":21,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যাকে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":20726,"position":22,"text_uthmani":"يَشَآءُ ۚ","transliteration":"yashāu","translation_bn":"তিনি ইচ্ছে করেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20728,"position":23,"text_uthmani":"وَلِلَّهِ","transliteration":"walillahi","translation_bn":"এবং জন্যে আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":20729,"position":24,"text_uthmani":"مُلْكُ","transliteration":"mul''ku","translation_bn":"সার্বভৌমত্ব","root":"ملك","lemma":"مُلْك","grammar_bn":"বিশেষ্য (Noun)"},{"id":20730,"position":25,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশসমূহের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":20731,"position":26,"text_uthmani":"وَٱلْأَرْضِ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20732,"position":27,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20733,"position":28,"text_uthmani":"بَيْنَهُمَا ۖ","transliteration":"baynahumā","translation_bn":"উভয়ের মাঝে (আছে)","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":20735,"position":29,"text_uthmani":"وَإِلَيْهِ","transliteration":"wa-ilayhi","translation_bn":"এবং দিকে তাঁরই","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20736,"position":30,"text_uthmani":"ٱلْمَصِيرُ","transliteration":"l-maṣīru","translation_bn":"প্রত্যাবর্তন হয় (সব কিছুরই)","root":"صير","lemma":"مَصِير","grammar_bn":"শব্দ"},{"id":20737,"position":31,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'waqālati l-yahūdu wal-naṣārā naḥnu abnāu l-lahi wa-aḥibbāuhu qul falima yuʿadhibukum bidhunūbikum bal antum basharun mimman khalaqa yaghfiru liman yashāu wayuʿadhibu man yashāu walillahi mul''ku l-samāwāti wal-arḍi wamā baynahumā wa-ilayhi l-maṣīru', 'ইয়াহূদী ও নাসারারা বলে, আমরা আল্লাহর পুত্র ও তাঁর প্রিয়পাত্র। বল, তাহলে তোমাদের পাপের জন্য আল্লাহ তোমাদেরকে শাস্তি দেন কেন? বরং তিনি যাদের সৃষ্টি করেছেন তোমরা তাদের অন্তর্গত মানুষ, তিনি যাকে ইচ্ছে ক্ষমা করেন, যাকে ইচ্ছে শাস্তি দেন, আকাশসমূহ ও পৃথিবী আর এদের মধ্যে যা আছে সবকিছুর সার্বভৌমত্ব আল্লাহরই জন্য, আর প্রত্যাবর্তন তাঁরই পানে।', 'But the Jews and the Christians say, "We are the children of Allah and His beloved." Say, "Then why does He punish you for your sins?" Rather, you are human beings from among those He has created. He forgives whom He wills, and He punishes whom He wills. And to Allah belongs the dominion of the heavens and the earth and whatever is between them, and to Him is the [final] destination.', 'ইয়াহূদী ও নাসারারা বলে, আমরা আল্লাহর পুত্র ও তাঁর প্রিয়পাত্র। বল, তাহলে তোমাদের পাপের জন্য আল্লাহ তোমাদেরকে শাস্তি দেন কেন? বরং তিনি যাদের সৃষ্টি করেছেন তোমরা তাদের অন্তর্গত মানুষ, তিনি যাকে ইচ্ছে ক্ষমা করেন, যাকে ইচ্ছে শাস্তি দেন, আকাশসমূহ ও পৃথিবী আর এদের মধ্যে যা আছে সবকিছুর সার্বভৌমত্ব আল্লাহরই জন্য, আর প্রত্যাবর্তন তাঁরই পানে।', 'But the Jews and the Christians say, "We are the children of Allah and His beloved." Say, "Then why does He punish you for your sins?" Rather, you are human beings from among those He has created. He forgives whom He wills, and He punishes whom He wills. And to Allah belongs the dominion of the heavens and the earth and whatever is between them, and to Him is the [final] destination.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/005018.mp3', now()),
  (5, 19, '', '[{"id":21772,"position":1,"text_uthmani":"يَـٰٓأَهْلَ","transliteration":"yāahla","translation_bn":"হে অধিকারীরা","root":"اهل","lemma":"أَهْل","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":21773,"position":2,"text_uthmani":"ٱلْكِتَـٰبِ","transliteration":"l-kitābi","translation_bn":"কিতাবের","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":21774,"position":3,"text_uthmani":"قَدْ","transliteration":"qad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":21775,"position":4,"text_uthmani":"جَآءَكُمْ","transliteration":"jāakum","translation_bn":"কাছে এসেছে তোমাদের","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21776,"position":5,"text_uthmani":"رَسُولُنَا","transliteration":"rasūlunā","translation_bn":"রাসূল আমাদের","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":21777,"position":6,"text_uthmani":"يُبَيِّنُ","transliteration":"yubayyinu","translation_bn":"স্পষ্ট বর্ণনা করেন","root":"بين","lemma":"بَيَّنُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21778,"position":7,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":21779,"position":8,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"পরে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21780,"position":9,"text_uthmani":"فَتْرَةٍۢ","transliteration":"fatratin","translation_bn":"বিরতির","root":"فتر","lemma":"فَتْرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":21781,"position":10,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"ধারায়","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21782,"position":11,"text_uthmani":"ٱلرُّسُلِ","transliteration":"l-rusuli","translation_bn":"রাসূলদের (আগমনের)","root":"رسل","lemma":"رَسُول","grammar_bn":"শব্দ"},{"id":21783,"position":12,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যেন (না)","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":21784,"position":13,"text_uthmani":"تَقُولُوا۟","transliteration":"taqūlū","translation_bn":"তোমরা বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21785,"position":14,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"\"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":21786,"position":15,"text_uthmani":"جَآءَنَا","transliteration":"jāanā","translation_bn":"কাছে এসেছে আমাদের","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21787,"position":16,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21788,"position":17,"text_uthmani":"بَشِيرٍۢ","transliteration":"bashīrin","translation_bn":"সুসংবাদদাতা","root":"بشر","lemma":"بَشِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":21789,"position":18,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21790,"position":19,"text_uthmani":"نَذِيرٍۢ ۖ","transliteration":"nadhīrin","translation_bn":"কোনো সতর্ককারী\"","root":"نذر","lemma":"نَذِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":21792,"position":20,"text_uthmani":"فَقَدْ","transliteration":"faqad","translation_bn":"তাই নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"শব্দ"},{"id":21793,"position":21,"text_uthmani":"جَآءَكُم","transliteration":"jāakum","translation_bn":"কাছে এসেছে তোমাদের","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21794,"position":22,"text_uthmani":"بَشِيرٌۭ","transliteration":"bashīrun","translation_bn":"সুসংবাদদাতা","root":"بشر","lemma":"بَشِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":21795,"position":23,"text_uthmani":"وَنَذِيرٌۭ ۗ","transliteration":"wanadhīrun","translation_bn":"ও সতর্ককারী","root":"نذر","lemma":"نَذِير","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21797,"position":24,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":21798,"position":25,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21799,"position":26,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"সব","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":21800,"position":27,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"কিছুর","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":21801,"position":28,"text_uthmani":"قَدِيرٌۭ","transliteration":"qadīrun","translation_bn":"সর্বশক্তিমান","root":"قدر","lemma":"قَدِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":21802,"position":29,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'yāahla l-kitābi qad jāakum rasūlunā yubayyinu lakum ʿalā fatratin mina l-rusuli an taqūlū mā jāanā min bashīrin walā nadhīrin faqad jāakum bashīrun wanadhīrun wal-lahu ʿalā kulli shayin qadīrun', 'ওহে আহলে কিতাব! রসূল প্রেরণে বিরতির পর তোমাদের কাছে আমার রসূল এসে স্পষ্টভাবে তোমাদের নিকট বর্ণনা করে দিচ্ছে যাতে তোমরা বলতে না পার যে, আমাদের কাছে কোন সুসংবাদদাতা ও সাবধানকারী আগমন করেনি। এখন তাই সুসংবাদদাতা ও সাবধানকারী এসে গেছে। আর আল্লাহ হচ্ছেন সকল বিষয়ে সর্বশক্তিমান।', 'O People of the Scripture, there has come to you Our Messenger to make clear to you [the religion] after a period [of suspension] of messengers, lest you say, "There came not to us any bringer of good tidings or a warner." But there has come to you a bringer of good tidings and a warner. And Allah is over all things competent.', 'ওহে আহলে কিতাব! রসূল প্রেরণে বিরতির পর তোমাদের কাছে আমার রসূল এসে স্পষ্টভাবে তোমাদের নিকট বর্ণনা করে দিচ্ছে যাতে তোমরা বলতে না পার যে, আমাদের কাছে কোন সুসংবাদদাতা ও সাবধানকারী আগমন করেনি। এখন তাই সুসংবাদদাতা ও সাবধানকারী এসে গেছে। আর আল্লাহ হচ্ছেন সকল বিষয়ে সর্বশক্তিমান।', 'O People of the Scripture, there has come to you Our Messenger to make clear to you [the religion] after a period [of suspension] of messengers, lest you say, "There came not to us any bringer of good tidings or a warner." But there has come to you a bringer of good tidings and a warner. And Allah is over all things competent.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/005019.mp3', now()),
  (5, 20, '', '[{"id":22910,"position":1,"text_uthmani":"وَإِذْ","transliteration":"wa-idh","translation_bn":"এবং (স্মরণ করো) যখন","root":"—","lemma":"إِذ\r","grammar_bn":"শব্দ"},{"id":22911,"position":2,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22912,"position":3,"text_uthmani":"مُوسَىٰ","transliteration":"mūsā","translation_bn":"মূসা","root":"—","lemma":"مُوسَىٰ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":22913,"position":4,"text_uthmani":"لِقَوْمِهِۦ","transliteration":"liqawmihi","translation_bn":"উদ্দেশ্যে তার জাতির","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":22914,"position":5,"text_uthmani":"يَـٰقَوْمِ","transliteration":"yāqawmi","translation_bn":"\"হে আমার জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":22915,"position":6,"text_uthmani":"ٱذْكُرُوا۟","transliteration":"udh''kurū","translation_bn":"তোমরা স্মরণ করো","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22916,"position":7,"text_uthmani":"نِعْمَةَ","transliteration":"niʿ''mata","translation_bn":"অনুগ্রহের","root":"نعم","lemma":"نِعْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":22917,"position":8,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":22918,"position":9,"text_uthmani":"عَلَيْكُمْ","transliteration":"ʿalaykum","translation_bn":"উপর তোমাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22919,"position":10,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":22920,"position":11,"text_uthmani":"جَعَلَ","transliteration":"jaʿala","translation_bn":"পাঠিয়েছিলেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22921,"position":12,"text_uthmani":"فِيكُمْ","transliteration":"fīkum","translation_bn":"মধ্যে তোমাদের","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22922,"position":13,"text_uthmani":"أَنۢبِيَآءَ","transliteration":"anbiyāa","translation_bn":"নাবীদেরকে","root":"نبا","lemma":"نَّبِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":22923,"position":14,"text_uthmani":"وَجَعَلَكُم","transliteration":"wajaʿalakum","translation_bn":"ও করেছিলেন তোমাদের","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22924,"position":15,"text_uthmani":"مُّلُوكًۭا","transliteration":"mulūkan","translation_bn":"রাজ্যের অধিপতি","root":"ملك","lemma":"مَلِك","grammar_bn":"বিশেষ্য (Noun)"},{"id":22925,"position":16,"text_uthmani":"وَءَاتَىٰكُم","transliteration":"waātākum","translation_bn":"ও দিয়েছিলেন তোমাদের(এমন অনেক কিছু)","root":"اتي","lemma":"ا^تَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22926,"position":17,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":22927,"position":18,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"নি","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":22928,"position":19,"text_uthmani":"يُؤْتِ","transliteration":"yu''ti","translation_bn":"দেন","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":22929,"position":20,"text_uthmani":"أَحَدًۭا","transliteration":"aḥadan","translation_bn":"কাউকে","root":"احد","lemma":"أَحَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":22930,"position":21,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"মধ্যে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22931,"position":22,"text_uthmani":"ٱلْعَـٰلَمِينَ","transliteration":"l-ʿālamīna","translation_bn":"বিশ্ব জগতের","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"শব্দ"},{"id":22932,"position":23,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idh qāla mūsā liqawmihi yāqawmi udh''kurū niʿ''mata l-lahi ʿalaykum idh jaʿala fīkum anbiyāa wajaʿalakum mulūkan waātākum mā lam yu''ti aḥadan mina l-ʿālamīna', 'স্মরণ কর, যখন মূসা তার সম্প্রদায়কে বলেছিল, হে আমার সম্প্রদায়! তোমরা তোমাদের প্রতি আল্লাহর নি‘য়ামাত স্মরণ কর যে, তিনি তোমাদের মধ্যে নাবী করেছেন এবং তোমাদেরকে বাদশাহ করেছেন আর তোমাদেরকে তিনি এমন কিছু দিয়েছেন যা বিশ্বভুবনে অন্য কাউকে দেননি।', 'And [mention, O Muhammad], when Moses said to his people, "O my people, remember the favor of Allah upon you when He appointed among you prophets and made you possessors and gave you that which He had not given anyone among the worlds.', 'স্মরণ কর, যখন মূসা তার সম্প্রদায়কে বলেছিল, হে আমার সম্প্রদায়! তোমরা তোমাদের প্রতি আল্লাহর নি‘য়ামাত স্মরণ কর যে, তিনি তোমাদের মধ্যে নাবী করেছেন এবং তোমাদেরকে বাদশাহ করেছেন আর তোমাদেরকে তিনি এমন কিছু দিয়েছেন যা বিশ্বভুবনে অন্য কাউকে দেননি।', 'And [mention, O Muhammad], when Moses said to his people, "O my people, remember the favor of Allah upon you when He appointed among you prophets and made you possessors and gave you that which He had not given anyone among the worlds.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/005020.mp3', now()),
  (5, 21, '', '[{"id":24130,"position":1,"text_uthmani":"يَـٰقَوْمِ","transliteration":"yāqawmi","translation_bn":"\"হে আমার জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":24131,"position":2,"text_uthmani":"ٱدْخُلُوا۟","transliteration":"ud''khulū","translation_bn":"তোমরা প্রবেশ করো","root":"دخل","lemma":"دَخَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24132,"position":3,"text_uthmani":"ٱلْأَرْضَ","transliteration":"l-arḍa","translation_bn":"জমিনে","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":24133,"position":4,"text_uthmani":"ٱلْمُقَدَّسَةَ","transliteration":"l-muqadasata","translation_bn":"পবিত্র (ফিলিস্তিনের)","root":"قدس","lemma":"مُقَدَّسَة","grammar_bn":"শব্দ"},{"id":24134,"position":5,"text_uthmani":"ٱلَّتِى","transliteration":"allatī","translation_bn":"যা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":24135,"position":6,"text_uthmani":"كَتَبَ","transliteration":"kataba","translation_bn":"নির্দিষ্ট করে দিয়েছেন","root":"كتب","lemma":"كَتَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24136,"position":7,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":24137,"position":8,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":24138,"position":9,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":24139,"position":10,"text_uthmani":"تَرْتَدُّوا۟","transliteration":"tartaddū","translation_bn":"তোমরা ফিরো","root":"ردد","lemma":"ٱرْتَدَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24140,"position":11,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"দিকে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24141,"position":12,"text_uthmani":"أَدْبَارِكُمْ","transliteration":"adbārikum","translation_bn":"পিছনের তোমাদের","root":"دبر","lemma":"دُبُر","grammar_bn":"বিশেষ্য (Noun)"},{"id":24142,"position":13,"text_uthmani":"فَتَنقَلِبُوا۟","transliteration":"fatanqalibū","translation_bn":"তাহ''লে তোমরা প্রত্যাবর্তন করবে","root":"قلب","lemma":"ٱنقَلَبَ","grammar_bn":"কারণবাচক (Cause)"},{"id":24143,"position":14,"text_uthmani":"خَـٰسِرِينَ","transliteration":"khāsirīna","translation_bn":"ক্ষতিগ্রস্ত হয়ে\"","root":"خسر","lemma":"خَٰسِرِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":24144,"position":15,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'yāqawmi ud''khulū l-arḍa l-muqadasata allatī kataba l-lahu lakum walā tartaddū ʿalā adbārikum fatanqalibū khāsirīna', 'হে আমার সম্প্রদায়! তোমাদের জন্য যে পবিত্র ভূমি আল্লাহ নির্দিষ্ট করেছেন তাতে প্রবেশ কর আর পশ্চাতে ঘুরে দাঁড়িও না, তা করলে ধ্বংসে পতিত হবে।', 'O my people, enter the Holy Land which Allah has assigned to you and do not turn back [from fighting in Allah ''s cause] and [thus] become losers."', 'হে আমার সম্প্রদায়! তোমাদের জন্য যে পবিত্র ভূমি আল্লাহ নির্দিষ্ট করেছেন তাতে প্রবেশ কর আর পশ্চাতে ঘুরে দাঁড়িও না, তা করলে ধ্বংসে পতিত হবে।', 'O my people, enter the Holy Land which Allah has assigned to you and do not turn back [from fighting in Allah ''s cause] and [thus] become losers."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/005021.mp3', now()),
  (5, 22, '', '[{"id":24976,"position":1,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24977,"position":2,"text_uthmani":"يَـٰمُوسَىٰٓ","transliteration":"yāmūsā","translation_bn":"\"হে মূসা","root":"—","lemma":"مُوسَىٰ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":24978,"position":3,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":24979,"position":4,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"আছে সেখানে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24980,"position":5,"text_uthmani":"قَوْمًۭا","transliteration":"qawman","translation_bn":"জাতি","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":24981,"position":6,"text_uthmani":"جَبَّارِينَ","transliteration":"jabbārīna","translation_bn":"দুর্দান্ত শক্তিধর","root":"جبر","lemma":"جَبَّار","grammar_bn":"বিশেষণ (Adjective)"},{"id":24982,"position":7,"text_uthmani":"وَإِنَّا","transliteration":"wa-innā","translation_bn":"এবং নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24983,"position":8,"text_uthmani":"لَن","transliteration":"lan","translation_bn":"কখনও না","root":"—","lemma":"لَن\r","grammar_bn":"না-বোধক (Negative)"},{"id":24984,"position":9,"text_uthmani":"نَّدْخُلَهَا","transliteration":"nadkhulahā","translation_bn":"প্রবেশ করবো সেখানে","root":"دخل","lemma":"دَخَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24985,"position":10,"text_uthmani":"حَتَّىٰ","transliteration":"ḥattā","translation_bn":"যতক্ষণ না","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24986,"position":11,"text_uthmani":"يَخْرُجُوا۟","transliteration":"yakhrujū","translation_bn":"তারা বের হবে","root":"خرج","lemma":"خَرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24987,"position":12,"text_uthmani":"مِنْهَا","transliteration":"min''hā","translation_bn":"থেকে সেখান","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24988,"position":13,"text_uthmani":"فَإِن","transliteration":"fa-in","translation_bn":"অত:পর যদি","root":"—","lemma":"إِن\r","grammar_bn":"শব্দ"},{"id":24989,"position":14,"text_uthmani":"يَخْرُجُوا۟","transliteration":"yakhrujū","translation_bn":"তারা বের হয়","root":"خرج","lemma":"خَرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24990,"position":15,"text_uthmani":"مِنْهَا","transliteration":"min''hā","translation_bn":"থেকে সেখান","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24991,"position":16,"text_uthmani":"فَإِنَّا","transliteration":"fa-innā","translation_bn":"তবে নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"ফলাফল পদ (Result)"},{"id":24992,"position":17,"text_uthmani":"دَٰخِلُونَ","transliteration":"dākhilūna","translation_bn":"প্রবেশ করবো\"","root":"دخل","lemma":"دَٰخِلُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":24993,"position":18,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'qālū yāmūsā inna fīhā qawman jabbārīna wa-innā lan nadkhulahā ḥattā yakhrujū min''hā fa-in yakhrujū min''hā fa-innā dākhilūna', 'তারা বলল, হে মূসা! ওখানে অত্যন্ত শক্তিধর এক সম্প্রদায় আছে, তারা ওখান থেকে বের না হওয়া পর্যন্ত আমরা ওখানে প্রবেশ করব না, তারা যদি বের হয় তাহলেই আমরা প্রবেশ করব।', 'They said, "O Moses, indeed within it is a people of tyrannical strength, and indeed, we will never enter it until they leave it; but if they leave it, then we will enter."', 'তারা বলল, হে মূসা! ওখানে অত্যন্ত শক্তিধর এক সম্প্রদায় আছে, তারা ওখান থেকে বের না হওয়া পর্যন্ত আমরা ওখানে প্রবেশ করব না, তারা যদি বের হয় তাহলেই আমরা প্রবেশ করব।', 'They said, "O Moses, indeed within it is a people of tyrannical strength, and indeed, we will never enter it until they leave it; but if they leave it, then we will enter."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/005022.mp3', now()),
  (5, 23, '', '[{"id":26045,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26046,"position":2,"text_uthmani":"رَجُلَانِ","transliteration":"rajulāni","translation_bn":"দু’ব্যক্তি","root":"رجل","lemma":"رَجُل","grammar_bn":"বিশেষ্য (Noun)"},{"id":26047,"position":3,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"(তাদের) মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26048,"position":4,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":26049,"position":5,"text_uthmani":"يَخَافُونَ","transliteration":"yakhāfūna","translation_bn":"ভয় করে (আল্লাহকে)","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26050,"position":6,"text_uthmani":"أَنْعَمَ","transliteration":"anʿama","translation_bn":"অনুগ্রহ করেছিলেন","root":"نعم","lemma":"أَنْعَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26051,"position":7,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":26052,"position":8,"text_uthmani":"عَلَيْهِمَا","transliteration":"ʿalayhimā","translation_bn":"উপর দু’জনের তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26053,"position":9,"text_uthmani":"ٱدْخُلُوا۟","transliteration":"ud''khulū","translation_bn":"\"তোমরা প্রবেশ করো","root":"دخل","lemma":"دَخَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26054,"position":10,"text_uthmani":"عَلَيْهِمُ","transliteration":"ʿalayhimu","translation_bn":"সাথে তাদের (মুকাবেলা করে)","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26055,"position":11,"text_uthmani":"ٱلْبَابَ","transliteration":"l-bāba","translation_bn":"দরজায়","root":"بوب","lemma":"بَاب","grammar_bn":"শব্দ"},{"id":26056,"position":12,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"অত:পর যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":26057,"position":13,"text_uthmani":"دَخَلْتُمُوهُ","transliteration":"dakhaltumūhu","translation_bn":"তাতে তোমরা প্রবেশ করবে","root":"دخل","lemma":"دَخَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26058,"position":14,"text_uthmani":"فَإِنَّكُمْ","transliteration":"fa-innakum","translation_bn":"তখন নিশ্চয়ই তোমরা","root":"—","lemma":"إِنّ","grammar_bn":"ফলাফল পদ (Result)"},{"id":26059,"position":15,"text_uthmani":"غَـٰلِبُونَ ۚ","transliteration":"ghālibūna","translation_bn":"বিজয়ী হবে","root":"غلب","lemma":"غَالِب","grammar_bn":"বিশেষ্য (Noun)"},{"id":26061,"position":16,"text_uthmani":"وَعَلَى","transliteration":"waʿalā","translation_bn":"এবং উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"শব্দ"},{"id":26062,"position":17,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":26063,"position":18,"text_uthmani":"فَتَوَكَّلُوٓا۟","transliteration":"fatawakkalū","translation_bn":"তাই তোমরা নির্ভর করো","root":"وكل","lemma":"تَوَكَّلْ","grammar_bn":"সম্পূরক পদ (Supplemental)"},{"id":26064,"position":19,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":26065,"position":20,"text_uthmani":"كُنتُم","transliteration":"kuntum","translation_bn":"হও তোমরা","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26066,"position":21,"text_uthmani":"مُّؤْمِنِينَ","transliteration":"mu''minīna","translation_bn":"মু''মিন","root":"امن","lemma":"مُؤْمِن","grammar_bn":"বিশেষ্য (Noun)"},{"id":26067,"position":22,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'qāla rajulāni mina alladhīna yakhāfūna anʿama l-lahu ʿalayhimā ud''khulū ʿalayhimu l-bāba fa-idhā dakhaltumūhu fa-innakum ghālibūna waʿalā l-lahi fatawakkalū in kuntum mu''minīna', 'যারা (আল্লাহকে) ভয় করছিল তাদের মধ্যে দু’জন লোক যাদেরকে আল্লাহ অনুগ্রহ করেছিলেন বলল, তাদের দরজায় হানা দাও, ঢুকলেই তোমরা জয়ী হয়ে যাবে। তোমরা মু’মিন হলে আল্লাহর উপর ভরসা কর।', 'Said two men from those who feared [to disobey] upon whom Allah had bestowed favor, "Enter upon them through the gate, for when you have entered it, you will be predominant. And upon Allah rely, if you should be believers."', 'যারা (আল্লাহকে) ভয় করছিল তাদের মধ্যে দু’জন লোক যাদেরকে আল্লাহ অনুগ্রহ করেছিলেন বলল, তাদের দরজায় হানা দাও, ঢুকলেই তোমরা জয়ী হয়ে যাবে। তোমরা মু’মিন হলে আল্লাহর উপর ভরসা কর।', 'Said two men from those who feared [to disobey] upon whom Allah had bestowed favor, "Enter upon them through the gate, for when you have entered it, you will be predominant. And upon Allah rely, if you should be believers."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/005023.mp3', now()),
  (5, 24, '', '[{"id":27122,"position":1,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"(কিন্তু এ সত্ত্বেও) তারা বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27123,"position":2,"text_uthmani":"يَـٰمُوسَىٰٓ","transliteration":"yāmūsā","translation_bn":"হে মূসা","root":"—","lemma":"مُوسَىٰ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":27124,"position":3,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":27125,"position":4,"text_uthmani":"لَن","transliteration":"lan","translation_bn":"কখনও না","root":"—","lemma":"لَن\r","grammar_bn":"না-বোধক (Negative)"},{"id":27126,"position":5,"text_uthmani":"نَّدْخُلَهَآ","transliteration":"nadkhulahā","translation_bn":"প্রবেশ করবো আমরা তাতে","root":"دخل","lemma":"دَخَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27127,"position":6,"text_uthmani":"أَبَدًۭا","transliteration":"abadan","translation_bn":"কখনও","root":"ابد","lemma":"أَبَدًا","grammar_bn":"কালবাচক (Time)"},{"id":27128,"position":7,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যতক্ষণ","root":"—","lemma":"مَا\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":27129,"position":8,"text_uthmani":"دَامُوا۟","transliteration":"dāmū","translation_bn":"তারা থাকবে","root":"دوم","lemma":"دَامُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27130,"position":9,"text_uthmani":"فِيهَا ۖ","transliteration":"fīhā","translation_bn":"মধ্যে তার","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27132,"position":10,"text_uthmani":"فَٱذْهَبْ","transliteration":"fa-idh''hab","translation_bn":"অতএব যাও","root":"ذهب","lemma":"ذَهَبَ","grammar_bn":"শব্দ"},{"id":27133,"position":11,"text_uthmani":"أَنتَ","transliteration":"anta","translation_bn":"তুমি","root":"—","lemma":"أَنتَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":27134,"position":12,"text_uthmani":"وَرَبُّكَ","transliteration":"warabbuka","translation_bn":"ও রব তোমার","root":"ربب","lemma":"رَبّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27135,"position":13,"text_uthmani":"فَقَـٰتِلَآ","transliteration":"faqātilā","translation_bn":"অত:পর উভয়ে যুদ্ধ করো","root":"قتل","lemma":"قَٰتَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27136,"position":14,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":27137,"position":15,"text_uthmani":"هَـٰهُنَا","transliteration":"hāhunā","translation_bn":"এখানে","root":"—","lemma":"هُنَا\r","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":27138,"position":16,"text_uthmani":"قَـٰعِدُونَ","transliteration":"qāʿidūna","translation_bn":"বসে থাকবো\"","root":"قعد","lemma":"قَاعِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":27139,"position":17,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'qālū yāmūsā innā lan nadkhulahā abadan mā dāmū fīhā fa-idh''hab anta warabbuka faqātilā innā hāhunā qāʿidūna', 'তারা বলল, হে মূসা! তারা ওখানে যদ্দিন থাকবে তদ্দিন আমরা ওখানে কক্ষনো প্রবেশ করব না, কাজেই তুমি আর তোমার প্রতিপালক যাও আর যুদ্ধ কর, আমরা এখানেই বসে রইলাম।', 'They said, "O Moses, indeed we will not enter it, ever, as long as they are within it; so go, you and your Lord, and fight. Indeed, we are remaining right here."', 'তারা বলল, হে মূসা! তারা ওখানে যদ্দিন থাকবে তদ্দিন আমরা ওখানে কক্ষনো প্রবেশ করব না, কাজেই তুমি আর তোমার প্রতিপালক যাও আর যুদ্ধ কর, আমরা এখানেই বসে রইলাম।', 'They said, "O Moses, indeed we will not enter it, ever, as long as they are within it; so go, you and your Lord, and fight. Indeed, we are remaining right here."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/005024.mp3', now()),
  (5, 25, '', '[{"id":28133,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28134,"position":2,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"\"হে আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":28135,"position":3,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":28136,"position":4,"text_uthmani":"لَآ","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":28137,"position":5,"text_uthmani":"أَمْلِكُ","transliteration":"amliku","translation_bn":"ক্ষমতা রাখি আমি","root":"ملك","lemma":"مَلَكَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28138,"position":6,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"ব্যাখ্যামূলক (Explanation)"},{"id":28139,"position":7,"text_uthmani":"نَفْسِى","transliteration":"nafsī","translation_bn":"আমার নিজের","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":28140,"position":8,"text_uthmani":"وَأَخِى ۖ","transliteration":"wa-akhī","translation_bn":"ও আমার ভাইয়ের","root":"اخو","lemma":"أَخ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28142,"position":9,"text_uthmani":"فَٱفْرُقْ","transliteration":"fa-uf''ruq","translation_bn":"তাই পৃথক করো","root":"فرق","lemma":"فَرَقْ","grammar_bn":"সম্পূরক পদ (Supplemental)"},{"id":28143,"position":10,"text_uthmani":"بَيْنَنَا","transliteration":"baynanā","translation_bn":"মাঝে আমাদের","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":28144,"position":11,"text_uthmani":"وَبَيْنَ","transliteration":"wabayna","translation_bn":"ও মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28145,"position":12,"text_uthmani":"ٱلْقَوْمِ","transliteration":"l-qawmi","translation_bn":"সম্প্রদায়ের\"","root":"قوم","lemma":"قَوْم","grammar_bn":"শব্দ"},{"id":28146,"position":13,"text_uthmani":"ٱلْفَـٰسِقِينَ","transliteration":"l-fāsiqīna","translation_bn":"(যারা)সত্যত্যাগী\"","root":"فسق","lemma":"فَاسِق","grammar_bn":"শব্দ"},{"id":28147,"position":14,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'qāla rabbi innī lā amliku illā nafsī wa-akhī fa-uf''ruq baynanā wabayna l-qawmi l-fāsiqīna', 'সে বলল, ‘‘হে আমার প্রতিপালক! আমার আর আমার ভাইয়ের উপর ছাড়া কারো উপর আমার ক্ষমতা নেই, কাজেই এই বিদ্রোহী সম্প্রদায় থেকে আমাদেরকে পৃথক করে দিন।', '[Moses] said, "My Lord, indeed I do not possess except myself and my brother, so part us from the defiantly disobedient people."', 'সে বলল, ‘‘হে আমার প্রতিপালক! আমার আর আমার ভাইয়ের উপর ছাড়া কারো উপর আমার ক্ষমতা নেই, কাজেই এই বিদ্রোহী সম্প্রদায় থেকে আমাদেরকে পৃথক করে দিন।', '[Moses] said, "My Lord, indeed I do not possess except myself and my brother, so part us from the defiantly disobedient people."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/005025.mp3', now()),
  (5, 26, '', '[{"id":28896,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(আল্লাহ) বললেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28897,"position":2,"text_uthmani":"فَإِنَّهَا","transliteration":"fa-innahā","translation_bn":"\"অত:পর নিশ্চয়ই তা","root":"—","lemma":"إِنّ","grammar_bn":"সম্পূরক পদ (Supplemental)"},{"id":28898,"position":3,"text_uthmani":"مُحَرَّمَةٌ","transliteration":"muḥarramatun","translation_bn":"নিষিদ্ধ (করা হলো)","root":"حرم","lemma":"مُحَرَّمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":28899,"position":4,"text_uthmani":"عَلَيْهِمْ ۛ","transliteration":"ʿalayhim","translation_bn":"উপর তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28901,"position":5,"text_uthmani":"أَرْبَعِينَ","transliteration":"arbaʿīna","translation_bn":"চল্লিশ","root":"ربع","lemma":"أَرْبَع","grammar_bn":"কালবাচক (Time)"},{"id":28902,"position":6,"text_uthmani":"سَنَةًۭ ۛ","transliteration":"sanatan","translation_bn":"বছর (পর্যন্ত)","root":"سنو","lemma":"سَنَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":28904,"position":7,"text_uthmani":"يَتِيهُونَ","transliteration":"yatīhūna","translation_bn":"তারা উদ্ভ্রান্ত হয়ে ফিরবে","root":"تيه","lemma":"يَتِيهُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28905,"position":8,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"উপর","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28906,"position":9,"text_uthmani":"ٱلْأَرْضِ ۚ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":28908,"position":10,"text_uthmani":"فَلَا","transliteration":"falā","translation_bn":"অতএব না","root":"—","lemma":"لَا\r","grammar_bn":"সম্পূরক পদ (Supplemental)"},{"id":28909,"position":11,"text_uthmani":"تَأْسَ","transliteration":"tasa","translation_bn":"দু:খ করো","root":"اسو","lemma":"تَأْسَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28910,"position":12,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"জন্যে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28911,"position":13,"text_uthmani":"ٱلْقَوْمِ","transliteration":"l-qawmi","translation_bn":"(ঐসব)সম্প্রদায়ের\"","root":"قوم","lemma":"قَوْم","grammar_bn":"শব্দ"},{"id":28912,"position":14,"text_uthmani":"ٱلْفَـٰسِقِينَ","transliteration":"l-fāsiqīna","translation_bn":"(যারা)সত্যত্যাগী\"","root":"فسق","lemma":"فَاسِق","grammar_bn":"শব্দ"},{"id":28913,"position":15,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'qāla fa-innahā muḥarramatun ʿalayhim arbaʿīna sanatan yatīhūna fī l-arḍi falā tasa ʿalā l-qawmi l-fāsiqīna', 'আল্লাহ বললেন, তবে তা চল্লিশ বছর পর্যন্ত তাদের জন্য নিষিদ্ধ হল, উদভ্রান্তের মত তারা যমীনে ঘুরে বেড়াবে, কাজেই এই অবাধ্য সম্প্রদায়ের জন্য হা-হুতাশ করো না।', '[Allah] said, "Then indeed, it is forbidden to them for forty years [in which] they will wander throughout the land. So do not grieve over the defiantly disobedient people."', 'আল্লাহ বললেন, তবে তা চল্লিশ বছর পর্যন্ত তাদের জন্য নিষিদ্ধ হল, উদভ্রান্তের মত তারা যমীনে ঘুরে বেড়াবে, কাজেই এই অবাধ্য সম্প্রদায়ের জন্য হা-হুতাশ করো না।', '[Allah] said, "Then indeed, it is forbidden to them for forty years [in which] they will wander throughout the land. So do not grieve over the defiantly disobedient people."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/005026.mp3', now()),
