  (6, 1, '', '[{"id":736,"position":1,"text_uthmani":"ٱلْحَمْدُ","transliteration":"al-ḥamdu","translation_bn":"সকল প্রশংসা","root":"حمد","lemma":"حَمْد","grammar_bn":"শব্দ"},{"id":737,"position":2,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"জন্যে আল্লাহরই","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":738,"position":3,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":739,"position":4,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":740,"position":5,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশসমূহ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":741,"position":6,"text_uthmani":"وَٱلْأَرْضَ","transliteration":"wal-arḍa","translation_bn":"ও পৃথিবী","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":742,"position":7,"text_uthmani":"وَجَعَلَ","transliteration":"wajaʿala","translation_bn":"ও বানিয়েছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":743,"position":8,"text_uthmani":"ٱلظُّلُمَـٰتِ","transliteration":"l-ẓulumāti","translation_bn":"অন্ধকারসমূহ","root":"ظلم","lemma":"ظُلُمَٰت","grammar_bn":"শব্দ"},{"id":744,"position":9,"text_uthmani":"وَٱلنُّورَ ۖ","transliteration":"wal-nūra","translation_bn":"ও আলো","root":"نور","lemma":"نُور","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":746,"position":10,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপরও","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":747,"position":11,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":748,"position":12,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অবিশ্বাস করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":749,"position":13,"text_uthmani":"بِرَبِّهِمْ","transliteration":"birabbihim","translation_bn":"প্রতি রবের তাদের","root":"ربب","lemma":"رَبّ","grammar_bn":"অব্যয় (Preposition)"},{"id":750,"position":14,"text_uthmani":"يَعْدِلُونَ","transliteration":"yaʿdilūna","translation_bn":"তাঁর সমকক্ষ দাঁড় করায় (অন্যান্যদেরকে)","root":"عدل","lemma":"عَدَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":751,"position":15,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'al-ḥamdu lillahi alladhī khalaqa l-samāwāti wal-arḍa wajaʿala l-ẓulumāti wal-nūra thumma alladhīna kafarū birabbihim yaʿdilūna', 'সমস্ত প্রশংসা আল্লাহর জন্য যিনি আসমানসমূহ ও যমীন সৃষ্টি করেছেন আর সৃষ্টি করেছেন অন্ধকার ও আলো, এতদসত্ত্বেও যারা কুফরী করেছে তারা (অন্যকে) তাদের প্রতিপালকের সমকক্ষ দাঁড় করিয়েছে।', '[All] praise is [due] to Allah, who created the heavens and the earth and made the darkness and the light. Then those who disbelieve equate [others] with their Lord.', 'সমস্ত প্রশংসা আল্লাহর জন্য যিনি আসমানসমূহ ও যমীন সৃষ্টি করেছেন আর সৃষ্টি করেছেন অন্ধকার ও আলো, এতদসত্ত্বেও যারা কুফরী করেছে তারা (অন্যকে) তাদের প্রতিপালকের সমকক্ষ দাঁড় করিয়েছে।', '[All] praise is [due] to Allah, who created the heavens and the earth and made the darkness and the light. Then those who disbelieve equate [others] with their Lord.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/006001.mp3', now()),
  (6, 2, '', '[{"id":1802,"position":1,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই (আল্লাহ)","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":1803,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1804,"position":3,"text_uthmani":"خَلَقَكُم","transliteration":"khalaqakum","translation_bn":"সৃষ্টি করেছেন তোমাদের","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1805,"position":4,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1806,"position":5,"text_uthmani":"طِينٍۢ","transliteration":"ṭīnin","translation_bn":"মাটি","root":"طين","lemma":"طِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":1807,"position":6,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1808,"position":7,"text_uthmani":"قَضَىٰٓ","transliteration":"qaḍā","translation_bn":"নির্দিষ্ট করেছেন","root":"قضي","lemma":"قَضَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":1809,"position":8,"text_uthmani":"أَجَلًۭا ۖ","transliteration":"ajalan","translation_bn":"একটি মেয়াদ (জীবনকাল)","root":"اجل","lemma":"أَجَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":1811,"position":9,"text_uthmani":"وَأَجَلٌۭ","transliteration":"wa-ajalun","translation_bn":"এবং (এছাড়াও) একটি মেয়াদ (অর্থাৎ ক্বিয়ামাত)","root":"اجل","lemma":"أَجَل","grammar_bn":"শব্দ"},{"id":1812,"position":10,"text_uthmani":"مُّسَمًّى","transliteration":"musamman","translation_bn":"নির্ধারিত (আছে)","root":"سمو","lemma":"مُّسَمًّى","grammar_bn":"বিশেষণ (Adjective)"},{"id":1813,"position":11,"text_uthmani":"عِندَهُۥ ۖ","transliteration":"ʿindahu","translation_bn":"কাছে তাঁর","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":1815,"position":12,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপরও","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1816,"position":13,"text_uthmani":"أَنتُمْ","transliteration":"antum","translation_bn":"তোমরা","root":"—","lemma":"أَنتُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":1817,"position":14,"text_uthmani":"تَمْتَرُونَ","transliteration":"tamtarūna","translation_bn":"সন্দেহ করছো","root":"مري","lemma":"يَمْتَرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1818,"position":15,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'huwa alladhī khalaqakum min ṭīnin thumma qaḍā ajalan wa-ajalun musamman ʿindahu thumma antum tamtarūna', 'যিনি মাটি থেকে তোমাদেরকে সৃষ্টি করেছেন অতঃপর (তোমাদের জীবনের জন্য) একটি নির্দিষ্ট মেয়াদ নির্ধারিত করেছেন, এছাড়া আরেকটি নির্ধারিত মেয়াদ আছে (যে সম্পর্কিত জ্ঞান আছে) তাঁর কাছে, কিন্তু তোমরা সন্দেহই করে চলেছ।', 'It is He who created you from clay and then decreed a term and a specified time [known] to Him; then [still] you are in dispute.', 'যিনি মাটি থেকে তোমাদেরকে সৃষ্টি করেছেন অতঃপর (তোমাদের জীবনের জন্য) একটি নির্দিষ্ট মেয়াদ নির্ধারিত করেছেন, এছাড়া আরেকটি নির্ধারিত মেয়াদ আছে (যে সম্পর্কিত জ্ঞান আছে) তাঁর কাছে, কিন্তু তোমরা সন্দেহই করে চলেছ।', 'It is He who created you from clay and then decreed a term and a specified time [known] to Him; then [still] you are in dispute.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/006002.mp3', now()),
  (6, 3, '', '[{"id":2956,"position":1,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2957,"position":2,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ (যিনি)","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":2958,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"আছেন","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2959,"position":4,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশসমূহে","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":2960,"position":5,"text_uthmani":"وَفِى","transliteration":"wafī","translation_bn":"এবং আছেন","root":"—","lemma":"فِى\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2961,"position":6,"text_uthmani":"ٱلْأَرْضِ ۖ","transliteration":"l-arḍi","translation_bn":"পৃথিবীতে","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":2963,"position":7,"text_uthmani":"يَعْلَمُ","transliteration":"yaʿlamu","translation_bn":"তিনি জানেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2964,"position":8,"text_uthmani":"سِرَّكُمْ","transliteration":"sirrakum","translation_bn":"গোপন বিষয় তোমাদের","root":"سرر","lemma":"سِرّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":2965,"position":9,"text_uthmani":"وَجَهْرَكُمْ","transliteration":"wajahrakum","translation_bn":"ও প্রকাশ্য বিষয় তোমাদের","root":"جهر","lemma":"جَهْر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2966,"position":10,"text_uthmani":"وَيَعْلَمُ","transliteration":"wayaʿlamu","translation_bn":"এবং তিনি জানেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2967,"position":11,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":2968,"position":12,"text_uthmani":"تَكْسِبُونَ","transliteration":"taksibūna","translation_bn":"তোমরা অর্জন করো","root":"كسب","lemma":"كَسَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2969,"position":13,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'wahuwa l-lahu fī l-samāwāti wafī l-arḍi yaʿlamu sirrakum wajahrakum wayaʿlamu mā taksibūna', 'আসমানসমূহ আর যমীনে তিনিই আল্লাহ, তোমাদের গোপন বিষয়াদি আর তোমাদের প্রকাশ্য বিষয়াদি সম্পর্কে তিনি জানেন, আর তিনি জানেন যা তোমরা উপার্জন কর।', 'And He is Allah, [the only deity] in the heavens and the earth. He knows your secret and what you make public, and He knows that which you earn.', 'আসমানসমূহ আর যমীনে তিনিই আল্লাহ, তোমাদের গোপন বিষয়াদি আর তোমাদের প্রকাশ্য বিষয়াদি সম্পর্কে তিনি জানেন, আর তিনি জানেন যা তোমরা উপার্জন কর।', 'And He is Allah, [the only deity] in the heavens and the earth. He knows your secret and what you make public, and He knows that which you earn.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/006003.mp3', now()),
  (6, 4, '', '[{"id":4296,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":4297,"position":2,"text_uthmani":"تَأْتِيهِم","transliteration":"tatīhim","translation_bn":"কাছে এসেছে তাদের","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":4298,"position":3,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4299,"position":4,"text_uthmani":"ءَايَةٍۢ","transliteration":"āyatin","translation_bn":"(এমন) নিদর্শন","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":4300,"position":5,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4301,"position":6,"text_uthmani":"ءَايَـٰتِ","transliteration":"āyāti","translation_bn":"নিদর্শনগুলোর","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":4302,"position":7,"text_uthmani":"رَبِّهِمْ","transliteration":"rabbihim","translation_bn":"রবের তাদের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":4303,"position":8,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া যে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":4304,"position":9,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা হয়েছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4305,"position":10,"text_uthmani":"عَنْهَا","transliteration":"ʿanhā","translation_bn":"হতে তা","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4306,"position":11,"text_uthmani":"مُعْرِضِينَ","transliteration":"muʿ''riḍīna","translation_bn":"বিমুখ","root":"عرض","lemma":"مُّعْرِضُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":4307,"position":12,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'wamā tatīhim min āyatin min āyāti rabbihim illā kānū ʿanhā muʿ''riḍīna', 'তাদের রব্বের নিদর্শনাবলী হতে এমন কোন নিদর্শন তাদের কাছে আসে না যা থেকে তারা মুখ ফিরিয়ে নেয় না।', 'And no sign comes to them from the signs of their Lord except that they turn away therefrom.', 'তাদের রব্বের নিদর্শনাবলী হতে এমন কোন নিদর্শন তাদের কাছে আসে না যা থেকে তারা মুখ ফিরিয়ে নেয় না।', 'And no sign comes to them from the signs of their Lord except that they turn away therefrom.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/006004.mp3', now()),
  (6, 5, '', '[{"id":5584,"position":1,"text_uthmani":"فَقَدْ","transliteration":"faqad","translation_bn":"সুতরাং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"ফলাফল পদ (Result)"},{"id":5585,"position":2,"text_uthmani":"كَذَّبُوا۟","transliteration":"kadhabū","translation_bn":"তারা মিথ্যা প্রতিপন্ন করেছে","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5586,"position":3,"text_uthmani":"بِٱلْحَقِّ","transliteration":"bil-ḥaqi","translation_bn":"প্রতি সত্যের","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":5587,"position":4,"text_uthmani":"لَمَّا","transliteration":"lammā","translation_bn":"যখনই","root":"—","lemma":"لَمَّا\r","grammar_bn":"কালবাচক (Time)"},{"id":5588,"position":5,"text_uthmani":"جَآءَهُمْ ۖ","transliteration":"jāahum","translation_bn":"কাছে তা এসেছে তাদের","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5590,"position":6,"text_uthmani":"فَسَوْفَ","transliteration":"fasawfa","translation_bn":"সুতরাং শীঘ্রই","root":"—","lemma":"سَوْف\r","grammar_bn":"ফলাফল পদ (Result)"},{"id":5591,"position":7,"text_uthmani":"يَأْتِيهِمْ","transliteration":"yatīhim","translation_bn":"কাছে আসবে তাদের","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":5592,"position":8,"text_uthmani":"أَنۢبَـٰٓؤُا۟","transliteration":"anbāu","translation_bn":"সংবাদ","root":"نبا","lemma":"نَبَأ","grammar_bn":"বিশেষ্য (Noun)"},{"id":5593,"position":9,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"ঐ বিষয়ের","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":5594,"position":10,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5595,"position":11,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"নিয়ে যা","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":5596,"position":12,"text_uthmani":"يَسْتَهْزِءُونَ","transliteration":"yastahziūna","translation_bn":"ঠাট্টা বিদ্রুপ করতো","root":"هزا","lemma":"ٱسْتُهْزِئَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5597,"position":13,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'faqad kadhabū bil-ḥaqi lammā jāahum fasawfa yatīhim anbāu mā kānū bihi yastahziūna', '(এখন) যে সত্য তাদের কাছে এসেছে তারা তা অস্বীকার করেছে। শীঘ্রই তাদের কাছে সে খবর আসবে যে সম্পর্কে তারা ঠাট্টা-বিদ্রূপ করত।', 'For they had denied the truth when it came to them, but there is going to reach them the news of what they used to ridicule.', '(এখন) যে সত্য তাদের কাছে এসেছে তারা তা অস্বীকার করেছে। শীঘ্রই তাদের কাছে সে খবর আসবে যে সম্পর্কে তারা ঠাট্টা-বিদ্রূপ করত।', 'For they had denied the truth when it came to them, but there is going to reach them the news of what they used to ridicule.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/006005.mp3', now()),
  (6, 6, '', '[{"id":6848,"position":1,"text_uthmani":"أَلَمْ","transliteration":"alam","translation_bn":"কি নি","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":6849,"position":2,"text_uthmani":"يَرَوْا۟","transliteration":"yaraw","translation_bn":"তারা দেখে","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":6850,"position":3,"text_uthmani":"كَمْ","transliteration":"kam","translation_bn":"কত (জাতিকে)","root":"—","lemma":"كَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":6851,"position":4,"text_uthmani":"أَهْلَكْنَا","transliteration":"ahlaknā","translation_bn":"ধ্বংস করেছি আমরা","root":"هلك","lemma":"أَهْلَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6852,"position":5,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6853,"position":6,"text_uthmani":"قَبْلِهِم","transliteration":"qablihim","translation_bn":"পূর্ব তাদের","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":6854,"position":7,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6855,"position":8,"text_uthmani":"قَرْنٍۢ","transliteration":"qarnin","translation_bn":"মানবগোষ্ঠী","root":"قرن","lemma":"قَرْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":6856,"position":9,"text_uthmani":"مَّكَّنَّـٰهُمْ","transliteration":"makkannāhum","translation_bn":"আমরা প্রতিষ্ঠিত করেছিলাম তাদের","root":"مكن","lemma":"مَكَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6857,"position":10,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6858,"position":11,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর (এমনভাবে)","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":6859,"position":12,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যেমনটি","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":6860,"position":13,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"না","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":6861,"position":14,"text_uthmani":"نُمَكِّن","transliteration":"numakkin","translation_bn":"আমরা প্রতিষ্ঠিত করেছি","root":"مكن","lemma":"مَكَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6862,"position":15,"text_uthmani":"لَّكُمْ","transliteration":"lakum","translation_bn":"তোমাদেরকে","root":"—","lemma":"لَّكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":6863,"position":16,"text_uthmani":"وَأَرْسَلْنَا","transliteration":"wa-arsalnā","translation_bn":"এবং আমরা পাঠিয়েছিলাম","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6864,"position":17,"text_uthmani":"ٱلسَّمَآءَ","transliteration":"l-samāa","translation_bn":"আকাশ (থেকে)","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":6865,"position":18,"text_uthmani":"عَلَيْهِم","transliteration":"ʿalayhim","translation_bn":"উপর তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6866,"position":19,"text_uthmani":"مِّدْرَارًۭا","transliteration":"mid''rāran","translation_bn":"মুষলধারে বৃষ্টি","root":"درر","lemma":"مِّدْرَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":6867,"position":20,"text_uthmani":"وَجَعَلْنَا","transliteration":"wajaʿalnā","translation_bn":"ও করেছিলাম আমরা","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6868,"position":21,"text_uthmani":"ٱلْأَنْهَـٰرَ","transliteration":"l-anhāra","translation_bn":"নদীসমূহকে","root":"نهر","lemma":"نَهَر","grammar_bn":"শব্দ"},{"id":6869,"position":22,"text_uthmani":"تَجْرِى","transliteration":"tajrī","translation_bn":"প্রবাহিত","root":"جري","lemma":"جَرَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6870,"position":23,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6871,"position":24,"text_uthmani":"تَحْتِهِمْ","transliteration":"taḥtihim","translation_bn":"নিচ তাদের(ভূমি)","root":"تحت","lemma":"تَحْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":6872,"position":25,"text_uthmani":"فَأَهْلَكْنَـٰهُم","transliteration":"fa-ahlaknāhum","translation_bn":"অতঃপর আমরা ধ্বংস করেছি তাদের","root":"هلك","lemma":"أَهْلَكَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6873,"position":26,"text_uthmani":"بِذُنُوبِهِمْ","transliteration":"bidhunūbihim","translation_bn":"কারণে পাপের তাদের","root":"ذنب","lemma":"ذَنب","grammar_bn":"অব্যয় (Preposition)"},{"id":6874,"position":27,"text_uthmani":"وَأَنشَأْنَا","transliteration":"wa-anshanā","translation_bn":"ও সৃষ্টি করেছি আমরা","root":"نشا","lemma":"أَنشَأَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6875,"position":28,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6876,"position":29,"text_uthmani":"بَعْدِهِمْ","transliteration":"baʿdihim","translation_bn":"পর তাদের","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":6877,"position":30,"text_uthmani":"قَرْنًا","transliteration":"qarnan","translation_bn":"জাতিকে","root":"قرن","lemma":"قَرْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":6878,"position":31,"text_uthmani":"ءَاخَرِينَ","transliteration":"ākharīna","translation_bn":"অন্যান্য","root":"اخر","lemma":"ا^خَر","grammar_bn":"বিশেষণ (Adjective)"},{"id":6879,"position":32,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'alam yaraw kam ahlaknā min qablihim min qarnin makkannāhum fī l-arḍi mā lam numakkin lakum wa-arsalnā l-samāa ʿalayhim mid''rāran wajaʿalnā l-anhāra tajrī min taḥtihim fa-ahlaknāhum bidhunūbihim wa-anshanā min baʿdihim qarnan ākharīna', 'তারা কি লক্ষ্য করে না তাদের পূর্বে আমি কত জনগোষ্ঠীকে ধ্বংস করে দিয়েছি, তাদেরকে দুনিয়ায় (এমনভাবে) প্রতিষ্ঠিত করেছিলাম যে শক্তি-প্রতিষ্ঠা তোমাদেরকে দেয়া হয়নি, তাদের জন্য প্রচুর বৃষ্টিপাত ঘটিয়েছিলাম, তৈরি করেছিলাম নদী যা তাদের নিম্নদেশ দিয়ে প্রবাহিত হত, অতঃপর তাদের পাপের কারণে তাদেরকে ধ্বংস করে দিয়েছি আর তাদের পরে নতুন জনগোষ্ঠীর উত্থান ঘটালাম।', 'Have they not seen how many generations We destroyed before them which We had established upon the earth as We have not established you? And We sent [rain from] the sky upon them in showers and made rivers flow beneath them; then We destroyed them for their sins and brought forth after them a generation of others.', 'তারা কি লক্ষ্য করে না তাদের পূর্বে আমি কত জনগোষ্ঠীকে ধ্বংস করে দিয়েছি, তাদেরকে দুনিয়ায় (এমনভাবে) প্রতিষ্ঠিত করেছিলাম যে শক্তি-প্রতিষ্ঠা তোমাদেরকে দেয়া হয়নি, তাদের জন্য প্রচুর বৃষ্টিপাত ঘটিয়েছিলাম, তৈরি করেছিলাম নদী যা তাদের নিম্নদেশ দিয়ে প্রবাহিত হত, অতঃপর তাদের পাপের কারণে তাদেরকে ধ্বংস করে দিয়েছি আর তাদের পরে নতুন জনগোষ্ঠীর উত্থান ঘটালাম।', 'Have they not seen how many generations We destroyed before them which We had established upon the earth as We have not established you? And We sent [rain from] the sky upon them in showers and made rivers flow beneath them; then We destroyed them for their sins and brought forth after them a generation of others.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/006006.mp3', now()),
  (6, 7, '', '[{"id":8182,"position":1,"text_uthmani":"وَلَوْ","transliteration":"walaw","translation_bn":"এবং যদি","root":"—","lemma":"لَو\r","grammar_bn":"শব্দ"},{"id":8183,"position":2,"text_uthmani":"نَزَّلْنَا","transliteration":"nazzalnā","translation_bn":"অবতীর্ণ করতাম আমরা","root":"نزل","lemma":"نَزَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8184,"position":3,"text_uthmani":"عَلَيْكَ","transliteration":"ʿalayka","translation_bn":"উপর তোমার","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8185,"position":4,"text_uthmani":"كِتَـٰبًۭا","transliteration":"kitāban","translation_bn":"(লিখিত) কিতাব","root":"كتب","lemma":"كِتَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":8186,"position":5,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8187,"position":6,"text_uthmani":"قِرْطَاسٍۢ","transliteration":"qir''ṭāsin","translation_bn":"কাগজের","root":"قرطس","lemma":"قِرْطَاس","grammar_bn":"বিশেষ্য (Noun)"},{"id":8188,"position":7,"text_uthmani":"فَلَمَسُوهُ","transliteration":"falamasūhu","translation_bn":"অতঃপর তারা স্পর্শ করতো তা","root":"لمس","lemma":"لَمَسُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8189,"position":8,"text_uthmani":"بِأَيْدِيهِمْ","transliteration":"bi-aydīhim","translation_bn":"দিয়ে হাত তাদের","root":"يدي","lemma":"يَد","grammar_bn":"অব্যয় (Preposition)"},{"id":8190,"position":9,"text_uthmani":"لَقَالَ","transliteration":"laqāla","translation_bn":"(তবুও) অবশ্যই বলতো","root":"قول","lemma":"قَالَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":8191,"position":10,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":8192,"position":11,"text_uthmani":"كَفَرُوٓا۟","transliteration":"kafarū","translation_bn":"অবিশ্বাস করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8193,"position":12,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"\"নয়","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":8194,"position":13,"text_uthmani":"هَـٰذَآ","transliteration":"hādhā","translation_bn":"\"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":8195,"position":14,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া যে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":8196,"position":15,"text_uthmani":"سِحْرٌۭ","transliteration":"siḥ''run","translation_bn":"জাদু\"","root":"سحر","lemma":"سِحْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":8197,"position":16,"text_uthmani":"مُّبِينٌۭ","transliteration":"mubīnun","translation_bn":"সুস্পষ্ট\"","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":8198,"position":17,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'walaw nazzalnā ʿalayka kitāban fī qir''ṭāsin falamasūhu bi-aydīhim laqāla alladhīna kafarū in hādhā illā siḥ''run mubīnun', 'আমি যদি তোমার উপর কাগজে লেখা কিতাব নাযিল করতাম আর তা তারা তাদের হাতে স্পর্শ করত, তাহলে অবিশ্বাসীরা অবশ্যই বলত এটা স্পষ্ট যাদু ছাড়া আর কিছু না।', 'And even if We had sent down to you, [O Muhammad], a written scripture on a page and they touched it with their hands, the disbelievers would say, "This is not but obvious magic."', 'আমি যদি তোমার উপর কাগজে লেখা কিতাব নাযিল করতাম আর তা তারা তাদের হাতে স্পর্শ করত, তাহলে অবিশ্বাসীরা অবশ্যই বলত এটা স্পষ্ট যাদু ছাড়া আর কিছু না।', 'And even if We had sent down to you, [O Muhammad], a written scripture on a page and they touched it with their hands, the disbelievers would say, "This is not but obvious magic."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/006007.mp3', now()),
  (6, 8, '', '[{"id":9346,"position":1,"text_uthmani":"وَقَالُوا۟","transliteration":"waqālū","translation_bn":"এবং তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9347,"position":2,"text_uthmani":"لَوْلَآ","transliteration":"lawlā","translation_bn":"\"কেন না","root":"—","lemma":"لَوْلَا^\r","grammar_bn":"উৎসাহবাচক (Exhortation)"},{"id":9348,"position":3,"text_uthmani":"أُنزِلَ","transliteration":"unzila","translation_bn":"অবতীর্ণ করা হলো","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9349,"position":4,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"কাছে তার","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9350,"position":5,"text_uthmani":"مَلَكٌۭ ۖ","transliteration":"malakun","translation_bn":"ফেরেশতা (সাক্ষী রূপে)\"","root":"ملك","lemma":"مَلَك","grammar_bn":"বিশেষ্য (Noun)"},{"id":9352,"position":6,"text_uthmani":"وَلَوْ","transliteration":"walaw","translation_bn":"এবং যদি","root":"—","lemma":"لَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9353,"position":7,"text_uthmani":"أَنزَلْنَا","transliteration":"anzalnā","translation_bn":"অবতীর্ণ করতাম আমরা","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9354,"position":8,"text_uthmani":"مَلَكًۭا","transliteration":"malakan","translation_bn":"ফেরেশতা (সাক্ষীরূপে)","root":"ملك","lemma":"مَلَك","grammar_bn":"বিশেষ্য (Noun)"},{"id":9355,"position":9,"text_uthmani":"لَّقُضِىَ","transliteration":"laquḍiya","translation_bn":"অবশ্যই মীমাংসা হয়ে যেতো","root":"قضي","lemma":"قَضَىٰ^","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":9356,"position":10,"text_uthmani":"ٱلْأَمْرُ","transliteration":"l-amru","translation_bn":"(সব) বিষয়ের","root":"امر","lemma":"أَمْر","grammar_bn":"শব্দ"},{"id":9357,"position":11,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9358,"position":12,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":9359,"position":13,"text_uthmani":"يُنظَرُونَ","transliteration":"yunẓarūna","translation_bn":"তাদের অবকাশ দেয়া হতো","root":"نظر","lemma":"يُنظَرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9360,"position":14,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'waqālū lawlā unzila ʿalayhi malakun walaw anzalnā malakan laquḍiya l-amru thumma lā yunẓarūna', 'আর তারা বলে, আমাদের কাছে ফেরেশতা পাঠানো হয় না কেন? আমি যদি ফেরেশতা পাঠাতাম তাহলে (যাবতীয় ব্যাপারে) চূড়ান্ত ফায়সালাই তো হয়ে যেত, অতঃপর তাদেরকে আর অবকাশ দেয়া হত না।', 'And they say, "Why was there not sent down to him an angel?" But if We had sent down an angel, the matter would have been decided; then they would not be reprieved.', 'আর তারা বলে, আমাদের কাছে ফেরেশতা পাঠানো হয় না কেন? আমি যদি ফেরেশতা পাঠাতাম তাহলে (যাবতীয় ব্যাপারে) চূড়ান্ত ফায়সালাই তো হয়ে যেত, অতঃপর তাদেরকে আর অবকাশ দেয়া হত না।', 'And they say, "Why was there not sent down to him an angel?" But if We had sent down an angel, the matter would have been decided; then they would not be reprieved.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/006008.mp3', now()),
  (6, 9, '', '[{"id":10480,"position":1,"text_uthmani":"وَلَوْ","transliteration":"walaw","translation_bn":"এবং যদি","root":"—","lemma":"لَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10481,"position":2,"text_uthmani":"جَعَلْنَـٰهُ","transliteration":"jaʿalnāhu","translation_bn":"আমরা করতাম তাকে","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10482,"position":3,"text_uthmani":"مَلَكًۭا","transliteration":"malakan","translation_bn":"ফেরেশতা","root":"ملك","lemma":"مَلَك","grammar_bn":"বিশেষ্য (Noun)"},{"id":10483,"position":4,"text_uthmani":"لَّجَعَلْنَـٰهُ","transliteration":"lajaʿalnāhu","translation_bn":"অবশ্যই আমরা বানাতাম তাকে","root":"جعل","lemma":"جَعَلَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":10484,"position":5,"text_uthmani":"رَجُلًۭا","transliteration":"rajulan","translation_bn":"মানুষরূপে","root":"رجل","lemma":"رَجُل","grammar_bn":"বিশেষ্য (Noun)"},{"id":10485,"position":6,"text_uthmani":"وَلَلَبَسْنَا","transliteration":"walalabasnā","translation_bn":"এবং অবশ্যই বিভ্রমে ফেলতাম আমরা","root":"لبس","lemma":"لَبَسْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10486,"position":7,"text_uthmani":"عَلَيْهِم","transliteration":"ʿalayhim","translation_bn":"উপর তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10487,"position":8,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যেমন","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":10488,"position":9,"text_uthmani":"يَلْبِسُونَ","transliteration":"yalbisūna","translation_bn":"তারা বিভ্রমে পড়েছে (এমন)","root":"لبس","lemma":"لَبَسْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10489,"position":10,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'walaw jaʿalnāhu malakan lajaʿalnāhu rajulan walalabasnā ʿalayhim mā yalbisūna', 'আর আমি যদি তাকে ফেরেশতা করতাম তবে তাকে মানুষের আকৃতি বিশিষ্টই করতাম, আর তাদেরকে অবশ্যই গোলকধাঁধায় ফেলে দিতাম যেমন ধাঁধাঁয় তারা এখন পড়েছে।', 'And if We had made him an angel, We would have made him [appear as] a man, and We would have covered them with that in which they cover themselves.', 'আর আমি যদি তাকে ফেরেশতা করতাম তবে তাকে মানুষের আকৃতি বিশিষ্টই করতাম, আর তাদেরকে অবশ্যই গোলকধাঁধায় ফেলে দিতাম যেমন ধাঁধাঁয় তারা এখন পড়েছে।', 'And if We had made him an angel, We would have made him [appear as] a man, and We would have covered them with that in which they cover themselves.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/006009.mp3', now()),
  (6, 10, '', '[{"id":11734,"position":1,"text_uthmani":"وَلَقَدِ","transliteration":"walaqadi","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"শব্দ"},{"id":11735,"position":2,"text_uthmani":"ٱسْتُهْزِئَ","transliteration":"us''tuh''zi-a","translation_bn":"বিদ্রুপ করা হয়েছে","root":"هزا","lemma":"ٱسْتُهْزِئَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11736,"position":3,"text_uthmani":"بِرُسُلٍۢ","transliteration":"birusulin","translation_bn":"সাথে রাসূলদের","root":"رسل","lemma":"رَسُول","grammar_bn":"অব্যয় (Preposition)"},{"id":11737,"position":4,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11738,"position":5,"text_uthmani":"قَبْلِكَ","transliteration":"qablika","translation_bn":"পূর্ব তোমার","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":11739,"position":6,"text_uthmani":"فَحَاقَ","transliteration":"faḥāqa","translation_bn":"তখন ঘিরে ফেলেছে","root":"حيق","lemma":"حَاقَ","grammar_bn":"কারণবাচক (Cause)"},{"id":11740,"position":7,"text_uthmani":"بِٱلَّذِينَ","transliteration":"bi-alladhīna","translation_bn":"(তাদের)  উপর যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অব্যয় (Preposition)"},{"id":11741,"position":8,"text_uthmani":"سَخِرُوا۟","transliteration":"sakhirū","translation_bn":"ঠাট্টা করেছিলো","root":"سخر","lemma":"سَخِرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11742,"position":9,"text_uthmani":"مِنْهُم","transliteration":"min''hum","translation_bn":"মধ্যে হতে তাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11743,"position":10,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"ঐ বিষয়","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":11744,"position":11,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11745,"position":12,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"নিয়ে যা","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":11746,"position":13,"text_uthmani":"يَسْتَهْزِءُونَ","transliteration":"yastahziūna","translation_bn":"ঠাট্টা বিদ্রুপ করতো","root":"هزا","lemma":"ٱسْتُهْزِئَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11747,"position":14,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'walaqadi us''tuh''zi-a birusulin min qablika faḥāqa bi-alladhīna sakhirū min''hum mā kānū bihi yastahziūna', 'তোমার পূর্বেও রসূলদেরকে ঠাট্টা-বিদ্রূপ করা হয়েছে, অতঃপর যা নিয়ে তারা ঠাট্টা-বিদ্রূপ করত তাই তাদেরকে পরিবেষ্টন করে ফেলল।', 'And already were messengers ridiculed before you, but those who mocked them were enveloped by that which they used to ridicule.', 'তোমার পূর্বেও রসূলদেরকে ঠাট্টা-বিদ্রূপ করা হয়েছে, অতঃপর যা নিয়ে তারা ঠাট্টা-বিদ্রূপ করত তাই তাদেরকে পরিবেষ্টন করে ফেলল।', 'And already were messengers ridiculed before you, but those who mocked them were enveloped by that which they used to ridicule.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/006010.mp3', now()),
  (6, 11, '', '[{"id":13104,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13105,"position":2,"text_uthmani":"سِيرُوا۟","transliteration":"sīrū","translation_bn":"\"তোমরা ভ্রমণ করো","root":"سير","lemma":"سَارَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13106,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13107,"position":4,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":13108,"position":5,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13109,"position":6,"text_uthmani":"ٱنظُرُوا۟","transliteration":"unẓurū","translation_bn":"তোমরা দেখো","root":"نظر","lemma":"نَّظَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13110,"position":7,"text_uthmani":"كَيْفَ","transliteration":"kayfa","translation_bn":"কেমন","root":"كيف\r","lemma":"كَيْف","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":13111,"position":8,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13112,"position":9,"text_uthmani":"عَـٰقِبَةُ","transliteration":"ʿāqibatu","translation_bn":"পরিণাম","root":"عقب","lemma":"عَٰقِبَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":13113,"position":10,"text_uthmani":"ٱلْمُكَذِّبِينَ","transliteration":"l-mukadhibīna","translation_bn":"সত্য অমান্যকারীদের\"","root":"كذب","lemma":"مُّكَذِّبِين","grammar_bn":"শব্দ"},{"id":13114,"position":11,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'qul sīrū fī l-arḍi thumma unẓurū kayfa kāna ʿāqibatu l-mukadhibīna', 'বল, দুনিয়ায় পরিভ্রমণ কর, অতঃপর দেখ সত্য প্রত্যাখ্যানকারীদের পরিণাম কী দাঁড়িয়েছিল।', 'Say, "Travel through the land; then observe how was the end of the deniers."', 'বল, দুনিয়ায় পরিভ্রমণ কর, অতঃপর দেখ সত্য প্রত্যাখ্যানকারীদের পরিণাম কী দাঁড়িয়েছিল।', 'Say, "Travel through the land; then observe how was the end of the deniers."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/006011.mp3', now()),
  (6, 12, '', '[{"id":14377,"position":1,"text_uthmani":"قُل","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14378,"position":2,"text_uthmani":"لِّمَن","transliteration":"liman","translation_bn":"\"কার (মালিকানায়)","root":"—","lemma":"مَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14379,"position":3,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যাকিছু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":14380,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14381,"position":5,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশসমূহের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":14382,"position":6,"text_uthmani":"وَٱلْأَرْضِ ۖ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর\"","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14384,"position":7,"text_uthmani":"قُل","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14385,"position":8,"text_uthmani":"لِّلَّهِ ۚ","transliteration":"lillahi","translation_bn":"\"জন্যে আল্লাহরই (মালিকানায়)\"","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":14387,"position":9,"text_uthmani":"كَتَبَ","transliteration":"kataba","translation_bn":"তিনি নির্ধারিত করে দিয়েছেন","root":"كتب","lemma":"كَتَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14388,"position":10,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14389,"position":11,"text_uthmani":"نَفْسِهِ","transliteration":"nafsihi","translation_bn":"নিজের তাঁর","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":14390,"position":12,"text_uthmani":"ٱلرَّحْمَةَ ۚ","transliteration":"l-raḥmata","translation_bn":"দয়া করা","root":"رحم","lemma":"رَحْمَة","grammar_bn":"শব্দ"},{"id":14392,"position":13,"text_uthmani":"لَيَجْمَعَنَّكُمْ","transliteration":"layajmaʿannakum","translation_bn":"নিশ্চয়ই একত্র করবেন তোমাদের","root":"جمع","lemma":"جَمَعَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":14393,"position":14,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14394,"position":15,"text_uthmani":"يَوْمِ","transliteration":"yawmi","translation_bn":"দিনে","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":14395,"position":16,"text_uthmani":"ٱلْقِيَـٰمَةِ","transliteration":"l-qiyāmati","translation_bn":"ক্বিয়ামাতের","root":"قوم","lemma":"قِيَٰمَة","grammar_bn":"শব্দ"},{"id":14396,"position":17,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا","grammar_bn":"না-বোধক (Negative)"},{"id":14397,"position":18,"text_uthmani":"رَيْبَ","transliteration":"rayba","translation_bn":"সন্দেহ","root":"ريب","lemma":"رَيْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":14398,"position":19,"text_uthmani":"فِيهِ ۚ","transliteration":"fīhi","translation_bn":"মধ্যে তার (বিন্দুমাত্র)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14400,"position":20,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":14401,"position":21,"text_uthmani":"خَسِرُوٓا۟","transliteration":"khasirū","translation_bn":"ক্ষতিগ্রস্ত করেছে","root":"خسر","lemma":"خَسِرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14402,"position":22,"text_uthmani":"أَنفُسَهُمْ","transliteration":"anfusahum","translation_bn":"নিজেদেরকে তাদের","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":14403,"position":23,"text_uthmani":"فَهُمْ","transliteration":"fahum","translation_bn":"অতঃপর তারা","root":"—","lemma":"فَهُمْ","grammar_bn":"শব্দ"},{"id":14404,"position":24,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":14405,"position":25,"text_uthmani":"يُؤْمِنُونَ","transliteration":"yu''minūna","translation_bn":"ঈমান আনবে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14406,"position":26,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'qul liman mā fī l-samāwāti wal-arḍi qul lillahi kataba ʿalā nafsihi l-raḥmata layajmaʿannakum ilā yawmi l-qiyāmati lā rayba fīhi alladhīna khasirū anfusahum fahum lā yu''minūna', 'বল, আসমানে আর যমীনে যা আছে তা কার? বল, আল্লাহরই। দয়া করা তিনি তাঁর জন্য কর্তব্য স্থির করে নিয়েছেন, তিনি কিয়ামাত দিবসে তোমাদের সবাইকে একত্রিত করবেন, এতে কোন সন্দেহ নেই। যারা নিজেরাই নিজেদের ক্ষতি করেছে তারা ঈমান আনবে না।', 'Say, "To whom belongs whatever is in the heavens and earth?" Say, "To Allah." He has decreed upon Himself mercy. He will surely assemble you for the Day of Resurrection, about which there is no doubt. Those who will lose themselves [that Day] do not believe.', 'বল, আসমানে আর যমীনে যা আছে তা কার? বল, আল্লাহরই। দয়া করা তিনি তাঁর জন্য কর্তব্য স্থির করে নিয়েছেন, তিনি কিয়ামাত দিবসে তোমাদের সবাইকে একত্রিত করবেন, এতে কোন সন্দেহ নেই। যারা নিজেরাই নিজেদের ক্ষতি করেছে তারা ঈমান আনবে না।', 'Say, "To whom belongs whatever is in the heavens and earth?" Say, "To Allah." He has decreed upon Himself mercy. He will surely assemble you for the Day of Resurrection, about which there is no doubt. Those who will lose themselves [that Day] do not believe.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/006012.mp3', now()),
  (6, 13, '', '[{"id":15500,"position":1,"text_uthmani":"۞ وَلَهُۥ","transliteration":"walahu","translation_bn":"এবং জন্যে তাঁরই","root":"—","lemma":"۞ وَلَهُۥ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15501,"position":2,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যাকিছু","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":15502,"position":3,"text_uthmani":"سَكَنَ","transliteration":"sakana","translation_bn":"স্থিতি লাভ করে","root":"سكن","lemma":"سَكَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15503,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15504,"position":5,"text_uthmani":"ٱلَّيْلِ","transliteration":"al-layli","translation_bn":"রাতের","root":"ليل","lemma":"لَيْل","grammar_bn":"শব্দ"},{"id":15505,"position":6,"text_uthmani":"وَٱلنَّهَارِ ۚ","transliteration":"wal-nahāri","translation_bn":"ও দিনের","root":"نهر","lemma":"نَهَار","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15507,"position":7,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"শব্দ"},{"id":15508,"position":8,"text_uthmani":"ٱلسَّمِيعُ","transliteration":"l-samīʿu","translation_bn":"সবকিছু শুনেন","root":"سمع","lemma":"سَمِيع","grammar_bn":"শব্দ"},{"id":15509,"position":9,"text_uthmani":"ٱلْعَلِيمُ","transliteration":"l-ʿalīmu","translation_bn":"সবকিছু জানেন","root":"علم","lemma":"عَلِيم","grammar_bn":"শব্দ"},{"id":15510,"position":10,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'walahu mā sakana fī al-layli wal-nahāri wahuwa l-samīʿu l-ʿalīmu', 'রাতে (অন্ধকারে) আর দিনে (আলোয়) যা বাস করে তা তাঁরই, তিনি হলেন সর্বশ্রোতা, সর্বজ্ঞ।', 'And to Him belongs that which reposes by night and by day, and He is the Hearing, the Knowing.', 'রাতে (অন্ধকারে) আর দিনে (আলোয়) যা বাস করে তা তাঁরই, তিনি হলেন সর্বশ্রোতা, সর্বজ্ঞ।', 'And to Him belongs that which reposes by night and by day, and He is the Hearing, the Knowing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/006013.mp3', now()),
  (6, 14, '', '[{"id":16527,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16528,"position":2,"text_uthmani":"أَغَيْرَ","transliteration":"aghayra","translation_bn":"\"কি ছাড়া","root":"غير","lemma":"غَيْر","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":16529,"position":3,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":16530,"position":4,"text_uthmani":"أَتَّخِذُ","transliteration":"attakhidhu","translation_bn":"গ্রহণ করবো আমি","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16531,"position":5,"text_uthmani":"وَلِيًّۭا","transliteration":"waliyyan","translation_bn":"অভিভাবক (অন্য)","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":16532,"position":6,"text_uthmani":"فَاطِرِ","transliteration":"fāṭiri","translation_bn":"(অথচ আল্লাহ) স্রষ্টা","root":"فطر","lemma":"فَاطِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":16533,"position":7,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশসমূহের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":16534,"position":8,"text_uthmani":"وَٱلْأَرْضِ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16535,"position":9,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনিই","root":"—","lemma":"وَهُوَ","grammar_bn":"শব্দ"},{"id":16536,"position":10,"text_uthmani":"يُطْعِمُ","transliteration":"yuṭ''ʿimu","translation_bn":"খাওয়ান","root":"طعم","lemma":"أَطْعَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16537,"position":11,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"কিন্তু না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16538,"position":12,"text_uthmani":"يُطْعَمُ ۗ","transliteration":"yuṭ''ʿamu","translation_bn":"খাবার দেয়া হয় তাঁকে\"","root":"طعم","lemma":"أَطْعَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16540,"position":13,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16541,"position":14,"text_uthmani":"إِنِّىٓ","transliteration":"innī","translation_bn":"\"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":16542,"position":15,"text_uthmani":"أُمِرْتُ","transliteration":"umir''tu","translation_bn":"আমাকে আদেশ দেয়া হয়েছে","root":"امر","lemma":"أَمَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16543,"position":16,"text_uthmani":"أَنْ","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":16544,"position":17,"text_uthmani":"أَكُونَ","transliteration":"akūna","translation_bn":"হই আমি","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16545,"position":18,"text_uthmani":"أَوَّلَ","transliteration":"awwala","translation_bn":"প্রথম","root":"اول","lemma":"أَوَّل","grammar_bn":"বিশেষ্য (Noun)"},{"id":16546,"position":19,"text_uthmani":"مَنْ","transliteration":"man","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":16547,"position":20,"text_uthmani":"أَسْلَمَ ۖ","transliteration":"aslama","translation_bn":"আত্মসমর্পণ করে","root":"سلم","lemma":"أَسْلَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16549,"position":21,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":16550,"position":22,"text_uthmani":"تَكُونَنَّ","transliteration":"takūnanna","translation_bn":"তুমি কিছুতেই হয়ো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16551,"position":23,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16552,"position":24,"text_uthmani":"ٱلْمُشْرِكِينَ","transliteration":"l-mush''rikīna","translation_bn":"মুশরিকদের\"","root":"شرك","lemma":"مُشْرِك","grammar_bn":"শব্দ"},{"id":16553,"position":25,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'qul aghayra l-lahi attakhidhu waliyyan fāṭiri l-samāwāti wal-arḍi wahuwa yuṭ''ʿimu walā yuṭ''ʿamu qul innī umir''tu an akūna awwala man aslama walā takūnanna mina l-mush''rikīna', 'বল, আমি কি আসমান যমীনের সৃষ্টিকর্তা আল্লাহকে বাদ দিয়ে অন্যকে অভিভাবক বানিয়ে নেব, অথচ তিনিই খাওয়ান, তাঁকে খাওয়ানো হয় না, বল আমাকে আদেশ করা হয়েছে আমি যেন আত্মসমর্পণকারীদের প্রথম হই, আর তুমি কিছুতেই মুশরিকদের মধ্যে শামিল হবে না।', 'Say, "Is it other than Allah I should take as a protector, Creator of the heavens and the earth, while it is He who feeds and is not fed?" Say, [O Muhammad], "Indeed, I have been commanded to be the first [among you] who submit [to Allah] and [was commanded], ''Do not ever be of the polytheists.'' "', 'বল, আমি কি আসমান যমীনের সৃষ্টিকর্তা আল্লাহকে বাদ দিয়ে অন্যকে অভিভাবক বানিয়ে নেব, অথচ তিনিই খাওয়ান, তাঁকে খাওয়ানো হয় না, বল আমাকে আদেশ করা হয়েছে আমি যেন আত্মসমর্পণকারীদের প্রথম হই, আর তুমি কিছুতেই মুশরিকদের মধ্যে শামিল হবে না।', 'Say, "Is it other than Allah I should take as a protector, Creator of the heavens and the earth, while it is He who feeds and is not fed?" Say, [O Muhammad], "Indeed, I have been commanded to be the first [among you] who submit [to Allah] and [was commanded], ''Do not ever be of the polytheists.'' "', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/006014.mp3', now()),
  (6, 15, '', '[{"id":17734,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17735,"position":2,"text_uthmani":"إِنِّىٓ","transliteration":"innī","translation_bn":"\"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":17736,"position":3,"text_uthmani":"أَخَافُ","transliteration":"akhāfu","translation_bn":"ভয় করি আমি","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17737,"position":4,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":17738,"position":5,"text_uthmani":"عَصَيْتُ","transliteration":"ʿaṣaytu","translation_bn":"আমি অবাধ্য হই","root":"عصي","lemma":"عَصَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":17739,"position":6,"text_uthmani":"رَبِّى","transliteration":"rabbī","translation_bn":"আমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":17740,"position":7,"text_uthmani":"عَذَابَ","transliteration":"ʿadhāba","translation_bn":"শাস্তির","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":17741,"position":8,"text_uthmani":"يَوْمٍ","transliteration":"yawmin","translation_bn":"দিনের\"","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":17742,"position":9,"text_uthmani":"عَظِيمٍۢ","transliteration":"ʿaẓīmin","translation_bn":"ভয়াবহ\"","root":"عظم","lemma":"عَظِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":17743,"position":10,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'qul innī akhāfu in ʿaṣaytu rabbī ʿadhāba yawmin ʿaẓīmin', 'বল, যদি আমি আমার রবের অবাধ্য হই, তবে আমি বড় (ভয়াবহ) দিনের শাস্তির ভয় করি।', 'Say, "Indeed I fear, if I should disobey my Lord, the punishment of a tremendous Day."', 'বল, যদি আমি আমার রবের অবাধ্য হই, তবে আমি বড় (ভয়াবহ) দিনের শাস্তির ভয় করি।', 'Say, "Indeed I fear, if I should disobey my Lord, the punishment of a tremendous Day."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/006015.mp3', now()),
  (6, 16, '', '[{"id":18729,"position":1,"text_uthmani":"مَّن","transliteration":"man","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":18730,"position":2,"text_uthmani":"يُصْرَفْ","transliteration":"yuṣ''raf","translation_bn":"রেহাই পেলো","root":"صرف","lemma":"صَرَفَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18731,"position":3,"text_uthmani":"عَنْهُ","transliteration":"ʿanhu","translation_bn":"থেকে তা","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18732,"position":4,"text_uthmani":"يَوْمَئِذٍۢ","transliteration":"yawma-idhin","translation_bn":"সেদিন","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":18733,"position":5,"text_uthmani":"فَقَدْ","transliteration":"faqad","translation_bn":"তবে নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"ফলাফল পদ (Result)"},{"id":18734,"position":6,"text_uthmani":"رَحِمَهُۥ ۚ","transliteration":"raḥimahu","translation_bn":"তিনি দয়া করলেন তাকে","root":"رحم","lemma":"رَّحِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18736,"position":7,"text_uthmani":"وَذَٰلِكَ","transliteration":"wadhālika","translation_bn":"এবং এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"শব্দ"},{"id":18737,"position":8,"text_uthmani":"ٱلْفَوْزُ","transliteration":"l-fawzu","translation_bn":"সাফল্য","root":"فوز","lemma":"فَوْز","grammar_bn":"শব্দ"},{"id":18738,"position":9,"text_uthmani":"ٱلْمُبِينُ","transliteration":"l-mubīnu","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"শব্দ"},{"id":18739,"position":10,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'man yuṣ''raf ʿanhu yawma-idhin faqad raḥimahu wadhālika l-fawzu l-mubīnu', 'সে দিন যাকে (শাস্তি থেকে) রক্ষা করা হবে তাকে তো বড় অনুগ্রহ করা হবে। আর এটাই হবে সুস্পষ্ট সাফল্য।', 'He from whom it is averted that Day - [Allah] has granted him mercy. And that is the clear attainment.', 'সে দিন যাকে (শাস্তি থেকে) রক্ষা করা হবে তাকে তো বড় অনুগ্রহ করা হবে। আর এটাই হবে সুস্পষ্ট সাফল্য।', 'He from whom it is averted that Day - [Allah] has granted him mercy. And that is the clear attainment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/006016.mp3', now()),
  (6, 17, '', '[{"id":19824,"position":1,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"এবং যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19825,"position":2,"text_uthmani":"يَمْسَسْكَ","transliteration":"yamsaska","translation_bn":"তোমাকে স্পর্শ করেন","root":"مسس","lemma":"مَسَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19826,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19827,"position":4,"text_uthmani":"بِضُرٍّۢ","transliteration":"biḍurrin","translation_bn":"দিয়ে অনিষ্ট","root":"ضرر","lemma":"ضُرّ","grammar_bn":"অব্যয় (Preposition)"},{"id":19828,"position":5,"text_uthmani":"فَلَا","transliteration":"falā","translation_bn":"তবে নেই","root":"—","lemma":"لَا","grammar_bn":"ফলাফল পদ (Result)"},{"id":19829,"position":6,"text_uthmani":"كَاشِفَ","transliteration":"kāshifa","translation_bn":"কোনো অপসারণকারী","root":"كشف","lemma":"كَاشِف","grammar_bn":"বিশেষ্য (Noun)"},{"id":19830,"position":7,"text_uthmani":"لَهُۥٓ","transliteration":"lahu","translation_bn":"জন্যে তার","root":"—","lemma":"لَهُۥٓ","grammar_bn":"অব্যয় (Preposition)"},{"id":19831,"position":8,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"ব্যাখ্যামূলক (Explanation)"},{"id":19832,"position":9,"text_uthmani":"هُوَ ۖ","transliteration":"huwa","translation_bn":"তিনি","root":"—","lemma":"هُوَ ۖ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":19834,"position":10,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"এবং যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19835,"position":11,"text_uthmani":"يَمْسَسْكَ","transliteration":"yamsaska","translation_bn":"তোমাকে স্পর্শ করেন","root":"مسس","lemma":"مَسَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19836,"position":12,"text_uthmani":"بِخَيْرٍۢ","transliteration":"bikhayrin","translation_bn":"দিয়ে কল্যাণ","root":"خير","lemma":"خَيْر","grammar_bn":"অব্যয় (Preposition)"},{"id":19837,"position":13,"text_uthmani":"فَهُوَ","transliteration":"fahuwa","translation_bn":"তবুও তিনি","root":"—","lemma":"فَهُوَ","grammar_bn":"ফলাফল পদ (Result)"},{"id":19838,"position":14,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19839,"position":15,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"সব","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":19840,"position":16,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"কিছুর","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":19841,"position":17,"text_uthmani":"قَدِيرٌۭ","transliteration":"qadīrun","translation_bn":"সর্বশক্তিমান","root":"قدر","lemma":"قَدِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":19842,"position":18,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'wa-in yamsaska l-lahu biḍurrin falā kāshifa lahu illā huwa wa-in yamsaska bikhayrin fahuwa ʿalā kulli shayin qadīrun', 'আল্লাহ তোমার কোন ক্ষতি করতে চাইলে তিনি ছাড়া কেউ তা সরাতে পারবে না। আর তিনি যদি তোমার কল্যাণ করতে চান, তবে তো সব কিছুই করার তাঁর ক্ষমতা রয়েছে।', 'And if Allah should touch you with adversity, there is no remover of it except Him. And if He touches you with good - then He is over all things competent.', 'আল্লাহ তোমার কোন ক্ষতি করতে চাইলে তিনি ছাড়া কেউ তা সরাতে পারবে না। আর তিনি যদি তোমার কল্যাণ করতে চান, তবে তো সব কিছুই করার তাঁর ক্ষমতা রয়েছে।', 'And if Allah should touch you with adversity, there is no remover of it except Him. And if He touches you with good - then He is over all things competent.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/006017.mp3', now()),
  (6, 18, '', '[{"id":20903,"position":1,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনি","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20904,"position":2,"text_uthmani":"ٱلْقَاهِرُ","transliteration":"l-qāhiru","translation_bn":"পরাক্রমশালী","root":"قهر","lemma":"قَاهِر","grammar_bn":"শব্দ"},{"id":20905,"position":3,"text_uthmani":"فَوْقَ","transliteration":"fawqa","translation_bn":"উপর","root":"فوق","lemma":"فَوْق","grammar_bn":"স্থানবাচক (Location)"},{"id":20906,"position":4,"text_uthmani":"عِبَادِهِۦ ۚ","transliteration":"ʿibādihi","translation_bn":"দাসদের তাঁর","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":20908,"position":5,"text_uthmani":"وَهُوَ","transliteration":"wahuwa","translation_bn":"এবং তিনি","root":"—","lemma":"وَهُوَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20909,"position":6,"text_uthmani":"ٱلْحَكِيمُ","transliteration":"l-ḥakīmu","translation_bn":"প্রজ্ঞাময়","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":20910,"position":7,"text_uthmani":"ٱلْخَبِيرُ","transliteration":"l-khabīru","translation_bn":"খুবই অবহিত","root":"خبر","lemma":"خَبِير","grammar_bn":"শব্দ"},{"id":20911,"position":8,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'wahuwa l-qāhiru fawqa ʿibādihi wahuwa l-ḥakīmu l-khabīru', 'তিনি তাঁর বান্দাদের উপর একচ্ছত্র নিয়ন্ত্রণকারী, তিনি হলেন প্রজ্ঞাময়, সর্ববিষয়ে ওয়াকিফহাল।', 'And He is the subjugator over His servants. And He is the Wise, the Acquainted [with all].', 'তিনি তাঁর বান্দাদের উপর একচ্ছত্র নিয়ন্ত্রণকারী, তিনি হলেন প্রজ্ঞাময়, সর্ববিষয়ে ওয়াকিফহাল।', 'And He is the subjugator over His servants. And He is the Wise, the Acquainted [with all].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/006018.mp3', now()),
