  (7, 1, '', '[{"id":813,"position":1,"text_uthmani":"الٓمٓصٓ","transliteration":"alif-lam-meem-sad","translation_bn":"আলীফ-লাম-মীম-সাদ","root":"—","lemma":"الٓمٓصٓ","grammar_bn":"শব্দ"},{"id":814,"position":2,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'alif-lam-meem-sad', 'আলিফ, লাম, মীম, সাদ।', 'Alif, Lam, Meem, Sad.', 'আলিফ, লাম, মীম, সাদ।', 'Alif, Lam, Meem, Sad.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007001.mp3', now()),
  (7, 2, '', '[{"id":1980,"position":1,"text_uthmani":"كِتَـٰبٌ","transliteration":"kitābun","translation_bn":"(এই) কিতাব","root":"كتب","lemma":"كِتَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":1981,"position":2,"text_uthmani":"أُنزِلَ","transliteration":"unzila","translation_bn":"অবতীর্ণ হয়েছে","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1982,"position":3,"text_uthmani":"إِلَيْكَ","transliteration":"ilayka","translation_bn":"তোমার প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1983,"position":4,"text_uthmani":"فَلَا","transliteration":"falā","translation_bn":"অতএব না (যেন)","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":1984,"position":5,"text_uthmani":"يَكُن","transliteration":"yakun","translation_bn":"হয়","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1985,"position":6,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1986,"position":7,"text_uthmani":"صَدْرِكَ","transliteration":"ṣadrika","translation_bn":"তোমার মনের","root":"صدر","lemma":"صَدْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":1987,"position":8,"text_uthmani":"حَرَجٌۭ","transliteration":"ḥarajun","translation_bn":"কোনো সংকোচ","root":"حرج","lemma":"حَرَج","grammar_bn":"বিশেষ্য (Noun)"},{"id":1988,"position":9,"text_uthmani":"مِّنْهُ","transliteration":"min''hu","translation_bn":"হতে তা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1989,"position":10,"text_uthmani":"لِتُنذِرَ","transliteration":"litundhira","translation_bn":"যেন তুমি সতর্ক করো","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"শব্দ"},{"id":1990,"position":11,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"দিয়ে তা","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":1991,"position":12,"text_uthmani":"وَذِكْرَىٰ","transliteration":"wadhik''rā","translation_bn":"এবং (এই কিতাব) উপদেশ","root":"ذكر","lemma":"ذِكْرَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1992,"position":13,"text_uthmani":"لِلْمُؤْمِنِينَ","transliteration":"lil''mu''minīna","translation_bn":"জন্যে মু`মিনদের","root":"امن","lemma":"مُؤْمِن","grammar_bn":"অব্যয় (Preposition)"},{"id":1993,"position":14,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'kitābun unzila ilayka falā yakun fī ṣadrika ḥarajun min''hu litundhira bihi wadhik''rā lil''mu''minīna', 'এটি একটি কিতাব যা তোমার উপর নাযিল করা হয়েছে, এ ব্যাপারে তোমার অন্তরে যেন কোন প্রকার কুণ্ঠাবোধ না হয়, (এটা নাযিল করা হয়েছে অমান্যকারীদেরকে) এর দ্বারা ভয় প্রদর্শনের জন্য এবং মু’মিনদেরকে উপদেশ প্রদানের জন্য।', '[This is] a Book revealed to you, [O Muhammad] - so let there not be in your breast distress therefrom - that you may warn thereby and as a reminder to the believers.', 'এটি একটি কিতাব যা তোমার উপর নাযিল করা হয়েছে, এ ব্যাপারে তোমার অন্তরে যেন কোন প্রকার কুণ্ঠাবোধ না হয়, (এটা নাযিল করা হয়েছে অমান্যকারীদেরকে) এর দ্বারা ভয় প্রদর্শনের জন্য এবং মু’মিনদেরকে উপদেশ প্রদানের জন্য।', '[This is] a Book revealed to you, [O Muhammad] - so let there not be in your breast distress therefrom - that you may warn thereby and as a reminder to the believers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007002.mp3', now()),
  (7, 3, '', '[{"id":3176,"position":1,"text_uthmani":"ٱتَّبِعُوا۟","transliteration":"ittabiʿū","translation_bn":"তোমরা অনুসরন করো","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3177,"position":2,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":3178,"position":3,"text_uthmani":"أُنزِلَ","transliteration":"unzila","translation_bn":"অবতীর্ণ হয়েছে","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3179,"position":4,"text_uthmani":"إِلَيْكُم","transliteration":"ilaykum","translation_bn":"প্রতি তোমাদের প","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3180,"position":5,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"পক্ষ হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3181,"position":6,"text_uthmani":"رَّبِّكُمْ","transliteration":"rabbikum","translation_bn":"রবের তোমাদের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":3182,"position":7,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3183,"position":8,"text_uthmani":"تَتَّبِعُوا۟","transliteration":"tattabiʿū","translation_bn":"তোমরা অনুসরণ করো","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3184,"position":9,"text_uthmani":"مِن","transliteration":"min","translation_bn":"ছাড়া","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3185,"position":10,"text_uthmani":"دُونِهِۦٓ","transliteration":"dūnihi","translation_bn":"তাকে","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":3186,"position":11,"text_uthmani":"أَوْلِيَآءَ ۗ","transliteration":"awliyāa","translation_bn":"(অন্যান্যদেরকে) অভিভাবকরূপে","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":3188,"position":12,"text_uthmani":"قَلِيلًۭا","transliteration":"qalīlan","translation_bn":"(কিন্তু) অল্পই","root":"قلل","lemma":"قَلِيل","grammar_bn":"বিশেষণ (Adjective)"},{"id":3189,"position":13,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সম্পূরক পদ (Supplemental)"},{"id":3190,"position":14,"text_uthmani":"تَذَكَّرُونَ","transliteration":"tadhakkarūna","translation_bn":"তোমরা উপদেশ গ্রহণ করো","root":"ذكر","lemma":"تَذَكَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3191,"position":15,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'ittabiʿū mā unzila ilaykum min rabbikum walā tattabiʿū min dūnihi awliyāa qalīlan mā tadhakkarūna', 'তোমাদের প্রতিপালকের নিকট হতে তোমাদের প্রতি যা অবতীর্ণ হয়েছে তোমরা তা মান্য করে চল, তাঁকে ছাড়া (অন্যদের) অভিভাবক মান্য করো না, তোমরা খুব সামান্য উপদেশই গ্রহণ কর।', 'Follow, [O mankind], what has been revealed to you from your Lord and do not follow other than Him any allies. Little do you remember.', 'তোমাদের প্রতিপালকের নিকট হতে তোমাদের প্রতি যা অবতীর্ণ হয়েছে তোমরা তা মান্য করে চল, তাঁকে ছাড়া (অন্যদের) অভিভাবক মান্য করো না, তোমরা খুব সামান্য উপদেশই গ্রহণ কর।', 'Follow, [O mankind], what has been revealed to you from your Lord and do not follow other than Him any allies. Little do you remember.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007003.mp3', now()),
  (7, 4, '', '[{"id":4532,"position":1,"text_uthmani":"وَكَم","transliteration":"wakam","translation_bn":"এবং কত (সব)","root":"—","lemma":"كَم","grammar_bn":"শব্দ"},{"id":4533,"position":2,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4534,"position":3,"text_uthmani":"قَرْيَةٍ","transliteration":"qaryatin","translation_bn":"জনপদ","root":"قري","lemma":"قَرْيَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":4535,"position":4,"text_uthmani":"أَهْلَكْنَـٰهَا","transliteration":"ahlaknāhā","translation_bn":"ধ্বংস করেছি আমরা তা","root":"هلك","lemma":"أَهْلَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4536,"position":5,"text_uthmani":"فَجَآءَهَا","transliteration":"fajāahā","translation_bn":"তখন উপর এসেছিলো তার","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4537,"position":6,"text_uthmani":"بَأْسُنَا","transliteration":"basunā","translation_bn":"শাস্তি আমাদের","root":"باس","lemma":"بَأْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":4538,"position":7,"text_uthmani":"بَيَـٰتًا","transliteration":"bayātan","translation_bn":"রাতের বেলায়","root":"بيت","lemma":"بَيَٰت","grammar_bn":"বিশেষ্য (Noun)"},{"id":4539,"position":8,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4540,"position":9,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা (ছিলো)","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":4541,"position":10,"text_uthmani":"قَآئِلُونَ","transliteration":"qāilūna","translation_bn":"দুপুরে বিশ্রাম গ্রহণকারী","root":"قيل","lemma":"قَا^ئِلُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":4542,"position":11,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'wakam min qaryatin ahlaknāhā fajāahā basunā bayātan aw hum qāilūna', 'আমি কত জনপদকে ধ্বংস করে দিয়েছি। আমার শাস্তি তাদের নিকট এসেছিল হঠাৎ রাত্রিবেলা কিংবা দুপুর বেলা তারা যখন বিশ্রাম নিচ্ছিল।', 'And how many cities have We destroyed, and Our punishment came to them at night or while they were sleeping at noon.', 'আমি কত জনপদকে ধ্বংস করে দিয়েছি। আমার শাস্তি তাদের নিকট এসেছিল হঠাৎ রাত্রিবেলা কিংবা দুপুর বেলা তারা যখন বিশ্রাম নিচ্ছিল।', 'And how many cities have We destroyed, and Our punishment came to them at night or while they were sleeping at noon.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007004.mp3', now()),
  (7, 5, '', '[{"id":5808,"position":1,"text_uthmani":"فَمَا","transliteration":"famā","translation_bn":"অতঃপর না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5809,"position":2,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5810,"position":3,"text_uthmani":"دَعْوَىٰهُمْ","transliteration":"daʿwāhum","translation_bn":"দাবি তাদের(কথা)","root":"دعو","lemma":"دَعْوَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":5811,"position":4,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":5812,"position":5,"text_uthmani":"جَآءَهُم","transliteration":"jāahum","translation_bn":"তাদের (কাছে) এসেছিলো","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5813,"position":6,"text_uthmani":"بَأْسُنَآ","transliteration":"basunā","translation_bn":"শাস্তি আমাদের","root":"باس","lemma":"بَأْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":5814,"position":7,"text_uthmani":"إِلَّآ","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":5815,"position":8,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":5816,"position":9,"text_uthmani":"قَالُوٓا۟","transliteration":"qālū","translation_bn":"তারা বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5817,"position":10,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"\"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":5818,"position":11,"text_uthmani":"كُنَّا","transliteration":"kunnā","translation_bn":"আমরা ছিলাম","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5819,"position":12,"text_uthmani":"ظَـٰلِمِينَ","transliteration":"ẓālimīna","translation_bn":"সীমালঙ্ঘনকারী\"","root":"ظلم","lemma":"ظَالِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":5820,"position":13,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'famā kāna daʿwāhum idh jāahum basunā illā an qālū innā kunnā ẓālimīna', 'আমার শাস্তি যখন তাদের উপর এসেছিল তখন এ কথা বলা ছাড়া তারা আর কোন ধ্বনি উচ্চারণ করতে পারেনি যে, ‘‘অবশ্যই আমরা যালিম ছিলাম’’।', 'And their declaration when Our punishment came to them was only that they said, "Indeed, we were wrongdoers!"', 'আমার শাস্তি যখন তাদের উপর এসেছিল তখন এ কথা বলা ছাড়া তারা আর কোন ধ্বনি উচ্চারণ করতে পারেনি যে, ‘‘অবশ্যই আমরা যালিম ছিলাম’’।', 'And their declaration when Our punishment came to them was only that they said, "Indeed, we were wrongdoers!"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007005.mp3', now()),
  (7, 6, '', '[{"id":7096,"position":1,"text_uthmani":"فَلَنَسْـَٔلَنَّ","transliteration":"falanasalanna","translation_bn":"অতএব জিজ্ঞাসা করবোই আমরা","root":"سال","lemma":"سَأَلَ","grammar_bn":"শব্দ"},{"id":7097,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"তাদেরকে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":7098,"position":3,"text_uthmani":"أُرْسِلَ","transliteration":"ur''sila","translation_bn":"পাঠান হয়েছিলো","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7099,"position":4,"text_uthmani":"إِلَيْهِمْ","transliteration":"ilayhim","translation_bn":"প্রতি যাদের","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7100,"position":5,"text_uthmani":"وَلَنَسْـَٔلَنَّ","transliteration":"walanasalanna","translation_bn":"ও অবশ্যই জিজ্ঞাসা করবো আমরা","root":"سال","lemma":"سَأَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7101,"position":6,"text_uthmani":"ٱلْمُرْسَلِينَ","transliteration":"l-mur''salīna","translation_bn":"রাসূলদেরকেও","root":"رسل","lemma":"مُّرْسَل","grammar_bn":"শব্দ"},{"id":7102,"position":7,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'falanasalanna alladhīna ur''sila ilayhim walanasalanna l-mur''salīna', 'অতঃপর যাদের নিকট রসূল পাঠানো হয়েছিল আমি অবশ্যই তাদেরকে জিজ্ঞেস করব আর রসূলগণকেও (আল্লাহর বাণী পৌঁছে দেয়া সম্পর্কে) অবশ্যই জিজ্ঞেস করব।', 'Then We will surely question those to whom [a message] was sent, and We will surely question the messengers.', 'অতঃপর যাদের নিকট রসূল পাঠানো হয়েছিল আমি অবশ্যই তাদেরকে জিজ্ঞেস করব আর রসূলগণকেও (আল্লাহর বাণী পৌঁছে দেয়া সম্পর্কে) অবশ্যই জিজ্ঞেস করব।', 'Then We will surely question those to whom [a message] was sent, and We will surely question the messengers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007006.mp3', now()),
  (7, 7, '', '[{"id":8421,"position":1,"text_uthmani":"فَلَنَقُصَّنَّ","transliteration":"falanaquṣṣanna","translation_bn":"অতঃপর ঘটনা বর্ণনা করবোই আমরা","root":"قصص","lemma":"قَصَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8422,"position":2,"text_uthmani":"عَلَيْهِم","transliteration":"ʿalayhim","translation_bn":"কাছে তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8423,"position":3,"text_uthmani":"بِعِلْمٍۢ ۖ","transliteration":"biʿil''min","translation_bn":"ভিত্তিতে জ্ঞানের","root":"علم","lemma":"عِلْم","grammar_bn":"অব্যয় (Preposition)"},{"id":8425,"position":4,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর না","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":8426,"position":5,"text_uthmani":"كُنَّا","transliteration":"kunnā","translation_bn":"আমরা ছিলাম","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8427,"position":6,"text_uthmani":"غَآئِبِينَ","transliteration":"ghāibīna","translation_bn":"অনুপস্থিত","root":"غيب","lemma":"غَا^ئِبِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":8428,"position":7,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'falanaquṣṣanna ʿalayhim biʿil''min wamā kunnā ghāibīna', 'অতঃপর পরিপূর্ণ জ্ঞানের ভিত্তিতে তাদের নিকট তাদের সমস্ত কাহিনী অবশ্যই জানিয়ে দেব, কেননা আমি তো মোটেই অনুপস্থিত ছিলাম না।', 'Then We will surely relate [their deeds] to them with knowledge, and We were not [at all] absent.', 'অতঃপর পরিপূর্ণ জ্ঞানের ভিত্তিতে তাদের নিকট তাদের সমস্ত কাহিনী অবশ্যই জানিয়ে দেব, কেননা আমি তো মোটেই অনুপস্থিত ছিলাম না।', 'Then We will surely relate [their deeds] to them with knowledge, and We were not [at all] absent.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007007.mp3', now()),
  (7, 8, '', '[{"id":9610,"position":1,"text_uthmani":"وَٱلْوَزْنُ","transliteration":"wal-waznu","translation_bn":"এবং ওজন","root":"وزن","lemma":"وَزْن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9611,"position":2,"text_uthmani":"يَوْمَئِذٍ","transliteration":"yawma-idhin","translation_bn":"সেদিন (হবে)","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":9612,"position":3,"text_uthmani":"ٱلْحَقُّ ۚ","transliteration":"l-ḥaqu","translation_bn":"যথার্থই","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":9614,"position":4,"text_uthmani":"فَمَن","transliteration":"faman","translation_bn":"অতঃপর যার","root":"—","lemma":"مَن\r","grammar_bn":"শব্দ"},{"id":9615,"position":5,"text_uthmani":"ثَقُلَتْ","transliteration":"thaqulat","translation_bn":"ভারী হবে","root":"ثقل","lemma":"ثَقُلَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9616,"position":6,"text_uthmani":"مَوَٰزِينُهُۥ","transliteration":"mawāzīnuhu","translation_bn":"পাল্লাসমূহ তার","root":"وزن","lemma":"مِيزَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":9617,"position":7,"text_uthmani":"فَأُو۟لَـٰٓئِكَ","transliteration":"fa-ulāika","translation_bn":"অতঃপর ঐসব লোক","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"ফলাফল পদ (Result)"},{"id":9618,"position":8,"text_uthmani":"هُمُ","transliteration":"humu","translation_bn":"তারাই","root":"—","lemma":"هُمُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":9619,"position":9,"text_uthmani":"ٱلْمُفْلِحُونَ","transliteration":"l-muf''liḥūna","translation_bn":"সফলকাম (হবে)","root":"فلح","lemma":"مُفْلِحُون","grammar_bn":"শব্দ"},{"id":9620,"position":10,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'wal-waznu yawma-idhin l-ḥaqu faman thaqulat mawāzīnuhu fa-ulāika humu l-muf''liḥūna', 'সেদিনের ওজন হবে ঠিক ঠিক। ফলে যাদের পাল্লা ভারী হবে তারা সফলকাম হবে।', 'And the weighing [of deeds] that Day will be the truth. So those whose scales are heavy - it is they who will be the successful.', 'সেদিনের ওজন হবে ঠিক ঠিক। ফলে যাদের পাল্লা ভারী হবে তারা সফলকাম হবে।', 'And the weighing [of deeds] that Day will be the truth. So those whose scales are heavy - it is they who will be the successful.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007008.mp3', now()),
  (7, 9, '', '[{"id":10772,"position":1,"text_uthmani":"وَمَنْ","transliteration":"waman","translation_bn":"এবং যার","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10773,"position":2,"text_uthmani":"خَفَّتْ","transliteration":"khaffat","translation_bn":"হালকা হবে","root":"خفف","lemma":"خَفَّتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10774,"position":3,"text_uthmani":"مَوَٰزِينُهُۥ","transliteration":"mawāzīnuhu","translation_bn":"পাল্লাসমূহ তার","root":"وزن","lemma":"مِيزَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":10775,"position":4,"text_uthmani":"فَأُو۟لَـٰٓئِكَ","transliteration":"fa-ulāika","translation_bn":"অতঃপর ঐসবলোক","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"ফলাফল পদ (Result)"},{"id":10776,"position":5,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তারাই) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":10777,"position":6,"text_uthmani":"خَسِرُوٓا۟","transliteration":"khasirū","translation_bn":"ক্ষতি করেছে","root":"خسر","lemma":"خَسِرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10778,"position":7,"text_uthmani":"أَنفُسَهُم","transliteration":"anfusahum","translation_bn":"নিজেদেরকে তাদের","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":10779,"position":8,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"একারণে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10780,"position":9,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10781,"position":10,"text_uthmani":"بِـَٔايَـٰتِنَا","transliteration":"biāyātinā","translation_bn":"সাথে আমাদের নির্দশনাদির","root":"ايي","lemma":"ءَايَة","grammar_bn":"অব্যয় (Preposition)"},{"id":10782,"position":11,"text_uthmani":"يَظْلِمُونَ","transliteration":"yaẓlimūna","translation_bn":"সীমালঙ্ঘন করতো","root":"ظلم","lemma":"ظَلَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10783,"position":12,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'waman khaffat mawāzīnuhu fa-ulāika alladhīna khasirū anfusahum bimā kānū biāyātinā yaẓlimūna', 'যাদের পাল্লা হালকা হবে তারা হল যারা নিজেদেরকে ক্ষতিগ্রস্ত করেছে, কারণ তারা আমার নিদর্শনসমূহকে প্রত্যাখ্যান করেছিল।', 'And those whose scales are light - they are the ones who will lose themselves for what injustice they were doing toward Our verses.', 'যাদের পাল্লা হালকা হবে তারা হল যারা নিজেদেরকে ক্ষতিগ্রস্ত করেছে, কারণ তারা আমার নিদর্শনসমূহকে প্রত্যাখ্যান করেছিল।', 'And those whose scales are light - they are the ones who will lose themselves for what injustice they were doing toward Our verses.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007009.mp3', now()),
  (7, 10, '', '[{"id":12026,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"শব্দ"},{"id":12027,"position":2,"text_uthmani":"مَكَّنَّـٰكُمْ","transliteration":"makkannākum","translation_bn":"আমরা প্রতিষ্ঠিত করেছি তোমাদেরকে","root":"مكن","lemma":"مَكَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12028,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"উপর","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12029,"position":4,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":12030,"position":5,"text_uthmani":"وَجَعَلْنَا","transliteration":"wajaʿalnā","translation_bn":"এবং ব্যবস্হা করেছি আমরা","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12031,"position":6,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":12032,"position":7,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"মধ্যে তার","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12033,"position":8,"text_uthmani":"مَعَـٰيِشَ ۗ","transliteration":"maʿāyisha","translation_bn":"জীবিকার","root":"عيش","lemma":"مَعَٰيِش","grammar_bn":"বিশেষ্য (Noun)"},{"id":12035,"position":9,"text_uthmani":"قَلِيلًۭا","transliteration":"qalīlan","translation_bn":"(কিন্তু) অল্পই","root":"قلل","lemma":"قَلِيل","grammar_bn":"বিশেষণ (Adjective)"},{"id":12036,"position":10,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সম্পূরক পদ (Supplemental)"},{"id":12037,"position":11,"text_uthmani":"تَشْكُرُونَ","transliteration":"tashkurūna","translation_bn":"তোমরা কৃতজ্ঞতা জ্ঞাপন করো","root":"شكر","lemma":"شَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12038,"position":12,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad makkannākum fī l-arḍi wajaʿalnā lakum fīhā maʿāyisha qalīlan mā tashkurūna', 'আমি তোমাদেরকে যমীনে প্রতিষ্ঠিত করেছি; আর সেখানে তোমাদের জন্য জীবিকার ব্যবস্থা করেছি তোমরা খুব সামান্যই কৃতজ্ঞতা প্রকাশ কর।', 'And We have certainly established you upon the earth and made for you therein ways of livelihood. Little are you grateful.', 'আমি তোমাদেরকে যমীনে প্রতিষ্ঠিত করেছি; আর সেখানে তোমাদের জন্য জীবিকার ব্যবস্থা করেছি তোমরা খুব সামান্যই কৃতজ্ঞতা প্রকাশ কর।', 'And We have certainly established you upon the earth and made for you therein ways of livelihood. Little are you grateful.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007010.mp3', now()),
  (7, 11, '', '[{"id":13350,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13351,"position":2,"text_uthmani":"خَلَقْنَـٰكُمْ","transliteration":"khalaqnākum","translation_bn":"সৃষ্টি করেছি আমরা তোমাদের","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13352,"position":3,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13353,"position":4,"text_uthmani":"صَوَّرْنَـٰكُمْ","transliteration":"ṣawwarnākum","translation_bn":"রূপদান করেছি আমরা তোমাদেরকে","root":"صور","lemma":"صَوَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13354,"position":5,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13355,"position":6,"text_uthmani":"قُلْنَا","transliteration":"qul''nā","translation_bn":"বলেছিলাম আমরা","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13356,"position":7,"text_uthmani":"لِلْمَلَـٰٓئِكَةِ","transliteration":"lil''malāikati","translation_bn":"উদ্দেশ্যে ফেরেশতাদের","root":"ملك","lemma":"مَلَك","grammar_bn":"অব্যয় (Preposition)"},{"id":13357,"position":8,"text_uthmani":"ٱسْجُدُوا۟","transliteration":"us''judū","translation_bn":"\"তোমরা সিজদা করো","root":"سجد","lemma":"سَجَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13358,"position":9,"text_uthmani":"لِـَٔادَمَ","transliteration":"liādama","translation_bn":"উদ্দেশ্যে আদমের\"","root":"—","lemma":"ا^دَم","grammar_bn":"অব্যয় (Preposition)"},{"id":13359,"position":10,"text_uthmani":"فَسَجَدُوٓا۟","transliteration":"fasajadū","translation_bn":"অতঃপর তারা সিজদা করলো","root":"سجد","lemma":"سَجَدَ","grammar_bn":"শব্দ"},{"id":13360,"position":11,"text_uthmani":"إِلَّآ","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"ব্যাখ্যামূলক (Explanation)"},{"id":13361,"position":12,"text_uthmani":"إِبْلِيسَ","transliteration":"ib''līsa","translation_bn":"ইবলীস","root":"—","lemma":"إِبْلِيس","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":13362,"position":13,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"নি","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":13363,"position":14,"text_uthmani":"يَكُن","transliteration":"yakun","translation_bn":"সে হয়","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13364,"position":15,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13365,"position":16,"text_uthmani":"ٱلسَّـٰجِدِينَ","transliteration":"l-sājidīna","translation_bn":"সিজদাকারীদের","root":"سجد","lemma":"سَاجِد","grammar_bn":"শব্দ"},{"id":13366,"position":17,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad khalaqnākum thumma ṣawwarnākum thumma qul''nā lil''malāikati us''judū liādama fasajadū illā ib''līsa lam yakun mina l-sājidīna', 'আমি তো তোমাদেরকে সৃষ্টি করেছি, অতঃপর তোমাদের আকৃতি দিয়েছি, অতঃপর ফেরেশতাদের নির্দেশ দিলাম আদামকে সাজদাহ করার জন্য। তখন ইবলিস ছাড়া সবাই সিজদা করল। সে সিজদাকারীদের অন্তর্ভুক্ত হল না।', 'And We have certainly created you, [O Mankind], and given you [human] form. Then We said to the angels, "Prostrate to Adam"; so they prostrated, except for Iblees. He was not of those who prostrated.', 'আমি তো তোমাদেরকে সৃষ্টি করেছি, অতঃপর তোমাদের আকৃতি দিয়েছি, অতঃপর ফেরেশতাদের নির্দেশ দিলাম আদামকে সাজদাহ করার জন্য। তখন ইবলিস ছাড়া সবাই সিজদা করল। সে সিজদাকারীদের অন্তর্ভুক্ত হল না।', 'And We have certainly created you, [O Mankind], and given you [human] form. Then We said to the angels, "Prostrate to Adam"; so they prostrated, except for Iblees. He was not of those who prostrated.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007011.mp3', now()),
  (7, 12, '', '[{"id":14629,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(আল্লাহ) বললেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14630,"position":2,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"\"কিসে","root":"—","lemma":"مَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":14631,"position":3,"text_uthmani":"مَنَعَكَ","transliteration":"manaʿaka","translation_bn":"তোমাকে বাধা দিলো","root":"منع","lemma":"مَّنَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14632,"position":4,"text_uthmani":"أَلَّا","transliteration":"allā","translation_bn":"যে না","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":14633,"position":5,"text_uthmani":"تَسْجُدَ","transliteration":"tasjuda","translation_bn":"তুমি সিজদা করলে (আদমকে)","root":"سجد","lemma":"سَجَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14634,"position":6,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":14635,"position":7,"text_uthmani":"أَمَرْتُكَ ۖ","transliteration":"amartuka","translation_bn":"তোমাকে আমি নির্দেশ দিয়েছি\"","root":"امر","lemma":"أَمَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14637,"position":8,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(ইবলীস) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14638,"position":9,"text_uthmani":"أَنَا۠","transliteration":"anā","translation_bn":"\"আমি","root":"—","lemma":"أَنَا۠","grammar_bn":"সর্বনাম (Pronoun)"},{"id":14639,"position":10,"text_uthmani":"خَيْرٌۭ","transliteration":"khayrun","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":14640,"position":11,"text_uthmani":"مِّنْهُ","transliteration":"min''hu","translation_bn":"চেয়েও তার","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14641,"position":12,"text_uthmani":"خَلَقْتَنِى","transliteration":"khalaqtanī","translation_bn":"আপনি সৃষ্টি করেছেন আমাকে","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14642,"position":13,"text_uthmani":"مِن","transliteration":"min","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14643,"position":14,"text_uthmani":"نَّارٍۢ","transliteration":"nārin","translation_bn":"আগুন","root":"نور","lemma":"نَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":14644,"position":15,"text_uthmani":"وَخَلَقْتَهُۥ","transliteration":"wakhalaqtahu","translation_bn":"এবং আপনি সৃষ্টি করেছেন তাকে","root":"خلق","lemma":"خَلَقَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14645,"position":16,"text_uthmani":"مِن","transliteration":"min","translation_bn":"দিয়ে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14646,"position":17,"text_uthmani":"طِينٍۢ","transliteration":"ṭīnin","translation_bn":"কাদা মাটি\"","root":"طين","lemma":"طِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":14647,"position":18,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'qāla mā manaʿaka allā tasjuda idh amartuka qāla anā khayrun min''hu khalaqtanī min nārin wakhalaqtahu min ṭīnin', '(আল্লাহ) বললেন, ‘আমি নির্দেশ দেয়ার পরেও কিসে তোকে সাজদাহ থেকে নিবৃত্ত রাখল?’ সে বলল, ‘আমি তার চেয়ে উত্তম, আমাকে সৃষ্টি করেছ আগুন থেকে আর তাকে সৃষ্টি করেছ কাদা থেকে।’', '[Allah] said, "What prevented you from prostrating when I commanded you?" [Satan] said, "I am better than him. You created me from fire and created him from clay."', '(আল্লাহ) বললেন, ‘আমি নির্দেশ দেয়ার পরেও কিসে তোকে সাজদাহ থেকে নিবৃত্ত রাখল?’ সে বলল, ‘আমি তার চেয়ে উত্তম, আমাকে সৃষ্টি করেছ আগুন থেকে আর তাকে সৃষ্টি করেছ কাদা থেকে।’', '[Allah] said, "What prevented you from prostrating when I commanded you?" [Satan] said, "I am better than him. You created me from fire and created him from clay."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007012.mp3', now()),
  (7, 13, '', '[{"id":15719,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(আল্লা্হ) বললেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15720,"position":2,"text_uthmani":"فَٱهْبِطْ","transliteration":"fa-ih''biṭ","translation_bn":"\"তাহ''লে তুমি নেমে যাও","root":"هبط","lemma":"يَهْبِطُ","grammar_bn":"সম্পূরক পদ (Supplemental)"},{"id":15721,"position":3,"text_uthmani":"مِنْهَا","transliteration":"min''hā","translation_bn":"থেকে এখান","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15722,"position":4,"text_uthmani":"فَمَا","transliteration":"famā","translation_bn":"কারণ না","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":15723,"position":5,"text_uthmani":"يَكُونُ","transliteration":"yakūnu","translation_bn":"হতে পারে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15724,"position":6,"text_uthmani":"لَكَ","transliteration":"laka","translation_bn":"জন্যে তোমার","root":"—","lemma":"لَكَ","grammar_bn":"অব্যয় (Preposition)"},{"id":15725,"position":7,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":15726,"position":8,"text_uthmani":"تَتَكَبَّرَ","transliteration":"tatakabbara","translation_bn":"অহংকার করবে তুমি","root":"كبر","lemma":"يَتَكَبَّرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15727,"position":9,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"মধ্যে এর","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15728,"position":10,"text_uthmani":"فَٱخْرُجْ","transliteration":"fa-ukh''ruj","translation_bn":"অতএব তুমি বের হও","root":"خرج","lemma":"خَرَجَ","grammar_bn":"শব্দ"},{"id":15729,"position":11,"text_uthmani":"إِنَّكَ","transliteration":"innaka","translation_bn":"নিশ্চয়ই তুমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":15730,"position":12,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15731,"position":13,"text_uthmani":"ٱلصَّـٰغِرِينَ","transliteration":"l-ṣāghirīna","translation_bn":"অধমদের\"","root":"صغر","lemma":"صَٰغِرُون","grammar_bn":"শব্দ"},{"id":15732,"position":14,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'qāla fa-ih''biṭ min''hā famā yakūnu laka an tatakabbara fīhā fa-ukh''ruj innaka mina l-ṣāghirīna', 'তিনি বললেন, ‘নেমে যা এখান থেকে, এর ভিতরে থেকে অহঙ্কার করবে তা হতে পারে না, অতএব বেরিয়ে যা, অধমদের মাঝে তোর স্থান।’', '[Allah] said, "Descend from Paradise, for it is not for you to be arrogant therein. So get out; indeed, you are of the debased.', 'তিনি বললেন, ‘নেমে যা এখান থেকে, এর ভিতরে থেকে অহঙ্কার করবে তা হতে পারে না, অতএব বেরিয়ে যা, অধমদের মাঝে তোর স্থান।’', '[Allah] said, "Descend from Paradise, for it is not for you to be arrogant therein. So get out; indeed, you are of the debased.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007013.mp3', now()),
  (7, 14, '', '[{"id":16782,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(ইবলীস) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16783,"position":2,"text_uthmani":"أَنظِرْنِىٓ","transliteration":"anẓir''nī","translation_bn":"\"আমাকে অবকাশ দিন","root":"نظر","lemma":"يُنظَرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16784,"position":3,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"পর্যন্ত","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16785,"position":4,"text_uthmani":"يَوْمِ","transliteration":"yawmi","translation_bn":"(ঐ) দিন","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":16786,"position":5,"text_uthmani":"يُبْعَثُونَ","transliteration":"yub''ʿathūna","translation_bn":"(যখন) তারা উত্থিত হবে\"","root":"بعث","lemma":"بَعَثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16787,"position":6,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'qāla anẓir''nī ilā yawmi yub''ʿathūna', 'সে বলল, ‘তাহলে যেদিন সবাই (দুনিয়া ছেড়ে) উঠবে সেদিন পর্যন্ত আমাকে সময় দাও।’', '[Satan] said, "Reprieve me until the Day they are resurrected."', 'সে বলল, ‘তাহলে যেদিন সবাই (দুনিয়া ছেড়ে) উঠবে সেদিন পর্যন্ত আমাকে সময় দাও।’', '[Satan] said, "Reprieve me until the Day they are resurrected."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007014.mp3', now()),
  (7, 15, '', '[{"id":17942,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(আল্লাহ) বললেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17943,"position":2,"text_uthmani":"إِنَّكَ","transliteration":"innaka","translation_bn":"\"নিশ্চয়ই তুমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":17944,"position":3,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17945,"position":4,"text_uthmani":"ٱلْمُنظَرِينَ","transliteration":"l-munẓarīna","translation_bn":"অবকাশ প্রাপ্তদের\"","root":"نظر","lemma":"مُنظَرُون","grammar_bn":"শব্দ"},{"id":17946,"position":5,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'qāla innaka mina l-munẓarīna', 'তিনি বললেন, নিশ্চয়ই তুই নিকৃষ্টদের অন্তর্ভুক্ত', '[Allah] said, "Indeed, you are of those reprieved."', 'তিনি বললেন, নিশ্চয়ই তুই নিকৃষ্টদের অন্তর্ভুক্ত', '[Allah] said, "Indeed, you are of those reprieved."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007015.mp3', now()),
  (7, 16, '', '[{"id":18951,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18952,"position":2,"text_uthmani":"فَبِمَآ","transliteration":"fabimā","translation_bn":"\"অতঃপর যে কারণে","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":18953,"position":3,"text_uthmani":"أَغْوَيْتَنِى","transliteration":"aghwaytanī","translation_bn":"আপনি পথভ্রষ্ট করলেন আমাকে","root":"غوي","lemma":"أَغْوَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18954,"position":4,"text_uthmani":"لَأَقْعُدَنَّ","transliteration":"la-aqʿudanna","translation_bn":"অবশ্যই আমি ওৎ পেতে বসবোই","root":"قعد","lemma":"قَعَدَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":18955,"position":5,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"জন্যে তাদের","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":18956,"position":6,"text_uthmani":"صِرَٰطَكَ","transliteration":"ṣirāṭaka","translation_bn":"তোমার পথে","root":"صرط","lemma":"صِرَٰط","grammar_bn":"বিশেষ্য (Noun)"},{"id":18957,"position":7,"text_uthmani":"ٱلْمُسْتَقِيمَ","transliteration":"l-mus''taqīma","translation_bn":"(যা) সরল সঠিক","root":"قوم","lemma":"مُّسْتَقِيم","grammar_bn":"শব্দ"},{"id":18958,"position":8,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'qāla fabimā aghwaytanī la-aqʿudanna lahum ṣirāṭaka l-mus''taqīma', 'সে বলল, যেহেতু তার কারণেই (পথ থেকে) আমাকে ছুঁড়ে ফেলে দিয়েছ, কাজেই আমি অবশ্যই তোমার সরল পথে মানুষদের জন্য ওঁৎ পেতে থাকব।', '[Satan] said, "Because You have put me in error, I will surely sit in wait for them on Your straight path.', 'সে বলল, যেহেতু তার কারণেই (পথ থেকে) আমাকে ছুঁড়ে ফেলে দিয়েছ, কাজেই আমি অবশ্যই তোমার সরল পথে মানুষদের জন্য ওঁৎ পেতে থাকব।', '[Satan] said, "Because You have put me in error, I will surely sit in wait for them on Your straight path.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007016.mp3', now()),
  (7, 17, '', '[{"id":20055,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20056,"position":2,"text_uthmani":"لَـَٔاتِيَنَّهُم","transliteration":"laātiyannahum","translation_bn":"অবশ্যই আমি আসবোই কাছে তাদের","root":"اتي","lemma":"أَتَى","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":20057,"position":3,"text_uthmani":"مِّنۢ","transliteration":"min","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20058,"position":4,"text_uthmani":"بَيْنِ","transliteration":"bayni","translation_bn":"মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":20059,"position":5,"text_uthmani":"أَيْدِيهِمْ","transliteration":"aydīhim","translation_bn":"হাতের তাদের","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":20060,"position":6,"text_uthmani":"وَمِنْ","transliteration":"wamin","translation_bn":"ও হতে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20061,"position":7,"text_uthmani":"خَلْفِهِمْ","transliteration":"khalfihim","translation_bn":"পিছন তাদের","root":"خلف","lemma":"خَلْف","grammar_bn":"বিশেষ্য (Noun)"},{"id":20062,"position":8,"text_uthmani":"وَعَنْ","transliteration":"waʿan","translation_bn":"ও হতে","root":"—","lemma":"عَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20063,"position":9,"text_uthmani":"أَيْمَـٰنِهِمْ","transliteration":"aymānihim","translation_bn":"ডানদিক তাদের","root":"يمن","lemma":"يَمِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":20064,"position":10,"text_uthmani":"وَعَن","transliteration":"waʿan","translation_bn":"ও হতে","root":"—","lemma":"عَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20065,"position":11,"text_uthmani":"شَمَآئِلِهِمْ ۖ","transliteration":"shamāilihim","translation_bn":"বামদিক তাদের","root":"شمل","lemma":"شَمَا^ئِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":20067,"position":12,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20068,"position":13,"text_uthmani":"تَجِدُ","transliteration":"tajidu","translation_bn":"তুমি পাবে","root":"وجد","lemma":"وَجَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20069,"position":14,"text_uthmani":"أَكْثَرَهُمْ","transliteration":"aktharahum","translation_bn":"অধিকাংশকে তাদের","root":"كثر","lemma":"أَكْثَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":20070,"position":15,"text_uthmani":"شَـٰكِرِينَ","transliteration":"shākirīna","translation_bn":"কৃতজ্ঞরূপে\"","root":"شكر","lemma":"شَاكِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":20071,"position":16,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'thumma laātiyannahum min bayni aydīhim wamin khalfihim waʿan aymānihim waʿan shamāilihim walā tajidu aktharahum shākirīna', 'তারপর আমি তাদের সামনে দিয়ে, তাদের পেছন দিয়ে, তাদের ডান দিয়ে, তাদের বাম দিয়ে, তাদের কাছে অবশ্যই আসব, তুমি তাদের অধিকাংশকেই শোকর আদায়কারী পাবে না।', 'Then I will come to them from before them and from behind them and on their right and on their left, and You will not find most of them grateful [to You]."', 'তারপর আমি তাদের সামনে দিয়ে, তাদের পেছন দিয়ে, তাদের ডান দিয়ে, তাদের বাম দিয়ে, তাদের কাছে অবশ্যই আসব, তুমি তাদের অধিকাংশকেই শোকর আদায়কারী পাবে না।', 'Then I will come to them from before them and from behind them and on their right and on their left, and You will not find most of them grateful [to You]."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007017.mp3', now()),
  (7, 18, '', '[{"id":21147,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(আল্লাহ) বললেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21148,"position":2,"text_uthmani":"ٱخْرُجْ","transliteration":"ukh''ruj","translation_bn":"\"তুমি বের হও","root":"خرج","lemma":"خَرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21149,"position":3,"text_uthmani":"مِنْهَا","transliteration":"min''hā","translation_bn":"হতে এখান","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21150,"position":4,"text_uthmani":"مَذْءُومًۭا","transliteration":"madhūman","translation_bn":"ধিকৃতরূপে","root":"ذام","lemma":"مَذْءُوم","grammar_bn":"বিশেষ্য (Noun)"},{"id":21151,"position":5,"text_uthmani":"مَّدْحُورًۭا ۖ","transliteration":"madḥūran","translation_bn":"বিতাড়িত হয়ে","root":"دحر","lemma":"مَّدْحُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":21153,"position":6,"text_uthmani":"لَّمَن","transliteration":"laman","translation_bn":"অবশ্যই যে","root":"—","lemma":"مَن\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":21154,"position":7,"text_uthmani":"تَبِعَكَ","transliteration":"tabiʿaka","translation_bn":"তোমাকে অনুসরণ করবে","root":"تبع","lemma":"تَبِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21155,"position":8,"text_uthmani":"مِنْهُمْ","transliteration":"min''hum","translation_bn":"মধ্য হতে তাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21156,"position":9,"text_uthmani":"لَأَمْلَأَنَّ","transliteration":"la-amla-anna","translation_bn":"অবশ্যই পূর্ণ করব আমি","root":"ملا","lemma":"مُلِئَتْ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":21157,"position":10,"text_uthmani":"جَهَنَّمَ","transliteration":"jahannama","translation_bn":"জাহান্নামকে","root":"—","lemma":"جَهَنَّم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":21158,"position":11,"text_uthmani":"مِنكُمْ","transliteration":"minkum","translation_bn":"দিয়ে তোমাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21159,"position":12,"text_uthmani":"أَجْمَعِينَ","transliteration":"ajmaʿīna","translation_bn":"সবাইকে","root":"جمع","lemma":"أَجْمَعِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":21160,"position":13,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'qāla ukh''ruj min''hā madhūman madḥūran laman tabiʿaka min''hum la-amla-anna jahannama minkum ajmaʿīna', 'তিনি বললেন, ধিকৃত আর বিতাড়িত হয়ে এখান থেকে বেরিয়ে যা, তাদের মধ্যে যারা তোকে মান্য করবে তোমাদের সবাইকে দিয়ে আমি অবশ্যই জাহান্নাম ভর্তি করব।', '[Allah] said, "Get out of Paradise, reproached and expelled. Whoever follows you among them - I will surely fill Hell with you, all together."', 'তিনি বললেন, ধিকৃত আর বিতাড়িত হয়ে এখান থেকে বেরিয়ে যা, তাদের মধ্যে যারা তোকে মান্য করবে তোমাদের সবাইকে দিয়ে আমি অবশ্যই জাহান্নাম ভর্তি করব।', '[Allah] said, "Get out of Paradise, reproached and expelled. Whoever follows you among them - I will surely fill Hell with you, all together."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007018.mp3', now()),
  (7, 19, '', '[{"id":22258,"position":1,"text_uthmani":"وَيَـٰٓـَٔادَمُ","transliteration":"wayāādamu","translation_bn":"এবং হে আদম","root":"—","lemma":"ا^دَم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22259,"position":2,"text_uthmani":"ٱسْكُنْ","transliteration":"us''kun","translation_bn":"বসবাস করো","root":"سكن","lemma":"سَكَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22260,"position":3,"text_uthmani":"أَنتَ","transliteration":"anta","translation_bn":"তুমি","root":"—","lemma":"أَنتَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":22261,"position":4,"text_uthmani":"وَزَوْجُكَ","transliteration":"wazawjuka","translation_bn":"ও তোমার স্ত্রী","root":"زوج","lemma":"زَوْج","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22262,"position":5,"text_uthmani":"ٱلْجَنَّةَ","transliteration":"l-janata","translation_bn":"জান্নাতে","root":"جنن","lemma":"جَنَّة","grammar_bn":"শব্দ"},{"id":22263,"position":6,"text_uthmani":"فَكُلَا","transliteration":"fakulā","translation_bn":"অতঃপর দু''জনে খাও","root":"اكل","lemma":"أَكَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22264,"position":7,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22265,"position":8,"text_uthmani":"حَيْثُ","transliteration":"ḥaythu","translation_bn":"যেখান","root":"حيث","lemma":"حَيْث","grammar_bn":"বিশেষ্য (Noun)"},{"id":22266,"position":9,"text_uthmani":"شِئْتُمَا","transliteration":"shi''tumā","translation_bn":"তোমরা দু''জনে চাও","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22267,"position":10,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"তবে না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22268,"position":11,"text_uthmani":"تَقْرَبَا","transliteration":"taqrabā","translation_bn":"দু''জনে নিকটে হবে","root":"قرب","lemma":"يَقْرَبُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22269,"position":12,"text_uthmani":"هَـٰذِهِ","transliteration":"hādhihi","translation_bn":"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":22270,"position":13,"text_uthmani":"ٱلشَّجَرَةَ","transliteration":"l-shajarata","translation_bn":"গাছের","root":"شجر","lemma":"شَجَرَة","grammar_bn":"শব্দ"},{"id":22271,"position":14,"text_uthmani":"فَتَكُونَا","transliteration":"fatakūnā","translation_bn":"তাহ''লে দু''জনে হবে","root":"كون","lemma":"كَانَ","grammar_bn":"কারণবাচক (Cause)"},{"id":22272,"position":15,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22273,"position":16,"text_uthmani":"ٱلظَّـٰلِمِينَ","transliteration":"l-ẓālimīna","translation_bn":"সীমালঙ্ঘনকারীদের\"","root":"ظلم","lemma":"ظَالِم","grammar_bn":"শব্দ"},{"id":22274,"position":17,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'wayāādamu us''kun anta wazawjuka l-janata fakulā min ḥaythu shi''tumā walā taqrabā hādhihi l-shajarata fatakūnā mina l-ẓālimīna', '‘আর, হে আদাম! তুমি ও তোমার স্ত্রী জান্নাতে বাস করতে থাক, দু’জনে যা পছন্দ হয় খাও আর এই গাছের কাছে যেও না, তাহলে যালিমদের দলে শামিল হয়ে যাবে।’', 'And "O Adam, dwell, you and your wife, in Paradise and eat from wherever you will but do not approach this tree, lest you be among the wrongdoers."', '‘আর, হে আদাম! তুমি ও তোমার স্ত্রী জান্নাতে বাস করতে থাক, দু’জনে যা পছন্দ হয় খাও আর এই গাছের কাছে যেও না, তাহলে যালিমদের দলে শামিল হয়ে যাবে।’', 'And "O Adam, dwell, you and your wife, in Paradise and eat from wherever you will but do not approach this tree, lest you be among the wrongdoers."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007019.mp3', now()),
  (7, 20, '', '[{"id":23303,"position":1,"text_uthmani":"فَوَسْوَسَ","transliteration":"fawaswasa","translation_bn":"অতঃপর কুমন্ত্রণা দিলো","root":"وسوس","lemma":"وَسْوَسَ","grammar_bn":"শব্দ"},{"id":23304,"position":2,"text_uthmani":"لَهُمَا","transliteration":"lahumā","translation_bn":"প্রতি তাদের দুজনের","root":"—","lemma":"لَهُمَا","grammar_bn":"অব্যয় (Preposition)"},{"id":23305,"position":3,"text_uthmani":"ٱلشَّيْطَـٰنُ","transliteration":"l-shayṭānu","translation_bn":"শয়তান","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"শব্দ"},{"id":23306,"position":4,"text_uthmani":"لِيُبْدِىَ","transliteration":"liyub''diya","translation_bn":"যেন প্রকাশ করে দেয়","root":"بدو","lemma":"يُبْدِىَ","grammar_bn":"শব্দ"},{"id":23307,"position":5,"text_uthmani":"لَهُمَا","transliteration":"lahumā","translation_bn":"কাছে তাদের দু''জনের","root":"—","lemma":"لَهُمَا","grammar_bn":"অব্যয় (Preposition)"},{"id":23308,"position":6,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":23309,"position":7,"text_uthmani":"وُۥرِىَ","transliteration":"wūriya","translation_bn":"গোপন রাখা হয়েছিলো","root":"وري","lemma":"وُ,رِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23310,"position":8,"text_uthmani":"عَنْهُمَا","transliteration":"ʿanhumā","translation_bn":"নিকট তাদের দুজন","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23311,"position":9,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23312,"position":10,"text_uthmani":"سَوْءَٰتِهِمَا","transliteration":"sawātihimā","translation_bn":"দুজনের লজ্জাস্থানগুলো তাদের","root":"سوا","lemma":"سَوْءَٰت","grammar_bn":"বিশেষ্য (Noun)"},{"id":23313,"position":11,"text_uthmani":"وَقَالَ","transliteration":"waqāla","translation_bn":"এবং (শয়তান) বললো","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23314,"position":12,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"\"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":23315,"position":13,"text_uthmani":"نَهَىٰكُمَا","transliteration":"nahākumā","translation_bn":"তোমাদের দুজনকে নিষেধ করেছেন","root":"نهي","lemma":"نَهَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23316,"position":14,"text_uthmani":"رَبُّكُمَا","transliteration":"rabbukumā","translation_bn":"তোমাদের দুজনের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":23317,"position":15,"text_uthmani":"عَنْ","transliteration":"ʿan","translation_bn":"হতে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23318,"position":16,"text_uthmani":"هَـٰذِهِ","transliteration":"hādhihi","translation_bn":"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":23319,"position":17,"text_uthmani":"ٱلشَّجَرَةِ","transliteration":"l-shajarati","translation_bn":"গাছ","root":"شجر","lemma":"شَجَرَة","grammar_bn":"শব্দ"},{"id":23320,"position":18,"text_uthmani":"إِلَّآ","transliteration":"illā","translation_bn":"এছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":23321,"position":19,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":23322,"position":20,"text_uthmani":"تَكُونَا","transliteration":"takūnā","translation_bn":"তোমরা দুজনে হয়ে যাবে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23323,"position":21,"text_uthmani":"مَلَكَيْنِ","transliteration":"malakayni","translation_bn":"দুই ফেরেশতা","root":"ملك","lemma":"مَلَك","grammar_bn":"বিশেষ্য (Noun)"},{"id":23324,"position":22,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23325,"position":23,"text_uthmani":"تَكُونَا","transliteration":"takūnā","translation_bn":"তোমরা দুজনে হবে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23326,"position":24,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23327,"position":25,"text_uthmani":"ٱلْخَـٰلِدِينَ","transliteration":"l-khālidīna","translation_bn":"চিরস্থায়ীদের\"","root":"خلد","lemma":"خَٰلِد","grammar_bn":"শব্দ"},{"id":23328,"position":26,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'fawaswasa lahumā l-shayṭānu liyub''diya lahumā mā wūriya ʿanhumā min sawātihimā waqāla mā nahākumā rabbukumā ʿan hādhihi l-shajarati illā an takūnā malakayni aw takūnā mina l-khālidīna', 'অতঃপর শয়ত্বান তাদেরকে কুমন্ত্রণা দিল তাদের লজ্জাস্থান প্রকাশ করার জন্য যা তাদের পরস্পরের নিকট গোপন রাখা হয়েছিল; আর বলল, ‘তোমাদেরকে তোমাদের রব্ব এ গাছের নিকটবর্তী হতে যে নিষেধ করেছেন তার কারণ এছাড়া আর কিছুই নয় যে (নিকটবর্তী হলে) তোমরা দু’জন ফেরেশতা হয়ে যাবে কিংবা (জান্নাতে) স্থায়ী হয়ে যাবে।’', 'But Satan whispered to them to make apparent to them that which was concealed from them of their private parts. He said, "Your Lord did not forbid you this tree except that you become angels or become of the immortal."', 'অতঃপর শয়ত্বান তাদেরকে কুমন্ত্রণা দিল তাদের লজ্জাস্থান প্রকাশ করার জন্য যা তাদের পরস্পরের নিকট গোপন রাখা হয়েছিল; আর বলল, ‘তোমাদেরকে তোমাদের রব্ব এ গাছের নিকটবর্তী হতে যে নিষেধ করেছেন তার কারণ এছাড়া আর কিছুই নয় যে (নিকটবর্তী হলে) তোমরা দু’জন ফেরেশতা হয়ে যাবে কিংবা (জান্নাতে) স্থায়ী হয়ে যাবে।’', 'But Satan whispered to them to make apparent to them that which was concealed from them of their private parts. He said, "Your Lord did not forbid you this tree except that you become angels or become of the immortal."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007020.mp3', now()),
  (7, 21, '', '[{"id":24349,"position":1,"text_uthmani":"وَقَاسَمَهُمَآ","transliteration":"waqāsamahumā","translation_bn":"এবং তাদের দুজনের কাছে সে শপথ করলে","root":"قسم","lemma":"قَاسَمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":24350,"position":2,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"\"নিশ্চয়ই আমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":24351,"position":3,"text_uthmani":"لَكُمَا","transliteration":"lakumā","translation_bn":"জন্যে তোমাদের দুজনের","root":"—","lemma":"لَكُمَا","grammar_bn":"অব্যয় (Preposition)"},{"id":24352,"position":4,"text_uthmani":"لَمِنَ","transliteration":"lamina","translation_bn":"অবশ্যই অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":24353,"position":5,"text_uthmani":"ٱلنَّـٰصِحِينَ","transliteration":"l-nāṣiḥīna","translation_bn":"শুভাকাঙ্ক্ষী\"","root":"نصح","lemma":"نَاصِح","grammar_bn":"শব্দ"},{"id":24354,"position":6,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'waqāsamahumā innī lakumā lamina l-nāṣiḥīna', 'সে শপথ করে তাদের বলল, ‘আমি তোমাদের সত্যিকারের হিতাকাঙ্ক্ষী।’', 'And he swore [by Allah] to them, "Indeed, I am to you from among the sincere advisors."', 'সে শপথ করে তাদের বলল, ‘আমি তোমাদের সত্যিকারের হিতাকাঙ্ক্ষী।’', 'And he swore [by Allah] to them, "Indeed, I am to you from among the sincere advisors."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007021.mp3', now()),
  (7, 22, '', '[{"id":25377,"position":1,"text_uthmani":"فَدَلَّىٰهُمَا","transliteration":"fadallāhumā","translation_bn":"এভাবে সে অধঃপতিত করলো তাদের দুজনকে","root":"دلل","lemma":"دَلَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25378,"position":2,"text_uthmani":"بِغُرُورٍۢ ۚ","transliteration":"bighurūrin","translation_bn":"দ্বারা ধোঁকা","root":"غرر","lemma":"غُرُور","grammar_bn":"অব্যয় (Preposition)"},{"id":25380,"position":3,"text_uthmani":"فَلَمَّا","transliteration":"falammā","translation_bn":"অতঃপর যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"শব্দ"},{"id":25381,"position":4,"text_uthmani":"ذَاقَا","transliteration":"dhāqā","translation_bn":"দু''জনে স্বাদ নিলো","root":"ذوق","lemma":"ذَاقُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25382,"position":5,"text_uthmani":"ٱلشَّجَرَةَ","transliteration":"l-shajarata","translation_bn":"গাছের (ফলের)","root":"شجر","lemma":"شَجَرَة","grammar_bn":"শব্দ"},{"id":25383,"position":6,"text_uthmani":"بَدَتْ","transliteration":"badat","translation_bn":"প্রকাশ পেলো","root":"بدو","lemma":"بَدَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":25384,"position":7,"text_uthmani":"لَهُمَا","transliteration":"lahumā","translation_bn":"কাছে তাদের দু''জনের","root":"—","lemma":"لَهُمَا","grammar_bn":"অব্যয় (Preposition)"},{"id":25385,"position":8,"text_uthmani":"سَوْءَٰتُهُمَا","transliteration":"sawātuhumā","translation_bn":"লজ্জাস্থানগুলো তাদের দু''জনের","root":"سوا","lemma":"سَوْءَٰت","grammar_bn":"বিশেষ্য (Noun)"},{"id":25386,"position":9,"text_uthmani":"وَطَفِقَا","transliteration":"waṭafiqā","translation_bn":"এবং দু''জনে শুরু করলো","root":"طفق","lemma":"طَفِقَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25387,"position":10,"text_uthmani":"يَخْصِفَانِ","transliteration":"yakhṣifāni","translation_bn":"দু''জনে ঢাকতে","root":"خصف","lemma":"يَخْصِفَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25388,"position":11,"text_uthmani":"عَلَيْهِمَا","transliteration":"ʿalayhimā","translation_bn":"দু''জনের উপর তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25389,"position":12,"text_uthmani":"مِن","transliteration":"min","translation_bn":"দিয়ে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25390,"position":13,"text_uthmani":"وَرَقِ","transliteration":"waraqi","translation_bn":"পাতা","root":"ورق","lemma":"وَرَق","grammar_bn":"বিশেষ্য (Noun)"},{"id":25391,"position":14,"text_uthmani":"ٱلْجَنَّةِ ۖ","transliteration":"l-janati","translation_bn":"জান্নাতের","root":"جنن","lemma":"جَنَّة","grammar_bn":"শব্দ"},{"id":25393,"position":15,"text_uthmani":"وَنَادَىٰهُمَا","transliteration":"wanādāhumā","translation_bn":"এবং দু''জনকে ডাকলেন তাদের","root":"ندو","lemma":"نَادَىٰ","grammar_bn":"শব্দ"},{"id":25394,"position":16,"text_uthmani":"رَبُّهُمَآ","transliteration":"rabbuhumā","translation_bn":"দু''জনের রব তাদের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":25395,"position":17,"text_uthmani":"أَلَمْ","transliteration":"alam","translation_bn":"\"কি নি","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":25396,"position":18,"text_uthmani":"أَنْهَكُمَا","transliteration":"anhakumā","translation_bn":"তোমাদের দু''জনকে আমি নিষেধ করি","root":"نهي","lemma":"نَهَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25397,"position":19,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25398,"position":20,"text_uthmani":"تِلْكُمَا","transliteration":"til''kumā","translation_bn":"এই","root":"—","lemma":"تِلْكُم","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":25399,"position":21,"text_uthmani":"ٱلشَّجَرَةِ","transliteration":"l-shajarati","translation_bn":"গাছ","root":"شجر","lemma":"شَجَرَة","grammar_bn":"শব্দ"},{"id":25400,"position":22,"text_uthmani":"وَأَقُل","transliteration":"wa-aqul","translation_bn":"এবং আমি বলি (নি)","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25401,"position":23,"text_uthmani":"لَّكُمَآ","transliteration":"lakumā","translation_bn":"উদ্দেশ্যে তোমাদের দু''জনের","root":"—","lemma":"لَّكُمَآ","grammar_bn":"অব্যয় (Preposition)"},{"id":25402,"position":24,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":25403,"position":25,"text_uthmani":"ٱلشَّيْطَـٰنَ","transliteration":"l-shayṭāna","translation_bn":"শয়তান","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"শব্দ"},{"id":25404,"position":26,"text_uthmani":"لَكُمَا","transliteration":"lakumā","translation_bn":"জন্যে তোমাদের দু''জনের","root":"—","lemma":"لَكُمَا","grammar_bn":"অব্যয় (Preposition)"},{"id":25405,"position":27,"text_uthmani":"عَدُوٌّۭ","transliteration":"ʿaduwwun","translation_bn":"শত্রু\"","root":"عدو","lemma":"عَدُوّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":25406,"position":28,"text_uthmani":"مُّبِينٌۭ","transliteration":"mubīnun","translation_bn":"প্রকাশ্য\"","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":25407,"position":29,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'fadallāhumā bighurūrin falammā dhāqā l-shajarata badat lahumā sawātuhumā waṭafiqā yakhṣifāni ʿalayhimā min waraqi l-janati wanādāhumā rabbuhumā alam anhakumā ʿan til''kumā l-shajarati wa-aqul lakumā inna l-shayṭāna lakumā ʿaduwwun mubīnun', 'এভাবে সে ধোঁকা দিয়ে তাদের অধঃপতন ঘটিয়ে দিল। যখন তারা গাছের ফলের স্বাদ নিল, তখন তাদের গোপনীয় স্থান পরস্পরের নিকট প্রকাশিত হয়ে গেল, তারা জান্নাতের পাতা দিয়ে নিজেদেরকে ঢাকতে লাগল। তখন তাদের প্রতিপালক তাদেরকে ডেকে বললেন, ‘আমি কি তোমাদেরকে এ গাছের কাছে যেতে নিষেধ করিনি আর বলিনি- শয়ত্বান হচ্ছে তোমাদের উভয়ের খোলাখুলি দুশমন?’', 'So he made them fall, through deception. And when they tasted of the tree, their private parts became apparent to them, and they began to fasten together over themselves from the leaves of Paradise. And their Lord called to them, "Did I not forbid you from that tree and tell you that Satan is to you a clear enemy?"', 'এভাবে সে ধোঁকা দিয়ে তাদের অধঃপতন ঘটিয়ে দিল। যখন তারা গাছের ফলের স্বাদ নিল, তখন তাদের গোপনীয় স্থান পরস্পরের নিকট প্রকাশিত হয়ে গেল, তারা জান্নাতের পাতা দিয়ে নিজেদেরকে ঢাকতে লাগল। তখন তাদের প্রতিপালক তাদেরকে ডেকে বললেন, ‘আমি কি তোমাদেরকে এ গাছের কাছে যেতে নিষেধ করিনি আর বলিনি- শয়ত্বান হচ্ছে তোমাদের উভয়ের খোলাখুলি দুশমন?’', 'So he made them fall, through deception. And when they tasted of the tree, their private parts became apparent to them, and they began to fasten together over themselves from the leaves of Paradise. And their Lord called to them, "Did I not forbid you from that tree and tell you that Satan is to you a clear enemy?"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007022.mp3', now()),
  (7, 23, '', '[{"id":26452,"position":1,"text_uthmani":"قَالَا","transliteration":"qālā","translation_bn":"(আদম ও হাওয়া) দু''জনে বললো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26453,"position":2,"text_uthmani":"رَبَّنَا","transliteration":"rabbanā","translation_bn":"\"হে আমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":26454,"position":3,"text_uthmani":"ظَلَمْنَآ","transliteration":"ẓalamnā","translation_bn":"অন্যায় করেছি আমরা","root":"ظلم","lemma":"ظَلَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26455,"position":4,"text_uthmani":"أَنفُسَنَا","transliteration":"anfusanā","translation_bn":"আমাদের নিজেদের (উপর)","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":26456,"position":5,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"এবং যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26457,"position":6,"text_uthmani":"لَّمْ","transliteration":"lam","translation_bn":"না","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":26458,"position":7,"text_uthmani":"تَغْفِرْ","transliteration":"taghfir","translation_bn":"ক্ষমা করো তুমি","root":"غفر","lemma":"غَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26459,"position":8,"text_uthmani":"لَنَا","transliteration":"lanā","translation_bn":"আমাদেরকে","root":"—","lemma":"لَنَا","grammar_bn":"অব্যয় (Preposition)"},{"id":26460,"position":9,"text_uthmani":"وَتَرْحَمْنَا","transliteration":"watarḥamnā","translation_bn":"ও আমাদেরকে দয়া (না) করো","root":"رحم","lemma":"رَّحِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26461,"position":10,"text_uthmani":"لَنَكُونَنَّ","transliteration":"lanakūnanna","translation_bn":"অবশ্যই  আমরা হবো","root":"كون","lemma":"كَانَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":26462,"position":11,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26463,"position":12,"text_uthmani":"ٱلْخَـٰسِرِينَ","transliteration":"l-khāsirīna","translation_bn":"ক্ষতিগ্রস্তদের\"","root":"خسر","lemma":"خَٰسِرِين","grammar_bn":"শব্দ"},{"id":26464,"position":13,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'qālā rabbanā ẓalamnā anfusanā wa-in lam taghfir lanā watarḥamnā lanakūnanna mina l-khāsirīna', 'তারা বলল, ‘হে আমাদের প্রতিপালক! আমরা নিজেদের প্রতি অন্যায় করে ফেলেছি, যদি তুমি আমাদেরকে ক্ষমা না কর আর দয়া না কর তাহলে আমরা অবশ্য অবশ্যই ক্ষতিগ্রস্তদের অন্তর্ভুক্ত হয়ে যাব।’', 'They said, "Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy upon us, we will surely be among the losers."', 'তারা বলল, ‘হে আমাদের প্রতিপালক! আমরা নিজেদের প্রতি অন্যায় করে ফেলেছি, যদি তুমি আমাদেরকে ক্ষমা না কর আর দয়া না কর তাহলে আমরা অবশ্য অবশ্যই ক্ষতিগ্রস্তদের অন্তর্ভুক্ত হয়ে যাব।’', 'They said, "Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy upon us, we will surely be among the losers."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007023.mp3', now()),
  (7, 24, '', '[{"id":27449,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(আল্লাহ) বললেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27450,"position":2,"text_uthmani":"ٱهْبِطُوا۟","transliteration":"ih''biṭū","translation_bn":"\"তোমরা নেমে যাও","root":"هبط","lemma":"يَهْبِطُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27451,"position":3,"text_uthmani":"بَعْضُكُمْ","transliteration":"baʿḍukum","translation_bn":"তোমাদের একে","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":27452,"position":4,"text_uthmani":"لِبَعْضٍ","transliteration":"libaʿḍin","translation_bn":"জন্যে অপরের","root":"بعض","lemma":"بَعْض","grammar_bn":"অব্যয় (Preposition)"},{"id":27453,"position":5,"text_uthmani":"عَدُوٌّۭ ۖ","transliteration":"ʿaduwwun","translation_bn":"শত্রু","root":"عدو","lemma":"عَدُوّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":27455,"position":6,"text_uthmani":"وَلَكُمْ","transliteration":"walakum","translation_bn":"এবং জন্যে  তোমাদের (থাকবে)","root":"—","lemma":"وَلَكُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27456,"position":7,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27457,"position":8,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":27458,"position":9,"text_uthmani":"مُسْتَقَرٌّۭ","transliteration":"mus''taqarrun","translation_bn":"অবস্থান","root":"قرر","lemma":"مُسْتَقَرّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":27459,"position":10,"text_uthmani":"وَمَتَـٰعٌ","transliteration":"wamatāʿun","translation_bn":"ও জীবন সামগ্রী","root":"متع","lemma":"مَتَٰع","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27460,"position":11,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"পর্যন্ত","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27461,"position":12,"text_uthmani":"حِينٍۢ","transliteration":"ḥīnin","translation_bn":"নির্দিষ্ট সময়\"","root":"حين","lemma":"حِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":27462,"position":13,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'qāla ih''biṭū baʿḍukum libaʿḍin ʿaduwwun walakum fī l-arḍi mus''taqarrun wamatāʿun ilā ḥīnin', 'তিনি বললেন, ‘তোমরা নেমে যাও, তোমরা একে অন্যের শত্রু, পৃথিবীতে তোমাদের অবস্থান ও জীবিকা থাকবে একটা নির্দিষ্ট সময়ের জন্য।’', '[Allah] said, "Descend, being to one another enemies. And for you on the earth is a place of settlement and enjoyment for a time."', 'তিনি বললেন, ‘তোমরা নেমে যাও, তোমরা একে অন্যের শত্রু, পৃথিবীতে তোমাদের অবস্থান ও জীবিকা থাকবে একটা নির্দিষ্ট সময়ের জন্য।’', '[Allah] said, "Descend, being to one another enemies. And for you on the earth is a place of settlement and enjoyment for a time."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007024.mp3', now()),
  (7, 25, '', '[{"id":28512,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"তিনি বললেন","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28513,"position":2,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"\"মধ্যে তার","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28514,"position":3,"text_uthmani":"تَحْيَوْنَ","transliteration":"taḥyawna","translation_bn":"জীবিত থাকবে তোমরা","root":"حيي","lemma":"حَىَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28515,"position":4,"text_uthmani":"وَفِيهَا","transliteration":"wafīhā","translation_bn":"ও মধ্যে তার","root":"—","lemma":"فِى\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28516,"position":5,"text_uthmani":"تَمُوتُونَ","transliteration":"tamūtūna","translation_bn":"মৃত্যুবরণ করবে তোমরা","root":"موت","lemma":"مَّاتَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28517,"position":6,"text_uthmani":"وَمِنْهَا","transliteration":"wamin''hā","translation_bn":"ও থেকে তা","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28518,"position":7,"text_uthmani":"تُخْرَجُونَ","transliteration":"tukh''rajūna","translation_bn":"তোমাদের বের করা হবে\"","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28519,"position":8,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'qāla fīhā taḥyawna wafīhā tamūtūna wamin''hā tukh''rajūna', 'বললেন, ‘ওখানে তোমরা জীবন যাপন করবে, ওখানেই তোমাদের মৃত্যু হবে, আর তাথেকেই তোমাদেরকে বের করা হবে।’', 'He said, "Therein you will live, and therein you will die, and from it you will be brought forth."', 'বললেন, ‘ওখানে তোমরা জীবন যাপন করবে, ওখানেই তোমাদের মৃত্যু হবে, আর তাথেকেই তোমাদেরকে বের করা হবে।’', 'He said, "Therein you will live, and therein you will die, and from it you will be brought forth."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007025.mp3', now()),
  (7, 26, '', '[{"id":29449,"position":1,"text_uthmani":"يَـٰبَنِىٓ","transliteration":"yābanī","translation_bn":"হে সন্তান","root":"بني","lemma":"بُنَىّ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":29450,"position":2,"text_uthmani":"ءَادَمَ","transliteration":"ādama","translation_bn":"আদমের","root":"—","lemma":"ا^دَم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":29451,"position":3,"text_uthmani":"قَدْ","transliteration":"qad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":29452,"position":4,"text_uthmani":"أَنزَلْنَا","transliteration":"anzalnā","translation_bn":"অবতীর্ণ করেছি আমরা","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29453,"position":5,"text_uthmani":"عَلَيْكُمْ","transliteration":"ʿalaykum","translation_bn":"উপর তোমাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29454,"position":6,"text_uthmani":"لِبَاسًۭا","transliteration":"libāsan","translation_bn":"পোশাক","root":"لبس","lemma":"لِبَاس","grammar_bn":"বিশেষ্য (Noun)"},{"id":29455,"position":7,"text_uthmani":"يُوَٰرِى","transliteration":"yuwārī","translation_bn":"তা ঢেকে রাখে","root":"وري","lemma":"وُ,رِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29456,"position":8,"text_uthmani":"سَوْءَٰتِكُمْ","transliteration":"sawātikum","translation_bn":"লজ্জাস্থানগুলো তোমাদের","root":"سوا","lemma":"سَوْءَٰت","grammar_bn":"বিশেষ্য (Noun)"},{"id":29457,"position":9,"text_uthmani":"وَرِيشًۭا ۖ","transliteration":"warīshan","translation_bn":"ও শোভা বর্ধকরূপে","root":"ريش","lemma":"رِيش","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29459,"position":10,"text_uthmani":"وَلِبَاسُ","transliteration":"walibāsu","translation_bn":"ও পোশাক","root":"لبس","lemma":"لِبَاس","grammar_bn":"শব্দ"},{"id":29460,"position":11,"text_uthmani":"ٱلتَّقْوَىٰ","transliteration":"l-taqwā","translation_bn":"তাকওয়ার","root":"وقي","lemma":"تَقْوَى","grammar_bn":"শব্দ"},{"id":29461,"position":12,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটাই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":29462,"position":13,"text_uthmani":"خَيْرٌۭ ۚ","transliteration":"khayrun","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":29464,"position":14,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":29465,"position":15,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29466,"position":16,"text_uthmani":"ءَايَـٰتِ","transliteration":"āyāti","translation_bn":"নিদর্শনাবলীর","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":29467,"position":17,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":29468,"position":18,"text_uthmani":"لَعَلَّهُمْ","transliteration":"laʿallahum","translation_bn":"সম্ভবতঃ তারা","root":"—","lemma":"لَعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":29469,"position":19,"text_uthmani":"يَذَّكَّرُونَ","transliteration":"yadhakkarūna","translation_bn":"শিক্ষা গ্রহন করবে","root":"ذكر","lemma":"تَذَكَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29470,"position":20,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'yābanī ādama qad anzalnā ʿalaykum libāsan yuwārī sawātikum warīshan walibāsu l-taqwā dhālika khayrun dhālika min āyāti l-lahi laʿallahum yadhakkarūna', 'হে আদাম সন্তান! আমি তোমাদেরকে পোষাক-পরিচ্ছদ দিয়েছি তোমাদের লজ্জাস্থান আবৃত করার জন্য এবং শোভা বর্ধনের জন্য। আর তাকওয়ার পোশাক হচ্ছে সর্বোত্তম পোশাক। ওটা আল্লাহর নিদর্শনসমূহের মধ্যে একটি যাতে তারা উপদেশ গ্রহণ করে।', 'O children of Adam, We have bestowed upon you clothing to conceal your private parts and as adornment. But the clothing of righteousness - that is best. That is from the signs of Allah that perhaps they will remember.', 'হে আদাম সন্তান! আমি তোমাদেরকে পোষাক-পরিচ্ছদ দিয়েছি তোমাদের লজ্জাস্থান আবৃত করার জন্য এবং শোভা বর্ধনের জন্য। আর তাকওয়ার পোশাক হচ্ছে সর্বোত্তম পোশাক। ওটা আল্লাহর নিদর্শনসমূহের মধ্যে একটি যাতে তারা উপদেশ গ্রহণ করে।', 'O children of Adam, We have bestowed upon you clothing to conceal your private parts and as adornment. But the clothing of righteousness - that is best. That is from the signs of Allah that perhaps they will remember.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007026.mp3', now()),
  (7, 27, '', '[{"id":30443,"position":1,"text_uthmani":"يَـٰبَنِىٓ","transliteration":"yābanī","translation_bn":"হে সন্তান","root":"بني","lemma":"بُنَىّ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":30444,"position":2,"text_uthmani":"ءَادَمَ","transliteration":"ādama","translation_bn":"আদমের","root":"—","lemma":"ا^دَم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":30445,"position":3,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না (যেন)","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":30446,"position":4,"text_uthmani":"يَفْتِنَنَّكُمُ","transliteration":"yaftinannakumu","translation_bn":"তোমাদের পরীক্ষায় ফেলে","root":"فتن","lemma":"فَتَنُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30447,"position":5,"text_uthmani":"ٱلشَّيْطَـٰنُ","transliteration":"l-shayṭānu","translation_bn":"শয়তান","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"শব্দ"},{"id":30448,"position":6,"text_uthmani":"كَمَآ","transliteration":"kamā","translation_bn":"যেমন","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":30449,"position":7,"text_uthmani":"أَخْرَجَ","transliteration":"akhraja","translation_bn":"সে বের করেছিলো","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30450,"position":8,"text_uthmani":"أَبَوَيْكُم","transliteration":"abawaykum","translation_bn":"পিতা-মাতাকে তোমাদের","root":"ابو","lemma":"أَبَوَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":30451,"position":9,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":30452,"position":10,"text_uthmani":"ٱلْجَنَّةِ","transliteration":"l-janati","translation_bn":"জান্নাত","root":"جنن","lemma":"جَنَّة","grammar_bn":"শব্দ"},{"id":30453,"position":11,"text_uthmani":"يَنزِعُ","transliteration":"yanziʿu","translation_bn":"খুলে ফেলে","root":"نزع","lemma":"نَزَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30454,"position":12,"text_uthmani":"عَنْهُمَا","transliteration":"ʿanhumā","translation_bn":"থেকে তাদের দু''জন","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":30455,"position":13,"text_uthmani":"لِبَاسَهُمَا","transliteration":"libāsahumā","translation_bn":"পোষাক তাদের দু''জনের","root":"لبس","lemma":"لِبَاس","grammar_bn":"বিশেষ্য (Noun)"},{"id":30456,"position":14,"text_uthmani":"لِيُرِيَهُمَا","transliteration":"liyuriyahumā","translation_bn":"জন্যে তাদের দু''জনকে দেখানোর","root":"راي","lemma":"أَرَيْ","grammar_bn":"শব্দ"},{"id":30457,"position":15,"text_uthmani":"سَوْءَٰتِهِمَآ ۗ","transliteration":"sawātihimā","translation_bn":"লজ্জাস্থান তাদের দু''জনের","root":"سوا","lemma":"سَوْءَٰت","grammar_bn":"বিশেষ্য (Noun)"},{"id":30459,"position":16,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"নিশ্চয়ই সে","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":30460,"position":17,"text_uthmani":"يَرَىٰكُمْ","transliteration":"yarākum","translation_bn":"দেখে তোমাদের","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":30461,"position":18,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"সে","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":30462,"position":19,"text_uthmani":"وَقَبِيلُهُۥ","transliteration":"waqabīluhu","translation_bn":"ও দলবল তার","root":"قبل","lemma":"قَبِيل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30463,"position":20,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":30464,"position":21,"text_uthmani":"حَيْثُ","transliteration":"ḥaythu","translation_bn":"যেখান","root":"حيث","lemma":"حَيْث","grammar_bn":"বিশেষ্য (Noun)"},{"id":30465,"position":22,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":30466,"position":23,"text_uthmani":"تَرَوْنَهُمْ ۗ","transliteration":"tarawnahum","translation_bn":"তোমরা দেখো তাদেরকে","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":30468,"position":24,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":30469,"position":25,"text_uthmani":"جَعَلْنَا","transliteration":"jaʿalnā","translation_bn":"আমরা বানিয়েছি","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30470,"position":26,"text_uthmani":"ٱلشَّيَـٰطِينَ","transliteration":"l-shayāṭīna","translation_bn":"শয়তানদেরকে","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"শব্দ"},{"id":30471,"position":27,"text_uthmani":"أَوْلِيَآءَ","transliteration":"awliyāa","translation_bn":"অভিভাবকরূপে","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":30472,"position":28,"text_uthmani":"لِلَّذِينَ","transliteration":"lilladhīna","translation_bn":"(তাদের) জন্যে যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অব্যয় (Preposition)"},{"id":30473,"position":29,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":30474,"position":30,"text_uthmani":"يُؤْمِنُونَ","transliteration":"yu''minūna","translation_bn":"ঈমান আনে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":30475,"position":31,"text_uthmani":"٢٧","transliteration":"","translation_bn":"(২৭)","root":"—","lemma":"٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'yābanī ādama lā yaftinannakumu l-shayṭānu kamā akhraja abawaykum mina l-janati yanziʿu ʿanhumā libāsahumā liyuriyahumā sawātihimā innahu yarākum huwa waqabīluhu min ḥaythu lā tarawnahum innā jaʿalnā l-shayāṭīna awliyāa lilladhīna lā yu''minūna', 'হে আদাম সন্তান! শয়ত্বান যেন তোমাদেরকে কিছুতেই ফিতনায় ফেলতে না পারে যেমনভাবে তোমাদের পিতা-মাতাকে (আদম ও হাওয়াকে) জান্নাত থেকে বের করেছিল। সে তাদের পরস্পরকে লজ্জাস্থান দেখানোর জন্য তাদের দেহ হতে পোষাক খুলিয়ে ফেলেছিল। সে আর তার সাথীরা তোমাদেরকে এমনভাবে দেখতে পায় যে তোমরা তাদেরকে দেখতে পাও না। যারা ঈমান আনে না তাদের জন্য আমি শয়ত্বানকে অভিভাবক বানিয়ে দিয়েছি।', 'O children of Adam, let not Satan tempt you as he removed your parents from Paradise, stripping them of their clothing to show them their private parts. Indeed, he sees you, he and his tribe, from where you do not see them. Indeed, We have made the devils allies to those who do not believe.', 'হে আদাম সন্তান! শয়ত্বান যেন তোমাদেরকে কিছুতেই ফিতনায় ফেলতে না পারে যেমনভাবে তোমাদের পিতা-মাতাকে (আদম ও হাওয়াকে) জান্নাত থেকে বের করেছিল। সে তাদের পরস্পরকে লজ্জাস্থান দেখানোর জন্য তাদের দেহ হতে পোষাক খুলিয়ে ফেলেছিল। সে আর তার সাথীরা তোমাদেরকে এমনভাবে দেখতে পায় যে তোমরা তাদেরকে দেখতে পাও না। যারা ঈমান আনে না তাদের জন্য আমি শয়ত্বানকে অভিভাবক বানিয়ে দিয়েছি।', 'O children of Adam, let not Satan tempt you as he removed your parents from Paradise, stripping them of their clothing to show them their private parts. Indeed, he sees you, he and his tribe, from where you do not see them. Indeed, We have made the devils allies to those who do not believe.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007027.mp3', now()),
  (7, 28, '', '[{"id":31438,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":31439,"position":2,"text_uthmani":"فَعَلُوا۟","transliteration":"faʿalū","translation_bn":"তারা করে","root":"فعل","lemma":"فَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31440,"position":3,"text_uthmani":"فَـٰحِشَةًۭ","transliteration":"fāḥishatan","translation_bn":"অশ্লীল কাজ","root":"فحش","lemma":"فَٰحِشَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":31441,"position":4,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31442,"position":5,"text_uthmani":"وَجَدْنَا","transliteration":"wajadnā","translation_bn":"\"পেয়েছি আমরা","root":"وجد","lemma":"وَجَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31443,"position":6,"text_uthmani":"عَلَيْهَآ","transliteration":"ʿalayhā","translation_bn":"উপর এসবের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31444,"position":7,"text_uthmani":"ءَابَآءَنَا","transliteration":"ābāanā","translation_bn":"বাপ-দাদাদেরকে আমাদের","root":"ابو","lemma":"ا^بَاء","grammar_bn":"বিশেষ্য (Noun)"},{"id":31445,"position":8,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":31446,"position":9,"text_uthmani":"أَمَرَنَا","transliteration":"amaranā","translation_bn":"নির্দেশ দিয়েছেন আমাদের","root":"امر","lemma":"أَمَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31447,"position":10,"text_uthmani":"بِهَا ۗ","transliteration":"bihā","translation_bn":"সম্পর্কে এর\"","root":"—","lemma":"بِهَا ۗ","grammar_bn":"অব্যয় (Preposition)"},{"id":31449,"position":11,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"তুমি বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31450,"position":12,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"\"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":31451,"position":13,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":31452,"position":14,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":31453,"position":15,"text_uthmani":"يَأْمُرُ","transliteration":"yamuru","translation_bn":"নির্দেশ দেন","root":"امر","lemma":"أَمَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31454,"position":16,"text_uthmani":"بِٱلْفَحْشَآءِ ۖ","transliteration":"bil-faḥshāi","translation_bn":"ব্যাপারে অশ্লীলতার","root":"فحش","lemma":"فَحْشَا^ء","grammar_bn":"অব্যয় (Preposition)"},{"id":31456,"position":17,"text_uthmani":"أَتَقُولُونَ","transliteration":"ataqūlūna","translation_bn":"কি তোমরা বলছো","root":"قول","lemma":"قَالَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":31457,"position":18,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"সম্পর্কে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31458,"position":19,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":31459,"position":20,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":31460,"position":21,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না\"","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":31461,"position":22,"text_uthmani":"تَعْلَمُونَ","transliteration":"taʿlamūna","translation_bn":"তোমরা জানো\"","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31462,"position":23,"text_uthmani":"٢٨","transliteration":"","translation_bn":"(২৮)","root":"—","lemma":"٢٨","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā faʿalū fāḥishatan qālū wajadnā ʿalayhā ābāanā wal-lahu amaranā bihā qul inna l-laha lā yamuru bil-faḥshāi ataqūlūna ʿalā l-lahi mā lā taʿlamūna', 'তারা যখন কোন অশ্লীল কাজ করে তখন তারা বলে- ‘আমরা আমাদের পিতৃপুরুষদেরকে এ কাজই করতে দেখেছি, আর আল্লাহ আমাদেরকে এসব কাজ করার আদেশ দিয়েছেন।’ বল, ‘আল্লাহ অশ্লীলতার নির্দেশ দেন না, আল্লাহর সম্বন্ধে তোমরা কি এমন কথা বলছ যা তোমরা জান না?’', 'And when they commit an immorality, they say, "We found our fathers doing it, and Allah has ordered us to do it." Say, "Indeed, Allah does not order immorality. Do you say about Allah that which you do not know?"', 'তারা যখন কোন অশ্লীল কাজ করে তখন তারা বলে- ‘আমরা আমাদের পিতৃপুরুষদেরকে এ কাজই করতে দেখেছি, আর আল্লাহ আমাদেরকে এসব কাজ করার আদেশ দিয়েছেন।’ বল, ‘আল্লাহ অশ্লীলতার নির্দেশ দেন না, আল্লাহর সম্বন্ধে তোমরা কি এমন কথা বলছ যা তোমরা জান না?’', 'And when they commit an immorality, they say, "We found our fathers doing it, and Allah has ordered us to do it." Say, "Indeed, Allah does not order immorality. Do you say about Allah that which you do not know?"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007028.mp3', now()),
  (7, 29, '', '[{"id":32406,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"(হে নাবী) বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32407,"position":2,"text_uthmani":"أَمَرَ","transliteration":"amara","translation_bn":"\"নির্দেশ দিয়েছেন","root":"امر","lemma":"أَمَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32408,"position":3,"text_uthmani":"رَبِّى","transliteration":"rabbī","translation_bn":"\"আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":32409,"position":4,"text_uthmani":"بِٱلْقِسْطِ ۖ","transliteration":"bil-qis''ṭi","translation_bn":"ব্যাপারে ন্যায়ের","root":"قسط","lemma":"قِسْط","grammar_bn":"অব্যয় (Preposition)"},{"id":32411,"position":5,"text_uthmani":"وَأَقِيمُوا۟","transliteration":"wa-aqīmū","translation_bn":"এবং তোমরা স্থির রাখো","root":"قوم","lemma":"أَقَامَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":32412,"position":6,"text_uthmani":"وُجُوهَكُمْ","transliteration":"wujūhakum","translation_bn":"লক্ষ্য তোমাদের","root":"وجه","lemma":"وَجْه","grammar_bn":"বিশেষ্য (Noun)"},{"id":32413,"position":7,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"সময়","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":32414,"position":8,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":32415,"position":9,"text_uthmani":"مَسْجِدٍۢ","transliteration":"masjidin","translation_bn":"মাসজীদের (সালাতের)","root":"سجد","lemma":"مَسْجِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":32416,"position":10,"text_uthmani":"وَٱدْعُوهُ","transliteration":"wa-id''ʿūhu","translation_bn":"এবং তোমরা ডাকো তাঁকে","root":"دعو","lemma":"دَعَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":32417,"position":11,"text_uthmani":"مُخْلِصِينَ","transliteration":"mukh''liṣīna","translation_bn":"তোমরা একনিষ্ঠভাবে","root":"خلص","lemma":"مُخْلِص","grammar_bn":"বিশেষ্য (Noun)"},{"id":32418,"position":12,"text_uthmani":"لَهُ","transliteration":"lahu","translation_bn":"জন্যে তাঁরই","root":"—","lemma":"لَهُ","grammar_bn":"অব্যয় (Preposition)"},{"id":32419,"position":13,"text_uthmani":"ٱلدِّينَ ۚ","transliteration":"l-dīna","translation_bn":"আনুগত্যকে (নিষ্ঠাপূর্ণ করে)","root":"دين","lemma":"دِين","grammar_bn":"শব্দ"},{"id":32421,"position":14,"text_uthmani":"كَمَا","transliteration":"kamā","translation_bn":"যেমন","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":32422,"position":15,"text_uthmani":"بَدَأَكُمْ","transliteration":"bada-akum","translation_bn":"প্রথম সৃষ্টি করেছেন তোমাদের","root":"بدا","lemma":"بَدَأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32423,"position":16,"text_uthmani":"تَعُودُونَ","transliteration":"taʿūdūna","translation_bn":"তোমরা (তেমনি) ফিরে আসবে\"","root":"عود","lemma":"عَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32424,"position":17,"text_uthmani":"٢٩","transliteration":"","translation_bn":"(২৯)","root":"—","lemma":"٢٩","grammar_bn":"মার্কার"}]'::jsonb, 'qul amara rabbī bil-qis''ṭi wa-aqīmū wujūhakum ʿinda kulli masjidin wa-id''ʿūhu mukh''liṣīna lahu l-dīna kamā bada-akum taʿūdūna', 'বল, ‘আমার প্রতিপালক ন্যায়পরায়ণতার নির্দেশ দিয়েছেন’, আর প্রত্যেক সলাতে তোমাদের লক্ষ্য ও মনোযোগকে (তাঁর প্রতি) নিবদ্ধ কর, তাঁর আনুগত্যে বিশুদ্ধ-চিত্ত হয়ে তাঁকে ডাক। যেভাবে তোমাদেরকে প্রথমে সৃষ্টি করা হয়েছে (তোমাদের মৃত্যুর পর আবার জীবিত হয়ে) সেভাবেই তোমরা ফিরে আসবে।', 'Say, [O Muhammad], "My Lord has ordered justice and that you maintain yourselves [in worship of Him] at every place [or time] of prostration, and invoke Him, sincere to Him in religion." Just as He originated you, you will return [to life] -', 'বল, ‘আমার প্রতিপালক ন্যায়পরায়ণতার নির্দেশ দিয়েছেন’, আর প্রত্যেক সলাতে তোমাদের লক্ষ্য ও মনোযোগকে (তাঁর প্রতি) নিবদ্ধ কর, তাঁর আনুগত্যে বিশুদ্ধ-চিত্ত হয়ে তাঁকে ডাক। যেভাবে তোমাদেরকে প্রথমে সৃষ্টি করা হয়েছে (তোমাদের মৃত্যুর পর আবার জীবিত হয়ে) সেভাবেই তোমরা ফিরে আসবে।', 'Say, [O Muhammad], "My Lord has ordered justice and that you maintain yourselves [in worship of Him] at every place [or time] of prostration, and invoke Him, sincere to Him in religion." Just as He originated you, you will return [to life] -', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007029.mp3', now()),
  (7, 30, '', '[{"id":33251,"position":1,"text_uthmani":"فَرِيقًا","transliteration":"farīqan","translation_bn":"একদলকে","root":"فرق","lemma":"فَرِيق","grammar_bn":"বিশেষ্য (Noun)"},{"id":33252,"position":2,"text_uthmani":"هَدَىٰ","transliteration":"hadā","translation_bn":"তিনি সঠিক পথে চলিয়েছেন","root":"هدي","lemma":"هَدَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":33253,"position":3,"text_uthmani":"وَفَرِيقًا","transliteration":"wafarīqan","translation_bn":"এবং (অপর এক) দলের (জন্যে)","root":"فرق","lemma":"فَرِيق","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33254,"position":4,"text_uthmani":"حَقَّ","transliteration":"ḥaqqa","translation_bn":"অবধারিত হয়েছে","root":"حقق","lemma":"حَقَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33255,"position":5,"text_uthmani":"عَلَيْهِمُ","transliteration":"ʿalayhimu","translation_bn":"উপর তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33256,"position":6,"text_uthmani":"ٱلضَّلَـٰلَةُ ۗ","transliteration":"l-ḍalālatu","translation_bn":"পথ ভ্রষ্টতা","root":"ضلل","lemma":"ضَلَٰلَة","grammar_bn":"শব্দ"},{"id":33258,"position":7,"text_uthmani":"إِنَّهُمُ","transliteration":"innahumu","translation_bn":"নিশ্চয়ই তারা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":33259,"position":8,"text_uthmani":"ٱتَّخَذُوا۟","transliteration":"ittakhadhū","translation_bn":"গ্রহন করেছে","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33260,"position":9,"text_uthmani":"ٱلشَّيَـٰطِينَ","transliteration":"l-shayāṭīna","translation_bn":"শয়তানদেরকে","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"শব্দ"},{"id":33261,"position":10,"text_uthmani":"أَوْلِيَآءَ","transliteration":"awliyāa","translation_bn":"অভিভাবকরূপে","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":33262,"position":11,"text_uthmani":"مِن","transliteration":"min","translation_bn":"দিয়ে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33263,"position":12,"text_uthmani":"دُونِ","transliteration":"dūni","translation_bn":"বাদ","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":33264,"position":13,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":33265,"position":14,"text_uthmani":"وَيَحْسَبُونَ","transliteration":"wayaḥsabūna","translation_bn":"এবং তারা মনে করে","root":"حسب","lemma":"حَسِبَ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":33266,"position":15,"text_uthmani":"أَنَّهُم","transliteration":"annahum","translation_bn":"যে তারা","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":33267,"position":16,"text_uthmani":"مُّهْتَدُونَ","transliteration":"muh''tadūna","translation_bn":"সঠিক-পথপ্রাপ্ত","root":"هدي","lemma":"مُّهْتَدُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":33268,"position":17,"text_uthmani":"٣٠","transliteration":"","translation_bn":"(৩০)","root":"—","lemma":"٣٠","grammar_bn":"মার্কার"}]'::jsonb, 'farīqan hadā wafarīqan ḥaqqa ʿalayhimu l-ḍalālatu innahumu ittakhadhū l-shayāṭīna awliyāa min dūni l-lahi wayaḥsabūna annahum muh''tadūna', 'একদলকে তিনি সঠিক পথ দেখিয়েছেন, আর অন্য দলের প্রতি গোমরাহী নির্ধারিত হয়েছে, তারা আল্লাহকে বাদ দিয়ে শয়ত্বানদেরকে তাদের অভিভাবক করে নিয়েছে আর মনে করছে যে তারা সঠিক পথে আছে।', 'A group [of you] He guided, and a group deserved [to be in] error. Indeed, they had taken the devils as allies instead of Allah while they thought that they were guided.', 'একদলকে তিনি সঠিক পথ দেখিয়েছেন, আর অন্য দলের প্রতি গোমরাহী নির্ধারিত হয়েছে, তারা আল্লাহকে বাদ দিয়ে শয়ত্বানদেরকে তাদের অভিভাবক করে নিয়েছে আর মনে করছে যে তারা সঠিক পথে আছে।', 'A group [of you] He guided, and a group deserved [to be in] error. Indeed, they had taken the devils as allies instead of Allah while they thought that they were guided.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007030.mp3', now()),
  (7, 31, '', '[{"id":34296,"position":1,"text_uthmani":"۞ يَـٰبَنِىٓ","transliteration":"yābanī","translation_bn":"হে সন্তান","root":"بني","lemma":"بُنَىّ","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":34297,"position":2,"text_uthmani":"ءَادَمَ","transliteration":"ādama","translation_bn":"আদমের","root":"—","lemma":"ا^دَم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":34298,"position":3,"text_uthmani":"خُذُوا۟","transliteration":"khudhū","translation_bn":"তোমরা গ্রহণ করো","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":34299,"position":4,"text_uthmani":"زِينَتَكُمْ","transliteration":"zīnatakum","translation_bn":"সুন্দর পোশাক তোমাদের","root":"زين","lemma":"زِينَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":34300,"position":5,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"সময়","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":34301,"position":6,"text_uthmani":"كُلِّ","transliteration":"kulli","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":34302,"position":7,"text_uthmani":"مَسْجِدٍۢ","transliteration":"masjidin","translation_bn":"মাসজীদের (সালাতের)","root":"سجد","lemma":"مَسْجِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":34303,"position":8,"text_uthmani":"وَكُلُوا۟","transliteration":"wakulū","translation_bn":"এবং তোমরা খাও","root":"اكل","lemma":"أَكَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34304,"position":9,"text_uthmani":"وَٱشْرَبُوا۟","transliteration":"wa-ish''rabū","translation_bn":"ও তোমরা পান কর","root":"شرب","lemma":"شَرِبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34305,"position":10,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"কিন্তু না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34306,"position":11,"text_uthmani":"تُسْرِفُوٓا۟ ۚ","transliteration":"tus''rifū","translation_bn":"তোমরা সীমালঙ্ঘন করো","root":"سرف","lemma":"أَسْرَفَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":34308,"position":12,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"নিশ্চয়ই তিনি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":34309,"position":13,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":34310,"position":14,"text_uthmani":"يُحِبُّ","transliteration":"yuḥibbu","translation_bn":"ভালোবাসেন","root":"حبب","lemma":"أَحْبَبْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":34311,"position":15,"text_uthmani":"ٱلْمُسْرِفِينَ","transliteration":"l-mus''rifīna","translation_bn":"সীমালঙ্ঘনকারীদেরকে","root":"سرف","lemma":"مُسْرِف","grammar_bn":"শব্দ"},{"id":34312,"position":16,"text_uthmani":"٣١","transliteration":"","translation_bn":"(৩১)","root":"—","lemma":"٣١","grammar_bn":"মার্কার"}]'::jsonb, 'yābanī ādama khudhū zīnatakum ʿinda kulli masjidin wakulū wa-ish''rabū walā tus''rifū innahu lā yuḥibbu l-mus''rifīna', 'হে আদাম সন্তান! প্রত্যেক সলাতের সময় তোমরা সাজসজ্জা গ্রহণ কর, আর খাও, পান কর কিন্তু অপচয় করো না, অবশ্যই তিনি অপচয়কারীদেরকে পছন্দ করেন না।', 'O children of Adam, take your adornment at every masjid, and eat and drink, but be not excessive. Indeed, He likes not those who commit excess.', 'হে আদাম সন্তান! প্রত্যেক সলাতের সময় তোমরা সাজসজ্জা গ্রহণ কর, আর খাও, পান কর কিন্তু অপচয় করো না, অবশ্যই তিনি অপচয়কারীদেরকে পছন্দ করেন না।', 'O children of Adam, take your adornment at every masjid, and eat and drink, but be not excessive. Indeed, He likes not those who commit excess.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007031.mp3', now()),
