  (7, 108, '', '[{"id":73693,"position":1,"text_uthmani":"وَنَزَعَ","transliteration":"wanazaʿa","translation_bn":"এবং টেনে বের করলো","root":"نزع","lemma":"نَزَعَ","grammar_bn":"শব্দ"},{"id":73694,"position":2,"text_uthmani":"يَدَهُۥ","transliteration":"yadahu","translation_bn":"তার হাত","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":73695,"position":3,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"অতঃপর তখন","root":"—","lemma":"إِذَا2\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":73696,"position":4,"text_uthmani":"هِىَ","transliteration":"hiya","translation_bn":"তা","root":"—","lemma":"هِىَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":73697,"position":5,"text_uthmani":"بَيْضَآءُ","transliteration":"bayḍāu","translation_bn":"সাদা উজ্জ্বল (হলো)","root":"بيض","lemma":"أَبْيَض","grammar_bn":"বিশেষ্য (Noun)"},{"id":73698,"position":6,"text_uthmani":"لِلنَّـٰظِرِينَ","transliteration":"lilnnāẓirīna","translation_bn":"কাছে দর্শকদের","root":"نظر","lemma":"نَٰظِرِين","grammar_bn":"অব্যয় (Preposition)"},{"id":73699,"position":7,"text_uthmani":"١٠٨","transliteration":"","translation_bn":"(১০৮)","root":"—","lemma":"١٠٨","grammar_bn":"মার্কার"}]'::jsonb, 'wanazaʿa yadahu fa-idhā hiya bayḍāu lilnnāẓirīna', 'আর সে তার হাত (বগল থেকে) টেনে বের করল, তখন তা দর্শকদের দৃষ্টিতে সাদা উজ্জ্বল হয়ে দেখা দিল।', 'And he drew out his hand; thereupon it was white [with radiance] for the observers.', 'আর সে তার হাত (বগল থেকে) টেনে বের করল, তখন তা দর্শকদের দৃষ্টিতে সাদা উজ্জ্বল হয়ে দেখা দিল।', 'And he drew out his hand; thereupon it was white [with radiance] for the observers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/007108.mp3', now()),
