  (8, 1, '', '[{"id":193,"position":1,"text_uthmani":"يَسْـَٔلُونَكَ","transliteration":"yasalūnaka","translation_bn":"তোমাকে তারা জিজ্ঞাসা করে","root":"سال","lemma":"سَأَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":194,"position":2,"text_uthmani":"عَنِ","transliteration":"ʿani","translation_bn":"সম্পর্কে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":195,"position":3,"text_uthmani":"ٱلْأَنفَالِ ۖ","transliteration":"l-anfāli","translation_bn":"যুদ্ধলব্ধ সম্পদ","root":"نفل","lemma":"أَنفَال","grammar_bn":"শব্দ"},{"id":197,"position":4,"text_uthmani":"قُلِ","transliteration":"quli","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":198,"position":5,"text_uthmani":"ٱلْأَنفَالُ","transliteration":"l-anfālu","translation_bn":"\"যুদ্ধলব্ধ সম্পদ","root":"نفل","lemma":"أَنفَال","grammar_bn":"শব্দ"},{"id":199,"position":6,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"জন্যে আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":200,"position":7,"text_uthmani":"وَٱلرَّسُولِ ۖ","transliteration":"wal-rasūli","translation_bn":"ও রাসূলের (জন্যে)","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":202,"position":8,"text_uthmani":"فَٱتَّقُوا۟","transliteration":"fa-ittaqū","translation_bn":"অতএব তোমরা ভয় করো","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"শব্দ"},{"id":203,"position":9,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":204,"position":10,"text_uthmani":"وَأَصْلِحُوا۟","transliteration":"wa-aṣliḥū","translation_bn":"এবং তোমরা সংশোধন করো","root":"صلح","lemma":"أَصْلَحَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":205,"position":11,"text_uthmani":"ذَاتَ","transliteration":"dhāta","translation_bn":"অবস্থা","root":"—","lemma":"ذُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":206,"position":12,"text_uthmani":"بَيْنِكُمْ ۖ","transliteration":"baynikum","translation_bn":"মধ্যকার তোমাদের","root":"بين","lemma":"بَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":208,"position":13,"text_uthmani":"وَأَطِيعُوا۟","transliteration":"wa-aṭīʿū","translation_bn":"এবং তোমরা আনুগত্য করো","root":"طوع","lemma":"أَطَاعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":209,"position":14,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":210,"position":15,"text_uthmani":"وَرَسُولَهُۥٓ","transliteration":"warasūlahu","translation_bn":"এবং রাসূলের তাঁর","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":211,"position":16,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":212,"position":17,"text_uthmani":"كُنتُم","transliteration":"kuntum","translation_bn":"হও তোমরা","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":213,"position":18,"text_uthmani":"مُّؤْمِنِينَ","transliteration":"mu''minīna","translation_bn":"মু''মিন\"","root":"امن","lemma":"مُؤْمِن","grammar_bn":"বিশেষ্য (Noun)"},{"id":214,"position":19,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'yasalūnaka ʿani l-anfāli quli l-anfālu lillahi wal-rasūli fa-ittaqū l-laha wa-aṣliḥū dhāta baynikum wa-aṭīʿū l-laha warasūlahu in kuntum mu''minīna', 'তারা তোমাকে যুদ্ধে প্রাপ্ত সম্পদ সম্পর্কে জিজ্ঞেস করছে। বল, ‘যুদ্ধে প্রাপ্ত সম্পদ হচ্ছে আল্লাহ ও তাঁর রসূলের; কাজেই তোমরা আল্লাহকে ভয় কর আর নিজেদের সম্পর্ককে সুষ্ঠু সুন্দর ভিত্তির উপর প্রতিষ্ঠিত কর। তোমরা যদি মু’মিন হয়ে থাক তবে তোমরা আল্লাহ ও তাঁর রসূলের আনুগত্য কর।’', 'They ask you, [O Muhammad], about the bounties [of war]. Say, "The [decision concerning] bounties is for Allah and the Messenger." So fear Allah and amend that which is between you and obey Allah and His Messenger, if you should be believers.', 'তারা তোমাকে যুদ্ধে প্রাপ্ত সম্পদ সম্পর্কে জিজ্ঞেস করছে। বল, ‘যুদ্ধে প্রাপ্ত সম্পদ হচ্ছে আল্লাহ ও তাঁর রসূলের; কাজেই তোমরা আল্লাহকে ভয় কর আর নিজেদের সম্পর্ককে সুষ্ঠু সুন্দর ভিত্তির উপর প্রতিষ্ঠিত কর। তোমরা যদি মু’মিন হয়ে থাক তবে তোমরা আল্লাহ ও তাঁর রসূলের আনুগত্য কর।’', 'They ask you, [O Muhammad], about the bounties [of war]. Say, "The [decision concerning] bounties is for Allah and the Messenger." So fear Allah and amend that which is between you and obey Allah and His Messenger, if you should be believers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008001.mp3', now()),
  (8, 2, '', '[{"id":1135,"position":1,"text_uthmani":"إِنَّمَا","transliteration":"innamā","translation_bn":"প্রকৃতপক্ষে","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":1136,"position":2,"text_uthmani":"ٱلْمُؤْمِنُونَ","transliteration":"l-mu''minūna","translation_bn":"মু''মিন","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":1137,"position":3,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তারাই) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1138,"position":4,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"(এমন যে) যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":1139,"position":5,"text_uthmani":"ذُكِرَ","transliteration":"dhukira","translation_bn":"স্মরণ করা হয়","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1140,"position":6,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":1141,"position":7,"text_uthmani":"وَجِلَتْ","transliteration":"wajilat","translation_bn":"কেঁপে উঠে","root":"وجل","lemma":"وَجِلَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1142,"position":8,"text_uthmani":"قُلُوبُهُمْ","transliteration":"qulūbuhum","translation_bn":"অন্তরগুলো তাদের","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":1143,"position":9,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1144,"position":10,"text_uthmani":"تُلِيَتْ","transliteration":"tuliyat","translation_bn":"পাঠ করা হয়","root":"تلو","lemma":"تَلَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1145,"position":11,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"নিকট তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1146,"position":12,"text_uthmani":"ءَايَـٰتُهُۥ","transliteration":"āyātuhu","translation_bn":"আয়াতগুলো তাঁর","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":1147,"position":13,"text_uthmani":"زَادَتْهُمْ","transliteration":"zādathum","translation_bn":"বৃদ্ধি পায় তাদের","root":"زيد","lemma":"زَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1148,"position":14,"text_uthmani":"إِيمَـٰنًۭا","transliteration":"īmānan","translation_bn":"ঈমান","root":"امن","lemma":"إِيمَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":1149,"position":15,"text_uthmani":"وَعَلَىٰ","transliteration":"waʿalā","translation_bn":"ও উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"শব্দ"},{"id":1150,"position":16,"text_uthmani":"رَبِّهِمْ","transliteration":"rabbihim","translation_bn":"রবের তাদের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":1151,"position":17,"text_uthmani":"يَتَوَكَّلُونَ","transliteration":"yatawakkalūna","translation_bn":"তারা নির্ভর করে","root":"وكل","lemma":"تَوَكَّلْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1152,"position":18,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'innamā l-mu''minūna alladhīna idhā dhukira l-lahu wajilat qulūbuhum wa-idhā tuliyat ʿalayhim āyātuhu zādathum īmānan waʿalā rabbihim yatawakkalūna', 'মু’মিন তো তারাই আল্লাহর কথা আলোচিত হলেই যাদের অন্তর কেঁপে উঠে, আর তাদের কাছে যখন তাঁর আয়াত পঠিত হয়, তখন তা তাদের ঈমান বৃদ্ধি করে আর তারা তাদের প্রতিপালকের উপর নির্ভর করে।', 'The believers are only those who, when Allah is mentioned, their hearts become fearful, and when His verses are recited to them, it increases them in faith; and upon their Lord they rely -', 'মু’মিন তো তারাই আল্লাহর কথা আলোচিত হলেই যাদের অন্তর কেঁপে উঠে, আর তাদের কাছে যখন তাঁর আয়াত পঠিত হয়, তখন তা তাদের ঈমান বৃদ্ধি করে আর তারা তাদের প্রতিপালকের উপর নির্ভর করে।', 'The believers are only those who, when Allah is mentioned, their hearts become fearful, and when His verses are recited to them, it increases them in faith; and upon their Lord they rely -', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008002.mp3', now()),
  (8, 3, '', '[{"id":2196,"position":1,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":2197,"position":2,"text_uthmani":"يُقِيمُونَ","transliteration":"yuqīmūna","translation_bn":"প্রতিষ্ঠা করে","root":"قوم","lemma":"أَقَامَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2198,"position":3,"text_uthmani":"ٱلصَّلَوٰةَ","transliteration":"l-ṣalata","translation_bn":"সালাত","root":"صلو","lemma":"صَلَوٰة","grammar_bn":"শব্দ"},{"id":2199,"position":4,"text_uthmani":"وَمِمَّا","transliteration":"wamimmā","translation_bn":"ও (তা) হতে যা","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2200,"position":5,"text_uthmani":"رَزَقْنَـٰهُمْ","transliteration":"razaqnāhum","translation_bn":"আমরা জীবিকা দিয়েছি তাদের","root":"رزق","lemma":"رَزَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2201,"position":6,"text_uthmani":"يُنفِقُونَ","transliteration":"yunfiqūna","translation_bn":"তারা ব্যয় করে","root":"نفق","lemma":"أَنفَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2202,"position":7,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'alladhīna yuqīmūna l-ṣalata wamimmā razaqnāhum yunfiqūna', 'তারা নামায ক্বায়িম করে, আর আমি তাদেরকে যে জীবিকা দিয়েছি তাত্থেকে ব্যয় করে।', 'The ones who establish prayer, and from what We have provided them, they spend.', 'তারা নামায ক্বায়িম করে, আর আমি তাদেরকে যে জীবিকা দিয়েছি তাত্থেকে ব্যয় করে।', 'The ones who establish prayer, and from what We have provided them, they spend.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008003.mp3', now()),
  (8, 4, '', '[{"id":3518,"position":1,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"ঐসব(লোক)","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":3519,"position":2,"text_uthmani":"هُمُ","transliteration":"humu","translation_bn":"তারাই","root":"—","lemma":"هُمُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":3520,"position":3,"text_uthmani":"ٱلْمُؤْمِنُونَ","transliteration":"l-mu''minūna","translation_bn":"মু''মিন","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":3521,"position":4,"text_uthmani":"حَقًّۭا ۚ","transliteration":"ḥaqqan","translation_bn":"প্রকৃত","root":"حقق","lemma":"حَقّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":3523,"position":5,"text_uthmani":"لَّهُمْ","transliteration":"lahum","translation_bn":"জন্যে তাদের(রয়েছে)","root":"—","lemma":"لَّهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":3524,"position":6,"text_uthmani":"دَرَجَـٰتٌ","transliteration":"darajātun","translation_bn":"মর্যাদাসমূহ","root":"درج","lemma":"دَرَجَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":3525,"position":7,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"কাছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":3526,"position":8,"text_uthmani":"رَبِّهِمْ","transliteration":"rabbihim","translation_bn":"রবের তাদের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":3527,"position":9,"text_uthmani":"وَمَغْفِرَةٌۭ","transliteration":"wamaghfiratun","translation_bn":"ও ক্ষমা","root":"غفر","lemma":"مَّغْفِرَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3528,"position":10,"text_uthmani":"وَرِزْقٌۭ","transliteration":"wariz''qun","translation_bn":"ও জীবিকা","root":"رزق","lemma":"رِزْق","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3529,"position":11,"text_uthmani":"كَرِيمٌۭ","transliteration":"karīmun","translation_bn":"সম্মানজনক","root":"كرم","lemma":"كَرِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":3530,"position":12,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'ulāika humu l-mu''minūna ḥaqqan lahum darajātun ʿinda rabbihim wamaghfiratun wariz''qun karīmun', 'এসব লোকেরাই হল প্রকৃত মু’মিন। এদের জন্য এদের প্রতিপালকের নিকট আছে নানান মর্যাদা, ক্ষমা আর সম্মানজনক জীবিকা।', 'Those are the believers, truly. For them are degrees [of high position] with their Lord and forgiveness and noble provision.', 'এসব লোকেরাই হল প্রকৃত মু’মিন। এদের জন্য এদের প্রতিপালকের নিকট আছে নানান মর্যাদা, ক্ষমা আর সম্মানজনক জীবিকা।', 'Those are the believers, truly. For them are degrees [of high position] with their Lord and forgiveness and noble provision.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008004.mp3', now()),
  (8, 5, '', '[{"id":4880,"position":1,"text_uthmani":"كَمَآ","transliteration":"kamā","translation_bn":"যেমন","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4881,"position":2,"text_uthmani":"أَخْرَجَكَ","transliteration":"akhrajaka","translation_bn":"তোমাকে বের করেছিলেন","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4882,"position":3,"text_uthmani":"رَبُّكَ","transliteration":"rabbuka","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":4883,"position":4,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4884,"position":5,"text_uthmani":"بَيْتِكَ","transliteration":"baytika","translation_bn":"তোমার ঘর","root":"بيت","lemma":"بَيْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":4885,"position":6,"text_uthmani":"بِٱلْحَقِّ","transliteration":"bil-ḥaqi","translation_bn":"ভাবে ন্যায়","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":4886,"position":7,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":4887,"position":8,"text_uthmani":"فَرِيقًۭا","transliteration":"farīqan","translation_bn":"একদল","root":"فرق","lemma":"فَرِيق","grammar_bn":"বিশেষ্য (Noun)"},{"id":4888,"position":9,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"মধ্য হতে(ছিলো)","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4889,"position":10,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"মু''মিনদের","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":4890,"position":11,"text_uthmani":"لَكَـٰرِهُونَ","transliteration":"lakārihūna","translation_bn":"অবশ্যই অপছন্দকারী","root":"كره","lemma":"كَٰرِهُون","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":4891,"position":12,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'kamā akhrajaka rabbuka min baytika bil-ḥaqi wa-inna farīqan mina l-mu''minīna lakārihūna', '(তারা যেমন প্রকৃত মু’মিন) ঠিক তেমনি প্রকৃতভাবেই তোমার প্রতিপালক তোমাকে তোমার ঘর হতে বের করে এনেছিলেন যদিও মু’মিনদের একদল তা পছন্দ করেনি।', '[It is] just as when your Lord brought you out of your home [for the battle of Badr] in truth, while indeed, a party among the believers were unwilling,', '(তারা যেমন প্রকৃত মু’মিন) ঠিক তেমনি প্রকৃতভাবেই তোমার প্রতিপালক তোমাকে তোমার ঘর হতে বের করে এনেছিলেন যদিও মু’মিনদের একদল তা পছন্দ করেনি।', '[It is] just as when your Lord brought you out of your home [for the battle of Badr] in truth, while indeed, a party among the believers were unwilling,', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008005.mp3', now()),
  (8, 6, '', '[{"id":6115,"position":1,"text_uthmani":"يُجَـٰدِلُونَكَ","transliteration":"yujādilūnaka","translation_bn":"তোমার সাথে তারা বিতর্ক করে","root":"جدل","lemma":"جَٰدَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6116,"position":2,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"ব্যাপারে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6117,"position":3,"text_uthmani":"ٱلْحَقِّ","transliteration":"l-ḥaqi","translation_bn":"সত্যের","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":6118,"position":4,"text_uthmani":"بَعْدَ مَا","transliteration":"baʿdamā","translation_bn":"পরেও তা","root":"بعد\r","lemma":"بَعْد","grammar_bn":"কালবাচক (Time)"},{"id":6119,"position":5,"text_uthmani":"تَبَيَّنَ","transliteration":"tabayyana","translation_bn":"সুস্পষ্ট হওয়ার","root":"بين","lemma":"تَبَيَّنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6120,"position":6,"text_uthmani":"كَأَنَّمَا","transliteration":"ka-annamā","translation_bn":"যেন প্রকৃতপক্ষে","root":"—","lemma":"كَأَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":6121,"position":7,"text_uthmani":"يُسَاقُونَ","transliteration":"yusāqūna","translation_bn":"তারা চালিত হচ্ছে","root":"سوق","lemma":"سِيقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6122,"position":8,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6123,"position":9,"text_uthmani":"ٱلْمَوْتِ","transliteration":"l-mawti","translation_bn":"মৃত্যুর","root":"موت","lemma":"مَوْت","grammar_bn":"শব্দ"},{"id":6124,"position":10,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"এ অবস্থায়(যেন) তারা","root":"—","lemma":"وَهُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":6125,"position":11,"text_uthmani":"يَنظُرُونَ","transliteration":"yanẓurūna","translation_bn":"প্রত্যক্ষ করছে(মৃত্যু)","root":"نظر","lemma":"نَّظَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6127,"position":12,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'yujādilūnaka fī l-ḥaqi baʿdamā tabayyana ka-annamā yusāqūna ilā l-mawti wahum yanẓurūna', 'সত্য স্পষ্ট হওয়ার পরও তারা তোমার সঙ্গে বাদানুবাদে লিপ্ত হয়েছিল, (তাদের অবস্থা দেখে মনে হচ্ছিল যে,) তারা যেন চেয়ে চেয়ে দেখছিল যে, তাদেরকে মৃত্যুর দিকে তাড়িয়ে নেয়া হচ্ছে।', 'Arguing with you concerning the truth after it had become clear, as if they were being driven toward death while they were looking on.', 'সত্য স্পষ্ট হওয়ার পরও তারা তোমার সঙ্গে বাদানুবাদে লিপ্ত হয়েছিল, (তাদের অবস্থা দেখে মনে হচ্ছিল যে,) তারা যেন চেয়ে চেয়ে দেখছিল যে, তাদেরকে মৃত্যুর দিকে তাড়িয়ে নেয়া হচ্ছে।', 'Arguing with you concerning the truth after it had become clear, as if they were being driven toward death while they were looking on.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008006.mp3', now()),
  (8, 7, '', '[{"id":7458,"position":1,"text_uthmani":"وَإِذْ","transliteration":"wa-idh","translation_bn":"এবং (স্মরণ করো)যখন","root":"—","lemma":"إِذ\r","grammar_bn":"শব্দ"},{"id":7459,"position":2,"text_uthmani":"يَعِدُكُمُ","transliteration":"yaʿidukumu","translation_bn":"প্রতিশ্রুতি দেন তোমাদের","root":"وعد","lemma":"وَعَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7460,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":7461,"position":4,"text_uthmani":"إِحْدَى","transliteration":"iḥ''dā","translation_bn":"একটির","root":"احد","lemma":"إِحْدَى","grammar_bn":"বিশেষ্য (Noun)"},{"id":7462,"position":5,"text_uthmani":"ٱلطَّآئِفَتَيْنِ","transliteration":"l-ṭāifatayni","translation_bn":"দুইদলের(মধ্যে)","root":"طوف","lemma":"طَا^ئِفَة","grammar_bn":"শব্দ"},{"id":7463,"position":6,"text_uthmani":"أَنَّهَا","transliteration":"annahā","translation_bn":"যে তা(আওতাধীন হবে)","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":7464,"position":7,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":7465,"position":8,"text_uthmani":"وَتَوَدُّونَ","transliteration":"watawaddūna","translation_bn":"অথচ তোমরা চেয়েছিলে","root":"ودد","lemma":"وَدَّ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":7466,"position":9,"text_uthmani":"أَنَّ","transliteration":"anna","translation_bn":"যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":7467,"position":10,"text_uthmani":"غَيْرَ","transliteration":"ghayra","translation_bn":"নয়","root":"غير","lemma":"غَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":7468,"position":11,"text_uthmani":"ذَاتِ","transliteration":"dhāti","translation_bn":"যুক্ত","root":"—","lemma":"ذُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":7469,"position":12,"text_uthmani":"ٱلشَّوْكَةِ","transliteration":"l-shawkati","translation_bn":"কাঁটা","root":"شوك","lemma":"شَّوْكَة","grammar_bn":"শব্দ"},{"id":7470,"position":13,"text_uthmani":"تَكُونُ","transliteration":"takūnu","translation_bn":"তা হবে (সংঘর্ষশীল)","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7471,"position":14,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":7472,"position":15,"text_uthmani":"وَيُرِيدُ","transliteration":"wayurīdu","translation_bn":"কিন্তু চান","root":"رود","lemma":"أَرَادَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7473,"position":16,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":7474,"position":17,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":7475,"position":18,"text_uthmani":"يُحِقَّ","transliteration":"yuḥiqqa","translation_bn":"সত্যে পরিণত করতে","root":"حقق","lemma":"يُحِقَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7476,"position":19,"text_uthmani":"ٱلْحَقَّ","transliteration":"l-ḥaqa","translation_bn":"সত্যকে","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":7477,"position":20,"text_uthmani":"بِكَلِمَـٰتِهِۦ","transliteration":"bikalimātihi","translation_bn":"দিয়ে বাণীসমূহ তাঁর","root":"كلم","lemma":"كَلِمَٰت","grammar_bn":"অব্যয় (Preposition)"},{"id":7478,"position":21,"text_uthmani":"وَيَقْطَعَ","transliteration":"wayaqṭaʿa","translation_bn":"এবং কাটবেন","root":"قطع","lemma":"قُطِعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7479,"position":22,"text_uthmani":"دَابِرَ","transliteration":"dābira","translation_bn":"মূল","root":"دبر","lemma":"دَابِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":7480,"position":23,"text_uthmani":"ٱلْكَـٰفِرِينَ","transliteration":"l-kāfirīna","translation_bn":"কাফেরদের","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"শব্দ"},{"id":7481,"position":24,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idh yaʿidukumu l-lahu iḥ''dā l-ṭāifatayni annahā lakum watawaddūna anna ghayra dhāti l-shawkati takūnu lakum wayurīdu l-lahu an yuḥiqqa l-ḥaqa bikalimātihi wayaqṭaʿa dābira l-kāfirīna', 'স্মরণ কর, যখন আল্লাহ তোমাদেরকে প্রতিশ্রুতি দিয়েছিলেন যে, দু’টি দলের মধ্যে একটি তোমরা পাবে, আর তোমরা চেয়েছিলে যেন নিরস্ত্র দলটি তোমরা লাভ কর আর আল্লাহ চেয়েছিলেন তাঁর বাণী দ্বারা সত্যকে সত্যরূপে প্রতিষ্ঠিত করতে আর কাফিরদের জড় কেটে দিতে।', '[Remember, O believers], when Allah promised you one of the two groups - that it would be yours - and you wished that the unarmed one would be yours. But Allah intended to establish the truth by His words and to eliminate the disbelievers', 'স্মরণ কর, যখন আল্লাহ তোমাদেরকে প্রতিশ্রুতি দিয়েছিলেন যে, দু’টি দলের মধ্যে একটি তোমরা পাবে, আর তোমরা চেয়েছিলে যেন নিরস্ত্র দলটি তোমরা লাভ কর আর আল্লাহ চেয়েছিলেন তাঁর বাণী দ্বারা সত্যকে সত্যরূপে প্রতিষ্ঠিত করতে আর কাফিরদের জড় কেটে দিতে।', '[Remember, O believers], when Allah promised you one of the two groups - that it would be yours - and you wished that the unarmed one would be yours. But Allah intended to establish the truth by His words and to eliminate the disbelievers', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008007.mp3', now()),
  (8, 8, '', '[{"id":8719,"position":1,"text_uthmani":"لِيُحِقَّ","transliteration":"liyuḥiqqa","translation_bn":"যেন সত্যে পরিণত করেন","root":"حقق","lemma":"يُحِقَّ","grammar_bn":"শব্দ"},{"id":8720,"position":2,"text_uthmani":"ٱلْحَقَّ","transliteration":"l-ḥaqa","translation_bn":"সত্যকে","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":8721,"position":3,"text_uthmani":"وَيُبْطِلَ","transliteration":"wayub''ṭila","translation_bn":"ও অসত্যে পরিণত করেন","root":"بطل","lemma":"يُبْطِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8722,"position":4,"text_uthmani":"ٱلْبَـٰطِلَ","transliteration":"l-bāṭila","translation_bn":"অসত্যকে","root":"بطل","lemma":"بَٰطِل","grammar_bn":"শব্দ"},{"id":8723,"position":5,"text_uthmani":"وَلَوْ","transliteration":"walaw","translation_bn":"এবং যদিও (তা)","root":"—","lemma":"لَو\r","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":8724,"position":6,"text_uthmani":"كَرِهَ","transliteration":"kariha","translation_bn":"অপছন্দ করে","root":"كره","lemma":"كَرِهَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8725,"position":7,"text_uthmani":"ٱلْمُجْرِمُونَ","transliteration":"l-muj''rimūna","translation_bn":"অপরাধীরা","root":"جرم","lemma":"مُجْرِم","grammar_bn":"শব্দ"},{"id":8726,"position":8,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'liyuḥiqqa l-ḥaqa wayub''ṭila l-bāṭila walaw kariha l-muj''rimūna', 'যাতে তিনি সত্যকে সত্য হিসেবে প্রতিষ্ঠিত করেন আর মিথ্যেকে মিথ্যে প্রমাণিত করেন, যদিও তা পাপীদের কাছে পছন্দনীয় নয়।', 'That He should establish the truth and abolish falsehood, even if the criminals disliked it.', 'যাতে তিনি সত্যকে সত্য হিসেবে প্রতিষ্ঠিত করেন আর মিথ্যেকে মিথ্যে প্রমাণিত করেন, যদিও তা পাপীদের কাছে পছন্দনীয় নয়।', 'That He should establish the truth and abolish falsehood, even if the criminals disliked it.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008008.mp3', now()),
  (8, 9, '', '[{"id":9940,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"(স্মরণ করো) যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":9941,"position":2,"text_uthmani":"تَسْتَغِيثُونَ","transliteration":"tastaghīthūna","translation_bn":"তোমরা সাহায্য চেয়েছিলে","root":"غوث","lemma":"ٱسْتَغَٰثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9942,"position":3,"text_uthmani":"رَبَّكُمْ","transliteration":"rabbakum","translation_bn":"তোমাদের রবের কাছে","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":9943,"position":4,"text_uthmani":"فَٱسْتَجَابَ","transliteration":"fa-is''tajāba","translation_bn":"তখন তিনি ডাকে সাড়া দিলেন","root":"جوب","lemma":"ٱسْتَجَابَ","grammar_bn":"কারণবাচক (Cause)"},{"id":9944,"position":5,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"প্রতি তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":9945,"position":6,"text_uthmani":"أَنِّى","transliteration":"annī","translation_bn":"\"(এভাবে) যে আমি","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":9946,"position":7,"text_uthmani":"مُمِدُّكُم","transliteration":"mumiddukum","translation_bn":"সাহায্য করছি তোমাদের","root":"مدد","lemma":"مُمِدّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":9947,"position":8,"text_uthmani":"بِأَلْفٍۢ","transliteration":"bi-alfin","translation_bn":"দিয়ে এক হাজার","root":"الف","lemma":"أَلْف","grammar_bn":"অব্যয় (Preposition)"},{"id":9948,"position":9,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9949,"position":10,"text_uthmani":"ٱلْمَلَـٰٓئِكَةِ","transliteration":"l-malāikati","translation_bn":"ফেরেশতাদের","root":"ملك","lemma":"مَلَك","grammar_bn":"শব্দ"},{"id":9950,"position":11,"text_uthmani":"مُرْدِفِينَ","transliteration":"mur''difīna","translation_bn":"ধারাবাহিকভাবে আগত\"","root":"ردف","lemma":"مُرْدِفِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":9951,"position":12,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'idh tastaghīthūna rabbakum fa-is''tajāba lakum annī mumiddukum bi-alfin mina l-malāikati mur''difīna', 'স্মরণ কর, যখন তোমরা তোমাদের প্রতিপালকের নিকট সাহায্য প্রার্থনা করছিলে তখন তিনি তোমাদেরকে জবাব দিলেন, ‘আমি তোমাদেরকে এক হাজার ফেরেশতা দিয়ে সাহায্য করব যারা পর পর আসবে।’', '[Remember] when you asked help of your Lord, and He answered you, "Indeed, I will reinforce you with a thousand from the angels, following one another."', 'স্মরণ কর, যখন তোমরা তোমাদের প্রতিপালকের নিকট সাহায্য প্রার্থনা করছিলে তখন তিনি তোমাদেরকে জবাব দিলেন, ‘আমি তোমাদেরকে এক হাজার ফেরেশতা দিয়ে সাহায্য করব যারা পর পর আসবে।’', '[Remember] when you asked help of your Lord, and He answered you, "Indeed, I will reinforce you with a thousand from the angels, following one another."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008009.mp3', now()),
  (8, 10, '', '[{"id":11134,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":11135,"position":2,"text_uthmani":"جَعَلَهُ","transliteration":"jaʿalahu","translation_bn":"করেছিলেন তা","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11136,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":11137,"position":4,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":11138,"position":5,"text_uthmani":"بُشْرَىٰ","transliteration":"bush''rā","translation_bn":"সুসংবাদ হিসেবে","root":"بشر","lemma":"بُشْرَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":11139,"position":6,"text_uthmani":"وَلِتَطْمَئِنَّ","transliteration":"walitaṭma-inna","translation_bn":"এবং যেন প্রশান্ত হয়","root":"طمن","lemma":"ٱطْمَأَنَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11140,"position":7,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"দিয়ে তা","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":11141,"position":8,"text_uthmani":"قُلُوبُكُمْ ۚ","transliteration":"qulūbukum","translation_bn":"অন্তরসমূহ তোমাদের","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":11143,"position":9,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":11144,"position":10,"text_uthmani":"ٱلنَّصْرُ","transliteration":"l-naṣru","translation_bn":"সাহায্য(আসে)","root":"نصر","lemma":"نَصْر","grammar_bn":"শব্দ"},{"id":11145,"position":11,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":11146,"position":12,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11147,"position":13,"text_uthmani":"عِندِ","transliteration":"ʿindi","translation_bn":"নিকট","root":"عند","lemma":"عِند","grammar_bn":"বিশেষ্য (Noun)"},{"id":11148,"position":14,"text_uthmani":"ٱللَّهِ ۚ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":11150,"position":15,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":11151,"position":16,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":11152,"position":17,"text_uthmani":"عَزِيزٌ","transliteration":"ʿazīzun","translation_bn":"পরাক্রমশালী","root":"عزز","lemma":"عَزِيز","grammar_bn":"বিশেষ্য (Noun)"},{"id":11153,"position":18,"text_uthmani":"حَكِيمٌ","transliteration":"ḥakīmun","translation_bn":"মহাবিজ্ঞ","root":"حكم","lemma":"حَكِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":11154,"position":19,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'wamā jaʿalahu l-lahu illā bush''rā walitaṭma-inna bihi qulūbukum wamā l-naṣru illā min ʿindi l-lahi inna l-laha ʿazīzun ḥakīmun', 'আর আল্লাহ যে এটা করেছিলেন তার উদ্দেশ্য তোমাদেরকে সুসংবাদ দান ছাড়া অন্য কিছু নয় আর যাতে এর মাধ্যমে তোমাদের অন্তর প্রশান্তি লাভ করে। কেননা, সাহায্য তো একমাত্র আল্লাহর নিকট থেকেই আসে। আল্লাহ তো মহাপরাক্রমশালী, মহাবিজ্ঞানী।', 'And Allah made it not but good tidings and so that your hearts would be assured thereby. And victory is not but from Allah. Indeed, Allah is Exalted in Might and Wise.', 'আর আল্লাহ যে এটা করেছিলেন তার উদ্দেশ্য তোমাদেরকে সুসংবাদ দান ছাড়া অন্য কিছু নয় আর যাতে এর মাধ্যমে তোমাদের অন্তর প্রশান্তি লাভ করে। কেননা, সাহায্য তো একমাত্র আল্লাহর নিকট থেকেই আসে। আল্লাহ তো মহাপরাক্রমশালী, মহাবিজ্ঞানী।', 'And Allah made it not but good tidings and so that your hearts would be assured thereby. And victory is not but from Allah. Indeed, Allah is Exalted in Might and Wise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008010.mp3', now()),
  (8, 11, '', '[{"id":12458,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"(স্মরণ করো) যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":12459,"position":2,"text_uthmani":"يُغَشِّيكُمُ","transliteration":"yughashīkumu","translation_bn":"তিনি আচ্ছন্ন করেন তোমাদেরকে","root":"غشو","lemma":"غَشَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12460,"position":3,"text_uthmani":"ٱلنُّعَاسَ","transliteration":"l-nuʿāsa","translation_bn":"তন্দ্রা(দিয়ে)","root":"نعس","lemma":"نُّعَاس","grammar_bn":"শব্দ"},{"id":12461,"position":4,"text_uthmani":"أَمَنَةًۭ","transliteration":"amanatan","translation_bn":"নিরাপত্তার জন্যে","root":"امن","lemma":"أَمَنَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":12462,"position":5,"text_uthmani":"مِّنْهُ","transliteration":"min''hu","translation_bn":"পক্ষ হতে তাঁর","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12463,"position":6,"text_uthmani":"وَيُنَزِّلُ","transliteration":"wayunazzilu","translation_bn":"ও অবতীর্ণ করেন","root":"نزل","lemma":"نَزَّلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12464,"position":7,"text_uthmani":"عَلَيْكُم","transliteration":"ʿalaykum","translation_bn":"উপর তোমাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12465,"position":8,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12466,"position":9,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":12467,"position":10,"text_uthmani":"مَآءًۭ","transliteration":"māan","translation_bn":"পানি","root":"موه","lemma":"مَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":12468,"position":11,"text_uthmani":"لِّيُطَهِّرَكُم","transliteration":"liyuṭahhirakum","translation_bn":"জন্যে পবিত্র করার তোমাদেরকে","root":"طهر","lemma":"طَهَّرَ","grammar_bn":"শব্দ"},{"id":12469,"position":12,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"দিয়ে তা","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":12470,"position":13,"text_uthmani":"وَيُذْهِبَ","transliteration":"wayudh''hiba","translation_bn":"এবং দূর করার(জন্যে)","root":"ذهب","lemma":"أَذْهَبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12471,"position":14,"text_uthmani":"عَنكُمْ","transliteration":"ʿankum","translation_bn":"হতে তোমাদের","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12472,"position":15,"text_uthmani":"رِجْزَ","transliteration":"rij''za","translation_bn":"অপবিত্রতা","root":"رجز","lemma":"رِجْز","grammar_bn":"বিশেষ্য (Noun)"},{"id":12473,"position":16,"text_uthmani":"ٱلشَّيْطَـٰنِ","transliteration":"l-shayṭāni","translation_bn":"শয়তানের","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"শব্দ"},{"id":12474,"position":17,"text_uthmani":"وَلِيَرْبِطَ","transliteration":"waliyarbiṭa","translation_bn":"এবং জন্যে  দূঢ় করার","root":"ربط","lemma":"رَّبَطْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12475,"position":18,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12476,"position":19,"text_uthmani":"قُلُوبِكُمْ","transliteration":"qulūbikum","translation_bn":"অন্তরসমূহের তোমাদের","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":12477,"position":20,"text_uthmani":"وَيُثَبِّتَ","transliteration":"wayuthabbita","translation_bn":"ও স্থির করার (জন্যে)","root":"ثبت","lemma":"ثَبَّتْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12478,"position":21,"text_uthmani":"بِهِ","transliteration":"bihi","translation_bn":"দিয়ে তা","root":"—","lemma":"بِهِ","grammar_bn":"অব্যয় (Preposition)"},{"id":12479,"position":22,"text_uthmani":"ٱلْأَقْدَامَ","transliteration":"l-aqdāma","translation_bn":"(তোমাদের) পাগুলোকে","root":"قدم","lemma":"قَدَم","grammar_bn":"শব্দ"},{"id":12480,"position":23,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'idh yughashīkumu l-nuʿāsa amanatan min''hu wayunazzilu ʿalaykum mina l-samāi māan liyuṭahhirakum bihi wayudh''hiba ʿankum rij''za l-shayṭāni waliyarbiṭa ʿalā qulūbikum wayuthabbita bihi l-aqdāma', 'স্মরণ কর, যখন আল্লাহ তাঁর নিকট হতে প্রশান্তি ধারা হিসেবে তোমাদেরকে তন্দ্রায় আচ্ছন্ন করেছিলেন, আকাশ হতে তোমাদের উপর বৃষ্টিধারা বর্ষণ করেছিলেন তোমাদেরকে তা দিয়ে পবিত্র করার জন্য। তোমাদের থেকে শয়ত্বানী পংকিলতা দূর করার জন্য, তোমাদের দিলকে মজবুত করার জন্য আর তা দিয়ে তোমাদের পায়ের ভিত শক্ত করার জন্য।', '[Remember] when He overwhelmed you with drowsiness [giving] security from Him and sent down upon you from the sky, rain by which to purify you and remove from you the evil [suggestions] of Satan and to make steadfast your hearts and plant firmly thereby your feet.', 'স্মরণ কর, যখন আল্লাহ তাঁর নিকট হতে প্রশান্তি ধারা হিসেবে তোমাদেরকে তন্দ্রায় আচ্ছন্ন করেছিলেন, আকাশ হতে তোমাদের উপর বৃষ্টিধারা বর্ষণ করেছিলেন তোমাদেরকে তা দিয়ে পবিত্র করার জন্য। তোমাদের থেকে শয়ত্বানী পংকিলতা দূর করার জন্য, তোমাদের দিলকে মজবুত করার জন্য আর তা দিয়ে তোমাদের পায়ের ভিত শক্ত করার জন্য।', '[Remember] when He overwhelmed you with drowsiness [giving] security from Him and sent down upon you from the sky, rain by which to purify you and remove from you the evil [suggestions] of Satan and to make steadfast your hearts and plant firmly thereby your feet.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008011.mp3', now()),
  (8, 12, '', '[{"id":13772,"position":1,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"(স্মরণ করো) যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":13773,"position":2,"text_uthmani":"يُوحِى","transliteration":"yūḥī","translation_bn":"ওহী করেন","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":13774,"position":3,"text_uthmani":"رَبُّكَ","transliteration":"rabbuka","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":13775,"position":4,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13776,"position":5,"text_uthmani":"ٱلْمَلَـٰٓئِكَةِ","transliteration":"l-malāikati","translation_bn":"ফেরেশতাদের","root":"ملك","lemma":"مَلَك","grammar_bn":"শব্দ"},{"id":13777,"position":6,"text_uthmani":"أَنِّى","transliteration":"annī","translation_bn":"\"যে আমি","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":13778,"position":7,"text_uthmani":"مَعَكُمْ","transliteration":"maʿakum","translation_bn":"সাথে(আছি)তোমাদের","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":13779,"position":8,"text_uthmani":"فَثَبِّتُوا۟","transliteration":"fathabbitū","translation_bn":"সুতরাং তোমরা অবিচল রাখো","root":"ثبت","lemma":"ثَبَّتْ","grammar_bn":"শব্দ"},{"id":13780,"position":9,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদেরকে) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":13781,"position":10,"text_uthmani":"ءَامَنُوا۟ ۚ","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13783,"position":11,"text_uthmani":"سَأُلْقِى","transliteration":"sa-ul''qī","translation_bn":"অচিরেই আমি ঢুকিয়ে দিবো","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"ভবিষ্যদ্বাচক (Future)"},{"id":13784,"position":12,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13785,"position":13,"text_uthmani":"قُلُوبِ","transliteration":"qulūbi","translation_bn":"অন্তরসমূহের","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":13786,"position":14,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":13787,"position":15,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13788,"position":16,"text_uthmani":"ٱلرُّعْبَ","transliteration":"l-ruʿ''ba","translation_bn":"ভয়","root":"رعب","lemma":"رُعْب","grammar_bn":"শব্দ"},{"id":13789,"position":17,"text_uthmani":"فَٱضْرِبُوا۟","transliteration":"fa-iḍ''ribū","translation_bn":"অতএব তোমরা আঘাত করো","root":"ضرب","lemma":"ضَرَبَ","grammar_bn":"শব্দ"},{"id":13790,"position":18,"text_uthmani":"فَوْقَ","transliteration":"fawqa","translation_bn":"উপর","root":"فوق","lemma":"فَوْق","grammar_bn":"স্থানবাচক (Location)"},{"id":13791,"position":19,"text_uthmani":"ٱلْأَعْنَاقِ","transliteration":"l-aʿnāqi","translation_bn":"(তাদের)ঘাড়সমূহের","root":"عنق","lemma":"عُنُق","grammar_bn":"শব্দ"},{"id":13792,"position":20,"text_uthmani":"وَٱضْرِبُوا۟","transliteration":"wa-iḍ''ribū","translation_bn":"এবং তোমরা আঘাত করো","root":"ضرب","lemma":"ضَرَبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13793,"position":21,"text_uthmani":"مِنْهُمْ","transliteration":"min''hum","translation_bn":"মধ্য থেকে তাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13794,"position":22,"text_uthmani":"كُلَّ","transliteration":"kulla","translation_bn":"প্রত্যেকে","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":13795,"position":23,"text_uthmani":"بَنَانٍۢ","transliteration":"banānin","translation_bn":"জোড়ায় জোড়ায়\"","root":"بنن","lemma":"بَنَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":13796,"position":24,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'idh yūḥī rabbuka ilā l-malāikati annī maʿakum fathabbitū alladhīna āmanū sa-ul''qī fī qulūbi alladhīna kafarū l-ruʿ''ba fa-iḍ''ribū fawqa l-aʿnāqi wa-iḍ''ribū min''hum kulla banānin', 'স্মরণ কর যখন তোমার প্রতিপালক ফেরেশতাদের প্রতি ওয়াহী পাঠিয়েছিলেন, ‘আমি তোমাদের সঙ্গেই আছি; অতএব মু’মিনদেরকে তোমরা দৃঢ়পদ রেখ’। অচিরেই আমি কাফিরদের দিলে ভীতি সঞ্চার করব, কাজেই তাদের স্কন্ধে আঘাত হান, আঘাত হান প্রত্যেকটি আঙ্গুলের গিঁটে গিঁটে।', '[Remember] when your Lord inspired to the angels, "I am with you, so strengthen those who have believed. I will cast terror into the hearts of those who disbelieved, so strike [them] upon the necks and strike from them every fingertip."', 'স্মরণ কর যখন তোমার প্রতিপালক ফেরেশতাদের প্রতি ওয়াহী পাঠিয়েছিলেন, ‘আমি তোমাদের সঙ্গেই আছি; অতএব মু’মিনদেরকে তোমরা দৃঢ়পদ রেখ’। অচিরেই আমি কাফিরদের দিলে ভীতি সঞ্চার করব, কাজেই তাদের স্কন্ধে আঘাত হান, আঘাত হান প্রত্যেকটি আঙ্গুলের গিঁটে গিঁটে।', '[Remember] when your Lord inspired to the angels, "I am with you, so strengthen those who have believed. I will cast terror into the hearts of those who disbelieved, so strike [them] upon the necks and strike from them every fingertip."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008012.mp3', now()),
  (8, 13, '', '[{"id":14944,"position":1,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":14945,"position":2,"text_uthmani":"بِأَنَّهُمْ","transliteration":"bi-annahum","translation_bn":"এজন্য যে তারা","root":"—","lemma":"أَنّ","grammar_bn":"অব্যয় (Preposition)"},{"id":14946,"position":3,"text_uthmani":"شَآقُّوا۟","transliteration":"shāqqū","translation_bn":"তারা বিরোধিতা করেছিলো","root":"شقق","lemma":"شَا^قُّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14947,"position":4,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":14948,"position":5,"text_uthmani":"وَرَسُولَهُۥ ۚ","transliteration":"warasūlahu","translation_bn":"ও রাসূলের তাঁর","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14950,"position":6,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"এবং যে","root":"—","lemma":"مَن\r","grammar_bn":"শব্দ"},{"id":14951,"position":7,"text_uthmani":"يُشَاقِقِ","transliteration":"yushāqiqi","translation_bn":"বিরোধিতা করে","root":"شقق","lemma":"شَا^قُّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14952,"position":8,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":14953,"position":9,"text_uthmani":"وَرَسُولَهُۥ","transliteration":"warasūlahu","translation_bn":"ও রাসূলের তাঁর","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14954,"position":10,"text_uthmani":"فَإِنَّ","transliteration":"fa-inna","translation_bn":"সেক্ষেত্রে নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"ফলাফল পদ (Result)"},{"id":14955,"position":11,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":14956,"position":12,"text_uthmani":"شَدِيدُ","transliteration":"shadīdu","translation_bn":"কঠোর","root":"شدد","lemma":"شَدِيد","grammar_bn":"বিশেষ্য (Noun)"},{"id":14957,"position":13,"text_uthmani":"ٱلْعِقَابِ","transliteration":"l-ʿiqābi","translation_bn":"দন্ডদানে","root":"عقب","lemma":"عِقَاب","grammar_bn":"শব্দ"},{"id":14958,"position":14,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'dhālika bi-annahum shāqqū l-laha warasūlahu waman yushāqiqi l-laha warasūlahu fa-inna l-laha shadīdu l-ʿiqābi', 'এর কারণ হল, তারা আল্লাহ ও রসূলের বিরোধিতা করে আর যারা আল্লাহ ও তাঁর রসূলের বিরোধিতা করবে (তাদের জেনে রাখা দরকার) আল্লাহ শাস্তিদানে বড়ই কঠোর।', 'That is because they opposed Allah and His Messenger. And whoever opposes Allah and His Messenger - indeed, Allah is severe in penalty.', 'এর কারণ হল, তারা আল্লাহ ও রসূলের বিরোধিতা করে আর যারা আল্লাহ ও তাঁর রসূলের বিরোধিতা করবে (তাদের জেনে রাখা দরকার) আল্লাহ শাস্তিদানে বড়ই কঠোর।', 'That is because they opposed Allah and His Messenger. And whoever opposes Allah and His Messenger - indeed, Allah is severe in penalty.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008013.mp3', now()),
  (8, 14, '', '[{"id":16016,"position":1,"text_uthmani":"ذَٰلِكُمْ","transliteration":"dhālikum","translation_bn":"এটাই(শাস্তি)তোমাদের","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":16017,"position":2,"text_uthmani":"فَذُوقُوهُ","transliteration":"fadhūqūhu","translation_bn":"\"তাই তোমরা স্বাদ নাও তার\"","root":"ذوق","lemma":"ذَاقُ","grammar_bn":"সম্পূরক পদ (Supplemental)"},{"id":16018,"position":3,"text_uthmani":"وَأَنَّ","transliteration":"wa-anna","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"أَنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16019,"position":4,"text_uthmani":"لِلْكَـٰفِرِينَ","transliteration":"lil''kāfirīna","translation_bn":"জন্যে কাফেরদের(রয়েছে)","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"অব্যয় (Preposition)"},{"id":16020,"position":5,"text_uthmani":"عَذَابَ","transliteration":"ʿadhāba","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":16021,"position":6,"text_uthmani":"ٱلنَّارِ","transliteration":"l-nāri","translation_bn":"আগুনের","root":"نور","lemma":"نَار","grammar_bn":"শব্দ"},{"id":16022,"position":7,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'dhālikum fadhūqūhu wa-anna lil''kāfirīna ʿadhāba l-nāri', 'এটাই তোমাদের শাস্তি, অতএব তার স্বাদ গ্রহণ কর, কাফিরদের জন্য আছে আগুনের (জাহান্নামের) শাস্তি।', '"That [is yours], so taste it." And indeed for the disbelievers is the punishment of the Fire.', 'এটাই তোমাদের শাস্তি, অতএব তার স্বাদ গ্রহণ কর, কাফিরদের জন্য আছে আগুনের (জাহান্নামের) শাস্তি।', '"That [is yours], so taste it." And indeed for the disbelievers is the punishment of the Fire.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008014.mp3', now()),
  (8, 15, '', '[{"id":17249,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":17250,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":17251,"position":3,"text_uthmani":"ءَامَنُوٓا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17252,"position":4,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":17253,"position":5,"text_uthmani":"لَقِيتُمُ","transliteration":"laqītumu","translation_bn":"তোমরা সম্মুখীন হও","root":"لقي","lemma":"لَقُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17254,"position":6,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদের)যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":17255,"position":7,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অবিশ্বাস করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17256,"position":8,"text_uthmani":"زَحْفًۭا","transliteration":"zaḥfan","translation_bn":"(সৈন্য) বাহিনী হিসেবে","root":"زحف","lemma":"زَحْف","grammar_bn":"বিশেষ্য (Noun)"},{"id":17257,"position":9,"text_uthmani":"فَلَا","transliteration":"falā","translation_bn":"তখন না","root":"—","lemma":"لَا\r","grammar_bn":"ফলাফল পদ (Result)"},{"id":17258,"position":10,"text_uthmani":"تُوَلُّوهُمُ","transliteration":"tuwallūhumu","translation_bn":"দিকে ফিরাবে তাদের","root":"ولي","lemma":"وَلَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17259,"position":11,"text_uthmani":"ٱلْأَدْبَارَ","transliteration":"l-adbāra","translation_bn":"পিঠসমূহকে","root":"دبر","lemma":"دُبُر","grammar_bn":"শব্দ"},{"id":17260,"position":12,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā alladhīna āmanū idhā laqītumu alladhīna kafarū zaḥfan falā tuwallūhumu l-adbāra', 'হে মু’মিনগণ! তোমরা যখন যোদ্ধা-বাহিনীরূপে কাফিরদের সম্মুখীন হও, তখন তাদেরকে পৃষ্ঠপ্রদর্শন করবে না।', 'O you who have believed, when you meet those who disbelieve advancing [for battle], do not turn to them your backs [in flight].', 'হে মু’মিনগণ! তোমরা যখন যোদ্ধা-বাহিনীরূপে কাফিরদের সম্মুখীন হও, তখন তাদেরকে পৃষ্ঠপ্রদর্শন করবে না।', 'O you who have believed, when you meet those who disbelieve advancing [for battle], do not turn to them your backs [in flight].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008015.mp3', now()),
  (8, 16, '', '[{"id":18313,"position":1,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"এবং যে","root":"—","lemma":"مَن\r","grammar_bn":"শব্দ"},{"id":18314,"position":2,"text_uthmani":"يُوَلِّهِمْ","transliteration":"yuwallihim","translation_bn":"দিকে ফিরাবে তাদের","root":"ولي","lemma":"وَلَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18315,"position":3,"text_uthmani":"يَوْمَئِذٍۢ","transliteration":"yawma-idhin","translation_bn":"সেদিন","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":18316,"position":4,"text_uthmani":"دُبُرَهُۥٓ","transliteration":"duburahu","translation_bn":"পিঠ তার","root":"دبر","lemma":"دُبُر","grammar_bn":"বিশেষ্য (Noun)"},{"id":18317,"position":5,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া যে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":18318,"position":6,"text_uthmani":"مُتَحَرِّفًۭا","transliteration":"mutaḥarrifan","translation_bn":"কৌশল গ্রহণ (হিসেবে)","root":"حرف","lemma":"مُتَحَرِّف","grammar_bn":"বিশেষ্য (Noun)"},{"id":18319,"position":7,"text_uthmani":"لِّقِتَالٍ","transliteration":"liqitālin","translation_bn":"জন্যে যুদ্ধের","root":"قتل","lemma":"قِتَال","grammar_bn":"অব্যয় (Preposition)"},{"id":18320,"position":8,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18321,"position":9,"text_uthmani":"مُتَحَيِّزًا","transliteration":"mutaḥayyizan","translation_bn":"মিলিত হওয়ার(জন্যে)","root":"حوز","lemma":"مُتَحَيِّز","grammar_bn":"বিশেষ্য (Noun)"},{"id":18322,"position":10,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"সাথে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18323,"position":11,"text_uthmani":"فِئَةٍۢ","transliteration":"fi-atin","translation_bn":"অপর দলের","root":"فاي","lemma":"فِئَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":18324,"position":12,"text_uthmani":"فَقَدْ","transliteration":"faqad","translation_bn":"তাহ''লে নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"ফলাফল পদ (Result)"},{"id":18325,"position":13,"text_uthmani":"بَآءَ","transliteration":"bāa","translation_bn":"সে পরিবেষ্টিত হবে","root":"بوا","lemma":"بَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18326,"position":14,"text_uthmani":"بِغَضَبٍۢ","transliteration":"bighaḍabin","translation_bn":"দিয়ে রাগ","root":"غضب","lemma":"غَضَب","grammar_bn":"অব্যয় (Preposition)"},{"id":18327,"position":15,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"পক্ষ হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18328,"position":16,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":18329,"position":17,"text_uthmani":"وَمَأْوَىٰهُ","transliteration":"wamawāhu","translation_bn":"এবং  আশ্রয়স্থল তার(হবে)","root":"اوي","lemma":"مَأْوَىٰ","grammar_bn":"শব্দ"},{"id":18330,"position":18,"text_uthmani":"جَهَنَّمُ ۖ","transliteration":"jahannamu","translation_bn":"জাহান্নাম","root":"—","lemma":"جَهَنَّم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":18332,"position":19,"text_uthmani":"وَبِئْسَ","transliteration":"wabi''sa","translation_bn":"এবং(তা) কত নিকৃষ্ট","root":"باس","lemma":"بِئْسَ","grammar_bn":"শব্দ"},{"id":18333,"position":20,"text_uthmani":"ٱلْمَصِيرُ","transliteration":"l-maṣīru","translation_bn":"গন্তব্যস্থল","root":"صير","lemma":"مَصِير","grammar_bn":"শব্দ"},{"id":18334,"position":21,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'waman yuwallihim yawma-idhin duburahu illā mutaḥarrifan liqitālin aw mutaḥayyizan ilā fi-atin faqad bāa bighaḍabin mina l-lahi wamawāhu jahannamu wabi''sa l-maṣīru', 'এমন দিনে যুদ্ধে কৌশল অবলম্বন বা নিজ দলের সঙ্গে মিলিত হওয়ার উদ্দেশ্য ছাড়া কেউ তাদেরকে পৃষ্ঠপ্রদর্শন করলে সে তো আল্লাহর গজবে পরিবেষ্টিত হয়ে পড়ল, জাহান্নামই তার ঠিকানা আর তা কতই না নিকৃষ্ট প্রত্যাবর্তনস্থল।', 'And whoever turns his back to them on such a day, unless swerving [as a strategy] for war or joining [another] company, has certainly returned with anger [upon him] from Allah, and his refuge is Hell - and wretched is the destination.', 'এমন দিনে যুদ্ধে কৌশল অবলম্বন বা নিজ দলের সঙ্গে মিলিত হওয়ার উদ্দেশ্য ছাড়া কেউ তাদেরকে পৃষ্ঠপ্রদর্শন করলে সে তো আল্লাহর গজবে পরিবেষ্টিত হয়ে পড়ল, জাহান্নামই তার ঠিকানা আর তা কতই না নিকৃষ্ট প্রত্যাবর্তনস্থল।', 'And whoever turns his back to them on such a day, unless swerving [as a strategy] for war or joining [another] company, has certainly returned with anger [upon him] from Allah, and his refuge is Hell - and wretched is the destination.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008016.mp3', now()),
  (8, 17, '', '[{"id":19323,"position":1,"text_uthmani":"فَلَمْ","transliteration":"falam","translation_bn":"আসলে কর নি","root":"—","lemma":"لَم\r","grammar_bn":"শব্দ"},{"id":19324,"position":2,"text_uthmani":"تَقْتُلُوهُمْ","transliteration":"taqtulūhum","translation_bn":"তোমরা হত্যা তাদেরকে","root":"قتل","lemma":"قَتَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19325,"position":3,"text_uthmani":"وَلَـٰكِنَّ","transliteration":"walākinna","translation_bn":"কিন্তু","root":"—","lemma":"لَٰكِنّ","grammar_bn":"শব্দ"},{"id":19326,"position":4,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহই","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19327,"position":5,"text_uthmani":"قَتَلَهُمْ ۚ","transliteration":"qatalahum","translation_bn":"হত্যা করেছেন তাদের","root":"قتل","lemma":"قَتَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19329,"position":6,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":19330,"position":7,"text_uthmani":"رَمَيْتَ","transliteration":"ramayta","translation_bn":"তুমি নিক্ষেপ করেছিলে(কংকর)","root":"رمي","lemma":"رَمَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19331,"position":8,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":19332,"position":9,"text_uthmani":"رَمَيْتَ","transliteration":"ramayta","translation_bn":"তুমি নিক্ষেপ করেছিলে","root":"رمي","lemma":"رَمَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19333,"position":10,"text_uthmani":"وَلَـٰكِنَّ","transliteration":"walākinna","translation_bn":"কিন্তু","root":"—","lemma":"لَٰكِنّ","grammar_bn":"শব্দ"},{"id":19334,"position":11,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহই","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19335,"position":12,"text_uthmani":"رَمَىٰ ۚ","transliteration":"ramā","translation_bn":"নিক্ষেপ করেছিলেন","root":"رمي","lemma":"رَمَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19337,"position":13,"text_uthmani":"وَلِيُبْلِىَ","transliteration":"waliyub''liya","translation_bn":"এবং জন্যে পরীক্ষার","root":"بلو","lemma":"يُبْلِىَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19338,"position":14,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"মু''মিনদেরকে","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":19339,"position":15,"text_uthmani":"مِنْهُ","transliteration":"min''hu","translation_bn":"হতে তা","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19340,"position":16,"text_uthmani":"بَلَآءً","transliteration":"balāan","translation_bn":"পরীক্ষা","root":"بلو","lemma":"بَلَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":19341,"position":17,"text_uthmani":"حَسَنًا ۚ","transliteration":"ḥasanan","translation_bn":"উত্তম","root":"حسن","lemma":"حَسَن","grammar_bn":"বিশেষণ (Adjective)"},{"id":19343,"position":18,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":19344,"position":19,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19345,"position":20,"text_uthmani":"سَمِيعٌ","transliteration":"samīʿun","translation_bn":"সবকিছু শুনেন","root":"سمع","lemma":"سَمِيع","grammar_bn":"বিশেষ্য (Noun)"},{"id":19346,"position":21,"text_uthmani":"عَلِيمٌۭ","transliteration":"ʿalīmun","translation_bn":"সবকিছু জানেন","root":"علم","lemma":"عَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":19347,"position":22,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'falam taqtulūhum walākinna l-laha qatalahum wamā ramayta idh ramayta walākinna l-laha ramā waliyub''liya l-mu''minīna min''hu balāan ḥasanan inna l-laha samīʿun ʿalīmun', '(আসল ব্যাপার হল) তোমরা তাদেরকে হত্যা করনি, বরং আল্লাহই তাদেরকে হত্যা করেছেন, তুমি যখন নিক্ষেপ করছিলে তাতো তুমি নিক্ষেপ করনি, বরং আল্লাহই নিক্ষেপ করেছিলেন যাতে তিনি মু’মিনদেরকে এক সুন্দরতম পরীক্ষায় সফলতার সঙ্গে উত্তীর্ণ করতে পারেন। আল্লাহ হলেন সর্বশ্রোতা, সর্বজ্ঞ।', 'And you did not kill them, but it was Allah who killed them. And you threw not, [O Muhammad], when you threw, but it was Allah who threw that He might test the believers with a good test. Indeed, Allah is Hearing and Knowing.', '(আসল ব্যাপার হল) তোমরা তাদেরকে হত্যা করনি, বরং আল্লাহই তাদেরকে হত্যা করেছেন, তুমি যখন নিক্ষেপ করছিলে তাতো তুমি নিক্ষেপ করনি, বরং আল্লাহই নিক্ষেপ করেছিলেন যাতে তিনি মু’মিনদেরকে এক সুন্দরতম পরীক্ষায় সফলতার সঙ্গে উত্তীর্ণ করতে পারেন। আল্লাহ হলেন সর্বশ্রোতা, সর্বজ্ঞ।', 'And you did not kill them, but it was Allah who killed them. And you threw not, [O Muhammad], when you threw, but it was Allah who threw that He might test the believers with a good test. Indeed, Allah is Hearing and Knowing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008017.mp3', now()),
  (8, 18, '', '[{"id":20396,"position":1,"text_uthmani":"ذَٰلِكُمْ","transliteration":"dhālikum","translation_bn":"এ (আচরণ)তোমাদের (সাথে)","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":20397,"position":2,"text_uthmani":"وَأَنَّ","transliteration":"wa-anna","translation_bn":"আর যে(কাফেরদের সাথে এরূপ)","root":"—","lemma":"أَنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20398,"position":3,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহই","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":20399,"position":4,"text_uthmani":"مُوهِنُ","transliteration":"mūhinu","translation_bn":"দুর্বলকারী","root":"وهن","lemma":"مُوهِن","grammar_bn":"বিশেষ্য (Noun)"},{"id":20400,"position":5,"text_uthmani":"كَيْدِ","transliteration":"kaydi","translation_bn":"কৌশল","root":"كيد","lemma":"كَيْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":20401,"position":6,"text_uthmani":"ٱلْكَـٰفِرِينَ","transliteration":"l-kāfirīna","translation_bn":"কাফেরদের","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"শব্দ"},{"id":20402,"position":7,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'dhālikum wa-anna l-laha mūhinu kaydi l-kāfirīna', 'আমার এ ব্যবস্থা তোমাদের জন্য, (আর কাফিরদের সম্পর্কে কথা এই যে) আল্লাহ কাফিরদের ষড়যন্ত্রকে অকেজো করে দেন।', 'That [is so], and [also] that Allah will weaken the plot of the disbelievers.', 'আমার এ ব্যবস্থা তোমাদের জন্য, (আর কাফিরদের সম্পর্কে কথা এই যে) আল্লাহ কাফিরদের ষড়যন্ত্রকে অকেজো করে দেন।', 'That [is so], and [also] that Allah will weaken the plot of the disbelievers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008018.mp3', now()),
  (8, 19, '', '[{"id":21470,"position":1,"text_uthmani":"إِن","transliteration":"in","translation_bn":"(হে কাফেররা) যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":21471,"position":2,"text_uthmani":"تَسْتَفْتِحُوا۟","transliteration":"tastaftiḥū","translation_bn":"তোমরা মীমাংসা চাও","root":"فتح","lemma":"ٱسْتَفْتَحُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21472,"position":3,"text_uthmani":"فَقَدْ","transliteration":"faqad","translation_bn":"তবে নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"ফলাফল পদ (Result)"},{"id":21473,"position":4,"text_uthmani":"جَآءَكُمُ","transliteration":"jāakumu","translation_bn":"কাছে এসেছে তোমাদের","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21474,"position":5,"text_uthmani":"ٱلْفَتْحُ ۖ","transliteration":"l-fatḥu","translation_bn":"মীমাংসা","root":"فتح","lemma":"فَتْح","grammar_bn":"শব্দ"},{"id":21476,"position":6,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"এবং যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21477,"position":7,"text_uthmani":"تَنتَهُوا۟","transliteration":"tantahū","translation_bn":"তোমরা বিরত হও","root":"نهي","lemma":"ٱنتَهَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21478,"position":8,"text_uthmani":"فَهُوَ","transliteration":"fahuwa","translation_bn":"তবে তা","root":"—","lemma":"فَهُوَ","grammar_bn":"ফলাফল পদ (Result)"},{"id":21479,"position":9,"text_uthmani":"خَيْرٌۭ","transliteration":"khayrun","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":21480,"position":10,"text_uthmani":"لَّكُمْ ۖ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَّكُمْ ۖ","grammar_bn":"অব্যয় (Preposition)"},{"id":21482,"position":11,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"এবং যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21483,"position":12,"text_uthmani":"تَعُودُوا۟","transliteration":"taʿūdū","translation_bn":"তোমরা পুনরাবৃত্তি করো","root":"عود","lemma":"عَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21484,"position":13,"text_uthmani":"نَعُدْ","transliteration":"naʿud","translation_bn":"পুনরাবৃত্তি করবো আমরা","root":"عود","lemma":"عَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21485,"position":14,"text_uthmani":"وَلَن","transliteration":"walan","translation_bn":"এবং কখনও না","root":"—","lemma":"لَن\r","grammar_bn":"শব্দ"},{"id":21486,"position":15,"text_uthmani":"تُغْنِىَ","transliteration":"tugh''niya","translation_bn":"কাজে আসবে","root":"غني","lemma":"أَغْنَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21487,"position":16,"text_uthmani":"عَنكُمْ","transliteration":"ʿankum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21488,"position":17,"text_uthmani":"فِئَتُكُمْ","transliteration":"fi-atukum","translation_bn":"দলবল তোমাদের","root":"فاي","lemma":"فِئَت","grammar_bn":"বিশেষ্য (Noun)"},{"id":21489,"position":18,"text_uthmani":"شَيْـًۭٔا","transliteration":"shayan","translation_bn":"কিছুমাত্রই","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":21490,"position":19,"text_uthmani":"وَلَوْ","transliteration":"walaw","translation_bn":"আর যদি","root":"—","lemma":"لَو\r","grammar_bn":"শব্দ"},{"id":21491,"position":20,"text_uthmani":"كَثُرَتْ","transliteration":"kathurat","translation_bn":"অধিকও হয়(তবুও)","root":"كثر","lemma":"كَثُرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21492,"position":21,"text_uthmani":"وَأَنَّ","transliteration":"wa-anna","translation_bn":"এবং (জেনে রেখো) যে","root":"—","lemma":"أَنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21493,"position":22,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":21494,"position":23,"text_uthmani":"مَعَ","transliteration":"maʿa","translation_bn":"সাথে(আছেন)","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":21495,"position":24,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"মু''মিনদের","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":21496,"position":25,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'in tastaftiḥū faqad jāakumu l-fatḥu wa-in tantahū fahuwa khayrun lakum wa-in taʿūdū naʿud walan tugh''niya ʿankum fi-atukum shayan walaw kathurat wa-anna l-laha maʿa l-mu''minīna', '(ওহে কাফিরগণ!) তোমরা মীমাংসা চাচ্ছিলে, মীমাংসা তো তোমাদের কাছে এসে গেছে; আর যদি তোমরা (অন্যায় থেকে) বিরত হও, তবে তা তোমাদের জন্যই কল্যাণকর, তোমরা যদি আবার (অন্যায়) কর, আমিও আবার শাস্তি দিব, তোমাদের দল-বাহিনী সংখ্যায় অধিক হলেও তোমাদের কোন উপকারে আসবে না এবং আল্লাহ তো মু’মিনদের সঙ্গে আছেন।', 'If you [disbelievers] seek the victory - the defeat has come to you. And if you desist [from hostilities], it is best for you; but if you return [to war], We will return, and never will you be availed by your [large] company at all, even if it should increase; and [that is] because Allah is with the believers.', '(ওহে কাফিরগণ!) তোমরা মীমাংসা চাচ্ছিলে, মীমাংসা তো তোমাদের কাছে এসে গেছে; আর যদি তোমরা (অন্যায় থেকে) বিরত হও, তবে তা তোমাদের জন্যই কল্যাণকর, তোমরা যদি আবার (অন্যায়) কর, আমিও আবার শাস্তি দিব, তোমাদের দল-বাহিনী সংখ্যায় অধিক হলেও তোমাদের কোন উপকারে আসবে না এবং আল্লাহ তো মু’মিনদের সঙ্গে আছেন।', 'If you [disbelievers] seek the victory - the defeat has come to you. And if you desist [from hostilities], it is best for you; but if you return [to war], We will return, and never will you be availed by your [large] company at all, even if it should increase; and [that is] because Allah is with the believers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008019.mp3', now()),
  (8, 20, '', '[{"id":22558,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":22559,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":22560,"position":3,"text_uthmani":"ءَامَنُوٓا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22561,"position":4,"text_uthmani":"أَطِيعُوا۟","transliteration":"aṭīʿū","translation_bn":"তোমরা আনুগত্য করো","root":"طوع","lemma":"أَطَاعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22562,"position":5,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":22563,"position":6,"text_uthmani":"وَرَسُولَهُۥ","transliteration":"warasūlahu","translation_bn":"ও রাসূলের তাঁর","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22564,"position":7,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22565,"position":8,"text_uthmani":"تَوَلَّوْا۟","transliteration":"tawallaw","translation_bn":"তোমরা মুখ ফিরাবে","root":"ولي","lemma":"تَوَلَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22566,"position":9,"text_uthmani":"عَنْهُ","transliteration":"ʿanhu","translation_bn":"হতে তা","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22567,"position":10,"text_uthmani":"وَأَنتُمْ","transliteration":"wa-antum","translation_bn":"যখন তোমরা","root":"—","lemma":"وَأَنتُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":22568,"position":11,"text_uthmani":"تَسْمَعُونَ","transliteration":"tasmaʿūna","translation_bn":"তোমরা শুনছো","root":"سمع","lemma":"سَمِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22569,"position":12,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā alladhīna āmanū aṭīʿū l-laha warasūlahu walā tawallaw ʿanhu wa-antum tasmaʿūna', 'ওহে বিশ্বাসীগণ! আল্লাহ ও তাঁর রসূলের আনুগত্য কর এবং আদেশ শোনার পর তা অমান্য কর না।', 'O you who have believed, obey Allah and His Messenger and do not turn from him while you hear [his order].', 'ওহে বিশ্বাসীগণ! আল্লাহ ও তাঁর রসূলের আনুগত্য কর এবং আদেশ শোনার পর তা অমান্য কর না।', 'O you who have believed, obey Allah and His Messenger and do not turn from him while you hear [his order].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008020.mp3', now()),
  (8, 21, '', '[{"id":23725,"position":1,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23726,"position":2,"text_uthmani":"تَكُونُوا۟","transliteration":"takūnū","translation_bn":"তোমরা হয়ো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23727,"position":3,"text_uthmani":"كَٱلَّذِينَ","transliteration":"ka-alladhīna","translation_bn":"(তাদের) মতো যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অব্যয় (Preposition)"},{"id":23728,"position":4,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23729,"position":5,"text_uthmani":"سَمِعْنَا","transliteration":"samiʿ''nā","translation_bn":"\"আমরা শুনলাম\"","root":"سمع","lemma":"سَمِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23730,"position":6,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"অথচ তারা","root":"—","lemma":"وَهُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":23731,"position":7,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":23732,"position":8,"text_uthmani":"يَسْمَعُونَ","transliteration":"yasmaʿūna","translation_bn":"তারা শোনে","root":"سمع","lemma":"سَمِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23733,"position":9,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'walā takūnū ka-alladhīna qālū samiʿ''nā wahum lā yasmaʿūna', 'তোমরা তাদের মত হয়ো না যারা বলেছিল, ‘আমরা শুনলাম’; প্রকৃতপক্ষে তারা শোনেনি।', 'And do not be like those who say, "We have heard," while they do not hear.', 'তোমরা তাদের মত হয়ো না যারা বলেছিল, ‘আমরা শুনলাম’; প্রকৃতপক্ষে তারা শোনেনি।', 'And do not be like those who say, "We have heard," while they do not hear.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008021.mp3', now()),
  (8, 22, '', '[{"id":24683,"position":1,"text_uthmani":"۞ إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":24684,"position":2,"text_uthmani":"شَرَّ","transliteration":"sharra","translation_bn":"নিকৃষ্ট","root":"شرر","lemma":"شَرّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":24685,"position":3,"text_uthmani":"ٱلدَّوَآبِّ","transliteration":"l-dawābi","translation_bn":"জীবগুলোর(মধ্যে)","root":"دبب","lemma":"دَا^بَّة","grammar_bn":"শব্দ"},{"id":24686,"position":4,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"কাছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":24687,"position":5,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":24688,"position":6,"text_uthmani":"ٱلصُّمُّ","transliteration":"l-ṣumu","translation_bn":"(এসব) বধির","root":"صمم","lemma":"أَصَمّ","grammar_bn":"শব্দ"},{"id":24689,"position":7,"text_uthmani":"ٱلْبُكْمُ","transliteration":"l-buk''mu","translation_bn":"বোবা","root":"بكم","lemma":"أَبْكَم","grammar_bn":"শব্দ"},{"id":24690,"position":8,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":24691,"position":9,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":24692,"position":10,"text_uthmani":"يَعْقِلُونَ","transliteration":"yaʿqilūna","translation_bn":"বুদ্ধি কাজে লাগায়","root":"عقل","lemma":"عَقَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":24693,"position":11,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'inna sharra l-dawābi ʿinda l-lahi l-ṣumu l-buk''mu alladhīna lā yaʿqilūna', 'আল্লাহর নিকট সবচেয়ে নিকৃষ্ট জীব হচ্ছে যারা (হক্ব কথা শুনার ব্যাপারে) বধির এবং (হক্ব কথা বলার ব্যাপারে) বোবা, যারা কিছুই বোঝে না।', 'Indeed, the worst of living creatures in the sight of Allah are the deaf and dumb who do not use reason.', 'আল্লাহর নিকট সবচেয়ে নিকৃষ্ট জীব হচ্ছে যারা (হক্ব কথা শুনার ব্যাপারে) বধির এবং (হক্ব কথা বলার ব্যাপারে) বোবা, যারা কিছুই বোঝে না।', 'Indeed, the worst of living creatures in the sight of Allah are the deaf and dumb who do not use reason.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008022.mp3', now()),
  (8, 23, '', '[{"id":25783,"position":1,"text_uthmani":"وَلَوْ","transliteration":"walaw","translation_bn":"এবং যদি","root":"—","lemma":"لَو\r","grammar_bn":"শব্দ"},{"id":25784,"position":2,"text_uthmani":"عَلِمَ","transliteration":"ʿalima","translation_bn":"জানতেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25785,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":25786,"position":4,"text_uthmani":"فِيهِمْ","transliteration":"fīhim","translation_bn":"মধ্যে তাদের(রয়েছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25787,"position":5,"text_uthmani":"خَيْرًۭا","transliteration":"khayran","translation_bn":"কোনো কল্যাণ","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":25788,"position":6,"text_uthmani":"لَّأَسْمَعَهُمْ ۖ","transliteration":"la-asmaʿahum","translation_bn":"অবশ্যই শুনাতেন তাদের","root":"سمع","lemma":"أَسْمَعَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":25790,"position":7,"text_uthmani":"وَلَوْ","transliteration":"walaw","translation_bn":"এবং যদি","root":"—","lemma":"لَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25791,"position":8,"text_uthmani":"أَسْمَعَهُمْ","transliteration":"asmaʿahum","translation_bn":"তিনি শুনাতেনও তাদের","root":"سمع","lemma":"أَسْمَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25792,"position":9,"text_uthmani":"لَتَوَلَّوا۟","transliteration":"latawallaw","translation_bn":"অবশ্যই তারা মুখ ফিরাতো","root":"ولي","lemma":"تَوَلَّىٰ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":25793,"position":10,"text_uthmani":"وَّهُم","transliteration":"wahum","translation_bn":"ও তারা","root":"—","lemma":"وَّهُم","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":25794,"position":11,"text_uthmani":"مُّعْرِضُونَ","transliteration":"muʿ''riḍūna","translation_bn":"উপেক্ষা করতো","root":"عرض","lemma":"مُّعْرِضُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":25795,"position":12,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'walaw ʿalima l-lahu fīhim khayran la-asmaʿahum walaw asmaʿahum latawallaw wahum muʿ''riḍūna', 'আল্লাহ যদি দেখতেন যে, তাদের মধ্যে কোন ভাল গুণ নিহিত আছে তবে তিনি তাদেরকে শুনবার তাওফীক দিতেন। আর (গুণ না থাকা অবস্থায়) তিনি যদি তাদেরকে শুনতে দিতেন তাহলে তারা উপেক্ষা করে মুখ ফিরিয়ে নিত।', 'Had Allah known any good in them, He would have made them hear. And if He had made them hear, they would [still] have turned away, while they were refusing.', 'আল্লাহ যদি দেখতেন যে, তাদের মধ্যে কোন ভাল গুণ নিহিত আছে তবে তিনি তাদেরকে শুনবার তাওফীক দিতেন। আর (গুণ না থাকা অবস্থায়) তিনি যদি তাদেরকে শুনতে দিতেন তাহলে তারা উপেক্ষা করে মুখ ফিরিয়ে নিত।', 'Had Allah known any good in them, He would have made them hear. And if He had made them hear, they would [still] have turned away, while they were refusing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008023.mp3', now()),
  (8, 24, '', '[{"id":26831,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":26832,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":26833,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26834,"position":4,"text_uthmani":"ٱسْتَجِيبُوا۟","transliteration":"is''tajībū","translation_bn":"তোমরা সাড়া দাও","root":"جوب","lemma":"ٱسْتَجَابَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26835,"position":5,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"উদ্দেশ্যে আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":26836,"position":6,"text_uthmani":"وَلِلرَّسُولِ","transliteration":"walilrrasūli","translation_bn":"ও উদ্দেশ্যে রাসূলের (ডাকে)","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26837,"position":7,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":26838,"position":8,"text_uthmani":"دَعَاكُمْ","transliteration":"daʿākum","translation_bn":"তিনি ডাকেন তোমাদেরকে","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":26839,"position":9,"text_uthmani":"لِمَا","transliteration":"limā","translation_bn":"(তাই) তার জন্যে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26840,"position":10,"text_uthmani":"يُحْيِيكُمْ ۖ","transliteration":"yuḥ''yīkum","translation_bn":"উদ্দীপ্ত করবে তোমাদেরকে","root":"حيي","lemma":"أَحْيَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":26842,"position":11,"text_uthmani":"وَٱعْلَمُوٓا۟","transliteration":"wa-iʿ''lamū","translation_bn":"এবং তোমরা জেনে রাখো","root":"علم","lemma":"عَلِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26843,"position":12,"text_uthmani":"أَنَّ","transliteration":"anna","translation_bn":"যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":26844,"position":13,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":26845,"position":14,"text_uthmani":"يَحُولُ","transliteration":"yaḥūlu","translation_bn":"অন্তরায় হয়ে থাকেন","root":"حول","lemma":"حَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26846,"position":15,"text_uthmani":"بَيْنَ","transliteration":"bayna","translation_bn":"মাঝে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":26847,"position":16,"text_uthmani":"ٱلْمَرْءِ","transliteration":"l-mari","translation_bn":"ব্যক্তি","root":"مرا","lemma":"مَرْء","grammar_bn":"শব্দ"},{"id":26848,"position":17,"text_uthmani":"وَقَلْبِهِۦ","transliteration":"waqalbihi","translation_bn":"ও অন্তরের তার","root":"قلب","lemma":"قَلْب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26849,"position":18,"text_uthmani":"وَأَنَّهُۥٓ","transliteration":"wa-annahu","translation_bn":"এবং (এও) যে","root":"—","lemma":"أَنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":26850,"position":19,"text_uthmani":"إِلَيْهِ","transliteration":"ilayhi","translation_bn":"দিকে তাঁরই","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26851,"position":20,"text_uthmani":"تُحْشَرُونَ","transliteration":"tuḥ''sharūna","translation_bn":"তোমাদের একত্র করা হবে","root":"حشر","lemma":"حَشَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26852,"position":21,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā alladhīna āmanū is''tajībū lillahi walilrrasūli idhā daʿākum limā yuḥ''yīkum wa-iʿ''lamū anna l-laha yaḥūlu bayna l-mari waqalbihi wa-annahu ilayhi tuḥ''sharūna', 'ওহে বিশ্বাসীগণ! তোমরা আল্লাহ ও তাঁর রসূলের ডাকে সাড়া দাও যখন তোমাদেরকে ডাকা হয় (এমন বিষয়ের দিকে) যা তোমাদের মাঝে জীবন সঞ্চার করে, আর জেনে রেখ যে আল্লাহ মানুষ ও তার অন্তরের মাঝে প্রতিবন্ধক হয়ে যান আর তোমাদেরকে তাঁর কাছেই একত্রিত করা হবে।', 'O you who have believed, respond to Allah and to the Messenger when he calls you to that which gives you life. And know that Allah intervenes between a man and his heart and that to Him you will be gathered.', 'ওহে বিশ্বাসীগণ! তোমরা আল্লাহ ও তাঁর রসূলের ডাকে সাড়া দাও যখন তোমাদেরকে ডাকা হয় (এমন বিষয়ের দিকে) যা তোমাদের মাঝে জীবন সঞ্চার করে, আর জেনে রেখ যে আল্লাহ মানুষ ও তার অন্তরের মাঝে প্রতিবন্ধক হয়ে যান আর তোমাদেরকে তাঁর কাছেই একত্রিত করা হবে।', 'O you who have believed, respond to Allah and to the Messenger when he calls you to that which gives you life. And know that Allah intervenes between a man and his heart and that to Him you will be gathered.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008024.mp3', now()),
  (8, 25, '', '[{"id":27873,"position":1,"text_uthmani":"وَٱتَّقُوا۟","transliteration":"wa-ittaqū","translation_bn":"ও তোমরা দূরে থাকো","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27874,"position":2,"text_uthmani":"فِتْنَةًۭ","transliteration":"fit''natan","translation_bn":"ফিতনা (হতে)","root":"فتن","lemma":"فِتْنَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":27875,"position":3,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"(যা) না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":27876,"position":4,"text_uthmani":"تُصِيبَنَّ","transliteration":"tuṣībanna","translation_bn":"(শুধু) পৌঁছবে","root":"صوب","lemma":"أَصَابَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27877,"position":5,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদেরকে) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":27878,"position":6,"text_uthmani":"ظَلَمُوا۟","transliteration":"ẓalamū","translation_bn":"সীমালঙ্ঘন করেছে","root":"ظلم","lemma":"ظَلَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27879,"position":7,"text_uthmani":"مِنكُمْ","transliteration":"minkum","translation_bn":"মধ্য হতে তোমাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27880,"position":8,"text_uthmani":"خَآصَّةًۭ ۖ","transliteration":"khāṣṣatan","translation_bn":"বিশেষভাবে","root":"خصص","lemma":"خَا^صَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":27882,"position":9,"text_uthmani":"وَٱعْلَمُوٓا۟","transliteration":"wa-iʿ''lamū","translation_bn":"এবং তোমরা জেনে রাখো","root":"علم","lemma":"عَلِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27883,"position":10,"text_uthmani":"أَنَّ","transliteration":"anna","translation_bn":"যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":27884,"position":11,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":27885,"position":12,"text_uthmani":"شَدِيدُ","transliteration":"shadīdu","translation_bn":"কঠোর","root":"شدد","lemma":"شَدِيد","grammar_bn":"বিশেষ্য (Noun)"},{"id":27886,"position":13,"text_uthmani":"ٱلْعِقَابِ","transliteration":"l-ʿiqābi","translation_bn":"দন্ডদানে","root":"عقب","lemma":"عِقَاب","grammar_bn":"শব্দ"},{"id":27887,"position":14,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ittaqū fit''natan lā tuṣībanna alladhīna ẓalamū minkum khāṣṣatan wa-iʿ''lamū anna l-laha shadīdu l-ʿiqābi', 'সতর্ক থাক সেই শাস্তি হতে যা বিশেষভাবে তোমাদের যালিম লোকেদেরকেই আক্রমন করবে না। আর জেনে রেখ যে আল্লাহ শাস্তিদানে খুবই কঠোর।', 'And fear a trial which will not strike those who have wronged among you exclusively, and know that Allah is severe in penalty.', 'সতর্ক থাক সেই শাস্তি হতে যা বিশেষভাবে তোমাদের যালিম লোকেদেরকেই আক্রমন করবে না। আর জেনে রেখ যে আল্লাহ শাস্তিদানে খুবই কঠোর।', 'And fear a trial which will not strike those who have wronged among you exclusively, and know that Allah is severe in penalty.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008025.mp3', now()),
  (8, 26, '', '[{"id":28848,"position":1,"text_uthmani":"وَٱذْكُرُوٓا۟","transliteration":"wa-udh''kurū","translation_bn":"এবং তোমরা স্বরণ করো","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28849,"position":2,"text_uthmani":"إِذْ","transliteration":"idh","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":28850,"position":3,"text_uthmani":"أَنتُمْ","transliteration":"antum","translation_bn":"তোমরা (ছিলে)","root":"—","lemma":"أَنتُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":28851,"position":4,"text_uthmani":"قَلِيلٌۭ","transliteration":"qalīlun","translation_bn":"স্বল্প (সংখ্যক)","root":"قلل","lemma":"قَلِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":28852,"position":5,"text_uthmani":"مُّسْتَضْعَفُونَ","transliteration":"mus''taḍʿafūna","translation_bn":"তোমাদেরকে দুর্বল মনে করে হতো","root":"ضعف","lemma":"مُّسْتَضْعَفُون","grammar_bn":"বিশেষণ (Adjective)"},{"id":28853,"position":6,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"উপর","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28854,"position":7,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":28855,"position":8,"text_uthmani":"تَخَافُونَ","transliteration":"takhāfūna","translation_bn":"তোমরা ভয় করতে","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28856,"position":9,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":28857,"position":10,"text_uthmani":"يَتَخَطَّفَكُمُ","transliteration":"yatakhaṭṭafakumu","translation_bn":"নিশ্চিহ্ন করে ফেলবে তোমাদেরকে","root":"خطف","lemma":"يَتَخَطَّفَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28858,"position":11,"text_uthmani":"ٱلنَّاسُ","transliteration":"l-nāsu","translation_bn":"মানুষেরা","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":28859,"position":12,"text_uthmani":"فَـَٔاوَىٰكُمْ","transliteration":"faāwākum","translation_bn":"তখন তিনি আশ্রয় দেন তোমাদেরকে","root":"اوي","lemma":"ءَاوَىٰ^","grammar_bn":"শব্দ"},{"id":28860,"position":13,"text_uthmani":"وَأَيَّدَكُم","transliteration":"wa-ayyadakum","translation_bn":"ও শক্তিশালী করেন তোমাদের","root":"ايد","lemma":"أَيَّدَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28861,"position":14,"text_uthmani":"بِنَصْرِهِۦ","transliteration":"binaṣrihi","translation_bn":"দিয়ে সাহায্য তাঁর","root":"نصر","lemma":"نَصْر","grammar_bn":"অব্যয় (Preposition)"},{"id":28862,"position":15,"text_uthmani":"وَرَزَقَكُم","transliteration":"warazaqakum","translation_bn":"ও জীবিকা দেন তোমাদেরকে","root":"رزق","lemma":"رَزَقَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28863,"position":16,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28864,"position":17,"text_uthmani":"ٱلطَّيِّبَـٰتِ","transliteration":"l-ṭayibāti","translation_bn":"পবিত্র জিনিসগুলো","root":"طيب","lemma":"طَيِّبَٰت","grammar_bn":"শব্দ"},{"id":28865,"position":18,"text_uthmani":"لَعَلَّكُمْ","transliteration":"laʿallakum","translation_bn":"যাতে তোমরা","root":"—","lemma":"لَعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":28866,"position":19,"text_uthmani":"تَشْكُرُونَ","transliteration":"tashkurūna","translation_bn":"কৃতজ্ঞতা প্রকাশ করো","root":"شكر","lemma":"شَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28867,"position":20,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'wa-udh''kurū idh antum qalīlun mus''taḍʿafūna fī l-arḍi takhāfūna an yatakhaṭṭafakumu l-nāsu faāwākum wa-ayyadakum binaṣrihi warazaqakum mina l-ṭayibāti laʿallakum tashkurūna', 'স্মরণ কর সে সময়ের কথা যখন তোমরা ছিলে সংখ্যায় অল্প, দুনিয়াতে তোমাদেরকে দুর্বল হিসেবে গণ্য করা হত। তোমরা আশঙ্কা করতে যে, মানুষেরা তোমাদের কখন না হঠাৎ ধরে নিয়ে যায়। এমন অবস্থায় তিনি তোমাদেরকে আশ্রয় দিলেন, তাঁর সাহায্য দিয়ে তোমাদেরকে শক্তিশালী করলেন, উত্তম জীবিকা দান করলেন যাতে তোমরা (তাঁর নির্দেশ পালনের মাধ্যমে) কৃতজ্ঞতা প্রকাশ কর।', 'And remember when you were few and oppressed in the land, fearing that people might abduct you, but He sheltered you, supported you with His victory, and provided you with good things - that you might be grateful.', 'স্মরণ কর সে সময়ের কথা যখন তোমরা ছিলে সংখ্যায় অল্প, দুনিয়াতে তোমাদেরকে দুর্বল হিসেবে গণ্য করা হত। তোমরা আশঙ্কা করতে যে, মানুষেরা তোমাদের কখন না হঠাৎ ধরে নিয়ে যায়। এমন অবস্থায় তিনি তোমাদেরকে আশ্রয় দিলেন, তাঁর সাহায্য দিয়ে তোমাদেরকে শক্তিশালী করলেন, উত্তম জীবিকা দান করলেন যাতে তোমরা (তাঁর নির্দেশ পালনের মাধ্যমে) কৃতজ্ঞতা প্রকাশ কর।', 'And remember when you were few and oppressed in the land, fearing that people might abduct you, but He sheltered you, supported you with His victory, and provided you with good things - that you might be grateful.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008026.mp3', now()),
  (8, 27, '', '[{"id":29652,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":29653,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":29654,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29655,"position":4,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":29656,"position":5,"text_uthmani":"تَخُونُوا۟","transliteration":"takhūnū","translation_bn":"তোমরা বিশ্বাস ভঙ্গ করো","root":"خون","lemma":"خَانُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29657,"position":6,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":29658,"position":7,"text_uthmani":"وَٱلرَّسُولَ","transliteration":"wal-rasūla","translation_bn":"ও রাসূলের","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29659,"position":8,"text_uthmani":"وَتَخُونُوٓا۟","transliteration":"watakhūnū","translation_bn":"এবং তোমরা বিশ্বাস ভঙ্গ করো (না)","root":"خون","lemma":"خَانُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29660,"position":9,"text_uthmani":"أَمَـٰنَـٰتِكُمْ","transliteration":"amānātikum","translation_bn":"আমানতসমূহের তোমাদের","root":"امن","lemma":"أَمَٰنَٰت","grammar_bn":"বিশেষ্য (Noun)"},{"id":29661,"position":10,"text_uthmani":"وَأَنتُمْ","transliteration":"wa-antum","translation_bn":"এমতাবস্হায় যে তোমরা","root":"—","lemma":"وَأَنتُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":29662,"position":11,"text_uthmani":"تَعْلَمُونَ","transliteration":"taʿlamūna","translation_bn":"জানো","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29663,"position":12,"text_uthmani":"٢٧","transliteration":"","translation_bn":"(২৭)","root":"—","lemma":"٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā alladhīna āmanū lā takhūnū l-laha wal-rasūla watakhūnū amānātikum wa-antum taʿlamūna', 'হে মু’মিনগণ! তোমরা জেনে বুঝে আল্লাহ ও তাঁর রসূলের সঙ্গে বিশ্বাসঘাতকতা করো না, আর যে বিষয়ে তোমরা আমানাত প্রাপ্ত হয়েছ তাতেও বিশ্বাস ভঙ্গ করো না।', 'O you who have believed, do not betray Allah and the Messenger or betray your trusts while you know [the consequence].', 'হে মু’মিনগণ! তোমরা জেনে বুঝে আল্লাহ ও তাঁর রসূলের সঙ্গে বিশ্বাসঘাতকতা করো না, আর যে বিষয়ে তোমরা আমানাত প্রাপ্ত হয়েছ তাতেও বিশ্বাস ভঙ্গ করো না।', 'O you who have believed, do not betray Allah and the Messenger or betray your trusts while you know [the consequence].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008027.mp3', now()),
  (8, 28, '', '[{"id":30738,"position":1,"text_uthmani":"وَٱعْلَمُوٓا۟","transliteration":"wa-iʿ''lamū","translation_bn":"এবং তোমরা জেনে রাখো","root":"علم","lemma":"عَلِمَ","grammar_bn":"শব্দ"},{"id":30739,"position":2,"text_uthmani":"أَنَّمَآ","transliteration":"annamā","translation_bn":"প্রকৃতপক্ষে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":30740,"position":3,"text_uthmani":"أَمْوَٰلُكُمْ","transliteration":"amwālukum","translation_bn":"সম্পদগুলো তোমাদের","root":"مول","lemma":"مَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":30741,"position":4,"text_uthmani":"وَأَوْلَـٰدُكُمْ","transliteration":"wa-awlādukum","translation_bn":"ও সন্তানেরা তোমাদের","root":"ولد","lemma":"وَلَد","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30742,"position":5,"text_uthmani":"فِتْنَةٌۭ","transliteration":"fit''natun","translation_bn":"পরীক্ষা (মাত্র)","root":"فتن","lemma":"فِتْنَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":30743,"position":6,"text_uthmani":"وَأَنَّ","transliteration":"wa-anna","translation_bn":"এবং বাস্তবিকই","root":"—","lemma":"أَنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":30744,"position":7,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":30745,"position":8,"text_uthmani":"عِندَهُۥٓ","transliteration":"ʿindahu","translation_bn":"কাছে তাঁরই (আছে)","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":30746,"position":9,"text_uthmani":"أَجْرٌ","transliteration":"ajrun","translation_bn":"পুরস্কার","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":30747,"position":10,"text_uthmani":"عَظِيمٌۭ","transliteration":"ʿaẓīmun","translation_bn":"বিরাট","root":"عظم","lemma":"عَظِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":30748,"position":11,"text_uthmani":"٢٨","transliteration":"","translation_bn":"(২৮)","root":"—","lemma":"٢٨","grammar_bn":"মার্কার"}]'::jsonb, 'wa-iʿ''lamū annamā amwālukum wa-awlādukum fit''natun wa-anna l-laha ʿindahu ajrun ʿaẓīmun', 'জেনে রেখ, তোমাদের ধন-সম্পদ আর সন্তান- সন্ততি হচ্ছে পরীক্ষার সামগ্রী মাত্র। (এ পরীক্ষায় যারা উত্তীর্ণ হবে তাদের জন্য) আল্লাহর নিকট রয়েছে মহাপুরস্কার।', 'And know that your properties and your children are but a trial and that Allah has with Him a great reward.', 'জেনে রেখ, তোমাদের ধন-সম্পদ আর সন্তান- সন্ততি হচ্ছে পরীক্ষার সামগ্রী মাত্র। (এ পরীক্ষায় যারা উত্তীর্ণ হবে তাদের জন্য) আল্লাহর নিকট রয়েছে মহাপুরস্কার।', 'And know that your properties and your children are but a trial and that Allah has with Him a great reward.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008028.mp3', now()),
  (8, 29, '', '[{"id":31810,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":31811,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":31812,"position":3,"text_uthmani":"ءَامَنُوٓا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31813,"position":4,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":31814,"position":5,"text_uthmani":"تَتَّقُوا۟","transliteration":"tattaqū","translation_bn":"তোমরা ভয় করো","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31815,"position":6,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":31816,"position":7,"text_uthmani":"يَجْعَل","transliteration":"yajʿal","translation_bn":"তিনি দিবেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31817,"position":8,"text_uthmani":"لَّكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَّكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":31818,"position":9,"text_uthmani":"فُرْقَانًۭا","transliteration":"fur''qānan","translation_bn":"ন্যায়-অন্যায় পার্থক্যের কষ্টিপাথর","root":"فرق","lemma":"فُرْقَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":31819,"position":10,"text_uthmani":"وَيُكَفِّرْ","transliteration":"wayukaffir","translation_bn":"এবং মোচন করবেন","root":"كفر","lemma":"كَفَّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31820,"position":11,"text_uthmani":"عَنكُمْ","transliteration":"ʿankum","translation_bn":"হতে তোমাদের","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31821,"position":12,"text_uthmani":"سَيِّـَٔاتِكُمْ","transliteration":"sayyiātikum","translation_bn":"পাপগুলো তোমাদের","root":"سوا","lemma":"سَيِّـ#َات","grammar_bn":"বিশেষ্য (Noun)"},{"id":31822,"position":13,"text_uthmani":"وَيَغْفِرْ","transliteration":"wayaghfir","translation_bn":"এবং ক্ষমা করবেন","root":"غفر","lemma":"غَفَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31823,"position":14,"text_uthmani":"لَكُمْ ۗ","transliteration":"lakum","translation_bn":"প্রতি তোমাদের","root":"—","lemma":"لَكُمْ ۗ","grammar_bn":"অব্যয় (Preposition)"},{"id":31825,"position":15,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31826,"position":16,"text_uthmani":"ذُو","transliteration":"dhū","translation_bn":"সম্পন্ন","root":"—","lemma":"ذُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":31827,"position":17,"text_uthmani":"ٱلْفَضْلِ","transliteration":"l-faḍli","translation_bn":"অনুগ্রহ","root":"فضل","lemma":"فَضْل","grammar_bn":"শব্দ"},{"id":31828,"position":18,"text_uthmani":"ٱلْعَظِيمِ","transliteration":"l-ʿaẓīmi","translation_bn":"মহান","root":"عظم","lemma":"عَظِيم","grammar_bn":"শব্দ"},{"id":31829,"position":19,"text_uthmani":"٢٩","transliteration":"","translation_bn":"(২৯)","root":"—","lemma":"٢٩","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā alladhīna āmanū in tattaqū l-laha yajʿal lakum fur''qānan wayukaffir ʿankum sayyiātikum wayaghfir lakum wal-lahu dhū l-faḍli l-ʿaẓīmi', 'ওহে ঈমানদারগণ! তোমরা যদি আল্লাহকে ভয় কর তাহলে তিনি তোমাদেরকে ভাল ও মন্দের মধ্যে পার্থক্য করার শক্তি প্রদান করবেন, তোমাদের দোষ-ত্রুটি দূর করে দিবেন, তোমাদেরকে ক্ষমা করবেন, আল্লাহ বড়ই অনুগ্রহশীল।', 'O you who have believed, if you fear Allah, He will grant you a criterion and will remove from you your misdeeds and forgive you. And Allah is the possessor of great bounty.', 'ওহে ঈমানদারগণ! তোমরা যদি আল্লাহকে ভয় কর তাহলে তিনি তোমাদেরকে ভাল ও মন্দের মধ্যে পার্থক্য করার শক্তি প্রদান করবেন, তোমাদের দোষ-ত্রুটি দূর করে দিবেন, তোমাদেরকে ক্ষমা করবেন, আল্লাহ বড়ই অনুগ্রহশীল।', 'O you who have believed, if you fear Allah, He will grant you a criterion and will remove from you your misdeeds and forgive you. And Allah is the possessor of great bounty.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008029.mp3', now()),
  (8, 30, '', '[{"id":32662,"position":1,"text_uthmani":"وَإِذْ","transliteration":"wa-idh","translation_bn":"এবং (স্বরণ করো) যখন","root":"—","lemma":"إِذ\r","grammar_bn":"শব্দ"},{"id":32663,"position":2,"text_uthmani":"يَمْكُرُ","transliteration":"yamkuru","translation_bn":"ষড়যন্ত্র করেছিলো","root":"مكر","lemma":"مَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32664,"position":3,"text_uthmani":"بِكَ","transliteration":"bika","translation_bn":"বিরুদ্ধে তোমার","root":"—","lemma":"بِكَ","grammar_bn":"অব্যয় (Preposition)"},{"id":32665,"position":4,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":32666,"position":5,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32667,"position":6,"text_uthmani":"لِيُثْبِتُوكَ","transliteration":"liyuth''bitūka","translation_bn":"জন্যে তোমাকে তারা বন্দি করার","root":"ثبت","lemma":"يُثْبِتُ","grammar_bn":"শব্দ"},{"id":32668,"position":7,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"বা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":32669,"position":8,"text_uthmani":"يَقْتُلُوكَ","transliteration":"yaqtulūka","translation_bn":"তোমাকে তারা হত্যা করবে","root":"قتل","lemma":"قَتَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32670,"position":9,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"বা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":32671,"position":10,"text_uthmani":"يُخْرِجُوكَ ۚ","transliteration":"yukh''rijūka","translation_bn":"তোমাকে তারা নির্বাসিত করবে","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32673,"position":11,"text_uthmani":"وَيَمْكُرُونَ","transliteration":"wayamkurūna","translation_bn":"এবং তারা ষড়যন্ত্র করবে","root":"مكر","lemma":"مَكَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":32674,"position":12,"text_uthmani":"وَيَمْكُرُ","transliteration":"wayamkuru","translation_bn":"আর পরিকল্পনা করেন","root":"مكر","lemma":"مَكَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":32675,"position":13,"text_uthmani":"ٱللَّهُ ۖ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":32677,"position":14,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":32678,"position":15,"text_uthmani":"خَيْرُ","transliteration":"khayru","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":32679,"position":16,"text_uthmani":"ٱلْمَـٰكِرِينَ","transliteration":"l-mākirīna","translation_bn":"পরিকল্পনাকারীদের","root":"مكر","lemma":"مَٰكِرِين","grammar_bn":"শব্দ"},{"id":32680,"position":17,"text_uthmani":"٣٠","transliteration":"","translation_bn":"(৩০)","root":"—","lemma":"٣٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idh yamkuru bika alladhīna kafarū liyuth''bitūka aw yaqtulūka aw yukh''rijūka wayamkurūna wayamkuru l-lahu wal-lahu khayru l-mākirīna', 'স্মরণ কর, সেই সময়ের কথা যখন কাফিরগণ তোমাকে বন্দী করার কিংবা হত্যা করার কিংবা দেশ থেকে বের করে দেয়ার জন্য ষড়যন্ত্র করে। তারা চক্রান্ত করে আর আল্লাহও কৌশল করেন। আল্লাহই হচ্ছেন সর্বশ্রেষ্ঠ কৌশলী।', 'And [remember, O Muhammad], when those who disbelieved plotted against you to restrain you or kill you or evict you [from Makkah]. But they plan, and Allah plans. And Allah is the best of planners.', 'স্মরণ কর, সেই সময়ের কথা যখন কাফিরগণ তোমাকে বন্দী করার কিংবা হত্যা করার কিংবা দেশ থেকে বের করে দেয়ার জন্য ষড়যন্ত্র করে। তারা চক্রান্ত করে আর আল্লাহও কৌশল করেন। আল্লাহই হচ্ছেন সর্বশ্রেষ্ঠ কৌশলী।', 'And [remember, O Muhammad], when those who disbelieved plotted against you to restrain you or kill you or evict you [from Makkah]. But they plan, and Allah plans. And Allah is the best of planners.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008030.mp3', now()),
  (8, 31, '', '[{"id":33730,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33731,"position":2,"text_uthmani":"تُتْلَىٰ","transliteration":"tut''lā","translation_bn":"তিলাওয়াত করা হয়","root":"تلو","lemma":"تَلَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33732,"position":3,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"নিকট তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33733,"position":4,"text_uthmani":"ءَايَـٰتُنَا","transliteration":"āyātunā","translation_bn":"আয়াতগুলো আমাদের","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":33734,"position":5,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33735,"position":6,"text_uthmani":"قَدْ","transliteration":"qad","translation_bn":"\"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":33736,"position":7,"text_uthmani":"سَمِعْنَا","transliteration":"samiʿ''nā","translation_bn":"আমরা শুনলাম","root":"سمع","lemma":"سَمِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33737,"position":8,"text_uthmani":"لَوْ","transliteration":"law","translation_bn":"যদি","root":"—","lemma":"لَو\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":33738,"position":9,"text_uthmani":"نَشَآءُ","transliteration":"nashāu","translation_bn":"ইচ্ছে করি আমরা","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33739,"position":10,"text_uthmani":"لَقُلْنَا","transliteration":"laqul''nā","translation_bn":"অবশ্যই আমরা বলতে পারি","root":"قول","lemma":"قَالَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":33740,"position":11,"text_uthmani":"مِثْلَ","transliteration":"mith''la","translation_bn":"মতো","root":"مثل","lemma":"مِثْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":33741,"position":12,"text_uthmani":"هَـٰذَآ ۙ","transliteration":"hādhā","translation_bn":"এই (আয়াতগুলোর)","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":33743,"position":13,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"নয়","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":33744,"position":14,"text_uthmani":"هَـٰذَآ","transliteration":"hādhā","translation_bn":"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":33745,"position":15,"text_uthmani":"إِلَّآ","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":33746,"position":16,"text_uthmani":"أَسَـٰطِيرُ","transliteration":"asāṭīru","translation_bn":"উপকথাগুলো","root":"سطر","lemma":"أَسَٰطِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":33747,"position":17,"text_uthmani":"ٱلْأَوَّلِينَ","transliteration":"l-awalīna","translation_bn":"পূর্বকালের লোকদের\"","root":"اول","lemma":"أَوَّل","grammar_bn":"শব্দ"},{"id":33748,"position":18,"text_uthmani":"٣١","transliteration":"","translation_bn":"(৩১)","root":"—","lemma":"٣١","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā tut''lā ʿalayhim āyātunā qālū qad samiʿ''nā law nashāu laqul''nā mith''la hādhā in hādhā illā asāṭīru l-awalīna', 'তাদের কাছে যখন আমার আয়াত পাঠ করা হয় তখন তারা বলে, ‘শুনলাম তো, ইচ্ছে করলে এ রকম কথা আমরাও বলতে পারি, এগুলো তো আগে কালের কেচ্ছা কাহিনী ছাড়া আর কিছুই না।’', 'And when Our verses are recited to them, they say, "We have heard. If we willed, we could say [something] like this. This is not but legends of the former peoples."', 'তাদের কাছে যখন আমার আয়াত পাঠ করা হয় তখন তারা বলে, ‘শুনলাম তো, ইচ্ছে করলে এ রকম কথা আমরাও বলতে পারি, এগুলো তো আগে কালের কেচ্ছা কাহিনী ছাড়া আর কিছুই না।’', 'And when Our verses are recited to them, they say, "We have heard. If we willed, we could say [something] like this. This is not but legends of the former peoples."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008031.mp3', now()),
  (8, 32, '', '[{"id":34610,"position":1,"text_uthmani":"وَإِذْ","transliteration":"wa-idh","translation_bn":"এবং (স্মরণ করো) যখন","root":"—","lemma":"إِذ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34611,"position":2,"text_uthmani":"قَالُوا۟","transliteration":"qālū","translation_bn":"তারা বলেছিলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":34612,"position":3,"text_uthmani":"ٱللَّهُمَّ","transliteration":"l-lahuma","translation_bn":"\"হে আল্লাহ","root":"اله","lemma":"ٱللَّهُمَّ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":34613,"position":4,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":34614,"position":5,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হয়","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":34615,"position":6,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":34616,"position":7,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"সেই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":34617,"position":8,"text_uthmani":"ٱلْحَقَّ","transliteration":"l-ḥaqa","translation_bn":"সত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":34618,"position":9,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":34619,"position":10,"text_uthmani":"عِندِكَ","transliteration":"ʿindika","translation_bn":"তোমার নিকট","root":"عند","lemma":"عِند","grammar_bn":"বিশেষ্য (Noun)"},{"id":34620,"position":11,"text_uthmani":"فَأَمْطِرْ","transliteration":"fa-amṭir","translation_bn":"তবে বর্ষন করো","root":"مطر","lemma":"أُمْطِرَتْ","grammar_bn":"ফলাফল পদ (Result)"},{"id":34621,"position":12,"text_uthmani":"عَلَيْنَا","transliteration":"ʿalaynā","translation_bn":"উপর আমাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":34622,"position":13,"text_uthmani":"حِجَارَةًۭ","transliteration":"ḥijāratan","translation_bn":"পাথর","root":"حجر","lemma":"حِجَارَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":34623,"position":14,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":34624,"position":15,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":34625,"position":16,"text_uthmani":"أَوِ","transliteration":"awi","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34626,"position":17,"text_uthmani":"ٱئْتِنَا","transliteration":"i''tinā","translation_bn":"আমাদের উপর আসো","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":34627,"position":18,"text_uthmani":"بِعَذَابٍ","transliteration":"biʿadhābin","translation_bn":"নিয়ে শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"অব্যয় (Preposition)"},{"id":34628,"position":19,"text_uthmani":"أَلِيمٍۢ","transliteration":"alīmin","translation_bn":"নিদারুণ\"","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":34629,"position":20,"text_uthmani":"٣٢","transliteration":"","translation_bn":"(৩২)","root":"—","lemma":"٣٢","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idh qālū l-lahuma in kāna hādhā huwa l-ḥaqa min ʿindika fa-amṭir ʿalaynā ḥijāratan mina l-samāi awi i''tinā biʿadhābin alīmin', 'স্মরণ কর, যখন তারা বলেছিল, ‘হে আল্লাহ! এটা যদি তোমার নিকট থেকে (প্রেরিত) সত্য (দ্বীন) হয় তাহলে আমাদের উপর আসমান থেকে পাথর বর্ষণ কর, কিংবা আমাদের উপর কোন যন্ত্রণাদায়ক শাস্তি নিয়ে এসো।’', 'And [remember] when they said, "O Allah, if this should be the truth from You, then rain down upon us stones from the sky or bring us a painful punishment."', 'স্মরণ কর, যখন তারা বলেছিল, ‘হে আল্লাহ! এটা যদি তোমার নিকট থেকে (প্রেরিত) সত্য (দ্বীন) হয় তাহলে আমাদের উপর আসমান থেকে পাথর বর্ষণ কর, কিংবা আমাদের উপর কোন যন্ত্রণাদায়ক শাস্তি নিয়ে এসো।’', 'And [remember] when they said, "O Allah, if this should be the truth from You, then rain down upon us stones from the sky or bring us a painful punishment."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008032.mp3', now()),
  (8, 33, '', '[{"id":35387,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":35388,"position":2,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হয় (এমন যে)","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35389,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":35390,"position":4,"text_uthmani":"لِيُعَذِّبَهُمْ","transliteration":"liyuʿadhibahum","translation_bn":"যেন শাস্তি দিবেন তাদেরকে","root":"عذب","lemma":"عَذَّبَ","grammar_bn":"শব্দ"},{"id":35391,"position":5,"text_uthmani":"وَأَنتَ","transliteration":"wa-anta","translation_bn":"যখন তুমি","root":"—","lemma":"وَأَنتَ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":35392,"position":6,"text_uthmani":"فِيهِمْ ۚ","transliteration":"fīhim","translation_bn":"মধ্যে তাদের(উপস্থিত আছো)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":35394,"position":7,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":35395,"position":8,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হয় (এমনও যে)","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35396,"position":9,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":35397,"position":10,"text_uthmani":"مُعَذِّبَهُمْ","transliteration":"muʿadhibahum","translation_bn":"শাস্তিদানকারী তাদেরকে","root":"عذب","lemma":"مُعَذِّب","grammar_bn":"বিশেষ্য (Noun)"},{"id":35398,"position":11,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"অথচ তারা","root":"—","lemma":"وَهُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":35399,"position":12,"text_uthmani":"يَسْتَغْفِرُونَ","transliteration":"yastaghfirūna","translation_bn":"ক্ষমা চাচ্ছে","root":"غفر","lemma":"ٱسْتَغْفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":35400,"position":13,"text_uthmani":"٣٣","transliteration":"","translation_bn":"(৩৩)","root":"—","lemma":"٣٣","grammar_bn":"মার্কার"}]'::jsonb, 'wamā kāna l-lahu liyuʿadhibahum wa-anta fīhim wamā kāna l-lahu muʿadhibahum wahum yastaghfirūna', 'তুমি তাদের মাঝে থাকা অবস্থায় আল্লাহ তাদেরকে শাস্তি দিবেন না এবং যখন তারা ক্ষমা প্রার্থনা করতে থাকবে এরূপ অবস্থায়ও আল্লাহ তাদেরকে শাস্তি দিবেন না।', 'But Allah would not punish them while you, [O Muhammad], are among them, and Allah would not punish them while they seek forgiveness.', 'তুমি তাদের মাঝে থাকা অবস্থায় আল্লাহ তাদেরকে শাস্তি দিবেন না এবং যখন তারা ক্ষমা প্রার্থনা করতে থাকবে এরূপ অবস্থায়ও আল্লাহ তাদেরকে শাস্তি দিবেন না।', 'But Allah would not punish them while you, [O Muhammad], are among them, and Allah would not punish them while they seek forgiveness.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008033.mp3', now()),
  (8, 34, '', '[{"id":36468,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং (এখন এমন) কি (রয়েছে)","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":36469,"position":2,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"জন্যে তাদের","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":36470,"position":3,"text_uthmani":"أَلَّا","transliteration":"allā","translation_bn":"যে না","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":36471,"position":4,"text_uthmani":"يُعَذِّبَهُمُ","transliteration":"yuʿadhibahumu","translation_bn":"শাস্তি দিবেন তাদের","root":"عذب","lemma":"عَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":36472,"position":5,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ (যখন তুমি নাই)","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":36473,"position":6,"text_uthmani":"وَهُمْ","transliteration":"wahum","translation_bn":"আর তারা","root":"—","lemma":"وَهُمْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":36474,"position":7,"text_uthmani":"يَصُدُّونَ","transliteration":"yaṣuddūna","translation_bn":"(পথ) রোধ করছে","root":"صدد","lemma":"صَدَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":36475,"position":8,"text_uthmani":"عَنِ","transliteration":"ʿani","translation_bn":"হতে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":36476,"position":9,"text_uthmani":"ٱلْمَسْجِدِ","transliteration":"l-masjidi","translation_bn":"মাসজীদুল","root":"سجد","lemma":"مَسْجِد","grammar_bn":"শব্দ"},{"id":36477,"position":10,"text_uthmani":"ٱلْحَرَامِ","transliteration":"l-ḥarāmi","translation_bn":"হারাম","root":"حرم","lemma":"حَرَام","grammar_bn":"শব্দ"},{"id":36478,"position":11,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"অথচ না","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":36479,"position":12,"text_uthmani":"كَانُوٓا۟","transliteration":"kānū","translation_bn":"তারা হলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":36480,"position":13,"text_uthmani":"أَوْلِيَآءَهُۥٓ ۚ","transliteration":"awliyāahu","translation_bn":"তত্ত্বাবধায়ক তার","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":36482,"position":14,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"(প্রকৃতপক্ষে) না","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":36483,"position":15,"text_uthmani":"أَوْلِيَآؤُهُۥٓ","transliteration":"awliyāuhu","translation_bn":"তত্ত্বাবধায়ক তার","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":36484,"position":16,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":36485,"position":17,"text_uthmani":"ٱلْمُتَّقُونَ","transliteration":"l-mutaqūna","translation_bn":"(যারা) মুত্তাক্বী","root":"وقي","lemma":"مُتَّقِين","grammar_bn":"শব্দ"},{"id":36486,"position":18,"text_uthmani":"وَلَـٰكِنَّ","transliteration":"walākinna","translation_bn":"কিন্তু","root":"—","lemma":"لَٰكِنّ","grammar_bn":"শব্দ"},{"id":36487,"position":19,"text_uthmani":"أَكْثَرَهُمْ","transliteration":"aktharahum","translation_bn":"অধিকাংশ তাদের","root":"كثر","lemma":"أَكْثَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":36488,"position":20,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":36489,"position":21,"text_uthmani":"يَعْلَمُونَ","transliteration":"yaʿlamūna","translation_bn":"জানে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":36490,"position":22,"text_uthmani":"٣٤","transliteration":"","translation_bn":"(৩৪)","root":"—","lemma":"٣٤","grammar_bn":"মার্কার"}]'::jsonb, 'wamā lahum allā yuʿadhibahumu l-lahu wahum yaṣuddūna ʿani l-masjidi l-ḥarāmi wamā kānū awliyāahu in awliyāuhu illā l-mutaqūna walākinna aktharahum lā yaʿlamūna', 'আল্লাহ যে তাদেরকে শাস্তি দিবেন না এ ব্যাপারে ওজর পেশ করার জন্য তাদের কাছে কী আছে যখন তারা (মানুষদেরকে) মাসজিদুল হারাম-এর পথে বাধা দিচ্ছে? তারা তো ওর (প্রকৃত) মুতাওয়াল্লী নয়, মুত্তাকীরা ছাড়া কেউ তার মুতাওয়াল্লী হতে পারে না, কিন্তু তাদের অধিকাংশ লোক এ সম্পর্কে অবগত নয়।', 'But why should Allah not punish them while they obstruct [people] from al-Masjid al- Haram and they were not [fit to be] its guardians? Its [true] guardians are not but the righteous, but most of them do not know.', 'আল্লাহ যে তাদেরকে শাস্তি দিবেন না এ ব্যাপারে ওজর পেশ করার জন্য তাদের কাছে কী আছে যখন তারা (মানুষদেরকে) মাসজিদুল হারাম-এর পথে বাধা দিচ্ছে? তারা তো ওর (প্রকৃত) মুতাওয়াল্লী নয়, মুত্তাকীরা ছাড়া কেউ তার মুতাওয়াল্লী হতে পারে না, কিন্তু তাদের অধিকাংশ লোক এ সম্পর্কে অবগত নয়।', 'But why should Allah not punish them while they obstruct [people] from al-Masjid al- Haram and they were not [fit to be] its guardians? Its [true] guardians are not but the righteous, but most of them do not know.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008034.mp3', now()),
  (8, 35, '', '[{"id":37177,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37178,"position":2,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37179,"position":3,"text_uthmani":"صَلَاتُهُمْ","transliteration":"ṣalātuhum","translation_bn":"সালাত তাদের","root":"صلو","lemma":"صَلَوٰة","grammar_bn":"বিশেষ্য (Noun)"},{"id":37180,"position":4,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"কাছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":37181,"position":5,"text_uthmani":"ٱلْبَيْتِ","transliteration":"l-bayti","translation_bn":"(কা''বা) ঘরের","root":"بيت","lemma":"بَيْت","grammar_bn":"শব্দ"},{"id":37182,"position":6,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":37183,"position":7,"text_uthmani":"مُكَآءًۭ","transliteration":"mukāan","translation_bn":"শিষ দেওয়া","root":"مكو","lemma":"مُكَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":37184,"position":8,"text_uthmani":"وَتَصْدِيَةًۭ ۚ","transliteration":"wataṣdiyatan","translation_bn":"ও করতালি বাজানো","root":"صدي","lemma":"تَصْدِيَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37186,"position":9,"text_uthmani":"فَذُوقُوا۟","transliteration":"fadhūqū","translation_bn":"অতএব তোমরা স্বাদ নাও","root":"ذوق","lemma":"ذَاقُ","grammar_bn":"শব্দ"},{"id":37187,"position":10,"text_uthmani":"ٱلْعَذَابَ","transliteration":"l-ʿadhāba","translation_bn":"শাস্তির","root":"عذب","lemma":"عَذَاب","grammar_bn":"শব্দ"},{"id":37188,"position":11,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"এ কারণে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":37189,"position":12,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা ছিলে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37190,"position":13,"text_uthmani":"تَكْفُرُونَ","transliteration":"takfurūna","translation_bn":"তোমরা অবিশ্বাস করতে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37191,"position":14,"text_uthmani":"٣٥","transliteration":"","translation_bn":"(৩৫)","root":"—","lemma":"٣٥","grammar_bn":"মার্কার"}]'::jsonb, 'wamā kāna ṣalātuhum ʿinda l-bayti illā mukāan wataṣdiyatan fadhūqū l-ʿadhāba bimā kuntum takfurūna', 'আল্লাহর ঘরের নিকট তাদের নামায হাত তালি মারা আর শিশ দেয়া ছাড়া আর কিছুই না, (এসব অপরাধে লিপ্ত ব্যক্তিদেরকে বলা হবে) ‘‘আযাব ভোগ কর যেহেতু তোমরা কুফরীতে লিপ্ত ছিলে’’।', 'And their prayer at the House was not except whistling and handclapping. So taste the punishment for what you disbelieved.', 'আল্লাহর ঘরের নিকট তাদের নামায হাত তালি মারা আর শিশ দেয়া ছাড়া আর কিছুই না, (এসব অপরাধে লিপ্ত ব্যক্তিদেরকে বলা হবে) ‘‘আযাব ভোগ কর যেহেতু তোমরা কুফরীতে লিপ্ত ছিলে’’।', 'And their prayer at the House was not except whistling and handclapping. So taste the punishment for what you disbelieved.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008035.mp3', now()),
  (8, 36, '', '[{"id":37978,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":37979,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":37980,"position":3,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অবিশ্বাস করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37981,"position":4,"text_uthmani":"يُنفِقُونَ","transliteration":"yunfiqūna","translation_bn":"তারা ব্যয় করে","root":"نفق","lemma":"أَنفَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37982,"position":5,"text_uthmani":"أَمْوَٰلَهُمْ","transliteration":"amwālahum","translation_bn":"সম্পদসমূহকে তাদের","root":"مول","lemma":"مَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":37983,"position":6,"text_uthmani":"لِيَصُدُّوا۟","transliteration":"liyaṣuddū","translation_bn":"জন্যে বাধা দেওয়ার","root":"صدد","lemma":"صَدَّ","grammar_bn":"শব্দ"},{"id":37984,"position":7,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"হতে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":37985,"position":8,"text_uthmani":"سَبِيلِ","transliteration":"sabīli","translation_bn":"পথ","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":37986,"position":9,"text_uthmani":"ٱللَّهِ ۚ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":37988,"position":10,"text_uthmani":"فَسَيُنفِقُونَهَا","transliteration":"fasayunfiqūnahā","translation_bn":"অতঃপর অচিরেই তারা খরচ করতে থাকবে তা","root":"نفق","lemma":"أَنفَقَ","grammar_bn":"শব্দ"},{"id":37989,"position":11,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37990,"position":12,"text_uthmani":"تَكُونُ","transliteration":"takūnu","translation_bn":"তা হবে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37991,"position":13,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"উপর তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":37992,"position":14,"text_uthmani":"حَسْرَةًۭ","transliteration":"ḥasratan","translation_bn":"অাক্ষেপ","root":"حسر","lemma":"حَسْرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":37993,"position":15,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":37994,"position":16,"text_uthmani":"يُغْلَبُونَ ۗ","transliteration":"yugh''labūna","translation_bn":"তারা পরাজিত হবে","root":"غلب","lemma":"غَلَبُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37996,"position":17,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"এবং যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"শব্দ"},{"id":37997,"position":18,"text_uthmani":"كَفَرُوٓا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":37998,"position":19,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":37999,"position":20,"text_uthmani":"جَهَنَّمَ","transliteration":"jahannama","translation_bn":"জাহান্নামের","root":"—","lemma":"جَهَنَّم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":38000,"position":21,"text_uthmani":"يُحْشَرُونَ","transliteration":"yuḥ''sharūna","translation_bn":"তাদের একত্র করা হবে","root":"حشر","lemma":"حَشَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":38001,"position":22,"text_uthmani":"٣٦","transliteration":"","translation_bn":"(৩৬)","root":"—","lemma":"٣٦","grammar_bn":"মার্কার"}]'::jsonb, 'inna alladhīna kafarū yunfiqūna amwālahum liyaṣuddū ʿan sabīli l-lahi fasayunfiqūnahā thumma takūnu ʿalayhim ḥasratan thumma yugh''labūna wa-alladhīna kafarū ilā jahannama yuḥ''sharūna', 'যে সব লোক সত্যকে মেনে নিতে অস্বীকার করেছে তারা আল্লাহর পথ হতে (লোকেদেরকে) বাধা দেয়ার জন্য তাদের ধন-সম্পদ ব্যয় করে থাকে, তারা তা ব্যয় করতেই থাকবে, অতঃপর এটাই তাদের দুঃখ ও অনুশোচনার কারণ হবে। পরে তারা পরাজিতও হবে। যারা কুফরী করে তাদেরকে (অবশেষে) জাহান্নামের পানে একত্রিত করা হবে।', 'Indeed, those who disbelieve spend their wealth to avert [people] from the way of Allah. So they will spend it; then it will be for them a [source of] regret; then they will be overcome. And those who have disbelieved - unto Hell they will be gathered.', 'যে সব লোক সত্যকে মেনে নিতে অস্বীকার করেছে তারা আল্লাহর পথ হতে (লোকেদেরকে) বাধা দেয়ার জন্য তাদের ধন-সম্পদ ব্যয় করে থাকে, তারা তা ব্যয় করতেই থাকবে, অতঃপর এটাই তাদের দুঃখ ও অনুশোচনার কারণ হবে। পরে তারা পরাজিতও হবে। যারা কুফরী করে তাদেরকে (অবশেষে) জাহান্নামের পানে একত্রিত করা হবে।', 'Indeed, those who disbelieve spend their wealth to avert [people] from the way of Allah. So they will spend it; then it will be for them a [source of] regret; then they will be overcome. And those who have disbelieved - unto Hell they will be gathered.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008036.mp3', now()),
  (8, 37, '', '[{"id":38815,"position":1,"text_uthmani":"لِيَمِيزَ","transliteration":"liyamīza","translation_bn":"যেন পৃথক করেন","root":"ميز","lemma":"يَمِيزَ","grammar_bn":"শব্দ"},{"id":38816,"position":2,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":38817,"position":3,"text_uthmani":"ٱلْخَبِيثَ","transliteration":"l-khabītha","translation_bn":"অপবিত্রতাকে (অর্থাৎ কাফেরদেরকে)","root":"خبث","lemma":"خَبِيث","grammar_bn":"শব্দ"},{"id":38818,"position":4,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":38819,"position":5,"text_uthmani":"ٱلطَّيِّبِ","transliteration":"l-ṭayibi","translation_bn":"পবিত্রতা (অর্থাৎ মু''মিনদের)","root":"طيب","lemma":"طَيِّب","grammar_bn":"শব্দ"},{"id":38820,"position":6,"text_uthmani":"وَيَجْعَلَ","transliteration":"wayajʿala","translation_bn":"ও রাখবেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":38821,"position":7,"text_uthmani":"ٱلْخَبِيثَ","transliteration":"l-khabītha","translation_bn":"অপবিত্রতাকে","root":"خبث","lemma":"خَبِيث","grammar_bn":"শব্দ"},{"id":38822,"position":8,"text_uthmani":"بَعْضَهُۥ","transliteration":"baʿḍahu","translation_bn":"এককে তার","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":38823,"position":9,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":38824,"position":10,"text_uthmani":"بَعْضٍۢ","transliteration":"baʿḍin","translation_bn":"অন্যের","root":"بعض","lemma":"بَعْض","grammar_bn":"বিশেষ্য (Noun)"},{"id":38825,"position":11,"text_uthmani":"فَيَرْكُمَهُۥ","transliteration":"fayarkumahu","translation_bn":"অতঃপর তিনি জমা করবেন তা","root":"ركم","lemma":"يَرْكُمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":38826,"position":12,"text_uthmani":"جَمِيعًۭا","transliteration":"jamīʿan","translation_bn":"সকলকে","root":"جمع","lemma":"جَمِيع","grammar_bn":"বিশেষ্য (Noun)"},{"id":38827,"position":13,"text_uthmani":"فَيَجْعَلَهُۥ","transliteration":"fayajʿalahu","translation_bn":"অতঃপর রাখবেন তা","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":38828,"position":14,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":38829,"position":15,"text_uthmani":"جَهَنَّمَ ۚ","transliteration":"jahannama","translation_bn":"জাহান্নামের","root":"—","lemma":"جَهَنَّم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":38831,"position":16,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"ঐসবলোক","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":38832,"position":17,"text_uthmani":"هُمُ","transliteration":"humu","translation_bn":"তারাই","root":"—","lemma":"هُمُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":38833,"position":18,"text_uthmani":"ٱلْخَـٰسِرُونَ","transliteration":"l-khāsirūna","translation_bn":"ক্ষতিগ্রস্ত","root":"خسر","lemma":"خَٰسِرِين","grammar_bn":"শব্দ"},{"id":38834,"position":19,"text_uthmani":"٣٧","transliteration":"","translation_bn":"(৩৭)","root":"—","lemma":"٣٧","grammar_bn":"মার্কার"}]'::jsonb, 'liyamīza l-lahu l-khabītha mina l-ṭayibi wayajʿala l-khabītha baʿḍahu ʿalā baʿḍin fayarkumahu jamīʿan fayajʿalahu fī jahannama ulāika humu l-khāsirūna', 'যাতে আল্লাহ পবিত্র থেকে অপবিত্রকে আলাদা করে দেন, অতঃপর অপবিত্রদের এককে অন্যের উপর রাখবেন, সকলকে স্তুপীকৃত করবেন; অতঃপর এই সমষ্টিকে জাহান্নামে নিক্ষেপ করবেন। এরাই হল সর্বস্বান্ত।', '[This is] so that Allah may distinguish the wicked from the good and place the wicked some of them upon others and heap them all together and put them into Hell. It is those who are the losers.', 'যাতে আল্লাহ পবিত্র থেকে অপবিত্রকে আলাদা করে দেন, অতঃপর অপবিত্রদের এককে অন্যের উপর রাখবেন, সকলকে স্তুপীকৃত করবেন; অতঃপর এই সমষ্টিকে জাহান্নামে নিক্ষেপ করবেন। এরাই হল সর্বস্বান্ত।', '[This is] so that Allah may distinguish the wicked from the good and place the wicked some of them upon others and heap them all together and put them into Hell. It is those who are the losers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008037.mp3', now()),
  (8, 38, '', '[{"id":39705,"position":1,"text_uthmani":"قُل","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":39706,"position":2,"text_uthmani":"لِّلَّذِينَ","transliteration":"lilladhīna","translation_bn":"উদ্দেশ্যে (তাদের) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"অব্যয় (Preposition)"},{"id":39707,"position":3,"text_uthmani":"كَفَرُوٓا۟","transliteration":"kafarū","translation_bn":"অবিশ্বাস করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":39708,"position":4,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":39709,"position":5,"text_uthmani":"يَنتَهُوا۟","transliteration":"yantahū","translation_bn":"তারা বিরত হয়","root":"نهي","lemma":"ٱنتَهَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":39710,"position":6,"text_uthmani":"يُغْفَرْ","transliteration":"yugh''far","translation_bn":"ক্ষমা করে দেয়া হবে","root":"غفر","lemma":"غَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":39711,"position":7,"text_uthmani":"لَهُم","transliteration":"lahum","translation_bn":"প্রতি তাদের","root":"—","lemma":"لَهُم","grammar_bn":"অব্যয় (Preposition)"},{"id":39712,"position":8,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":39713,"position":9,"text_uthmani":"قَدْ","transliteration":"qad","translation_bn":"নিশ্চিত","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":39714,"position":10,"text_uthmani":"سَلَفَ","transliteration":"salafa","translation_bn":"অতীত হয়েছে","root":"سلف","lemma":"سَلَفَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":39715,"position":11,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"কিন্তু যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":39716,"position":12,"text_uthmani":"يَعُودُوا۟","transliteration":"yaʿūdū","translation_bn":"তারা পুনরাবৃত্তি করে","root":"عود","lemma":"عَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":39717,"position":13,"text_uthmani":"فَقَدْ","transliteration":"faqad","translation_bn":"তবে নিশ্চয়ই (সবার জানা যা)","root":"—","lemma":"قَد\r","grammar_bn":"ফলাফল পদ (Result)"},{"id":39718,"position":14,"text_uthmani":"مَضَتْ","transliteration":"maḍat","translation_bn":"গত হয়েছে","root":"مضي","lemma":"مَضَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":39719,"position":15,"text_uthmani":"سُنَّتُ","transliteration":"sunnatu","translation_bn":"অনুসৃত রীতি","root":"سنن","lemma":"سُنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":39720,"position":16,"text_uthmani":"ٱلْأَوَّلِينَ","transliteration":"l-awalīna","translation_bn":"পুর্ববর্তীদের (ক্ষেত্রে)","root":"اول","lemma":"أَوَّل","grammar_bn":"শব্দ"},{"id":39721,"position":17,"text_uthmani":"٣٨","transliteration":"","translation_bn":"(৩৮)","root":"—","lemma":"٣٨","grammar_bn":"মার্কার"}]'::jsonb, 'qul lilladhīna kafarū in yantahū yugh''far lahum mā qad salafa wa-in yaʿūdū faqad maḍat sunnatu l-awalīna', 'যারা কুফরী করে তাদেরকে বল, ‘তারা যদি নিবৃত্ত হয় তাহলে তারা পূর্বে যা করেছে তা ক্ষমা করা হবে, আর যদি (কুফরীর) পুনরাবৃত্তি করে, তাহলে আগের লোকেদের (প্রতি অনুসৃত) নীতির দৃষ্টান্ত তো অতীতের পাতাতেই আছে।’', 'Say to those who have disbelieved [that] if they cease, what has previously occurred will be forgiven for them. But if they return [to hostility] - then the precedent of the former [rebellious] peoples has already taken place.', 'যারা কুফরী করে তাদেরকে বল, ‘তারা যদি নিবৃত্ত হয় তাহলে তারা পূর্বে যা করেছে তা ক্ষমা করা হবে, আর যদি (কুফরীর) পুনরাবৃত্তি করে, তাহলে আগের লোকেদের (প্রতি অনুসৃত) নীতির দৃষ্টান্ত তো অতীতের পাতাতেই আছে।’', 'Say to those who have disbelieved [that] if they cease, what has previously occurred will be forgiven for them. But if they return [to hostility] - then the precedent of the former [rebellious] peoples has already taken place.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008038.mp3', now()),
  (8, 39, '', '[{"id":40522,"position":1,"text_uthmani":"وَقَـٰتِلُوهُمْ","transliteration":"waqātilūhum","translation_bn":"তাদের সাথে তোমরা লড়াই করো","root":"قتل","lemma":"قَٰتَلَ","grammar_bn":"শব্দ"},{"id":40523,"position":2,"text_uthmani":"حَتَّىٰ","transliteration":"ḥattā","translation_bn":"যতক্ষণ","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":40524,"position":3,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":40525,"position":4,"text_uthmani":"تَكُونَ","transliteration":"takūna","translation_bn":"থাকে (বাকী)","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40526,"position":5,"text_uthmani":"فِتْنَةٌۭ","transliteration":"fit''natun","translation_bn":"ফিতনা","root":"فتن","lemma":"فِتْنَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":40527,"position":6,"text_uthmani":"وَيَكُونَ","transliteration":"wayakūna","translation_bn":"এবং (প্রতিষ্ঠিত) হয়","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":40528,"position":7,"text_uthmani":"ٱلدِّينُ","transliteration":"l-dīnu","translation_bn":"দীন","root":"دين","lemma":"دِين","grammar_bn":"শব্দ"},{"id":40529,"position":8,"text_uthmani":"كُلُّهُۥ","transliteration":"kulluhu","translation_bn":"সামগ্রিকভাবে","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":40530,"position":9,"text_uthmani":"لِلَّهِ ۚ","transliteration":"lillahi","translation_bn":"জন্যে আল্লাহরই","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":40532,"position":10,"text_uthmani":"فَإِنِ","transliteration":"fa-ini","translation_bn":"অতঃপর যদি","root":"—","lemma":"إِن\r","grammar_bn":"শব্দ"},{"id":40533,"position":11,"text_uthmani":"ٱنتَهَوْا۟","transliteration":"intahaw","translation_bn":"তারা বিরত হয়","root":"نهي","lemma":"ٱنتَهَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40534,"position":12,"text_uthmani":"فَإِنَّ","transliteration":"fa-inna","translation_bn":"তবে নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"ফলাফল পদ (Result)"},{"id":40535,"position":13,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":40536,"position":14,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"সে বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":40537,"position":15,"text_uthmani":"يَعْمَلُونَ","transliteration":"yaʿmalūna","translation_bn":"তারা কাজ করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40538,"position":16,"text_uthmani":"بَصِيرٌۭ","transliteration":"baṣīrun","translation_bn":"খুব দেখছেন","root":"بصر","lemma":"بَصِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":40539,"position":17,"text_uthmani":"٣٩","transliteration":"","translation_bn":"(৩৯)","root":"—","lemma":"٣٩","grammar_bn":"মার্কার"}]'::jsonb, 'waqātilūhum ḥattā lā takūna fit''natun wayakūna l-dīnu kulluhu lillahi fa-ini intahaw fa-inna l-laha bimā yaʿmalūna baṣīrun', 'তাদের বিরুদ্ধে যুদ্ধ চালিয়ে যাও যে পর্যন্ত না ফিতনা (কুফর ও শিরক) খতম হয়ে যায় আর দ্বীন পুরোপুরিভাবে আল্লাহর জন্য হয়ে যায়। অতঃপর তারা যদি বিরত হয় তাহলে তারা (ন্যায় বা অন্যায়) যা করে আল্লাহ তার সম্যক দ্রষ্টা।', 'And fight them until there is no fitnah and [until] the religion, all of it, is for Allah. And if they cease - then indeed, Allah is Seeing of what they do.', 'তাদের বিরুদ্ধে যুদ্ধ চালিয়ে যাও যে পর্যন্ত না ফিতনা (কুফর ও শিরক) খতম হয়ে যায় আর দ্বীন পুরোপুরিভাবে আল্লাহর জন্য হয়ে যায়। অতঃপর তারা যদি বিরত হয় তাহলে তারা (ন্যায় বা অন্যায়) যা করে আল্লাহ তার সম্যক দ্রষ্টা।', 'And fight them until there is no fitnah and [until] the religion, all of it, is for Allah. And if they cease - then indeed, Allah is Seeing of what they do.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008039.mp3', now()),
  (8, 40, '', '[{"id":41234,"position":1,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"এবং যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":41235,"position":2,"text_uthmani":"تَوَلَّوْا۟","transliteration":"tawallaw","translation_bn":"তারা মুখ ফিরিয়ে নেয়","root":"ولي","lemma":"تَوَلَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":41236,"position":3,"text_uthmani":"فَٱعْلَمُوٓا۟","transliteration":"fa-iʿ''lamū","translation_bn":"তবে তোমরা জেনে রাখো","root":"علم","lemma":"عَلِمَ","grammar_bn":"ফলাফল পদ (Result)"},{"id":41237,"position":4,"text_uthmani":"أَنَّ","transliteration":"anna","translation_bn":"যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":41238,"position":5,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":41239,"position":6,"text_uthmani":"مَوْلَىٰكُمْ ۚ","transliteration":"mawlākum","translation_bn":"অভিভাবক তোমাদের","root":"ولي","lemma":"مَوْلَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":41241,"position":7,"text_uthmani":"نِعْمَ","transliteration":"niʿ''ma","translation_bn":"কত উত্তম","root":"نعم","lemma":"نِعْمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":41242,"position":8,"text_uthmani":"ٱلْمَوْلَىٰ","transliteration":"l-mawlā","translation_bn":"অভিভাবক","root":"ولي","lemma":"مَوْلَىٰ","grammar_bn":"শব্দ"},{"id":41243,"position":9,"text_uthmani":"وَنِعْمَ","transliteration":"waniʿ''ma","translation_bn":"ও কত উত্তম","root":"نعم","lemma":"نِعْمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":41244,"position":10,"text_uthmani":"ٱلنَّصِيرُ","transliteration":"l-naṣīru","translation_bn":"সাহায্যকারী","root":"نصر","lemma":"نَصِير","grammar_bn":"শব্দ"},{"id":41245,"position":11,"text_uthmani":"٤٠","transliteration":"","translation_bn":"(৪০)","root":"—","lemma":"٤٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-in tawallaw fa-iʿ''lamū anna l-laha mawlākum niʿ''ma l-mawlā waniʿ''ma l-naṣīru', 'আর তারা যদি মুখ ফিরিয়ে নেয় তাহলে জেনে রেখ যে, আল্লাহই তোমাদের অভিভাবক, কতই না উত্তম অভিভাবক! কতই না উত্তম সাহায্যকারী!', 'But if they turn away - then know that Allah is your protector. Excellent is the protector, and Excellent is the helper.', 'আর তারা যদি মুখ ফিরিয়ে নেয় তাহলে জেনে রেখ যে, আল্লাহই তোমাদের অভিভাবক, কতই না উত্তম অভিভাবক! কতই না উত্তম সাহায্যকারী!', 'But if they turn away - then know that Allah is your protector. Excellent is the protector, and Excellent is the helper.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/008040.mp3', now()),
  (8, 41, '', '[{"id":42087,"position":1,"text_uthmani":"۞ وَٱعْلَمُوٓا۟","transliteration":"wa-iʿ''lamū","translation_bn":"আর তোমরা জেনে রাখো","root":"علم","lemma":"عَلِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":42088,"position":2,"text_uthmani":"أَنَّمَا","transliteration":"annamā","translation_bn":"মূলতঃ","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":42089,"position":3,"text_uthmani":"غَنِمْتُم","transliteration":"ghanim''tum","translation_bn":"গণীমত পেয়েছো তোমরা","root":"غنم","lemma":"غَنِمْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":42090,"position":4,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":42091,"position":5,"text_uthmani":"شَىْءٍۢ","transliteration":"shayin","translation_bn":"(যা) কিছু","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":42092,"position":6,"text_uthmani":"فَأَنَّ","transliteration":"fa-anna","translation_bn":"তা নিশ্চয়ই","root":"—","lemma":"أَنّ","grammar_bn":"শব্দ"},{"id":42093,"position":7,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"জন্যে আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":42094,"position":8,"text_uthmani":"خُمُسَهُۥ","transliteration":"khumusahu","translation_bn":"এক পঞ্চমাংশ তার","root":"خمس","lemma":"خُمُس","grammar_bn":"বিশেষ্য (Noun)"},{"id":42095,"position":9,"text_uthmani":"وَلِلرَّسُولِ","transliteration":"walilrrasūli","translation_bn":"এবং জন্যে  রাসূলের","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":42096,"position":10,"text_uthmani":"وَلِذِى","transliteration":"walidhī","translation_bn":"ও জন্যে সম্পন্ন","root":"—","lemma":"ذُو","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":42097,"position":11,"text_uthmani":"ٱلْقُرْبَىٰ","transliteration":"l-qur''bā","translation_bn":"নৈকট্য","root":"قرب","lemma":"قُرْبَىٰ","grammar_bn":"শব্দ"},{"id":42098,"position":12,"text_uthmani":"وَٱل