  (9, 1, '', '[{"id":60,"position":1,"text_uthmani":"بَرَآءَةٌۭ","transliteration":"barāatun","translation_bn":"সম্পর্কচ্ছেদ (ঘোষণা)","root":"برا","lemma":"بَرَا^ءَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":61,"position":2,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"পক্ষ হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":62,"position":3,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":63,"position":4,"text_uthmani":"وَرَسُولِهِۦٓ","transliteration":"warasūlihi","translation_bn":"ও রাসূলের তাঁর","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":64,"position":5,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":65,"position":6,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"তাদের (যাদের সাথে)","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":66,"position":7,"text_uthmani":"عَـٰهَدتُّم","transliteration":"ʿāhadttum","translation_bn":"চুক্তি করেছিলে তোমরা","root":"عهد","lemma":"عَٰهَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":67,"position":8,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":68,"position":9,"text_uthmani":"ٱلْمُشْرِكِينَ","transliteration":"l-mush''rikīna","translation_bn":"মুশরিকদের","root":"شرك","lemma":"مُشْرِك","grammar_bn":"শব্দ"},{"id":69,"position":10,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'barāatun mina l-lahi warasūlihi ilā alladhīna ʿāhadttum mina l-mush''rikīna', 'মুশরিকদের মধ্যেকার যাদের সঙ্গে তোমরা সন্ধিচুক্তি করেছিলে তাদের সাথে আল্লাহ ও তাঁর রসূলের পক্ষ হতে সম্পর্কচ্ছেদের ঘোষণা দেয়া হল।', '[This is a declaration of] disassociation, from Allah and His Messenger, to those with whom you had made a treaty among the polytheists.', 'মুশরিকদের মধ্যেকার যাদের সঙ্গে তোমরা সন্ধিচুক্তি করেছিলে তাদের সাথে আল্লাহ ও তাঁর রসূলের পক্ষ হতে সম্পর্কচ্ছেদের ঘোষণা দেয়া হল।', '[This is a declaration of] disassociation, from Allah and His Messenger, to those with whom you had made a treaty among the polytheists.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009001.mp3', now()),
  (9, 2, '', '[{"id":1205,"position":1,"text_uthmani":"فَسِيحُوا۟","transliteration":"fasīḥū","translation_bn":"অতএব তোমরা চলাচল করো","root":"سيح","lemma":"سِيحُ","grammar_bn":"শব্দ"},{"id":1206,"position":2,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1207,"position":3,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"দেশের","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":1208,"position":4,"text_uthmani":"أَرْبَعَةَ","transliteration":"arbaʿata","translation_bn":"চার","root":"ربع","lemma":"أَرْبَعَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":1209,"position":5,"text_uthmani":"أَشْهُرٍۢ","transliteration":"ashhurin","translation_bn":"মাস (পর্যন্ত)","root":"شهر","lemma":"شَهْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":1210,"position":6,"text_uthmani":"وَٱعْلَمُوٓا۟","transliteration":"wa-iʿ''lamū","translation_bn":"ও তোমরা জেনে রাখো","root":"علم","lemma":"عَلِمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1211,"position":7,"text_uthmani":"أَنَّكُمْ","transliteration":"annakum","translation_bn":"যে তোমরা","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":1212,"position":8,"text_uthmani":"غَيْرُ","transliteration":"ghayru","translation_bn":"নও","root":"غير","lemma":"غَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":1213,"position":9,"text_uthmani":"مُعْجِزِى","transliteration":"muʿ''jizī","translation_bn":"অক্ষমকারী","root":"عجز","lemma":"مُعْجِز","grammar_bn":"বিশেষ্য (Noun)"},{"id":1214,"position":10,"text_uthmani":"ٱللَّهِ ۙ","transliteration":"l-lahi","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":1216,"position":11,"text_uthmani":"وَأَنَّ","transliteration":"wa-anna","translation_bn":"ও নিশ্চয়ই","root":"—","lemma":"أَنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1217,"position":12,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":1218,"position":13,"text_uthmani":"مُخْزِى","transliteration":"mukh''zī","translation_bn":"লাঞ্ছনাকারী","root":"خزي","lemma":"مُخْزِى","grammar_bn":"বিশেষ্য (Noun)"},{"id":1219,"position":14,"text_uthmani":"ٱلْكَـٰفِرِينَ","transliteration":"l-kāfirīna","translation_bn":"কাফেরদেরকে","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"শব্দ"},{"id":1220,"position":15,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'fasīḥū fī l-arḍi arbaʿata ashhurin wa-iʿ''lamū annakum ghayru muʿ''jizī l-lahi wa-anna l-laha mukh''zī l-kāfirīna', 'অতঃপর (হে কাফিরগণ!) চার মাস তোমরা যমীনে (ইচ্ছে মত) চলাফেরা করে নাও; আর জেনে রেখ যে, তোমরা আল্লাহকে নত করতে পারবে না, আল্লাহ্ই সত্য প্রত্যাখ্যানকারীদেরকে লাঞ্ছিত করবেন।', 'So travel freely, [O disbelievers], throughout the land [during] four months but know that you cannot cause failure to Allah and that Allah will disgrace the disbelievers.', 'অতঃপর (হে কাফিরগণ!) চার মাস তোমরা যমীনে (ইচ্ছে মত) চলাফেরা করে নাও; আর জেনে রেখ যে, তোমরা আল্লাহকে নত করতে পারবে না, আল্লাহ্ই সত্য প্রত্যাখ্যানকারীদেরকে লাঞ্ছিত করবেন।', 'So travel freely, [O disbelievers], throughout the land [during] four months but know that you cannot cause failure to Allah and that Allah will disgrace the disbelievers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009002.mp3', now()),
  (9, 3, '', '[{"id":2278,"position":1,"text_uthmani":"وَأَذَٰنٌۭ","transliteration":"wa-adhānun","translation_bn":"এবং সাধারণ ঘোষণা","root":"اذن","lemma":"أَذَٰن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2279,"position":2,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"পক্ষ হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2280,"position":3,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":2281,"position":4,"text_uthmani":"وَرَسُولِهِۦٓ","transliteration":"warasūlihi","translation_bn":"এবং রাসূলের তাঁর","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2282,"position":5,"text_uthmani":"إِلَى","transliteration":"ilā","translation_bn":"প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2283,"position":6,"text_uthmani":"ٱلنَّاسِ","transliteration":"l-nāsi","translation_bn":"জনসাধারণের","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":2284,"position":7,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"দিনে","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":2285,"position":8,"text_uthmani":"ٱلْحَجِّ","transliteration":"l-ḥaji","translation_bn":"হজ্জের","root":"حجج","lemma":"حَجّ","grammar_bn":"শব্দ"},{"id":2286,"position":9,"text_uthmani":"ٱلْأَكْبَرِ","transliteration":"l-akbari","translation_bn":"মহান","root":"كبر","lemma":"أَكْبَر","grammar_bn":"শব্দ"},{"id":2287,"position":10,"text_uthmani":"أَنَّ","transliteration":"anna","translation_bn":"যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":2288,"position":11,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":2289,"position":12,"text_uthmani":"بَرِىٓءٌۭ","transliteration":"barīon","translation_bn":"দায়মুক্ত","root":"برا","lemma":"بَرِى^ء","grammar_bn":"বিশেষণ (Adjective)"},{"id":2290,"position":13,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2291,"position":14,"text_uthmani":"ٱلْمُشْرِكِينَ ۙ","transliteration":"l-mush''rikīna","translation_bn":"মুশরিকদের","root":"شرك","lemma":"مُشْرِك","grammar_bn":"শব্দ"},{"id":2293,"position":15,"text_uthmani":"وَرَسُولُهُۥ ۚ","transliteration":"warasūluhu","translation_bn":"এবং রাসূলও তাঁর (দ্বায়িত্বমুক্ত)","root":"رسل","lemma":"رَسُول","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2295,"position":16,"text_uthmani":"فَإِن","transliteration":"fa-in","translation_bn":"অতএব যদি","root":"—","lemma":"إِن\r","grammar_bn":"শব্দ"},{"id":2296,"position":17,"text_uthmani":"تُبْتُمْ","transliteration":"tub''tum","translation_bn":"তোমরা তাওবা করো","root":"توب","lemma":"تَابَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2297,"position":18,"text_uthmani":"فَهُوَ","transliteration":"fahuwa","translation_bn":"তবে তা","root":"—","lemma":"فَهُوَ","grammar_bn":"শব্দ"},{"id":2298,"position":19,"text_uthmani":"خَيْرٌۭ","transliteration":"khayrun","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":2299,"position":20,"text_uthmani":"لَّكُمْ ۖ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَّكُمْ ۖ","grammar_bn":"অব্যয় (Preposition)"},{"id":2301,"position":21,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"আর যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2302,"position":22,"text_uthmani":"تَوَلَّيْتُمْ","transliteration":"tawallaytum","translation_bn":"ফিরে যাও তোমরা","root":"ولي","lemma":"تَوَلَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2303,"position":23,"text_uthmani":"فَٱعْلَمُوٓا۟","transliteration":"fa-iʿ''lamū","translation_bn":"তবে তোমরা জেনে রাখো","root":"علم","lemma":"عَلِمَ","grammar_bn":"শব্দ"},{"id":2304,"position":24,"text_uthmani":"أَنَّكُمْ","transliteration":"annakum","translation_bn":"যে তোমরা","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":2305,"position":25,"text_uthmani":"غَيْرُ","transliteration":"ghayru","translation_bn":"নও","root":"غير","lemma":"غَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":2306,"position":26,"text_uthmani":"مُعْجِزِى","transliteration":"muʿ''jizī","translation_bn":"অক্ষমকারী","root":"عجز","lemma":"مُعْجِز","grammar_bn":"বিশেষ্য (Noun)"},{"id":2307,"position":27,"text_uthmani":"ٱللَّهِ ۗ","transliteration":"l-lahi","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":2309,"position":28,"text_uthmani":"وَبَشِّرِ","transliteration":"wabashiri","translation_bn":"এবং সুসংবাদ দাও","root":"بشر","lemma":"بُشِّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2310,"position":29,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদেরকে) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":2311,"position":30,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2312,"position":31,"text_uthmani":"بِعَذَابٍ","transliteration":"biʿadhābin","translation_bn":"সম্পর্কে শাস্তির","root":"عذب","lemma":"عَذَاب","grammar_bn":"অব্যয় (Preposition)"},{"id":2313,"position":32,"text_uthmani":"أَلِيمٍ","transliteration":"alīmin","translation_bn":"নিদারুণ","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":2314,"position":33,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'wa-adhānun mina l-lahi warasūlihi ilā l-nāsi yawma l-ḥaji l-akbari anna l-laha barīon mina l-mush''rikīna warasūluhu fa-in tub''tum fahuwa khayrun lakum wa-in tawallaytum fa-iʿ''lamū annakum ghayru muʿ''jizī l-lahi wabashiri alladhīna kafarū biʿadhābin alīmin', 'আল্লাহ ও তাঁর রসূলের পক্ষ হতে বড় হাজ্জের দিনে মানুষদের কাছে ঘোষণা দেয়া হল যে আল্লাহ মুশরিকদের সাথে সম্পর্কহীন এবং তাঁর রসূলও। কাজেই এখন যদি তোমরা তাওবাহ কর, তাতে তোমাদেরই ভাল হবে, আর যদি তোমরা মুখ ফিরিয়ে নাও তাহলে জেনে রেখ যে, তোমরা আল্লাহকে হীন-দুর্বল করতে পারবে না, আর যারা কুফরী করে চলেছে তাদেরকে ভয়াবহ শাস্তির সুসংবাদ শুনিয়ে দাও।', 'And [it is] an announcement from Allah and His Messenger to the people on the day of the greater pilgrimage that Allah is disassociated from the disbelievers, and [so is] His Messenger. So if you repent, that is best for you; but if you turn away - then know that you will not cause failure to Allah. And give tidings to those who disbelieve of a painful punishment.', 'আল্লাহ ও তাঁর রসূলের পক্ষ হতে বড় হাজ্জের দিনে মানুষদের কাছে ঘোষণা দেয়া হল যে আল্লাহ মুশরিকদের সাথে সম্পর্কহীন এবং তাঁর রসূলও। কাজেই এখন যদি তোমরা তাওবাহ কর, তাতে তোমাদেরই ভাল হবে, আর যদি তোমরা মুখ ফিরিয়ে নাও তাহলে জেনে রেখ যে, তোমরা আল্লাহকে হীন-দুর্বল করতে পারবে না, আর যারা কুফরী করে চলেছে তাদেরকে ভয়াবহ শাস্তির সুসংবাদ শুনিয়ে দাও।', 'And [it is] an announcement from Allah and His Messenger to the people on the day of the greater pilgrimage that Allah is disassociated from the disbelievers, and [so is] His Messenger. So if you repent, that is best for you; but if you turn away - then know that you will not cause failure to Allah. And give tidings to those who disbelieve of a painful punishment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009003.mp3', now()),
  (9, 4, '', '[{"id":3614,"position":1,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"তবে","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":3615,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যাদের (সাথে)","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":3616,"position":3,"text_uthmani":"عَـٰهَدتُّم","transliteration":"ʿāhadttum","translation_bn":"চুক্তি করেছো তোমরা","root":"عهد","lemma":"عَٰهَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3617,"position":4,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3618,"position":5,"text_uthmani":"ٱلْمُشْرِكِينَ","transliteration":"l-mush''rikīna","translation_bn":"মুশরিকদের","root":"شرك","lemma":"مُشْرِك","grammar_bn":"শব্দ"},{"id":3619,"position":6,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3620,"position":7,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"নি","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":3621,"position":8,"text_uthmani":"يَنقُصُوكُمْ","transliteration":"yanquṣūkum","translation_bn":"তোমাদের সাথে ত্রুটি করে(চুক্তি রক্ষায়)","root":"نقص","lemma":"يُنقَصُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3622,"position":9,"text_uthmani":"شَيْـًۭٔا","transliteration":"shayan","translation_bn":"কিছুমাত্র","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":3623,"position":10,"text_uthmani":"وَلَمْ","transliteration":"walam","translation_bn":"এবং নি","root":"—","lemma":"لَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3624,"position":11,"text_uthmani":"يُظَـٰهِرُوا۟","transliteration":"yuẓāhirū","translation_bn":"তারা সাহায্য করে","root":"ظهر","lemma":"ظَٰهَرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3625,"position":12,"text_uthmani":"عَلَيْكُمْ","transliteration":"ʿalaykum","translation_bn":"বিরুদ্ধে তোমাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3626,"position":13,"text_uthmani":"أَحَدًۭا","transliteration":"aḥadan","translation_bn":"কাউকে","root":"احد","lemma":"أَحَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":3627,"position":14,"text_uthmani":"فَأَتِمُّوٓا۟","transliteration":"fa-atimmū","translation_bn":"তাহ''লে তোমরা পূর্ণ করো","root":"تمم","lemma":"أَتَمَّ","grammar_bn":"শব্দ"},{"id":3628,"position":15,"text_uthmani":"إِلَيْهِمْ","transliteration":"ilayhim","translation_bn":"সাথে তাদের","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3629,"position":16,"text_uthmani":"عَهْدَهُمْ","transliteration":"ʿahdahum","translation_bn":"চুক্তি তাদের","root":"عهد","lemma":"عَهْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":3630,"position":17,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"পর্যন্ত","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3631,"position":18,"text_uthmani":"مُدَّتِهِمْ ۚ","transliteration":"muddatihim","translation_bn":"মেয়াদ তাদের","root":"مدد","lemma":"مُدَّت","grammar_bn":"বিশেষ্য (Noun)"},{"id":3633,"position":19,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":3634,"position":20,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":3635,"position":21,"text_uthmani":"يُحِبُّ","transliteration":"yuḥibbu","translation_bn":"ভালোবাসেন","root":"حبب","lemma":"أَحْبَبْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3636,"position":22,"text_uthmani":"ٱلْمُتَّقِينَ","transliteration":"l-mutaqīna","translation_bn":"মুত্তাকীদেরকে","root":"وقي","lemma":"مُتَّقِين","grammar_bn":"শব্দ"},{"id":3637,"position":23,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'illā alladhīna ʿāhadttum mina l-mush''rikīna thumma lam yanquṣūkum shayan walam yuẓāhirū ʿalaykum aḥadan fa-atimmū ilayhim ʿahdahum ilā muddatihim inna l-laha yuḥibbu l-mutaqīna', 'কিন্তু মুশরিকদের মধ্যে যারা তোমাদের সঙ্গে চুক্তি রক্ষার ব্যাপারে বিন্দুমাত্র ত্রুটি করেনি, আর তোমাদের বিরুদ্ধে কাউকে সাহায্যও করেনি, তাদের সাথে নির্দিষ্ট সময় পর্যন্ত চুক্তি পূর্ণ কর। অবশ্যই আল্লাহ মুত্তাকীদের ভালবাসেন।', 'Excepted are those with whom you made a treaty among the polytheists and then they have not been deficient toward you in anything or supported anyone against you; so complete for them their treaty until their term [has ended]. Indeed, Allah loves the righteous [who fear Him].', 'কিন্তু মুশরিকদের মধ্যে যারা তোমাদের সঙ্গে চুক্তি রক্ষার ব্যাপারে বিন্দুমাত্র ত্রুটি করেনি, আর তোমাদের বিরুদ্ধে কাউকে সাহায্যও করেনি, তাদের সাথে নির্দিষ্ট সময় পর্যন্ত চুক্তি পূর্ণ কর। অবশ্যই আল্লাহ মুত্তাকীদের ভালবাসেন।', 'Excepted are those with whom you made a treaty among the polytheists and then they have not been deficient toward you in anything or supported anyone against you; so complete for them their treaty until their term [has ended]. Indeed, Allah loves the righteous [who fear Him].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009004.mp3', now()),
  (9, 5, '', '[{"id":4945,"position":1,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"অতঃপর যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":4946,"position":2,"text_uthmani":"ٱنسَلَخَ","transliteration":"insalakha","translation_bn":"অতিবাহিত হয়","root":"سلخ","lemma":"ٱنسَلَخَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4947,"position":3,"text_uthmani":"ٱلْأَشْهُرُ","transliteration":"l-ashhuru","translation_bn":"মাসসমূহ","root":"شهر","lemma":"شَهْر","grammar_bn":"শব্দ"},{"id":4948,"position":4,"text_uthmani":"ٱلْحُرُمُ","transliteration":"l-ḥurumu","translation_bn":"নিষিদ্ধ","root":"حرم","lemma":"حَرَام","grammar_bn":"শব্দ"},{"id":4949,"position":5,"text_uthmani":"فَٱقْتُلُوا۟","transliteration":"fa-uq''tulū","translation_bn":"তখন তোমরা হত্যা করো","root":"قتل","lemma":"قَتَلَ","grammar_bn":"শব্দ"},{"id":4950,"position":6,"text_uthmani":"ٱلْمُشْرِكِينَ","transliteration":"l-mush''rikīna","translation_bn":"মুশরিকদেরকে","root":"شرك","lemma":"مُشْرِك","grammar_bn":"শব্দ"},{"id":4951,"position":7,"text_uthmani":"حَيْثُ","transliteration":"ḥaythu","translation_bn":"যেখানে","root":"حيث\r","lemma":"حَيْث","grammar_bn":"স্থানবাচক (Location)"},{"id":4952,"position":8,"text_uthmani":"وَجَدتُّمُوهُمْ","transliteration":"wajadttumūhum","translation_bn":"তোমরা পাও তাদেরকে","root":"وجد","lemma":"وَجَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4953,"position":9,"text_uthmani":"وَخُذُوهُمْ","transliteration":"wakhudhūhum","translation_bn":"ও তোমরা ধরো তাদেরকে","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4954,"position":10,"text_uthmani":"وَٱحْصُرُوهُمْ","transliteration":"wa-uḥ''ṣurūhum","translation_bn":"ও তোমরা অবরোধ করো তাদেরকে","root":"حصر","lemma":"حَصِرَتْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4955,"position":11,"text_uthmani":"وَٱقْعُدُوا۟","transliteration":"wa-uq''ʿudū","translation_bn":"এবং তোমরা বসো","root":"قعد","lemma":"قَعَدَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4956,"position":12,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"জন্যে তাদের","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":4957,"position":13,"text_uthmani":"كُلَّ","transliteration":"kulla","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":4958,"position":14,"text_uthmani":"مَرْصَدٍۢ ۚ","transliteration":"marṣadin","translation_bn":"ঘাঁটিতে","root":"رصد","lemma":"مَرْصَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":4960,"position":15,"text_uthmani":"فَإِن","transliteration":"fa-in","translation_bn":"অতঃপর যদি","root":"—","lemma":"إِن\r","grammar_bn":"শব্দ"},{"id":4961,"position":16,"text_uthmani":"تَابُوا۟","transliteration":"tābū","translation_bn":"তারা তওবা করে","root":"توب","lemma":"تَابَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4962,"position":17,"text_uthmani":"وَأَقَامُوا۟","transliteration":"wa-aqāmū","translation_bn":"ও তারা প্রতিষ্ঠা করে","root":"قوم","lemma":"أَقَامَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4963,"position":18,"text_uthmani":"ٱلصَّلَوٰةَ","transliteration":"l-ṣalata","translation_bn":"সালাত","root":"صلو","lemma":"صَلَوٰة","grammar_bn":"শব্দ"},{"id":4964,"position":19,"text_uthmani":"وَءَاتَوُا۟","transliteration":"waātawū","translation_bn":"ও তারা দেয়","root":"اتي","lemma":"ا^تَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4965,"position":20,"text_uthmani":"ٱلزَّكَوٰةَ","transliteration":"l-zakata","translation_bn":"যাকাত","root":"زكو","lemma":"زَكَوٰة","grammar_bn":"শব্দ"},{"id":4966,"position":21,"text_uthmani":"فَخَلُّوا۟","transliteration":"fakhallū","translation_bn":"তবে তোমরা ছেড়ে দাও","root":"خلو","lemma":"خَلُّ","grammar_bn":"শব্দ"},{"id":4967,"position":22,"text_uthmani":"سَبِيلَهُمْ ۚ","transliteration":"sabīlahum","translation_bn":"রাস্তা তাদের","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":4969,"position":23,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":4970,"position":24,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":4971,"position":25,"text_uthmani":"غَفُورٌۭ","transliteration":"ghafūrun","translation_bn":"ক্ষমাশীল","root":"غفر","lemma":"غَفُور","grammar_bn":"বিশেষণ (Adjective)"},{"id":4972,"position":26,"text_uthmani":"رَّحِيمٌۭ","transliteration":"raḥīmun","translation_bn":"পরম দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":4973,"position":27,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'fa-idhā insalakha l-ashhuru l-ḥurumu fa-uq''tulū l-mush''rikīna ḥaythu wajadttumūhum wakhudhūhum wa-uḥ''ṣurūhum wa-uq''ʿudū lahum kulla marṣadin fa-in tābū wa-aqāmū l-ṣalata waātawū l-zakata fakhallū sabīlahum inna l-laha ghafūrun raḥīmun', 'তারপর (এই) নিষিদ্ধ মাস অতিক্রান্ত হয়ে গেলে মুশরিকদেরকে যেখানে পাও হত্যা কর, তাদেরকে পাকড়াও কর, তাদেরকে ঘেরাও কর, তাদের অপেক্ষায় প্রত্যেক ঘাঁটিতে ওৎ পেতে বসে থাক। কিন্তু তারা যদি তাওবাহ করে, নামায প্রতিষ্ঠা করে, যাকাত আদায় করে, তাহলে তাদের পথ ছেড়ে দাও, নিশ্চয়ই আল্লাহ বড়ই ক্ষমাশীল, বড়ই দয়ালু।', 'And when the sacred months have passed, then kill the polytheists wherever you find them and capture them and besiege them and sit in wait for them at every place of ambush. But if they should repent, establish prayer, and give zakah, let them [go] on their way. Indeed, Allah is Forgiving and Merciful.', 'তারপর (এই) নিষিদ্ধ মাস অতিক্রান্ত হয়ে গেলে মুশরিকদেরকে যেখানে পাও হত্যা কর, তাদেরকে পাকড়াও কর, তাদেরকে ঘেরাও কর, তাদের অপেক্ষায় প্রত্যেক ঘাঁটিতে ওৎ পেতে বসে থাক। কিন্তু তারা যদি তাওবাহ করে, নামায প্রতিষ্ঠা করে, যাকাত আদায় করে, তাহলে তাদের পথ ছেড়ে দাও, নিশ্চয়ই আল্লাহ বড়ই ক্ষমাশীল, বড়ই দয়ালু।', 'And when the sacred months have passed, then kill the polytheists wherever you find them and capture them and besiege them and sit in wait for them at every place of ambush. But if they should repent, establish prayer, and give zakah, let them [go] on their way. Indeed, Allah is Forgiving and Merciful.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009005.mp3', now()),
  (9, 6, '', '[{"id":6195,"position":1,"text_uthmani":"وَإِنْ","transliteration":"wa-in","translation_bn":"এবং যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6196,"position":2,"text_uthmani":"أَحَدٌۭ","transliteration":"aḥadun","translation_bn":"কেউ","root":"احد","lemma":"أَحَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":6197,"position":3,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6198,"position":4,"text_uthmani":"ٱلْمُشْرِكِينَ","transliteration":"l-mush''rikīna","translation_bn":"মুশরিকদের","root":"شرك","lemma":"مُشْرِك","grammar_bn":"শব্দ"},{"id":6199,"position":5,"text_uthmani":"ٱسْتَجَارَكَ","transliteration":"is''tajāraka","translation_bn":"তোমার আশ্রয় চায়","root":"جور","lemma":"ٱسْتَجَارَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6200,"position":6,"text_uthmani":"فَأَجِرْهُ","transliteration":"fa-ajir''hu","translation_bn":"তবে তাকে আশ্রয় দাও","root":"جور","lemma":"يُجِيرُ","grammar_bn":"শব্দ"},{"id":6201,"position":7,"text_uthmani":"حَتَّىٰ","transliteration":"ḥattā","translation_bn":"যতক্ষণ না","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6202,"position":8,"text_uthmani":"يَسْمَعَ","transliteration":"yasmaʿa","translation_bn":"সে শুনে","root":"سمع","lemma":"سَمِعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6203,"position":9,"text_uthmani":"كَلَـٰمَ","transliteration":"kalāma","translation_bn":"বাণী","root":"كلم","lemma":"كَلَٰم","grammar_bn":"বিশেষ্য (Noun)"},{"id":6204,"position":10,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6205,"position":11,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6206,"position":12,"text_uthmani":"أَبْلِغْهُ","transliteration":"abligh''hu","translation_bn":"তাকে পৌঁছাও","root":"بلغ","lemma":"أَبْلَغُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6207,"position":13,"text_uthmani":"مَأْمَنَهُۥ ۚ","transliteration":"mamanahu","translation_bn":"নিরাপদ স্থানে তার","root":"امن","lemma":"مَأْمَن","grammar_bn":"বিশেষ্য (Noun)"},{"id":6209,"position":14,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এটা","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":6210,"position":15,"text_uthmani":"بِأَنَّهُمْ","transliteration":"bi-annahum","translation_bn":"এজন্যে যে তারা","root":"—","lemma":"أَنّ","grammar_bn":"অব্যয় (Preposition)"},{"id":6211,"position":16,"text_uthmani":"قَوْمٌۭ","transliteration":"qawmun","translation_bn":"(এমন)সম্প্রদায়","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":6212,"position":17,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":6213,"position":18,"text_uthmani":"يَعْلَمُونَ","transliteration":"yaʿlamūna","translation_bn":"তারা জানে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6214,"position":19,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'wa-in aḥadun mina l-mush''rikīna is''tajāraka fa-ajir''hu ḥattā yasmaʿa kalāma l-lahi thumma abligh''hu mamanahu dhālika bi-annahum qawmun lā yaʿlamūna', 'মুশরিকদের কেউ যদি তোমার কাছে আশ্রয় প্রার্থনা করে তবে তাকে আশ্রয় দাও যাতে সে আল্লাহর বাণী শোনার সুযোগ পায়; তারপর তাকে তার নিরাপদ জায়গায় পৌঁছে দাও। এটা এজন্য করতে হবে যে, এরা এমন এক সম্প্রদায় যারা (ভাল-মন্দ, সত্য-মিথ্যা সম্পর্কে) অজ্ঞ।', 'And if any one of the polytheists seeks your protection, then grant him protection so that he may hear the words of Allah. Then deliver him to his place of safety. That is because they are a people who do not know.', 'মুশরিকদের কেউ যদি তোমার কাছে আশ্রয় প্রার্থনা করে তবে তাকে আশ্রয় দাও যাতে সে আল্লাহর বাণী শোনার সুযোগ পায়; তারপর তাকে তার নিরাপদ জায়গায় পৌঁছে দাও। এটা এজন্য করতে হবে যে, এরা এমন এক সম্প্রদায় যারা (ভাল-মন্দ, সত্য-মিথ্যা সম্পর্কে) অজ্ঞ।', 'And if any one of the polytheists seeks your protection, then grant him protection so that he may hear the words of Allah. Then deliver him to his place of safety. That is because they are a people who do not know.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009006.mp3', now()),
  (9, 7, '', '[{"id":7571,"position":1,"text_uthmani":"كَيْفَ","transliteration":"kayfa","translation_bn":"কেমন করে","root":"كيف\r","lemma":"كَيْف","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":7572,"position":2,"text_uthmani":"يَكُونُ","transliteration":"yakūnu","translation_bn":"(বহাল) থাকবে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7573,"position":3,"text_uthmani":"لِلْمُشْرِكِينَ","transliteration":"lil''mush''rikīna","translation_bn":"জন্যে মুশরিকদের","root":"شرك","lemma":"مُشْرِك","grammar_bn":"অব্যয় (Preposition)"},{"id":7574,"position":4,"text_uthmani":"عَهْدٌ","transliteration":"ʿahdun","translation_bn":"চুক্তি","root":"عهد","lemma":"عَهْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":7575,"position":5,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"কাছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":7576,"position":6,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":7577,"position":7,"text_uthmani":"وَعِندَ","transliteration":"waʿinda","translation_bn":"ও কাছে","root":"عند","lemma":"عِند","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7578,"position":8,"text_uthmani":"رَسُولِهِۦٓ","transliteration":"rasūlihi","translation_bn":"রাসূলের তাঁর","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":7579,"position":9,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":7580,"position":10,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যাদের (সাথে)","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":7581,"position":11,"text_uthmani":"عَـٰهَدتُّمْ","transliteration":"ʿāhadttum","translation_bn":"তোমরা চুক্তি করেছো","root":"عهد","lemma":"عَٰهَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7582,"position":12,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"কাছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":7583,"position":13,"text_uthmani":"ٱلْمَسْجِدِ","transliteration":"l-masjidi","translation_bn":"মাসজিদে","root":"سجد","lemma":"مَسْجِد","grammar_bn":"শব্দ"},{"id":7584,"position":14,"text_uthmani":"ٱلْحَرَامِ ۖ","transliteration":"l-ḥarāmi","translation_bn":"হারামের","root":"حرم","lemma":"حَرَام","grammar_bn":"শব্দ"},{"id":7586,"position":15,"text_uthmani":"فَمَا","transliteration":"famā","translation_bn":"তাই যতক্ষণ","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":7587,"position":16,"text_uthmani":"ٱسْتَقَـٰمُوا۟","transliteration":"is''taqāmū","translation_bn":"তারা স্হির থাকে","root":"قوم","lemma":"ٱسْتَقَٰمُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7588,"position":17,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":7589,"position":18,"text_uthmani":"فَٱسْتَقِيمُوا۟","transliteration":"fa-is''taqīmū","translation_bn":"অতঃপর তোমরাও স্হির থাকো","root":"قوم","lemma":"ٱسْتَقَٰمُ","grammar_bn":"শব্দ"},{"id":7590,"position":19,"text_uthmani":"لَهُمْ ۚ","transliteration":"lahum","translation_bn":"জন্যে তাদের","root":"—","lemma":"لَهُمْ ۚ","grammar_bn":"অব্যয় (Preposition)"},{"id":7592,"position":20,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":7593,"position":21,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":7594,"position":22,"text_uthmani":"يُحِبُّ","transliteration":"yuḥibbu","translation_bn":"ভালোবাসেন","root":"حبب","lemma":"أَحْبَبْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7595,"position":23,"text_uthmani":"ٱلْمُتَّقِينَ","transliteration":"l-mutaqīna","translation_bn":"মুত্তাকীদের","root":"وقي","lemma":"مُتَّقِين","grammar_bn":"শব্দ"},{"id":7596,"position":24,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'kayfa yakūnu lil''mush''rikīna ʿahdun ʿinda l-lahi waʿinda rasūlihi illā alladhīna ʿāhadttum ʿinda l-masjidi l-ḥarāmi famā is''taqāmū lakum fa-is''taqīmū lahum inna l-laha yuḥibbu l-mutaqīna', 'আল্লাহ ও তাঁর রসূলের সঙ্গে মুশরিকদের চুক্তি কী করে কার্যকর থাকতে পারে? অবশ্য ঐসব লোক ছাড়া যাদের সঙ্গে তোমরা মাসজিদুল হারামের নিকট চুক্তিবদ্ধ হয়েছিলে; তারা যদ্দিন তোমাদের সঙ্গে চুক্তি ঠিক রাখে, তোমরাও তাদের সঙ্গে কৃত চুক্তিতে দৃঢ় থাক। নিশ্চয়ই আল্লাহ মুত্তাকীদের ভালবাসেন।', 'How can there be for the polytheists a treaty in the sight of Allah and with His Messenger, except for those with whom you made a treaty at al-Masjid al-Haram? So as long as they are upright toward you, be upright toward them. Indeed, Allah loves the righteous [who fear Him].', 'আল্লাহ ও তাঁর রসূলের সঙ্গে মুশরিকদের চুক্তি কী করে কার্যকর থাকতে পারে? অবশ্য ঐসব লোক ছাড়া যাদের সঙ্গে তোমরা মাসজিদুল হারামের নিকট চুক্তিবদ্ধ হয়েছিলে; তারা যদ্দিন তোমাদের সঙ্গে চুক্তি ঠিক রাখে, তোমরাও তাদের সঙ্গে কৃত চুক্তিতে দৃঢ় থাক। নিশ্চয়ই আল্লাহ মুত্তাকীদের ভালবাসেন।', 'How can there be for the polytheists a treaty in the sight of Allah and with His Messenger, except for those with whom you made a treaty at al-Masjid al-Haram? So as long as they are upright toward you, be upright toward them. Indeed, Allah loves the righteous [who fear Him].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009007.mp3', now()),
  (9, 8, '', '[{"id":8779,"position":1,"text_uthmani":"كَيْفَ","transliteration":"kayfa","translation_bn":"কেমন করে (চুক্তি বহাল) থাকবে","root":"كيف\r","lemma":"كَيْف","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":8780,"position":2,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"অথচ যদি","root":"—","lemma":"إِن\r","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":8781,"position":3,"text_uthmani":"يَظْهَرُوا۟","transliteration":"yaẓharū","translation_bn":"তারা বিজয়ী হয়","root":"ظهر","lemma":"ظَهَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8782,"position":4,"text_uthmani":"عَلَيْكُمْ","transliteration":"ʿalaykum","translation_bn":"উপর তোমাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8783,"position":5,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":8784,"position":6,"text_uthmani":"يَرْقُبُوا۟","transliteration":"yarqubū","translation_bn":"তারা সম্মান করে","root":"رقب","lemma":"يَرْقُبُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8785,"position":7,"text_uthmani":"فِيكُمْ","transliteration":"fīkum","translation_bn":"ব্যাপারে তোমাদের","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8786,"position":8,"text_uthmani":"إِلًّۭا","transliteration":"illan","translation_bn":"আত্মীয়তার","root":"الل","lemma":"إِلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":8787,"position":9,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8788,"position":10,"text_uthmani":"ذِمَّةًۭ ۚ","transliteration":"dhimmatan","translation_bn":"প্রতিশ্রুতির (দায়িত্ব)","root":"ذمم","lemma":"ذِمَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":8790,"position":11,"text_uthmani":"يُرْضُونَكُم","transliteration":"yur''ḍūnakum","translation_bn":"খুশী করে তোমাদের","root":"رضو","lemma":"يُرْضُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8791,"position":12,"text_uthmani":"بِأَفْوَٰهِهِمْ","transliteration":"bi-afwāhihim","translation_bn":"দিয়ে মুখের কথা তাদের","root":"فوه","lemma":"أَفْوَٰه","grammar_bn":"অব্যয় (Preposition)"},{"id":8792,"position":13,"text_uthmani":"وَتَأْبَىٰ","transliteration":"watabā","translation_bn":"ও অস্বীকার করে","root":"ابي","lemma":"أَبَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8793,"position":14,"text_uthmani":"قُلُوبُهُمْ","transliteration":"qulūbuhum","translation_bn":"অন্তর তাদের","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":8794,"position":15,"text_uthmani":"وَأَكْثَرُهُمْ","transliteration":"wa-aktharuhum","translation_bn":"এবং অধিকাংশই তাদের","root":"كثر","lemma":"أَكْثَر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8795,"position":16,"text_uthmani":"فَـٰسِقُونَ","transliteration":"fāsiqūna","translation_bn":"সত্যত্যাগী","root":"فسق","lemma":"فَاسِق","grammar_bn":"বিশেষ্য (Noun)"},{"id":8796,"position":17,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'kayfa wa-in yaẓharū ʿalaykum lā yarqubū fīkum illan walā dhimmatan yur''ḍūnakum bi-afwāhihim watabā qulūbuhum wa-aktharuhum fāsiqūna', 'কীভাবে (চুক্তি থাকতে পারে) যদি তারা তোমাদেরকে পরাজিত করতে পারে তাহলে তারা তোমাদের সঙ্গে না আত্মীয়তার মর্যাদা দেয়, আর না ওয়াদা-অঙ্গীকারের; তারা তাদের মুখের কথায় তোমাদেরকে সন্তুষ্ট রাখতে চায় কিন্তু তাদের অন্তর তা অস্বীকার করে, তাদের অধিকাংশই সত্যত্যাগী অপরাধী।', 'How [can there be a treaty] while, if they gain dominance over you, they do not observe concerning you any pact of kinship or covenant of protection? They satisfy you with their mouths, but their hearts refuse [compliance], and most of them are defiantly disobedient.', 'কীভাবে (চুক্তি থাকতে পারে) যদি তারা তোমাদেরকে পরাজিত করতে পারে তাহলে তারা তোমাদের সঙ্গে না আত্মীয়তার মর্যাদা দেয়, আর না ওয়াদা-অঙ্গীকারের; তারা তাদের মুখের কথায় তোমাদেরকে সন্তুষ্ট রাখতে চায় কিন্তু তাদের অন্তর তা অস্বীকার করে, তাদের অধিকাংশই সত্যত্যাগী অপরাধী।', 'How [can there be a treaty] while, if they gain dominance over you, they do not observe concerning you any pact of kinship or covenant of protection? They satisfy you with their mouths, but their hearts refuse [compliance], and most of them are defiantly disobedient.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009008.mp3', now()),
  (9, 9, '', '[{"id":10006,"position":1,"text_uthmani":"ٱشْتَرَوْا۟","transliteration":"ish''taraw","translation_bn":"তারা কিনেছে","root":"شري","lemma":"ٱشْتَرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10007,"position":2,"text_uthmani":"بِـَٔايَـٰتِ","transliteration":"biāyāti","translation_bn":"বিনিময়ে আয়াতের","root":"ايي","lemma":"ءَايَة","grammar_bn":"অব্যয় (Preposition)"},{"id":10008,"position":3,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":10009,"position":4,"text_uthmani":"ثَمَنًۭا","transliteration":"thamanan","translation_bn":"মূল্য","root":"ثمن","lemma":"ثَمَن","grammar_bn":"বিশেষ্য (Noun)"},{"id":10010,"position":5,"text_uthmani":"قَلِيلًۭا","transliteration":"qalīlan","translation_bn":"সামান্য","root":"قلل","lemma":"قَلِيل","grammar_bn":"বিশেষণ (Adjective)"},{"id":10011,"position":6,"text_uthmani":"فَصَدُّوا۟","transliteration":"faṣaddū","translation_bn":"অতঃপর তারা বাধা দেয় (লোকদেরকে)","root":"صدد","lemma":"صَدَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10012,"position":7,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"হতে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10013,"position":8,"text_uthmani":"سَبِيلِهِۦٓ ۚ","transliteration":"sabīlihi","translation_bn":"তাঁর পথ","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":10015,"position":9,"text_uthmani":"إِنَّهُمْ","transliteration":"innahum","translation_bn":"নিশ্চয়ই তারা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":10016,"position":10,"text_uthmani":"سَآءَ","transliteration":"sāa","translation_bn":"অতি নিকৃষ্ট","root":"سوا","lemma":"سَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10017,"position":11,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":10018,"position":12,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10019,"position":13,"text_uthmani":"يَعْمَلُونَ","transliteration":"yaʿmalūna","translation_bn":"তারা কাজ করে আসছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10020,"position":14,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'ish''taraw biāyāti l-lahi thamanan qalīlan faṣaddū ʿan sabīlihi innahum sāa mā kānū yaʿmalūna', 'আল্লাহর আয়াতকে তারা (দুনিয়াবী স্বার্থে) অতি তুচ্ছ মূল্যে বিক্রি করে দিয়েছে, আল্লাহর পথে (মানুষদের চলার ক্ষেত্রে) প্রতিবন্ধকতা সৃষ্টি করেছে। তারা যা করে কতই না জঘন্য সে কাজ।', 'They have exchanged the signs of Allah for a small price and averted [people] from His way. Indeed, it was evil that they were doing.', 'আল্লাহর আয়াতকে তারা (দুনিয়াবী স্বার্থে) অতি তুচ্ছ মূল্যে বিক্রি করে দিয়েছে, আল্লাহর পথে (মানুষদের চলার ক্ষেত্রে) প্রতিবন্ধকতা সৃষ্টি করেছে। তারা যা করে কতই না জঘন্য সে কাজ।', 'They have exchanged the signs of Allah for a small price and averted [people] from His way. Indeed, it was evil that they were doing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009009.mp3', now()),
  (9, 10, '', '[{"id":11202,"position":1,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":11203,"position":2,"text_uthmani":"يَرْقُبُونَ","transliteration":"yarqubūna","translation_bn":"তারা সম্মান করে","root":"رقب","lemma":"يَرْقُبُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11204,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"ব্যাপারে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11205,"position":4,"text_uthmani":"مُؤْمِنٍ","transliteration":"mu''minin","translation_bn":"মু''মিনের","root":"امن","lemma":"مُؤْمِن","grammar_bn":"বিশেষ্য (Noun)"},{"id":11206,"position":5,"text_uthmani":"إِلًّۭا","transliteration":"illan","translation_bn":"আত্মীয়তার","root":"الل","lemma":"إِلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":11207,"position":6,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11208,"position":7,"text_uthmani":"ذِمَّةًۭ ۚ","transliteration":"dhimmatan","translation_bn":"প্রতিশ্রুতির (দায়িত্ব)","root":"ذمم","lemma":"ذِمَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":11210,"position":8,"text_uthmani":"وَأُو۟لَـٰٓئِكَ","transliteration":"wa-ulāika","translation_bn":"এবং ঐসব লোক","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11211,"position":9,"text_uthmani":"هُمُ","transliteration":"humu","translation_bn":"তারা","root":"—","lemma":"هُمُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":11212,"position":10,"text_uthmani":"ٱلْمُعْتَدُونَ","transliteration":"l-muʿ''tadūna","translation_bn":"সীমালঙ্ঘনকারী","root":"عدو","lemma":"مُعْتَدِين","grammar_bn":"শব্দ"},{"id":11213,"position":11,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'lā yarqubūna fī mu''minin illan walā dhimmatan wa-ulāika humu l-muʿ''tadūna', 'কোন ঈমানদার ব্যক্তির ব্যাপারে তারা না কোন আত্মীয়তার মর্যাদা দেয়, আর না কোন ওয়াদা-অঙ্গীকারের। এরা হল সেই লোক যারা সীমালঙ্ঘনকারী।', 'They do not observe toward a believer any pact of kinship or covenant of protection. And it is they who are the transgressors.', 'কোন ঈমানদার ব্যক্তির ব্যাপারে তারা না কোন আত্মীয়তার মর্যাদা দেয়, আর না কোন ওয়াদা-অঙ্গীকারের। এরা হল সেই লোক যারা সীমালঙ্ঘনকারী।', 'They do not observe toward a believer any pact of kinship or covenant of protection. And it is they who are the transgressors.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009010.mp3', now()),
  (9, 11, '', '[{"id":12543,"position":1,"text_uthmani":"فَإِن","transliteration":"fa-in","translation_bn":"অতঃপর যদি","root":"—","lemma":"إِن\r","grammar_bn":"শব্দ"},{"id":12544,"position":2,"text_uthmani":"تَابُوا۟","transliteration":"tābū","translation_bn":"তারা তওবা করে","root":"توب","lemma":"تَابَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12545,"position":3,"text_uthmani":"وَأَقَامُوا۟","transliteration":"wa-aqāmū","translation_bn":"ও প্রতিষ্ঠা করে","root":"قوم","lemma":"أَقَامَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12546,"position":4,"text_uthmani":"ٱلصَّلَوٰةَ","transliteration":"l-ṣalata","translation_bn":"সালাত","root":"صلو","lemma":"صَلَوٰة","grammar_bn":"শব্দ"},{"id":12547,"position":5,"text_uthmani":"وَءَاتَوُا۟","transliteration":"waātawū","translation_bn":"ও আদায় করে","root":"اتي","lemma":"ا^تَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12548,"position":6,"text_uthmani":"ٱلزَّكَوٰةَ","transliteration":"l-zakata","translation_bn":"যাকাত","root":"زكو","lemma":"زَكَوٰة","grammar_bn":"শব্দ"},{"id":12549,"position":7,"text_uthmani":"فَإِخْوَٰنُكُمْ","transliteration":"fa-ikh''wānukum","translation_bn":"তবে ভাই তোমাদের","root":"اخو","lemma":"أَخ","grammar_bn":"শব্দ"},{"id":12550,"position":8,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"ভিত্তিতে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12551,"position":9,"text_uthmani":"ٱلدِّينِ ۗ","transliteration":"l-dīni","translation_bn":"দীনের","root":"دين","lemma":"دِين","grammar_bn":"শব্দ"},{"id":12553,"position":10,"text_uthmani":"وَنُفَصِّلُ","transliteration":"wanufaṣṣilu","translation_bn":"এবং বিস্তারিত বর্ণনা করছি আমরা","root":"فصل","lemma":"فَصَّلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12554,"position":11,"text_uthmani":"ٱلْـَٔايَـٰتِ","transliteration":"l-āyāti","translation_bn":"বিধানাবলী","root":"ايي","lemma":"ءَايَة","grammar_bn":"শব্দ"},{"id":12555,"position":12,"text_uthmani":"لِقَوْمٍۢ","transliteration":"liqawmin","translation_bn":"জন্যে সম্প্রদায়ের","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":12556,"position":13,"text_uthmani":"يَعْلَمُونَ","transliteration":"yaʿlamūna","translation_bn":"(যারা) জ্ঞান রাখে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12557,"position":14,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'fa-in tābū wa-aqāmū l-ṣalata waātawū l-zakata fa-ikh''wānukum fī l-dīni wanufaṣṣilu l-āyāti liqawmin yaʿlamūna', 'এখন যদি তারা তাওবাহ করে, নামায প্রতিষ্ঠা করে, যাকাত আদায় করে তাহলে তারা তোমাদের দ্বীনী ভাই। জ্ঞান-বুদ্ধিসম্পন্ন লোকেদের জন্য আমি স্পষ্ট করে নিদর্শন বলে দিলাম।', 'But if they repent, establish prayer, and give zakah, then they are your brothers in religion; and We detail the verses for a people who know.', 'এখন যদি তারা তাওবাহ করে, নামায প্রতিষ্ঠা করে, যাকাত আদায় করে তাহলে তারা তোমাদের দ্বীনী ভাই। জ্ঞান-বুদ্ধিসম্পন্ন লোকেদের জন্য আমি স্পষ্ট করে নিদর্শন বলে দিলাম।', 'But if they repent, establish prayer, and give zakah, then they are your brothers in religion; and We detail the verses for a people who know.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009011.mp3', now()),
  (9, 12, '', '[{"id":13872,"position":1,"text_uthmani":"وَإِن","transliteration":"wa-in","translation_bn":"আর যদি","root":"—","lemma":"إِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13873,"position":2,"text_uthmani":"نَّكَثُوٓا۟","transliteration":"nakathū","translation_bn":"তারা ভঙ্গ করে","root":"نكث","lemma":"نَّكَثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13874,"position":3,"text_uthmani":"أَيْمَـٰنَهُم","transliteration":"aymānahum","translation_bn":"শপথ তাদের","root":"يمن","lemma":"يَمِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":13875,"position":4,"text_uthmani":"مِّنۢ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13876,"position":5,"text_uthmani":"بَعْدِ","transliteration":"baʿdi","translation_bn":"পর","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":13877,"position":6,"text_uthmani":"عَهْدِهِمْ","transliteration":"ʿahdihim","translation_bn":"চুক্তির তাদের","root":"عهد","lemma":"عَهْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":13878,"position":7,"text_uthmani":"وَطَعَنُوا۟","transliteration":"waṭaʿanū","translation_bn":"ও বিদ্রূপ করে","root":"طعن","lemma":"طَعَنُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13879,"position":8,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"সম্পর্কে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":13880,"position":9,"text_uthmani":"دِينِكُمْ","transliteration":"dīnikum","translation_bn":"দীনের তোমাদের","root":"دين","lemma":"دِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":13881,"position":10,"text_uthmani":"فَقَـٰتِلُوٓا۟","transliteration":"faqātilū","translation_bn":"তখন তোমরা লড়াই করো","root":"قتل","lemma":"قَٰتَلَ","grammar_bn":"শব্দ"},{"id":13882,"position":11,"text_uthmani":"أَئِمَّةَ","transliteration":"a-immata","translation_bn":"নেতৃবৃন্দের (বিরুদ্ধে)","root":"امم","lemma":"إِمَام","grammar_bn":"বিশেষ্য (Noun)"},{"id":13883,"position":12,"text_uthmani":"ٱلْكُفْرِ ۙ","transliteration":"l-kuf''ri","translation_bn":"অবিশ্বাসের","root":"كفر","lemma":"كُفْر","grammar_bn":"শব্দ"},{"id":13885,"position":13,"text_uthmani":"إِنَّهُمْ","transliteration":"innahum","translation_bn":"নিশ্চয়ই তারা (এমন যে)","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":13886,"position":14,"text_uthmani":"لَآ","transliteration":"lā","translation_bn":"নেই(বিশ্বাস)","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":13887,"position":15,"text_uthmani":"أَيْمَـٰنَ","transliteration":"aymāna","translation_bn":"শপথ","root":"يمن","lemma":"يَمِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":13888,"position":16,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"কাছে তাদের","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":13889,"position":17,"text_uthmani":"لَعَلَّهُمْ","transliteration":"laʿallahum","translation_bn":"(এরূপ আচরণে)সম্ভবতঃ তারা","root":"—","lemma":"لَعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":13890,"position":18,"text_uthmani":"يَنتَهُونَ","transliteration":"yantahūna","translation_bn":"বিরত হবে","root":"نهي","lemma":"ٱنتَهَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13891,"position":19,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'wa-in nakathū aymānahum min baʿdi ʿahdihim waṭaʿanū fī dīnikum faqātilū a-immata l-kuf''ri innahum lā aymāna lahum laʿallahum yantahūna', 'তারা যদি চুক্তি করার পর তাদের শপথ ভঙ্গ করে আর তোমাদের দীনের বিরুদ্ধে কটুক্তি করে, তাহলে কাফিরদের নেতৃবৃন্দের বিরুদ্ধে লড়াই কর, শপথ বলে কোন জিনিস তাদের কাছে নেই, (কাজেই শক্তি প্রয়োগ কর) যাতে তারা (শয়ত্বানী কার্যকলাপ থেকে) নিবৃত্ত হয়।', 'And if they break their oaths after their treaty and defame your religion, then fight the leaders of disbelief, for indeed, there are no oaths [sacred] to them; [fight them that] they might cease.', 'তারা যদি চুক্তি করার পর তাদের শপথ ভঙ্গ করে আর তোমাদের দীনের বিরুদ্ধে কটুক্তি করে, তাহলে কাফিরদের নেতৃবৃন্দের বিরুদ্ধে লড়াই কর, শপথ বলে কোন জিনিস তাদের কাছে নেই, (কাজেই শক্তি প্রয়োগ কর) যাতে তারা (শয়ত্বানী কার্যকলাপ থেকে) নিবৃত্ত হয়।', 'And if they break their oaths after their treaty and defame your religion, then fight the leaders of disbelief, for indeed, there are no oaths [sacred] to them; [fight them that] they might cease.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009012.mp3', now()),
  (9, 13, '', '[{"id":15018,"position":1,"text_uthmani":"أَلَا","transliteration":"alā","translation_bn":"কি না","root":"—","lemma":"لَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":15019,"position":2,"text_uthmani":"تُقَـٰتِلُونَ","transliteration":"tuqātilūna","translation_bn":"তোমরা যুদ্ধ করবে","root":"قتل","lemma":"قَٰتَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15020,"position":3,"text_uthmani":"قَوْمًۭا","transliteration":"qawman","translation_bn":"সম্প্রদায়ের(বিরুদ্ধে)","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":15021,"position":4,"text_uthmani":"نَّكَثُوٓا۟","transliteration":"nakathū","translation_bn":"(যারা) ভঙ্গ করেছে","root":"نكث","lemma":"نَّكَثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15022,"position":5,"text_uthmani":"أَيْمَـٰنَهُمْ","transliteration":"aymānahum","translation_bn":"শপথ তাদের","root":"يمن","lemma":"يَمِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":15023,"position":6,"text_uthmani":"وَهَمُّوا۟","transliteration":"wahammū","translation_bn":"এবং সংকল্প করেছিলো","root":"همم","lemma":"هَمَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15024,"position":7,"text_uthmani":"بِإِخْرَاجِ","transliteration":"bi-ikh''rāji","translation_bn":"ব্যাপারে বহিষ্কার করার","root":"خرج","lemma":"إِخْرَاج","grammar_bn":"অব্যয় (Preposition)"},{"id":15025,"position":8,"text_uthmani":"ٱلرَّسُولِ","transliteration":"l-rasūli","translation_bn":"রাসূলকে","root":"رسل","lemma":"رَسُول","grammar_bn":"শব্দ"},{"id":15026,"position":9,"text_uthmani":"وَهُم","transliteration":"wahum","translation_bn":"ও তারা","root":"—","lemma":"وَهُم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15027,"position":10,"text_uthmani":"بَدَءُوكُمْ","transliteration":"badaūkum","translation_bn":"তোমাদের সাথে শুরু করেছিলো (বাড়াবাড়ি)","root":"بدا","lemma":"بَدَأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15028,"position":11,"text_uthmani":"أَوَّلَ","transliteration":"awwala","translation_bn":"প্রথম","root":"اول","lemma":"أَوَّل","grammar_bn":"বিশেষ্য (Noun)"},{"id":15029,"position":12,"text_uthmani":"مَرَّةٍ ۚ","transliteration":"marratin","translation_bn":"বারেই","root":"مرر","lemma":"مَرَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":15031,"position":13,"text_uthmani":"أَتَخْشَوْنَهُمْ ۚ","transliteration":"atakhshawnahum","translation_bn":"কি তোমরা ভয় করো তাদেরকে","root":"خشي","lemma":"خَشِىَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":15033,"position":14,"text_uthmani":"فَٱللَّهُ","transliteration":"fal-lahu","translation_bn":"অথচ আল্লাহই","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":15034,"position":15,"text_uthmani":"أَحَقُّ","transliteration":"aḥaqqu","translation_bn":"অধিক অধিকারী","root":"حقق","lemma":"أَحَقّ","grammar_bn":"বিশেষণ (Adjective)"},{"id":15035,"position":16,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":15036,"position":17,"text_uthmani":"تَخْشَوْهُ","transliteration":"takhshawhu","translation_bn":"তোমরা ভয় করো তাঁকে","root":"خشي","lemma":"خَشِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15037,"position":18,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":15038,"position":19,"text_uthmani":"كُنتُم","transliteration":"kuntum","translation_bn":"হয়ে থাকো তোমরা","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15039,"position":20,"text_uthmani":"مُّؤْمِنِينَ","transliteration":"mu''minīna","translation_bn":"মু''মিন","root":"امن","lemma":"مُؤْمِن","grammar_bn":"বিশেষ্য (Noun)"},{"id":15040,"position":21,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'alā tuqātilūna qawman nakathū aymānahum wahammū bi-ikh''rāji l-rasūli wahum badaūkum awwala marratin atakhshawnahum fal-lahu aḥaqqu an takhshawhu in kuntum mu''minīna', 'তোমরা সেই সম্প্রদায়ের বিরুদ্ধে লড়াই কেন করবে না যারা তাদের প্রতিশ্রুতি ভঙ্গ করেছে, যারা রসূলকে দেশ থেকে বের করে দেয়ার ষড়যন্ত্র করেছিল? প্রথমে তারাই তোমাদেরকে আক্রমণ করেছিল। তোমরা কি তাদেরকে ভয় কর? তোমরা যাকে ভয় করবে তার সবচেয়ে বেশি হকদার হলেন আল্লাহ যদি তোমরা মু’মিন হয়ে থাক।', 'Would you not fight a people who broke their oaths and determined to expel the Messenger, and they had begun [the attack upon] you the first time? Do you fear them? But Allah has more right that you should fear Him, if you are [truly] believers.', 'তোমরা সেই সম্প্রদায়ের বিরুদ্ধে লড়াই কেন করবে না যারা তাদের প্রতিশ্রুতি ভঙ্গ করেছে, যারা রসূলকে দেশ থেকে বের করে দেয়ার ষড়যন্ত্র করেছিল? প্রথমে তারাই তোমাদেরকে আক্রমণ করেছিল। তোমরা কি তাদেরকে ভয় কর? তোমরা যাকে ভয় করবে তার সবচেয়ে বেশি হকদার হলেন আল্লাহ যদি তোমরা মু’মিন হয়ে থাক।', 'Would you not fight a people who broke their oaths and determined to expel the Messenger, and they had begun [the attack upon] you the first time? Do you fear them? But Allah has more right that you should fear Him, if you are [truly] believers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009013.mp3', now()),
  (9, 14, '', '[{"id":16070,"position":1,"text_uthmani":"قَـٰتِلُوهُمْ","transliteration":"qātilūhum","translation_bn":"তাদের বিরুদ্ধে লড়াই করো","root":"قتل","lemma":"قَٰتَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16071,"position":2,"text_uthmani":"يُعَذِّبْهُمُ","transliteration":"yuʿadhib''humu","translation_bn":"শাস্তি দিবেন তাদেরকে","root":"عذب","lemma":"عَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16072,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":16073,"position":4,"text_uthmani":"بِأَيْدِيكُمْ","transliteration":"bi-aydīkum","translation_bn":"দিয়ে হাত তোমাদের","root":"يدي","lemma":"يَد","grammar_bn":"অব্যয় (Preposition)"},{"id":16074,"position":5,"text_uthmani":"وَيُخْزِهِمْ","transliteration":"wayukh''zihim","translation_bn":"এবং লাঞ্ছিত করবেন তাদেরকে","root":"خزي","lemma":"أَخْزَيْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16075,"position":6,"text_uthmani":"وَيَنصُرْكُمْ","transliteration":"wayanṣur''kum","translation_bn":"এবং সাহায্য করবেন তোমাদেরকে","root":"نصر","lemma":"نَصَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16076,"position":7,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"বিরুদ্ধে তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16077,"position":8,"text_uthmani":"وَيَشْفِ","transliteration":"wayashfi","translation_bn":"ও আরোগ্য করবেন","root":"شفي","lemma":"يَشْفِ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16078,"position":9,"text_uthmani":"صُدُورَ","transliteration":"ṣudūra","translation_bn":"অন্তরসমুহকে","root":"صدر","lemma":"صَدْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":16079,"position":10,"text_uthmani":"قَوْمٍۢ","transliteration":"qawmin","translation_bn":"সম্প্রদায়ের","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":16080,"position":11,"text_uthmani":"مُّؤْمِنِينَ","transliteration":"mu''minīna","translation_bn":"(যারা)মু''মিন","root":"امن","lemma":"مُؤْمِن","grammar_bn":"বিশেষণ (Adjective)"},{"id":16081,"position":12,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'qātilūhum yuʿadhib''humu l-lahu bi-aydīkum wayukh''zihim wayanṣur''kum ʿalayhim wayashfi ṣudūra qawmin mu''minīna', 'তাদের বিরুদ্ধে লড়াই কর, তোমাদের হাত দিয়েই আল্লাহ তাদেরকে শাস্তি দিবেন, তাদেরকে অপমানিত করবেন, তাদের বিরুদ্ধে তোমাদেরকে সাহায্য করবেন আর মু’মিনদের প্রাণ ঠান্ডা করবেন।', 'Fight them; Allah will punish them by your hands and will disgrace them and give you victory over them and satisfy the breasts of a believing people', 'তাদের বিরুদ্ধে লড়াই কর, তোমাদের হাত দিয়েই আল্লাহ তাদেরকে শাস্তি দিবেন, তাদেরকে অপমানিত করবেন, তাদের বিরুদ্ধে তোমাদেরকে সাহায্য করবেন আর মু’মিনদের প্রাণ ঠান্ডা করবেন।', 'Fight them; Allah will punish them by your hands and will disgrace them and give you victory over them and satisfy the breasts of a believing people', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009014.mp3', now()),
  (9, 15, '', '[{"id":17312,"position":1,"text_uthmani":"وَيُذْهِبْ","transliteration":"wayudh''hib","translation_bn":"এবং দূর করবেন তিনি","root":"ذهب","lemma":"أَذْهَبَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17313,"position":2,"text_uthmani":"غَيْظَ","transliteration":"ghayẓa","translation_bn":"ক্ষোভ (জ্বালা)","root":"غيظ","lemma":"غَيْظ","grammar_bn":"বিশেষ্য (Noun)"},{"id":17314,"position":3,"text_uthmani":"قُلُوبِهِمْ ۗ","transliteration":"qulūbihim","translation_bn":"অন্তরসমূহের তাদের","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":17316,"position":4,"text_uthmani":"وَيَتُوبُ","transliteration":"wayatūbu","translation_bn":"ও তওবা কবুল করবেন","root":"توب","lemma":"تَابَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17317,"position":5,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":17318,"position":6,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"(তাদের) প্রতি","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17319,"position":7,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যাদেরকে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":17320,"position":8,"text_uthmani":"يَشَآءُ ۗ","transliteration":"yashāu","translation_bn":"তিনি ইচ্ছে করবেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17322,"position":9,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17323,"position":10,"text_uthmani":"عَلِيمٌ","transliteration":"ʿalīmun","translation_bn":"সর্বজ্ঞ","root":"علم","lemma":"عَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":17324,"position":11,"text_uthmani":"حَكِيمٌ","transliteration":"ḥakīmun","translation_bn":"সুবিজ্ঞ","root":"حكم","lemma":"حَكِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":17325,"position":12,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'wayudh''hib ghayẓa qulūbihim wayatūbu l-lahu ʿalā man yashāu wal-lahu ʿalīmun ḥakīmun', 'তিনি তাদের মনের জ্বালা নিভিয়ে দিবেন, আল্লাহ যাকে চাইবেন তাওবাহ করার তাওফীক দিবেন, আর আল্লাহ হলেন সর্বজ্ঞ, প্রজ্ঞাময়।', 'And remove the fury in the believers'' hearts. And Allah turns in forgiveness to whom He wills; and Allah is Knowing and Wise.', 'তিনি তাদের মনের জ্বালা নিভিয়ে দিবেন, আল্লাহ যাকে চাইবেন তাওবাহ করার তাওফীক দিবেন, আর আল্লাহ হলেন সর্বজ্ঞ, প্রজ্ঞাময়।', 'And remove the fury in the believers'' hearts. And Allah turns in forgiveness to whom He wills; and Allah is Knowing and Wise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009015.mp3', now()),
  (9, 16, '', '[{"id":18388,"position":1,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"কি","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18389,"position":2,"text_uthmani":"حَسِبْتُمْ","transliteration":"ḥasib''tum","translation_bn":"মনে করেছো তোমরা","root":"حسب","lemma":"حَسِبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18390,"position":3,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":18391,"position":4,"text_uthmani":"تُتْرَكُوا۟","transliteration":"tut''rakū","translation_bn":"তোমাদেরকে ছেড়ে দেয়া হবে","root":"ترك","lemma":"تَرَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18392,"position":5,"text_uthmani":"وَلَمَّا","transliteration":"walammā","translation_bn":"অথচ নি","root":"—","lemma":"لَم\r","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":18393,"position":6,"text_uthmani":"يَعْلَمِ","transliteration":"yaʿlami","translation_bn":"জানেন(এখন পর্যন্ত)","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18394,"position":7,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":18395,"position":8,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদেরকে) কারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":18396,"position":9,"text_uthmani":"جَـٰهَدُوا۟","transliteration":"jāhadū","translation_bn":"তারা জিহাদ করেছে (তাঁর পথে)","root":"جهد","lemma":"جَٰهَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18397,"position":10,"text_uthmani":"مِنكُمْ","transliteration":"minkum","translation_bn":"মধ্য থেকে তোমাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18398,"position":11,"text_uthmani":"وَلَمْ","transliteration":"walam","translation_bn":"ও নি","root":"—","lemma":"لَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18399,"position":12,"text_uthmani":"يَتَّخِذُوا۟","transliteration":"yattakhidhū","translation_bn":"ও তারা গ্রহণ করে(অন্য কাউকে)","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18400,"position":13,"text_uthmani":"مِن","transliteration":"min","translation_bn":"দিয়ে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18401,"position":14,"text_uthmani":"دُونِ","transliteration":"dūni","translation_bn":"বাদ","root":"دون","lemma":"دُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":18402,"position":15,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":18403,"position":16,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"ও না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18404,"position":17,"text_uthmani":"رَسُولِهِۦ","transliteration":"rasūlihi","translation_bn":"তাঁর রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":18405,"position":18,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"ও না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18406,"position":19,"text_uthmani":"ٱلْمُؤْمِنِينَ","transliteration":"l-mu''minīna","translation_bn":"মু''মিনদেরকে","root":"امن","lemma":"مُؤْمِن","grammar_bn":"শব্দ"},{"id":18407,"position":20,"text_uthmani":"وَلِيجَةًۭ ۚ","transliteration":"walījatan","translation_bn":"অন্তরঙ্গ বন্ধু হিসেবে","root":"ولج","lemma":"وَلِيجَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":18409,"position":21,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18410,"position":22,"text_uthmani":"خَبِيرٌۢ","transliteration":"khabīrun","translation_bn":"খুব জানেন","root":"خبر","lemma":"خَبِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":18411,"position":23,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18412,"position":24,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"তোমরা কাজ করছো","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18413,"position":25,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'am ḥasib''tum an tut''rakū walammā yaʿlami l-lahu alladhīna jāhadū minkum walam yattakhidhū min dūni l-lahi walā rasūlihi walā l-mu''minīna walījatan wal-lahu khabīrun bimā taʿmalūna', 'তোমরা কি মনে কর যে, তোমাদেরকে এমনিই ছেড়ে দেয়া হবে যে পর্যন্ত আল্লাহ জেনে না নেবেন তোমাদের মধ্যে কারা তাঁর পথে জিহাদ করেছে, আর আল্লাহ, তাঁর রসূল ও মু’মিনদের ছাড়া অন্য কাউকে বন্ধু ও অভিভাবক হিসেবে গ্রহণ করেন নি? তোমরা যা কর সে সম্পর্কে আল্লাহ বিশেষভাবে অবহিত।', 'Do you think that you will be left [as you are] while Allah has not yet made evident those among you who strive [for His cause] and do not take other than Allah, His Messenger and the believers as intimates? And Allah is Acquainted with what you do.', 'তোমরা কি মনে কর যে, তোমাদেরকে এমনিই ছেড়ে দেয়া হবে যে পর্যন্ত আল্লাহ জেনে না নেবেন তোমাদের মধ্যে কারা তাঁর পথে জিহাদ করেছে, আর আল্লাহ, তাঁর রসূল ও মু’মিনদের ছাড়া অন্য কাউকে বন্ধু ও অভিভাবক হিসেবে গ্রহণ করেন নি? তোমরা যা কর সে সম্পর্কে আল্লাহ বিশেষভাবে অবহিত।', 'Do you think that you will be left [as you are] while Allah has not yet made evident those among you who strive [for His cause] and do not take other than Allah, His Messenger and the believers as intimates? And Allah is Acquainted with what you do.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009016.mp3', now()),
  (9, 17, '', '[{"id":19396,"position":1,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":19397,"position":2,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হতে পারে (এমন)","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19398,"position":3,"text_uthmani":"لِلْمُشْرِكِينَ","transliteration":"lil''mush''rikīna","translation_bn":"জন্যে মুশরিকদের","root":"شرك","lemma":"مُشْرِك","grammar_bn":"অব্যয় (Preposition)"},{"id":19399,"position":4,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":19400,"position":5,"text_uthmani":"يَعْمُرُوا۟","transliteration":"yaʿmurū","translation_bn":"রক্ষণাবেক্ষণ করবে তারা","root":"عمر","lemma":"عَمَرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19401,"position":6,"text_uthmani":"مَسَـٰجِدَ","transliteration":"masājida","translation_bn":"মাসজিদসমূহের","root":"سجد","lemma":"مَسْجِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":19402,"position":7,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19403,"position":8,"text_uthmani":"شَـٰهِدِينَ","transliteration":"shāhidīna","translation_bn":"(যখন) তারা সাক্ষ্যদাতা","root":"شهد","lemma":"شَاهِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":19404,"position":9,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19405,"position":10,"text_uthmani":"أَنفُسِهِم","transliteration":"anfusihim","translation_bn":"নিজেদের তাদের","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":19406,"position":11,"text_uthmani":"بِٱلْكُفْرِ ۚ","transliteration":"bil-kuf''ri","translation_bn":"সম্পর্কে অবিশ্বাস","root":"كفر","lemma":"كُفْر","grammar_bn":"অব্যয় (Preposition)"},{"id":19408,"position":12,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"ঐসব লোকের","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":19409,"position":13,"text_uthmani":"حَبِطَتْ","transliteration":"ḥabiṭat","translation_bn":"নষ্ট হয়েছে","root":"حبط","lemma":"حَبِطَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19410,"position":14,"text_uthmani":"أَعْمَـٰلُهُمْ","transliteration":"aʿmāluhum","translation_bn":"কাজকর্ম তাদের","root":"عمل","lemma":"عَمَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":19411,"position":15,"text_uthmani":"وَفِى","transliteration":"wafī","translation_bn":"ও মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19412,"position":16,"text_uthmani":"ٱلنَّارِ","transliteration":"l-nāri","translation_bn":"জাহান্নামের","root":"نور","lemma":"نَار","grammar_bn":"শব্দ"},{"id":19413,"position":17,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":19414,"position":18,"text_uthmani":"خَـٰلِدُونَ","transliteration":"khālidūna","translation_bn":"চিরস্থায়ী হবে","root":"خلد","lemma":"خَٰلِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":19415,"position":19,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'mā kāna lil''mush''rikīna an yaʿmurū masājida l-lahi shāhidīna ʿalā anfusihim bil-kuf''ri ulāika ḥabiṭat aʿmāluhum wafī l-nāri hum khālidūna', 'মুশরিকদের এটা কাজ নয় যে, তারা আল্লাহর মাসজিদের রক্ষণাবেক্ষণকারী সেবক হবে যখন তারা নিজেরাই নিজেদের কুফরীর সাক্ষ্য দেয়, তাদের সমস্ত কাজ বরবাদ হয়ে গেছে, জাহান্নামেই তারা হবে চিরস্থায়ী।', 'It is not for the polytheists to maintain the mosques of Allah [while] witnessing against themselves with disbelief. [For] those, their deeds have become worthless, and in the Fire they will abide eternally.', 'মুশরিকদের এটা কাজ নয় যে, তারা আল্লাহর মাসজিদের রক্ষণাবেক্ষণকারী সেবক হবে যখন তারা নিজেরাই নিজেদের কুফরীর সাক্ষ্য দেয়, তাদের সমস্ত কাজ বরবাদ হয়ে গেছে, জাহান্নামেই তারা হবে চিরস্থায়ী।', 'It is not for the polytheists to maintain the mosques of Allah [while] witnessing against themselves with disbelief. [For] those, their deeds have become worthless, and in the Fire they will abide eternally.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009017.mp3', now()),
  (9, 18, '', '[{"id":20454,"position":1,"text_uthmani":"إِنَّمَا","transliteration":"innamā","translation_bn":"মূলত","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":20455,"position":2,"text_uthmani":"يَعْمُرُ","transliteration":"yaʿmuru","translation_bn":"রক্ষণাবেক্ষণ করবে","root":"عمر","lemma":"عَمَرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20456,"position":3,"text_uthmani":"مَسَـٰجِدَ","transliteration":"masājida","translation_bn":"মাসজিদসমূহের","root":"سجد","lemma":"مَسْجِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":20457,"position":4,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":20458,"position":5,"text_uthmani":"مَنْ","transliteration":"man","translation_bn":"(সেই) যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":20459,"position":6,"text_uthmani":"ءَامَنَ","transliteration":"āmana","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20460,"position":7,"text_uthmani":"بِٱللَّهِ","transliteration":"bil-lahi","translation_bn":"উপর আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":20461,"position":8,"text_uthmani":"وَٱلْيَوْمِ","transliteration":"wal-yawmi","translation_bn":"ও দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20462,"position":9,"text_uthmani":"ٱلْـَٔاخِرِ","transliteration":"l-ākhiri","translation_bn":"আখিরাতের","root":"اخر","lemma":"ا^خِر","grammar_bn":"শব্দ"},{"id":20463,"position":10,"text_uthmani":"وَأَقَامَ","transliteration":"wa-aqāma","translation_bn":"ও প্রতিষ্ঠা করে","root":"قوم","lemma":"أَقَامَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20464,"position":11,"text_uthmani":"ٱلصَّلَوٰةَ","transliteration":"l-ṣalata","translation_bn":"সালাত","root":"صلو","lemma":"صَلَوٰة","grammar_bn":"শব্দ"},{"id":20465,"position":12,"text_uthmani":"وَءَاتَى","transliteration":"waātā","translation_bn":"ও আদায় করে","root":"اتي","lemma":"ا^تَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20466,"position":13,"text_uthmani":"ٱلزَّكَوٰةَ","transliteration":"l-zakata","translation_bn":"যাকাত","root":"زكو","lemma":"زَكَوٰة","grammar_bn":"শব্দ"},{"id":20467,"position":14,"text_uthmani":"وَلَمْ","transliteration":"walam","translation_bn":"ও না","root":"—","lemma":"لَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20468,"position":15,"text_uthmani":"يَخْشَ","transliteration":"yakhsha","translation_bn":"ভয় করে (অন্য কাউকে)","root":"خشي","lemma":"خَشِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20469,"position":16,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":20470,"position":17,"text_uthmani":"ٱللَّهَ ۖ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":20472,"position":18,"text_uthmani":"فَعَسَىٰٓ","transliteration":"faʿasā","translation_bn":"আশা করা যায়","root":"عسي","lemma":"عَسَى","grammar_bn":"শব্দ"},{"id":20473,"position":19,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"ঐসব লোক","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":20474,"position":20,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":20475,"position":21,"text_uthmani":"يَكُونُوا۟","transliteration":"yakūnū","translation_bn":"তারাই হবে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20476,"position":22,"text_uthmani":"مِنَ","transliteration":"mina","translation_bn":"অন্তর্ভুক্ত","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20477,"position":23,"text_uthmani":"ٱلْمُهْتَدِينَ","transliteration":"l-muh''tadīna","translation_bn":"সঠিক পথপ্রাপ্তদের","root":"هدي","lemma":"مُّهْتَدُون","grammar_bn":"শব্দ"},{"id":20478,"position":24,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'innamā yaʿmuru masājida l-lahi man āmana bil-lahi wal-yawmi l-ākhiri wa-aqāma l-ṣalata waātā l-zakata walam yakhsha illā l-laha faʿasā ulāika an yakūnū mina l-muh''tadīna', 'আল্লাহর মাসজিদের আবাদ তো তারাই করবে যারা আল্লাহ ও শেষ দিবসের প্রতি ঈমান আনে, নামায প্রতিষ্ঠা করে, যাকাত আদায় করে আর আল্লাহ ছাড়া অন্য কাউকে ভয় করে না। আশা করা যায়, তারাই হবে সঠিক পথপ্রাপ্তদের অন্তর্ভুক্ত।', 'The mosques of Allah are only to be maintained by those who believe in Allah and the Last Day and establish prayer and give zakah and do not fear except Allah, for it is expected that those will be of the [rightly] guided.', 'আল্লাহর মাসজিদের আবাদ তো তারাই করবে যারা আল্লাহ ও শেষ দিবসের প্রতি ঈমান আনে, নামায প্রতিষ্ঠা করে, যাকাত আদায় করে আর আল্লাহ ছাড়া অন্য কাউকে ভয় করে না। আশা করা যায়, তারাই হবে সঠিক পথপ্রাপ্তদের অন্তর্ভুক্ত।', 'The mosques of Allah are only to be maintained by those who believe in Allah and the Last Day and establish prayer and give zakah and do not fear except Allah, for it is expected that those will be of the [rightly] guided.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009018.mp3', now()),
  (9, 19, '', '[{"id":21545,"position":1,"text_uthmani":"۞ أَجَعَلْتُمْ","transliteration":"ajaʿaltum","translation_bn":"কি তোমরা মনে করেছো","root":"جعل","lemma":"جَعَلَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":21546,"position":2,"text_uthmani":"سِقَايَةَ","transliteration":"siqāyata","translation_bn":"পানি পান করানো","root":"سقي","lemma":"سِقَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":21547,"position":3,"text_uthmani":"ٱلْحَآجِّ","transliteration":"l-ḥāji","translation_bn":"হাজ্বীদের","root":"حجج","lemma":"حَا^جّ","grammar_bn":"শব্দ"},{"id":21548,"position":4,"text_uthmani":"وَعِمَارَةَ","transliteration":"waʿimārata","translation_bn":"ও রক্ষণাবেক্ষণ করা","root":"عمر","lemma":"عِمَارَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21549,"position":5,"text_uthmani":"ٱلْمَسْجِدِ","transliteration":"l-masjidi","translation_bn":"মাসজিদে","root":"سجد","lemma":"مَسْجِد","grammar_bn":"শব্দ"},{"id":21550,"position":6,"text_uthmani":"ٱلْحَرَامِ","transliteration":"l-ḥarāmi","translation_bn":"হারামের","root":"حرم","lemma":"حَرَام","grammar_bn":"শব্দ"},{"id":21551,"position":7,"text_uthmani":"كَمَنْ","transliteration":"kaman","translation_bn":"সমান তার যে","root":"—","lemma":"مَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21552,"position":8,"text_uthmani":"ءَامَنَ","transliteration":"āmana","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21553,"position":9,"text_uthmani":"بِٱللَّهِ","transliteration":"bil-lahi","translation_bn":"প্রতি আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":21554,"position":10,"text_uthmani":"وَٱلْيَوْمِ","transliteration":"wal-yawmi","translation_bn":"ও দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21555,"position":11,"text_uthmani":"ٱلْـَٔاخِرِ","transliteration":"l-ākhiri","translation_bn":"আখিরাতের","root":"اخر","lemma":"ا^خِر","grammar_bn":"শব্দ"},{"id":21556,"position":12,"text_uthmani":"وَجَـٰهَدَ","transliteration":"wajāhada","translation_bn":"ও জিহাদ করে","root":"جهد","lemma":"جَٰهَدَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21557,"position":13,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21558,"position":14,"text_uthmani":"سَبِيلِ","transliteration":"sabīli","translation_bn":"পথের","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":21559,"position":15,"text_uthmani":"ٱللَّهِ ۚ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":21561,"position":16,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"নয়","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":21562,"position":17,"text_uthmani":"يَسْتَوُۥنَ","transliteration":"yastawūna","translation_bn":"তারা সমান","root":"سوي","lemma":"ٱسْتَوَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":21563,"position":18,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"নিকট","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":21564,"position":19,"text_uthmani":"ٱللَّهِ ۗ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":21566,"position":20,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21567,"position":21,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":21568,"position":22,"text_uthmani":"يَهْدِى","transliteration":"yahdī","translation_bn":"সঠিক পথ দেখান","root":"هدي","lemma":"هَدَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":21569,"position":23,"text_uthmani":"ٱلْقَوْمَ","transliteration":"l-qawma","translation_bn":"সম্প্রদায়কে","root":"قوم","lemma":"قَوْم","grammar_bn":"শব্দ"},{"id":21570,"position":24,"text_uthmani":"ٱلظَّـٰلِمِينَ","transliteration":"l-ẓālimīna","translation_bn":"(যারা)সীমালঙ্ঘনকারী","root":"ظلم","lemma":"ظَالِم","grammar_bn":"শব্দ"},{"id":21571,"position":25,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'ajaʿaltum siqāyata l-ḥāji waʿimārata l-masjidi l-ḥarāmi kaman āmana bil-lahi wal-yawmi l-ākhiri wajāhada fī sabīli l-lahi lā yastawūna ʿinda l-lahi wal-lahu lā yahdī l-qawma l-ẓālimīna', 'হাজীদেরকে পানি পান করানো আর মাসজিদে হারামের আবাদ করাকে কি তোমরা তাদের কাজের সমান মনে কর যারা আল্লাহ ও শেষ দিনে বিশ্বাস করে আর আল্লাহর পথে জিহাদ করে? আল্লাহর দৃষ্টিতে এরা সমান নয়। (যারা ভ্রান্তপথে আল্লাহর সন্তুষ্টি খুঁজে এমন) যালিম সম্প্রদায়কে আল্লাহ সৎপথে পরিচালিত করেন না।', 'Have you made the providing of water for the pilgrim and the maintenance of al-Masjid al-Haram equal to [the deeds of] one who believes in Allah and the Last Day and strives in the cause of Allah? They are not equal in the sight of Allah. And Allah does not guide the wrongdoing people.', 'হাজীদেরকে পানি পান করানো আর মাসজিদে হারামের আবাদ করাকে কি তোমরা তাদের কাজের সমান মনে কর যারা আল্লাহ ও শেষ দিনে বিশ্বাস করে আর আল্লাহর পথে জিহাদ করে? আল্লাহর দৃষ্টিতে এরা সমান নয়। (যারা ভ্রান্তপথে আল্লাহর সন্তুষ্টি খুঁজে এমন) যালিম সম্প্রদায়কে আল্লাহ সৎপথে পরিচালিত করেন না।', 'Have you made the providing of water for the pilgrim and the maintenance of al-Masjid al-Haram equal to [the deeds of] one who believes in Allah and the Last Day and strives in the cause of Allah? They are not equal in the sight of Allah. And Allah does not guide the wrongdoing people.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009019.mp3', now()),
  (9, 20, '', '[{"id":22646,"position":1,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":22647,"position":2,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22648,"position":3,"text_uthmani":"وَهَاجَرُوا۟","transliteration":"wahājarū","translation_bn":"ও হিজরত করেছে","root":"هجر","lemma":"هَاجَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22649,"position":4,"text_uthmani":"وَجَـٰهَدُوا۟","transliteration":"wajāhadū","translation_bn":"ও জিহাদ করেছে","root":"جهد","lemma":"جَٰهَدَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22650,"position":5,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22651,"position":6,"text_uthmani":"سَبِيلِ","transliteration":"sabīli","translation_bn":"পথের","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":22652,"position":7,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":22653,"position":8,"text_uthmani":"بِأَمْوَٰلِهِمْ","transliteration":"bi-amwālihim","translation_bn":"দিয়ে ধনসম্পদ তাদের","root":"مول","lemma":"مَال","grammar_bn":"অব্যয় (Preposition)"},{"id":22654,"position":9,"text_uthmani":"وَأَنفُسِهِمْ","transliteration":"wa-anfusihim","translation_bn":"ও প্রাণসমূহ তাদের (দিয়ে)","root":"نفس","lemma":"نَفْس","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22655,"position":10,"text_uthmani":"أَعْظَمُ","transliteration":"aʿẓamu","translation_bn":"(তারা) অতি বড়","root":"عظم","lemma":"أَعْظَم","grammar_bn":"বিশেষণ (Adjective)"},{"id":22656,"position":11,"text_uthmani":"دَرَجَةً","transliteration":"darajatan","translation_bn":"মর্যাদায় (অধিষ্ঠিত)","root":"درج","lemma":"دَرَجَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":22657,"position":12,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"কাছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":22658,"position":13,"text_uthmani":"ٱللَّهِ ۚ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":22660,"position":14,"text_uthmani":"وَأُو۟لَـٰٓئِكَ","transliteration":"wa-ulāika","translation_bn":"এবং ঐসব লোক","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22661,"position":15,"text_uthmani":"هُمُ","transliteration":"humu","translation_bn":"তারাই","root":"—","lemma":"هُمُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":22662,"position":16,"text_uthmani":"ٱلْفَآئِزُونَ","transliteration":"l-fāizūna","translation_bn":"সফলকাম","root":"فوز","lemma":"فَا^ئِزُون","grammar_bn":"শব্দ"},{"id":22663,"position":17,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'alladhīna āmanū wahājarū wajāhadū fī sabīli l-lahi bi-amwālihim wa-anfusihim aʿẓamu darajatan ʿinda l-lahi wa-ulāika humu l-fāizūna', 'যারা ঈমান আনে, হিজরাত করে, আর নিজেদের জান-মাল দিয়ে আল্লাহর পথে জিহাদ করে, আল্লাহর নিকট তাদের বিরাট মর্যাদা রয়েছে, এরাই হল সফলকাম।', 'The ones who have believed, emigrated and striven in the cause of Allah with their wealth and their lives are greater in rank in the sight of Allah. And it is those who are the attainers [of success].', 'যারা ঈমান আনে, হিজরাত করে, আর নিজেদের জান-মাল দিয়ে আল্লাহর পথে জিহাদ করে, আল্লাহর নিকট তাদের বিরাট মর্যাদা রয়েছে, এরাই হল সফলকাম।', 'The ones who have believed, emigrated and striven in the cause of Allah with their wealth and their lives are greater in rank in the sight of Allah. And it is those who are the attainers [of success].', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009020.mp3', now()),
  (9, 21, '', '[{"id":23824,"position":1,"text_uthmani":"يُبَشِّرُهُمْ","transliteration":"yubashiruhum","translation_bn":"সুসংবাদ দিচ্ছেন তাদেরকে","root":"بشر","lemma":"بُشِّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23825,"position":2,"text_uthmani":"رَبُّهُم","transliteration":"rabbuhum","translation_bn":"তাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":23826,"position":3,"text_uthmani":"بِرَحْمَةٍۢ","transliteration":"biraḥmatin","translation_bn":"সাহায্যে দয়ার","root":"رحم","lemma":"رَحْمَة","grammar_bn":"অব্যয় (Preposition)"},{"id":23827,"position":4,"text_uthmani":"مِّنْهُ","transliteration":"min''hu","translation_bn":"পক্ষ হতে তাঁর","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23828,"position":5,"text_uthmani":"وَرِضْوَٰنٍۢ","transliteration":"wariḍ''wānin","translation_bn":"ও (তাঁর) সন্তুষ্টির","root":"رضو","lemma":"رِضْوَٰن","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23829,"position":6,"text_uthmani":"وَجَنَّـٰتٍۢ","transliteration":"wajannātin","translation_bn":"এবং জান্নাতের","root":"جنن","lemma":"جَنَّة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23830,"position":7,"text_uthmani":"لَّهُمْ","transliteration":"lahum","translation_bn":"জন্যে তাদের","root":"—","lemma":"لَّهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":23831,"position":8,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"মধ্যে তার(রয়েছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23832,"position":9,"text_uthmani":"نَعِيمٌۭ","transliteration":"naʿīmun","translation_bn":"সুখ","root":"نعم","lemma":"نَعِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":23833,"position":10,"text_uthmani":"مُّقِيمٌ","transliteration":"muqīmun","translation_bn":"স্থায়ী","root":"قوم","lemma":"مُّقِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":23834,"position":11,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'yubashiruhum rabbuhum biraḥmatin min''hu wariḍ''wānin wajannātin lahum fīhā naʿīmun muqīmun', 'তাদের প্রতিপালক তাদেরকে সুসংবাদ দিচ্ছেন তাঁর দয়া ও সন্তুষ্টির, আর জান্নাতের যেখানে তাদের জন্য আছে স্থায়ী সুখ-সামগ্রী।', 'Their Lord gives them good tidings of mercy from Him and approval and of gardens for them wherein is enduring pleasure.', 'তাদের প্রতিপালক তাদেরকে সুসংবাদ দিচ্ছেন তাঁর দয়া ও সন্তুষ্টির, আর জান্নাতের যেখানে তাদের জন্য আছে স্থায়ী সুখ-সামগ্রী।', 'Their Lord gives them good tidings of mercy from Him and approval and of gardens for them wherein is enduring pleasure.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009021.mp3', now()),
  (9, 22, '', '[{"id":24841,"position":1,"text_uthmani":"خَـٰلِدِينَ","transliteration":"khālidīna","translation_bn":"তারা চিরস্থায়ী হবে","root":"خلد","lemma":"خَٰلِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":24842,"position":2,"text_uthmani":"فِيهَآ","transliteration":"fīhā","translation_bn":"মধ্যে তার","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":24843,"position":3,"text_uthmani":"أَبَدًا ۚ","transliteration":"abadan","translation_bn":"অনাগতকাল (পর্যন্ত)","root":"ابد","lemma":"أَبَدًا","grammar_bn":"কালবাচক (Time)"},{"id":24845,"position":4,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":24846,"position":5,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":24847,"position":6,"text_uthmani":"عِندَهُۥٓ","transliteration":"ʿindahu","translation_bn":"কাছে (আছে) তাঁর","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":24848,"position":7,"text_uthmani":"أَجْرٌ","transliteration":"ajrun","translation_bn":"পুরস্কার","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":24849,"position":8,"text_uthmani":"عَظِيمٌۭ","transliteration":"ʿaẓīmun","translation_bn":"বিরাট","root":"عظم","lemma":"عَظِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":24850,"position":9,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'khālidīna fīhā abadan inna l-laha ʿindahu ajrun ʿaẓīmun', 'যেখানে তারা চিরদিন থাকবে। আল্লাহর কাছেই তো রয়েছে মহাপুরস্কার।', '[They will be] abiding therein forever. Indeed, Allah has with Him a great reward.', 'যেখানে তারা চিরদিন থাকবে। আল্লাহর কাছেই তো রয়েছে মহাপুরস্কার।', '[They will be] abiding therein forever. Indeed, Allah has with Him a great reward.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009022.mp3', now()),
  (9, 23, '', '[{"id":25833,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":25834,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":25835,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25836,"position":4,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":25837,"position":5,"text_uthmani":"تَتَّخِذُوٓا۟","transliteration":"tattakhidhū","translation_bn":"তোমরা গ্রহণ করো","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25838,"position":6,"text_uthmani":"ءَابَآءَكُمْ","transliteration":"ābāakum","translation_bn":"বাপ-দাদাদেরকে তোমাদের","root":"ابو","lemma":"ا^بَاء","grammar_bn":"বিশেষ্য (Noun)"},{"id":25839,"position":7,"text_uthmani":"وَإِخْوَٰنَكُمْ","transliteration":"wa-ikh''wānakum","translation_bn":"ও ভাইদেরকে তোমাদের","root":"اخو","lemma":"أَخ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25840,"position":8,"text_uthmani":"أَوْلِيَآءَ","transliteration":"awliyāa","translation_bn":"বন্ধু্রূপে","root":"ولي","lemma":"وَلِىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":25841,"position":9,"text_uthmani":"إِنِ","transliteration":"ini","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":25842,"position":10,"text_uthmani":"ٱسْتَحَبُّوا۟","transliteration":"is''taḥabbū","translation_bn":"তারা অধিক ভালবাসে","root":"حبب","lemma":"ٱسْتَحَبُّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25843,"position":11,"text_uthmani":"ٱلْكُفْرَ","transliteration":"l-kuf''ra","translation_bn":"অবিশ্বাসকে","root":"كفر","lemma":"كُفْر","grammar_bn":"শব্দ"},{"id":25844,"position":12,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25845,"position":13,"text_uthmani":"ٱلْإِيمَـٰنِ ۚ","transliteration":"l-īmāni","translation_bn":"ঈমানের (তুলনায়)","root":"امن","lemma":"إِيمَٰن","grammar_bn":"শব্দ"},{"id":25847,"position":14,"text_uthmani":"وَمَن","transliteration":"waman","translation_bn":"এবং যে","root":"—","lemma":"مَن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25848,"position":15,"text_uthmani":"يَتَوَلَّهُم","transliteration":"yatawallahum","translation_bn":"ভালোবাসবে তাদেরকে","root":"ولي","lemma":"تَوَلَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25849,"position":16,"text_uthmani":"مِّنكُمْ","transliteration":"minkum","translation_bn":"মধ্য হতে তোমাদের","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":25850,"position":17,"text_uthmani":"فَأُو۟لَـٰٓئِكَ","transliteration":"fa-ulāika","translation_bn":"তবে ঐসব লোক","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"শব্দ"},{"id":25851,"position":18,"text_uthmani":"هُمُ","transliteration":"humu","translation_bn":"তারাই","root":"—","lemma":"هُمُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":25852,"position":19,"text_uthmani":"ٱلظَّـٰلِمُونَ","transliteration":"l-ẓālimūna","translation_bn":"সীমালঙ্ঘনকারী","root":"ظلم","lemma":"ظَالِم","grammar_bn":"শব্দ"},{"id":25853,"position":20,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā alladhīna āmanū lā tattakhidhū ābāakum wa-ikh''wānakum awliyāa ini is''taḥabbū l-kuf''ra ʿalā l-īmāni waman yatawallahum minkum fa-ulāika humu l-ẓālimūna', 'হে বিশ্বাসীগণ! তোমরা তোমাদের পিতা আর ভাইদেরকে বন্ধুরূপে গ্রহণ করো না যদি তারা ঈমানের চেয়ে কুফরীকেই বেশি ভালবাসে। তোমাদের মধ্যে যারা তাদেরকে বন্ধুরূপে গ্রহণ করে, তারাই যালিম।', 'O you who have believed, do not take your fathers or your brothers as allies if they have preferred disbelief over belief. And whoever does so among you - then it is those who are the wrongdoers.', 'হে বিশ্বাসীগণ! তোমরা তোমাদের পিতা আর ভাইদেরকে বন্ধুরূপে গ্রহণ করো না যদি তারা ঈমানের চেয়ে কুফরীকেই বেশি ভালবাসে। তোমাদের মধ্যে যারা তাদেরকে বন্ধুরূপে গ্রহণ করে, তারাই যালিম।', 'O you who have believed, do not take your fathers or your brothers as allies if they have preferred disbelief over belief. And whoever does so among you - then it is those who are the wrongdoers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/009023.mp3', now()),
