  (10, 1, '', '[{"id":340,"position":1,"text_uthmani":"الٓر ۚ","transliteration":"alif-lam-ra","translation_bn":"আলিফ- লাম- রা","root":"—","lemma":"الٓر ۚ","grammar_bn":"শব্দ"},{"id":342,"position":2,"text_uthmani":"تِلْكَ","transliteration":"til''ka","translation_bn":"এই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":343,"position":3,"text_uthmani":"ءَايَـٰتُ","transliteration":"āyātu","translation_bn":"এই আয়াতগুলো","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":344,"position":4,"text_uthmani":"ٱلْكِتَـٰبِ","transliteration":"l-kitābi","translation_bn":"(এমন) কিতাবের","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":345,"position":5,"text_uthmani":"ٱلْحَكِيمِ","transliteration":"l-ḥakīmi","translation_bn":"(যা)প্রজ্ঞাপূর্ণ","root":"حكم","lemma":"حَكِيم","grammar_bn":"শব্দ"},{"id":346,"position":6,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'alif-lam-ra til''ka āyātu l-kitābi l-ḥakīmi', 'আলিফ-লাম-র, এগুলো মহা বিজ্ঞানময় গ্রন্থের আয়াতসমূহ।', 'Alif, Lam, Ra. These are the verses of the wise Book', 'আলিফ-লাম-র, এগুলো মহা বিজ্ঞানময় গ্রন্থের আয়াতসমূহ।', 'Alif, Lam, Ra. These are the verses of the wise Book', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/010001.mp3', now()),
  (10, 2, '', '[{"id":1585,"position":1,"text_uthmani":"أَكَانَ","transliteration":"akāna","translation_bn":"কি হয়েছে","root":"كون","lemma":"كَانَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":1586,"position":2,"text_uthmani":"لِلنَّاسِ","transliteration":"lilnnāsi","translation_bn":"জন্যে মানুষের","root":"نوس","lemma":"نَّاس","grammar_bn":"অব্যয় (Preposition)"},{"id":1587,"position":3,"text_uthmani":"عَجَبًا","transliteration":"ʿajaban","translation_bn":"আশ্চর্যজনক","root":"عجب","lemma":"عَجَب","grammar_bn":"বিশেষ্য (Noun)"},{"id":1588,"position":4,"text_uthmani":"أَنْ","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":1589,"position":5,"text_uthmani":"أَوْحَيْنَآ","transliteration":"awḥaynā","translation_bn":"আমরা ওহী পাঠিয়েছি","root":"وحي","lemma":"أَوْحَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":1590,"position":6,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1591,"position":7,"text_uthmani":"رَجُلٍۢ","transliteration":"rajulin","translation_bn":"একজন ব্যক্তির","root":"رجل","lemma":"رَجُل","grammar_bn":"বিশেষ্য (Noun)"},{"id":1592,"position":8,"text_uthmani":"مِّنْهُمْ","transliteration":"min''hum","translation_bn":"মধ্য হতে তাদেরই","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1593,"position":9,"text_uthmani":"أَنْ","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"উদ্দেশ্যবাচক (Intention)"},{"id":1594,"position":10,"text_uthmani":"أَنذِرِ","transliteration":"andhiri","translation_bn":"\"সতর্ক করো","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1595,"position":11,"text_uthmani":"ٱلنَّاسَ","transliteration":"l-nāsa","translation_bn":"মানুষকে","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":1596,"position":12,"text_uthmani":"وَبَشِّرِ","transliteration":"wabashiri","translation_bn":"ও সুসংবাদ দাও","root":"بشر","lemma":"بُشِّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1597,"position":13,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদেরকে) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1598,"position":14,"text_uthmani":"ءَامَنُوٓا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1599,"position":15,"text_uthmani":"أَنَّ","transliteration":"anna","translation_bn":"যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":1600,"position":16,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"জন্যে তাদের (রয়েছে)","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":1601,"position":17,"text_uthmani":"قَدَمَ","transliteration":"qadama","translation_bn":"পদ (মর্যাদা)","root":"قدم","lemma":"قَدَم","grammar_bn":"বিশেষ্য (Noun)"},{"id":1602,"position":18,"text_uthmani":"صِدْقٍ","transliteration":"ṣid''qin","translation_bn":"সত্যিকার","root":"صدق","lemma":"صِدْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":1603,"position":19,"text_uthmani":"عِندَ","transliteration":"ʿinda","translation_bn":"কাছে","root":"عند","lemma":"عِند","grammar_bn":"স্থানবাচক (Location)"},{"id":1604,"position":20,"text_uthmani":"رَبِّهِمْ ۗ","transliteration":"rabbihim","translation_bn":"রবের তাদের\"","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":1606,"position":21,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"(এ কথাই) বলেছে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1607,"position":22,"text_uthmani":"ٱلْكَـٰفِرُونَ","transliteration":"l-kāfirūna","translation_bn":"কাফিররা","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"শব্দ"},{"id":1608,"position":23,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"\"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":1609,"position":24,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এই (ব্যক্তি)","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":1610,"position":25,"text_uthmani":"لَسَـٰحِرٌۭ","transliteration":"lasāḥirun","translation_bn":"অবশ্যই জাদুকর","root":"سحر","lemma":"سَٰحِر","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":1611,"position":26,"text_uthmani":"مُّبِينٌ","transliteration":"mubīnun","translation_bn":"সুস্পষ্ট\"","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":1612,"position":27,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'akāna lilnnāsi ʿajaban an awḥaynā ilā rajulin min''hum an andhiri l-nāsa wabashiri alladhīna āmanū anna lahum qadama ṣid''qin ʿinda rabbihim qāla l-kāfirūna inna hādhā lasāḥirun mubīnun', 'মানুষের কাছে কি এটা আশ্চর্যের বিষয় যে, আমি তাদেরই মধ্যেকার একজন লোকের কাছে ওয়াহী পাঠিয়েছি যে, লোকদের সতর্ক করে দাও, আর যারা ঈমান আনে তাদেরকে সুসংবাদ দাও যে, তাদের জন্য তাদের প্রতিপালকের কাছে আছে মহা মর্যাদা, (কিন্তু) কাফিররা বলে, ‘এ ব্যক্তি তো প্রকাশ্য যাদুকর’।', 'Have the people been amazed that We revealed [revelation] to a man from among them, [saying], "Warn mankind and give good tidings to those who believe that they will have a [firm] precedence of honor with their Lord"? [But] the disbelievers say, "Indeed, this is an obvious magician."', 'মানুষের কাছে কি এটা আশ্চর্যের বিষয় যে, আমি তাদেরই মধ্যেকার একজন লোকের কাছে ওয়াহী পাঠিয়েছি যে, লোকদের সতর্ক করে দাও, আর যারা ঈমান আনে তাদেরকে সুসংবাদ দাও যে, তাদের জন্য তাদের প্রতিপালকের কাছে আছে মহা মর্যাদা, (কিন্তু) কাফিররা বলে, ‘এ ব্যক্তি তো প্রকাশ্য যাদুকর’।', 'Have the people been amazed that We revealed [revelation] to a man from among them, [saying], "Warn mankind and give good tidings to those who believe that they will have a [firm] precedence of honor with their Lord"? [But] the disbelievers say, "Indeed, this is an obvious magician."', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/010002.mp3', now()),
  (10, 3, '', '[{"id":2712,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":2713,"position":2,"text_uthmani":"رَبَّكُمُ","transliteration":"rabbakumu","translation_bn":"রব তোমাদের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":2714,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"(সেই) আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":2715,"position":4,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":2716,"position":5,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2717,"position":6,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশসমূহকে","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":2718,"position":7,"text_uthmani":"وَٱلْأَرْضَ","transliteration":"wal-arḍa","translation_bn":"ও পৃথিবীকে","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2719,"position":8,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2720,"position":9,"text_uthmani":"سِتَّةِ","transliteration":"sittati","translation_bn":"ছয়টি","root":"ستت","lemma":"سِتَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":2721,"position":10,"text_uthmani":"أَيَّامٍۢ","transliteration":"ayyāmin","translation_bn":"দিনে","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":2722,"position":11,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2723,"position":12,"text_uthmani":"ٱسْتَوَىٰ","transliteration":"is''tawā","translation_bn":"সমাসীন হয়েছেন","root":"سوي","lemma":"ٱسْتَوَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":2724,"position":13,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2725,"position":14,"text_uthmani":"ٱلْعَرْشِ ۖ","transliteration":"l-ʿarshi","translation_bn":"আরশের","root":"عرش","lemma":"عَرْش","grammar_bn":"শব্দ"},{"id":2727,"position":15,"text_uthmani":"يُدَبِّرُ","transliteration":"yudabbiru","translation_bn":"পরিচালনা করেন","root":"دبر","lemma":"يُدَبِّرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2728,"position":16,"text_uthmani":"ٱلْأَمْرَ ۖ","transliteration":"l-amra","translation_bn":"সকল (বিষয়)","root":"امر","lemma":"أَمْر","grammar_bn":"শব্দ"},{"id":2730,"position":17,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"নেই","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":2731,"position":18,"text_uthmani":"مِن","transliteration":"min","translation_bn":"কোনো","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2732,"position":19,"text_uthmani":"شَفِيعٍ","transliteration":"shafīʿin","translation_bn":"সুপারিশকারী","root":"شفع","lemma":"شَفِيع","grammar_bn":"বিশেষ্য (Noun)"},{"id":2733,"position":20,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"তবে (কেউ সুপারিশ করলে)","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":2734,"position":21,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2735,"position":22,"text_uthmani":"بَعْدِ","transliteration":"baʿdi","translation_bn":"পর","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":2736,"position":23,"text_uthmani":"إِذْنِهِۦ ۚ","transliteration":"idh''nihi","translation_bn":"তাঁর অনুমতির (সেটা অন্য কথা)","root":"اذن","lemma":"إِذْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":2738,"position":24,"text_uthmani":"ذَٰلِكُمُ","transliteration":"dhālikumu","translation_bn":"তিনিই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":2739,"position":25,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":2740,"position":26,"text_uthmani":"رَبُّكُمْ","transliteration":"rabbukum","translation_bn":"তোমাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":2741,"position":27,"text_uthmani":"فَٱعْبُدُوهُ ۚ","transliteration":"fa-uʿ''budūhu","translation_bn":"অতএব তাঁরই ইবাদত করো তোমরা","root":"عبد","lemma":"عَبَدَ","grammar_bn":"শব্দ"},{"id":2743,"position":28,"text_uthmani":"أَفَلَا","transliteration":"afalā","translation_bn":"কি তবুও  না","root":"—","lemma":"لَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":2744,"position":29,"text_uthmani":"تَذَكَّرُونَ","transliteration":"tadhakkarūna","translation_bn":"তোমরা শিক্ষা গ্রহণ করবে","root":"ذكر","lemma":"تَذَكَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2745,"position":30,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'inna rabbakumu l-lahu alladhī khalaqa l-samāwāti wal-arḍa fī sittati ayyāmin thumma is''tawā ʿalā l-ʿarshi yudabbiru l-amra mā min shafīʿin illā min baʿdi idh''nihi dhālikumu l-lahu rabbukum fa-uʿ''budūhu afalā tadhakkarūna', 'নিশ্চয়ই তোমাদের প্রতিপালক হলেন আল্লাহ যিনি আকাশমন্ডলী আর পৃথিবীকে ছয় দিনে সৃষ্টি করেছেন। অতঃপর তিনি আরশে সমুন্নত হয়েছেন। তিনি যাবতীয় বিষয়াদি পরিচালনা করেন। তাঁর অনুমতি প্রাপ্তি ছাড়া সুপারিশ করার কেউ নেই। ইনিই হলেন আল্লাহ, তোমাদের প্রতিপালক। কাজেই তোমরা তাঁরই ‘ইবাদাত কর, তোমরা কি উপদেশ গ্রহণ করবে না?', 'Indeed, your Lord is Allah, who created the heavens and the earth in six days and then established Himself above the Throne, arranging the matter [of His creation]. There is no intercessor except after His permission. That is Allah, your Lord, so worship Him. Then will you not remember?', 'নিশ্চয়ই তোমাদের প্রতিপালক হলেন আল্লাহ যিনি আকাশমন্ডলী আর পৃথিবীকে ছয় দিনে সৃষ্টি করেছেন। অতঃপর তিনি আরশে সমুন্নত হয়েছেন। তিনি যাবতীয় বিষয়াদি পরিচালনা করেন। তাঁর অনুমতি প্রাপ্তি ছাড়া সুপারিশ করার কেউ নেই। ইনিই হলেন আল্লাহ, তোমাদের প্রতিপালক। কাজেই তোমরা তাঁরই ‘ইবাদাত কর, তোমরা কি উপদেশ গ্রহণ করবে না?', 'Indeed, your Lord is Allah, who created the heavens and the earth in six days and then established Himself above the Throne, arranging the matter [of His creation]. There is no intercessor except after His permission. That is Allah, your Lord, so worship Him. Then will you not remember?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/010003.mp3', now()),
  (10, 4, '', '[{"id":4099,"position":1,"text_uthmani":"إِلَيْهِ","transliteration":"ilayhi","translation_bn":"দিকে তাঁরই","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4100,"position":2,"text_uthmani":"مَرْجِعُكُمْ","transliteration":"marjiʿukum","translation_bn":"তোমাদের প্রত্যাবর্তন","root":"رجع","lemma":"مَرْجِع","grammar_bn":"বিশেষ্য (Noun)"},{"id":4101,"position":3,"text_uthmani":"جَمِيعًۭا ۖ","transliteration":"jamīʿan","translation_bn":"সকলেরই","root":"جمع","lemma":"جَمِيع","grammar_bn":"বিশেষ্য (Noun)"},{"id":4103,"position":4,"text_uthmani":"وَعْدَ","transliteration":"waʿda","translation_bn":"(এটা)প্রতিশ্রুতি","root":"وعد","lemma":"وَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":4104,"position":5,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":4105,"position":6,"text_uthmani":"حَقًّا ۚ","transliteration":"ḥaqqan","translation_bn":"সত্য","root":"حقق","lemma":"حَقّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":4107,"position":7,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"নিশ্চয়ই তিনি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":4108,"position":8,"text_uthmani":"يَبْدَؤُا۟","transliteration":"yabda-u","translation_bn":"প্রথম অস্তিত্বে আনেন","root":"بدا","lemma":"بَدَأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4109,"position":9,"text_uthmani":"ٱلْخَلْقَ","transliteration":"l-khalqa","translation_bn":"সৃষ্টিকে","root":"خلق","lemma":"خَلْق","grammar_bn":"শব্দ"},{"id":4110,"position":10,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"অতঃপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4111,"position":11,"text_uthmani":"يُعِيدُهُۥ","transliteration":"yuʿīduhu","translation_bn":"পুনরাবর্তন করবেন তার","root":"عود","lemma":"أُعِيدُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4112,"position":12,"text_uthmani":"لِيَجْزِىَ","transliteration":"liyajziya","translation_bn":"যেন তিনি প্রতিফল দিতে পারেন","root":"جزي","lemma":"جَزَىٰ","grammar_bn":"শব্দ"},{"id":4113,"position":13,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদেরকে) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":4114,"position":14,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4115,"position":15,"text_uthmani":"وَعَمِلُوا۟","transliteration":"waʿamilū","translation_bn":"ও কাজ করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4116,"position":16,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ","transliteration":"l-ṣāliḥāti","translation_bn":"সৎ","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":4117,"position":17,"text_uthmani":"بِٱلْقِسْطِ ۚ","transliteration":"bil-qis''ṭi","translation_bn":"সাথে ন্যায় বিচারের","root":"قسط","lemma":"قِسْط","grammar_bn":"অব্যয় (Preposition)"},{"id":4119,"position":18,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"ও যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4120,"position":19,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অস্বীকার করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4121,"position":20,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"জন্যে তাদের (হবে)","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":4122,"position":21,"text_uthmani":"شَرَابٌۭ","transliteration":"sharābun","translation_bn":"পানীয়","root":"شرب","lemma":"شَرَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":4123,"position":22,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4124,"position":23,"text_uthmani":"حَمِيمٍۢ","transliteration":"ḥamīmin","translation_bn":"ফুটন্ত পানি","root":"حمم","lemma":"حَمِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":4125,"position":24,"text_uthmani":"وَعَذَابٌ","transliteration":"waʿadhābun","translation_bn":"ও শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4126,"position":25,"text_uthmani":"أَلِيمٌۢ","transliteration":"alīmun","translation_bn":"নিদারুণ","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":4127,"position":26,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"এ কারণে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4128,"position":27,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4129,"position":28,"text_uthmani":"يَكْفُرُونَ","transliteration":"yakfurūna","translation_bn":"তারা অস্বীকার করতে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4130,"position":29,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'ilayhi marjiʿukum jamīʿan waʿda l-lahi ḥaqqan innahu yabda-u l-khalqa thumma yuʿīduhu liyajziya alladhīna āmanū waʿamilū l-ṣāliḥāti bil-qis''ṭi wa-alladhīna kafarū lahum sharābun min ḥamīmin waʿadhābun alīmun bimā kānū yakfurūna', 'তাঁর কাছেই তোমাদের সকলের প্রত্যাবর্তন। আল্লাহর ওয়া‘দা নিশ্চিত সত্য। তিনি সৃষ্টির সূচনা করেন, পরে তিনিই আবার সৃষ্টি করবেন যাতে তিনি- যারা ঈমান এনেছে ও সৎকর্ম করেছে- তাদেরকে পূর্ণ ইনসাফের সাথে প্রতিদান দিতে পারেন। আর যারা কুফুরী করেছে তাদের জন্য আছে অতি উত্তপ্তপানীয় ও বেদনা দায়ক শাস্তি, যেহেতু তারা সত্য প্রত্যাখ্যান করত।', 'To Him is your return all together. [It is] the promise of Allah [which is] truth. Indeed, He begins the [process of] creation and then repeats it that He may reward those who have believed and done righteous deeds, in justice. But those who disbelieved will have a drink of scalding water and a painful punishment for what they used to deny.', 'তাঁর কাছেই তোমাদের সকলের প্রত্যাবর্তন। আল্লাহর ওয়া‘দা নিশ্চিত সত্য। তিনি সৃষ্টির সূচনা করেন, পরে তিনিই আবার সৃষ্টি করবেন যাতে তিনি- যারা ঈমান এনেছে ও সৎকর্ম করেছে- তাদেরকে পূর্ণ ইনসাফের সাথে প্রতিদান দিতে পারেন। আর যারা কুফুরী করেছে তাদের জন্য আছে অতি উত্তপ্তপানীয় ও বেদনা দায়ক শাস্তি, যেহেতু তারা সত্য প্রত্যাখ্যান করত।', 'To Him is your return all together. [It is] the promise of Allah [which is] truth. Indeed, He begins the [process of] creation and then repeats it that He may reward those who have believed and done righteous deeds, in justice. But those who disbelieved will have a drink of scalding water and a painful punishment for what they used to deny.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/010004.mp3', now()),
  (10, 5, '', '[{"id":5401,"position":1,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই (আল্লাহ)","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":5402,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":5403,"position":3,"text_uthmani":"جَعَلَ","transliteration":"jaʿala","translation_bn":"বানিয়েছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5404,"position":4,"text_uthmani":"ٱلشَّمْسَ","transliteration":"l-shamsa","translation_bn":"সূর্যকে","root":"شمس","lemma":"شَمْس","grammar_bn":"শব্দ"},{"id":5405,"position":5,"text_uthmani":"ضِيَآءًۭ","transliteration":"ḍiyāan","translation_bn":"দীপ্তিময়","root":"ضوا","lemma":"ضِيَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":5406,"position":6,"text_uthmani":"وَٱلْقَمَرَ","transliteration":"wal-qamara","translation_bn":"ও চাঁদকে","root":"قمر","lemma":"قَمَر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5407,"position":7,"text_uthmani":"نُورًۭا","transliteration":"nūran","translation_bn":"আলোকময়","root":"نور","lemma":"نُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":5408,"position":8,"text_uthmani":"وَقَدَّرَهُۥ","transliteration":"waqaddarahu","translation_bn":"ও তার জন্যে নির্দিষ্ট করেছেন","root":"قدر","lemma":"قَدَّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5409,"position":9,"text_uthmani":"مَنَازِلَ","transliteration":"manāzila","translation_bn":"(হ্রাস-বৃদ্ধির)কক্ষপথ","root":"نزل","lemma":"مَنَازِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":5410,"position":10,"text_uthmani":"لِتَعْلَمُوا۟","transliteration":"litaʿlamū","translation_bn":"যেন তোমরা জানো","root":"علم","lemma":"عَلِمَ","grammar_bn":"শব্দ"},{"id":5411,"position":11,"text_uthmani":"عَدَدَ","transliteration":"ʿadada","translation_bn":"গণনা","root":"عدد","lemma":"عَدَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":5412,"position":12,"text_uthmani":"ٱلسِّنِينَ","transliteration":"l-sinīna","translation_bn":"বছরগুলোর","root":"سنو","lemma":"سِنِين","grammar_bn":"শব্দ"},{"id":5413,"position":13,"text_uthmani":"وَٱلْحِسَابَ ۚ","transliteration":"wal-ḥisāba","translation_bn":"ও (তারিখের) হিসাব","root":"حسب","lemma":"حِسَاب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5415,"position":14,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"নেই","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":5416,"position":15,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5417,"position":16,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":5418,"position":17,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"এসব","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":5419,"position":18,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":5420,"position":19,"text_uthmani":"بِٱلْحَقِّ ۚ","transliteration":"bil-ḥaqi","translation_bn":"ভাবে যথাযথ (উদ্দেশ্যে)","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":5422,"position":20,"text_uthmani":"يُفَصِّلُ","transliteration":"yufaṣṣilu","translation_bn":"বিশদ বিবৃত করেন তিনি","root":"فصل","lemma":"فَصَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5423,"position":21,"text_uthmani":"ٱلْـَٔايَـٰتِ","transliteration":"l-āyāti","translation_bn":"নিদর্শনগুলোকে","root":"ايي","lemma":"ءَايَة","grammar_bn":"শব্দ"},{"id":5424,"position":22,"text_uthmani":"لِقَوْمٍۢ","transliteration":"liqawmin","translation_bn":"জন্যে সম্প্রদায়ের","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":5425,"position":23,"text_uthmani":"يَعْلَمُونَ","transliteration":"yaʿlamūna","translation_bn":"যারা জানে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5426,"position":24,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'huwa alladhī jaʿala l-shamsa ḍiyāan wal-qamara nūran waqaddarahu manāzila litaʿlamū ʿadada l-sinīna wal-ḥisāba mā khalaqa l-lahu dhālika illā bil-ḥaqi yufaṣṣilu l-āyāti liqawmin yaʿlamūna', 'তিনি সূর্যকে করেছেন তেজোদীপ্ত, আর চন্দ্রকে করেছেন আলোকময় আর তার (হ্রাস বৃদ্ধির) মানযিলসমূহ সঠিকভাবে নির্ধারণ করেছেন যাতে তোমরা বৎসর গুণে (সময়ের) হিসাব রাখতে পার। আল্লাহ এটা অনর্থক সৃষ্টি করেননি, তিনি নিদর্শনগুলোকে বিশদভাবে বর্ণনা করেন জ্ঞানী সম্প্রদায়ের জন্য।', 'It is He who made the sun a shining light and the moon a derived light and determined for it phases - that you may know the number of years and account [of time]. Allah has not created this except in truth. He details the signs for a people who know', 'তিনি সূর্যকে করেছেন তেজোদীপ্ত, আর চন্দ্রকে করেছেন আলোকময় আর তার (হ্রাস বৃদ্ধির) মানযিলসমূহ সঠিকভাবে নির্ধারণ করেছেন যাতে তোমরা বৎসর গুণে (সময়ের) হিসাব রাখতে পার। আল্লাহ এটা অনর্থক সৃষ্টি করেননি, তিনি নিদর্শনগুলোকে বিশদভাবে বর্ণনা করেন জ্ঞানী সম্প্রদায়ের জন্য।', 'It is He who made the sun a shining light and the moon a derived light and determined for it phases - that you may know the number of years and account [of time]. Allah has not created this except in truth. He details the signs for a people who know', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/010005.mp3', now()),
  (10, 6, '', '[{"id":6633,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":6634,"position":2,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে (রয়েছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6635,"position":3,"text_uthmani":"ٱخْتِلَـٰفِ","transliteration":"ikh''tilāfi","translation_bn":"পরিবর্তনে","root":"خلف","lemma":"ٱخْتِلَٰف","grammar_bn":"বিশেষ্য (Noun)"},{"id":6636,"position":4,"text_uthmani":"ٱلَّيْلِ","transliteration":"al-layli","translation_bn":"রাতের","root":"ليل","lemma":"لَيْل","grammar_bn":"শব্দ"},{"id":6637,"position":5,"text_uthmani":"وَٱلنَّهَارِ","transliteration":"wal-nahāri","translation_bn":"ও দিনের","root":"نهر","lemma":"نَهَار","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6638,"position":6,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"ও যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6639,"position":7,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6640,"position":8,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6641,"position":9,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6642,"position":10,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশসমূহের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":6643,"position":11,"text_uthmani":"وَٱلْأَرْضِ","transliteration":"wal-arḍi","translation_bn":"ও পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6644,"position":12,"text_uthmani":"لَـَٔايَـٰتٍۢ","transliteration":"laāyātin","translation_bn":"অবশ্যই নিদর্শনসমূহ","root":"ايي","lemma":"ءَايَة","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":6645,"position":13,"text_uthmani":"لِّقَوْمٍۢ","transliteration":"liqawmin","translation_bn":"জন্যে সম্প্রদায়ের","root":"قوم","lemma":"قَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":6646,"position":14,"text_uthmani":"يَتَّقُونَ","transliteration":"yattaqūna","translation_bn":"যারা তাকওয়া অবলম্বন করে","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6647,"position":15,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'inna fī ikh''tilāfi al-layli wal-nahāri wamā khalaqa l-lahu fī l-samāwāti wal-arḍi laāyātin liqawmin yattaqūna', 'নিশ্চয়ই রাত ও দিনের আবর্তনে, আর আকাশমন্ডলী ও পৃথিবীর মাঝে আল্লাহ যা সৃষ্টি করেছেন তাতে মুত্তাকী সম্প্রদায়ের জন্য অবশ্যই নিদর্শন রয়েছে।', 'Indeed, in the alternation of the night and the day and [in] what Allah has created in the heavens and the earth are signs for a people who fear Allah', 'নিশ্চয়ই রাত ও দিনের আবর্তনে, আর আকাশমন্ডলী ও পৃথিবীর মাঝে আল্লাহ যা সৃষ্টি করেছেন তাতে মুত্তাকী সম্প্রদায়ের জন্য অবশ্যই নিদর্শন রয়েছে।', 'Indeed, in the alternation of the night and the day and [in] what Allah has created in the heavens and the earth are signs for a people who fear Allah', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/010006.mp3', now()),
  (10, 7, '', '[{"id":7989,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":7990,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":7991,"position":3,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":7992,"position":4,"text_uthmani":"يَرْجُونَ","transliteration":"yarjūna","translation_bn":"আশা রাখে","root":"رجو","lemma":"يَرْجُوا@","grammar_bn":"ক্রিয়া (Verb)"},{"id":7993,"position":5,"text_uthmani":"لِقَآءَنَا","transliteration":"liqāanā","translation_bn":"সাক্ষাতের আমাদের","root":"لقي","lemma":"لِقَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":7994,"position":6,"text_uthmani":"وَرَضُوا۟","transliteration":"waraḍū","translation_bn":"ও পরিতৃপ্ত হয়েছে","root":"رضو","lemma":"رَّضِىَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7995,"position":7,"text_uthmani":"بِٱلْحَيَوٰةِ","transliteration":"bil-ḥayati","translation_bn":"নিয়ে জীবন","root":"حيي","lemma":"حَيَوٰة","grammar_bn":"অব্যয় (Preposition)"},{"id":7996,"position":8,"text_uthmani":"ٱلدُّنْيَا","transliteration":"l-dun''yā","translation_bn":"পার্থিব","root":"دنو","lemma":"دُّنْيَا","grammar_bn":"শব্দ"},{"id":7997,"position":9,"text_uthmani":"وَٱطْمَأَنُّوا۟","transliteration":"wa-iṭ''ma-annū","translation_bn":"এবং নিশ্চিত থাকে","root":"طمن","lemma":"ٱطْمَأَنَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7998,"position":10,"text_uthmani":"بِهَا","transliteration":"bihā","translation_bn":"নিয়ে তা","root":"—","lemma":"بِهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":7999,"position":11,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"এবং (এমন) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8000,"position":12,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারাই","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":8001,"position":13,"text_uthmani":"عَنْ","transliteration":"ʿan","translation_bn":"হতে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8002,"position":14,"text_uthmani":"ءَايَـٰتِنَا","transliteration":"āyātinā","translation_bn":"নিদর্শনগুলো আমাদের","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":8003,"position":15,"text_uthmani":"غَـٰفِلُونَ","transliteration":"ghāfilūna","translation_bn":"উদাসীন","root":"غفل","lemma":"غَٰفِل","grammar_bn":"বিশেষ্য (Noun)"},{"id":8004,"position":16,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'inna alladhīna lā yarjūna liqāanā waraḍū bil-ḥayati l-dun''yā wa-iṭ''ma-annū bihā wa-alladhīna hum ʿan āyātinā ghāfilūna', 'যারা আমার সঙ্গে সাক্ষাৎ লাভের আশা রাখে না, এবং দুনিয়ার জীবন নিয়েই সন্তুষ্ট থাকে আর তাতেই নিশ্চিন্ত হয় এবং যারা আমার নিদর্শনগুলো হতে একেবারে উদাসীন,', 'Indeed, those who do not expect the meeting with Us and are satisfied with the life of this world and feel secure therein and those who are heedless of Our signs', 'যারা আমার সঙ্গে সাক্ষাৎ লাভের আশা রাখে না, এবং দুনিয়ার জীবন নিয়েই সন্তুষ্ট থাকে আর তাতেই নিশ্চিন্ত হয় এবং যারা আমার নিদর্শনগুলো হতে একেবারে উদাসীন,', 'Indeed, those who do not expect the meeting with Us and are satisfied with the life of this world and feel secure therein and those who are heedless of Our signs', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/010007.mp3', now()),
  (10, 8, '', '[{"id":9162,"position":1,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"ঐসব লোক","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":9163,"position":2,"text_uthmani":"مَأْوَىٰهُمُ","transliteration":"mawāhumu","translation_bn":"তাদের বাসস্থান (হবে)","root":"اوي","lemma":"مَأْوَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":9164,"position":3,"text_uthmani":"ٱلنَّارُ","transliteration":"l-nāru","translation_bn":"আগুন","root":"نور","lemma":"نَار","grammar_bn":"শব্দ"},{"id":9165,"position":4,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"এ কারণে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9166,"position":5,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9167,"position":6,"text_uthmani":"يَكْسِبُونَ","transliteration":"yaksibūna","translation_bn":"তারা অর্জন করতে","root":"كسب","lemma":"كَسَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9168,"position":7,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'ulāika mawāhumu l-nāru bimā kānū yaksibūna', 'তাদের আবাস হল জাহান্নাম তাদের কৃতকর্মের কারণে।', 'For those their refuge will be the Fire because of what they used to earn.', 'তাদের আবাস হল জাহান্নাম তাদের কৃতকর্মের কারণে।', 'For those their refuge will be the Fire because of what they used to earn.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/010008.mp3', now()),
  (10, 9, '', '[{"id":10354,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":10355,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":10356,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10357,"position":4,"text_uthmani":"وَعَمِلُوا۟","transliteration":"waʿamilū","translation_bn":"ও কাজ করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10358,"position":5,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ","transliteration":"l-ṣāliḥāti","translation_bn":"সৎ","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":10359,"position":6,"text_uthmani":"يَهْدِيهِمْ","transliteration":"yahdīhim","translation_bn":"সৎপথে পরিচালিত করবেন তাদেরকে","root":"هدي","lemma":"هَدَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":10360,"position":7,"text_uthmani":"رَبُّهُم","transliteration":"rabbuhum","translation_bn":"রব তাদের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":10361,"position":8,"text_uthmani":"بِإِيمَـٰنِهِمْ ۖ","transliteration":"biīmānihim","translation_bn":"কারনে ঈমানের তাদের","root":"امن","lemma":"إِيمَٰن","grammar_bn":"অব্যয় (Preposition)"},{"id":10363,"position":9,"text_uthmani":"تَجْرِى","transliteration":"tajrī","translation_bn":"প্রবাহিত হয়","root":"جري","lemma":"جَرَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10364,"position":10,"text_uthmani":"مِن","transliteration":"min","translation_bn":"দিয়ে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10365,"position":11,"text_uthmani":"تَحْتِهِمُ","transliteration":"taḥtihimu","translation_bn":"নিচ তাদের","root":"تحت","lemma":"تَحْت","grammar_bn":"বিশেষ্য (Noun)"},{"id":10366,"position":12,"text_uthmani":"ٱلْأَنْهَـٰرُ","transliteration":"l-anhāru","translation_bn":"ঝর্ণাধারাসমূহ","root":"نهر","lemma":"نَهَر","grammar_bn":"শব্দ"},{"id":10367,"position":13,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10368,"position":14,"text_uthmani":"جَنَّـٰتِ","transliteration":"jannāti","translation_bn":"জান্নাতের","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":10369,"position":15,"text_uthmani":"ٱلنَّعِيمِ","transliteration":"l-naʿīmi","translation_bn":"সুখকর","root":"نعم","lemma":"نَعِيم","grammar_bn":"শব্দ"},{"id":10370,"position":16,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'inna alladhīna āmanū waʿamilū l-ṣāliḥāti yahdīhim rabbuhum biīmānihim tajrī min taḥtihimu l-anhāru fī jannāti l-naʿīmi', 'যারা ঈমান আনে আর সৎ ‘আমাল করে, তাদের প্রতিপালক তাদের ঈমানের বদৌলতে তাদেরকে সৎপথে পরিচালিত করবেন। নি‘মাতরাজি দ্বারা পরিপূর্ণ জান্নাতে, তাদের পাদদেশে ঝর্ণাধারা প্রবাহিত হবে।', 'Indeed, those who have believed and done righteous deeds - their Lord will guide them because of their faith. Beneath them rivers will flow in the Gardens of Pleasure', 'যারা ঈমান আনে আর সৎ ‘আমাল করে, তাদের প্রতিপালক তাদের ঈমানের বদৌলতে তাদেরকে সৎপথে পরিচালিত করবেন। নি‘মাতরাজি দ্বারা পরিপূর্ণ জান্নাতে, তাদের পাদদেশে ঝর্ণাধারা প্রবাহিত হবে।', 'Indeed, those who have believed and done righteous deeds - their Lord will guide them because of their faith. Beneath them rivers will flow in the Gardens of Pleasure', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/010009.mp3', now()),
  (10, 10, '', '[{"id":11593,"position":1,"text_uthmani":"دَعْوَىٰهُمْ","transliteration":"daʿwāhum","translation_bn":"তাদের ধ্বনি (হবে)","root":"دعو","lemma":"دَعْوَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":11594,"position":2,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"মধ্যে তার","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11595,"position":3,"text_uthmani":"سُبْحَـٰنَكَ","transliteration":"sub''ḥānaka","translation_bn":"পবিত্র তুমি","root":"سبح","lemma":"سُبْحَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":11596,"position":4,"text_uthmani":"ٱللَّهُمَّ","transliteration":"l-lahuma","translation_bn":"হে আল্লাহ\"","root":"اله","lemma":"ٱللَّهُمَّ","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":11597,"position":5,"text_uthmani":"وَتَحِيَّتُهُمْ","transliteration":"wataḥiyyatuhum","translation_bn":"ও তাদের অভিবাদন (হবে)","root":"حيي","lemma":"تَحِيَّة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11598,"position":6,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"মধ্যে তার","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11599,"position":7,"text_uthmani":"سَلَـٰمٌۭ ۚ","transliteration":"salāmun","translation_bn":"\"সালাম (বর্ষিত হোক)\"","root":"سلم","lemma":"سَلَٰم","grammar_bn":"বিশেষ্য (Noun)"},{"id":11601,"position":8,"text_uthmani":"وَءَاخِرُ","transliteration":"waākhiru","translation_bn":"এবং শেষ (হবে)","root":"اخر","lemma":"ا^خِر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11602,"position":9,"text_uthmani":"دَعْوَىٰهُمْ","transliteration":"daʿwāhum","translation_bn":"ধ্বনি তাদের","root":"دعو","lemma":"دَعْوَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":11603,"position":10,"text_uthmani":"أَنِ","transliteration":"ani","translation_bn":"এই (যে)","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":11604,"position":11,"text_uthmani":"ٱلْحَمْدُ","transliteration":"l-ḥamdu","translation_bn":"\"সব প্রশংসা","root":"حمد","lemma":"حَمْد","grammar_bn":"শব্দ"},{"id":11605,"position":12,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"জন্যে আল্লাহরই","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":11606,"position":13,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":11607,"position":14,"text_uthmani":"ٱلْعَـٰلَمِينَ","transliteration":"l-ʿālamīna","translation_bn":"বিশ্বজগতের\"","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"শব্দ"},{"id":11608,"position":15,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'daʿwāhum fīhā sub''ḥānaka l-lahuma wataḥiyyatuhum fīhā salāmun waākhiru daʿwāhum ani l-ḥamdu lillahi rabbi l-ʿālamīna', 'তার ভিতরে তাদের দু’আ হবে, ‘‘পবিত্র তুমি হে আল্লাহ’’। আর সেখানে তাদের অভিবাদন হবে ‘‘শান্তি’’, আর তাদের দু‘আর সর্বশেষ কথা হবে ‘‘সমস্ত প্রশংসা জগৎসমূহের প্রতিপালক আল্লাহর জন্য’’।', 'Their call therein will be, "Exalted are You, O Allah," and their greeting therein will be, "Peace." And the last of their call will be, "Praise to Allah, Lord of the worlds!"', 'তার ভিতরে তাদের দু’আ হবে, ‘‘পবিত্র তুমি হে আল্লাহ’’। আর সেখানে তাদের অভিবাদন হবে ‘‘শান্তি’’, আর তাদের দু‘আর সর্বশেষ কথা হবে ‘‘সমস্ত প্রশংসা জগৎসমূহের প্রতিপালক আল্লাহর জন্য’’।', 'Their call therein will be, "Exalted are You, O Allah," and their greeting therein will be, "Peace." And the last of their call will be, "Praise to Allah, Lord of the worlds!"', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/010010.mp3', now()),
  (10, 11, '', '[{"id":12922,"position":1,"text_uthmani":"۞ وَلَوْ","transliteration":"walaw","translation_bn":"এবং যদি","root":"—","lemma":"لَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12923,"position":2,"text_uthmani":"يُعَجِّلُ","transliteration":"yuʿajjilu","translation_bn":"তাড়াতাড়ি করতেন","root":"عجل","lemma":"عَجَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12924,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":12925,"position":4,"text_uthmani":"لِلنَّاسِ","transliteration":"lilnnāsi","translation_bn":"জন্যে মানুষের","root":"نوس","lemma":"نَّاس","grammar_bn":"অব্যয় (Preposition)"},{"id":12926,"position":5,"text_uthmani":"ٱلشَّرَّ","transliteration":"l-shara","translation_bn":"অকল্যাণ","root":"شرر","lemma":"شَرّ","grammar_bn":"শব্দ"},{"id":12927,"position":6,"text_uthmani":"ٱسْتِعْجَالَهُم","transliteration":"is''tiʿ''jālahum","translation_bn":"(যেমন) তারা তাড়াতাড়ি চায়","root":"عجل","lemma":"ٱسْتِعْجَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":12928,"position":7,"text_uthmani":"بِٱلْخَيْرِ","transliteration":"bil-khayri","translation_bn":"ব্যাপারে (দুনিয়ার) কল্যাণের","root":"خير","lemma":"خَيْر","grammar_bn":"অব্যয় (Preposition)"},{"id":12929,"position":8,"text_uthmani":"لَقُضِىَ","transliteration":"laquḍiya","translation_bn":"অবশ্যই পুরা হয়ে যেতো","root":"قضي","lemma":"قَضَىٰ^","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":12930,"position":9,"text_uthmani":"إِلَيْهِمْ","transliteration":"ilayhim","translation_bn":"প্রতি তাদের","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12931,"position":10,"text_uthmani":"أَجَلُهُمْ ۖ","transliteration":"ajaluhum","translation_bn":"মেয়াদ তাদের","root":"اجل","lemma":"أَجَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":12933,"position":11,"text_uthmani":"فَنَذَرُ","transliteration":"fanadharu","translation_bn":"অতএব আমরা ছেড়ে দিয়েছি","root":"وذر","lemma":"يَذَرَ","grammar_bn":"শব্দ"},{"id":12934,"position":12,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদেরকে) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":12935,"position":13,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":12936,"position":14,"text_uthmani":"يَرْجُونَ","transliteration":"yarjūna","translation_bn":"আশা রাখে","root":"رجو","lemma":"يَرْجُوا@","grammar_bn":"ক্রিয়া (Verb)"},{"id":12937,"position":15,"text_uthmani":"لِقَآءَنَا","transliteration":"liqāanā","translation_bn":"সাক্ষাতের আমাদের","root":"لقي","lemma":"لِقَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":12938,"position":16,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12939,"position":17,"text_uthmani":"طُغْيَـٰنِهِمْ","transliteration":"ṭugh''yānihim","translation_bn":"অবাধ্যতার তাদের","root":"طغي","lemma":"طُغْيَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":12940,"position":18,"text_uthmani":"يَعْمَهُونَ","transliteration":"yaʿmahūna","translation_bn":"উদ্‌ভ্রান্ত হয়ে ঘুরে বেড়ায়","root":"عمه","lemma":"يَعْمَهُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12941,"position":19,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'walaw yuʿajjilu l-lahu lilnnāsi l-shara is''tiʿ''jālahum bil-khayri laquḍiya ilayhim ajaluhum fanadharu alladhīna lā yarjūna liqāanā fī ṭugh''yānihim yaʿmahūna', 'মানুষের অপকর্মের শাস্তি হিসেবে আল্লাহ যদি মানুষের অকল্যাণ করার ব্যাপারে দ্রুততা অবলম্বন করতেন যতটা দ্রুততার সঙ্গে তারা (দুনিয়ার) কল্যাণ পেতে চায়, তবে তাদের কাজ করার অবকাশ কবেই না খতম করে দেয়া হত, (কিন্তু আল্লাহ তা করেন না)। কাজেই যারা আমার সাক্ষাতের আশা রাখে না, তাদেরকে আমি তাদের অবাধ্যতায় দিশেহারা হয়ে ঘুরে বেড়ানোর অবকাশ দেই।', 'And if Allah was to hasten for the people the evil [they invoke] as He hastens for them the good, their term would have been ended for them. But We leave the ones who do not expect the meeting with Us, in their transgression, wandering blindly', 'মানুষের অপকর্মের শাস্তি হিসেবে আল্লাহ যদি মানুষের অকল্যাণ করার ব্যাপারে দ্রুততা অবলম্বন করতেন যতটা দ্রুততার সঙ্গে তারা (দুনিয়ার) কল্যাণ পেতে চায়, তবে তাদের কাজ করার অবকাশ কবেই না খতম করে দেয়া হত, (কিন্তু আল্লাহ তা করেন না)। কাজেই যারা আমার সাক্ষাতের আশা রাখে না, তাদেরকে আমি তাদের অবাধ্যতায় দিশেহারা হয়ে ঘুরে বেড়ানোর অবকাশ দেই।', 'And if Allah was to hasten for the people the evil [they invoke] as He hastens for them the good, their term would have been ended for them. But We leave the ones who do not expect the meeting with Us, in their transgression, wandering blindly', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/010011.mp3', now()),
  (10, 12, '', '[{"id":14200,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14201,"position":2,"text_uthmani":"مَسَّ","transliteration":"massa","translation_bn":"স্পর্শ করে","root":"مسس","lemma":"مَسَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14202,"position":3,"text_uthmani":"ٱلْإِنسَـٰنَ","transliteration":"l-insāna","translation_bn":"মানুষকে","root":"انس","lemma":"إِنسَٰن","grammar_bn":"শব্দ"},{"id":14203,"position":4,"text_uthmani":"ٱلضُّرُّ","transliteration":"l-ḍuru","translation_bn":"দুঃখ-দৈন্য (দিয়ে)","root":"ضرر","lemma":"ضُرّ","grammar_bn":"শব্দ"},{"id":14204,"position":5,"text_uthmani":"دَعَانَا","transliteration":"daʿānā","translation_bn":"(তখন) ডাকে আমাদেরকে","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":14205,"position":6,"text_uthmani":"لِجَنۢبِهِۦٓ","transliteration":"lijanbihi","translation_bn":"উপর পাশের তার (অর্থাৎ শুয়ে)","root":"جنب","lemma":"جَنب","grammar_bn":"অব্যয় (Preposition)"},{"id":14206,"position":7,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"বা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14207,"position":8,"text_uthmani":"قَاعِدًا","transliteration":"qāʿidan","translation_bn":"বসে","root":"قعد","lemma":"قَاعِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":14208,"position":9,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"বা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14209,"position":10,"text_uthmani":"قَآئِمًۭا","transliteration":"qāiman","translation_bn":"দাঁড়িয়ে","root":"قوم","lemma":"قَا^ئِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":14210,"position":11,"text_uthmani":"فَلَمَّا","transliteration":"falammā","translation_bn":"অতঃপর যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"শব্দ"},{"id":14211,"position":12,"text_uthmani":"كَشَفْنَا","transliteration":"kashafnā","translation_bn":"আমরা দূর করি","root":"كشف","lemma":"كَشَفَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14212,"position":13,"text_uthmani":"عَنْهُ","transliteration":"ʿanhu","translation_bn":"থেকে তার","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14213,"position":14,"text_uthmani":"ضُرَّهُۥ","transliteration":"ḍurrahu","translation_bn":"দুঃখ-দৈন্য তার","root":"ضرر","lemma":"ضُرّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":14214,"position":15,"text_uthmani":"مَرَّ","transliteration":"marra","translation_bn":"সে চলে (এমনভাবে)","root":"مرر","lemma":"مَرَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14215,"position":16,"text_uthmani":"كَأَن","transliteration":"ka-an","translation_bn":"যেন","root":"—","lemma":"أَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14216,"position":17,"text_uthmani":"لَّمْ","transliteration":"lam","translation_bn":"নি","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":14217,"position":18,"text_uthmani":"يَدْعُنَآ","transliteration":"yadʿunā","translation_bn":"আমাদেরকে ডাকেই","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":14218,"position":19,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"জন্যে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14219,"position":20,"text_uthmani":"ضُرٍّۢ","transliteration":"ḍurrin","translation_bn":"দুঃখের","root":"ضرر","lemma":"ضُرّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":14220,"position":21,"text_uthmani":"مَّسَّهُۥ ۚ","transliteration":"massahu","translation_bn":"স্পর্শ করেছিলো তাকে","root":"مسس","lemma":"مَسَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14222,"position":22,"text_uthmani":"كَذَٰلِكَ","transliteration":"kadhālika","translation_bn":"এভাবে","root":"—","lemma":"ذَٰلِك","grammar_bn":"অব্যয় (Preposition)"},{"id":14223,"position":23,"text_uthmani":"زُيِّنَ","transliteration":"zuyyina","translation_bn":"সুশোভিত করা হয়েছে","root":"زين","lemma":"زَيَّنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14224,"position":24,"text_uthmani":"لِلْمُسْرِفِينَ","transliteration":"lil''mus''rifīna","translation_bn":"জন্যে সীমালঙ্ঘনকারীদের","root":"سرف","lemma":"مُسْرِف","grammar_bn":"অব্যয় (Preposition)"},{"id":14225,"position":25,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":14226,"position":26,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14227,"position":27,"text_uthmani":"يَعْمَلُونَ","transliteration":"yaʿmalūna","translation_bn":"তারা কাজ করতে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14228,"position":28,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā massa l-insāna l-ḍuru daʿānā lijanbihi aw qāʿidan aw qāiman falammā kashafnā ʿanhu ḍurrahu marra ka-an lam yadʿunā ilā ḍurrin massahu kadhālika zuyyina lil''mus''rifīna mā kānū yaʿmalūna', 'মানুষকে যখন দুঃখ ক্লেশ স্পর্শ করে, তখন তারা শুয়ে, বসে ও দাঁড়িয়ে আমাকে ডাকতে থাকে। অতঃপর যখন আমি তার দুঃখ ক্লেশ দূর করে দেই, তখন সে এমনভাবে চলে যায়, মনে হয় যেন তাকে দুঃখ-ক্লেশ স্পর্শ করার কারণে সে আমাকে কখনই ডাকেনি। এভাবেই যারা সীমালঙ্ঘন করে তাদের জন্য তাদের কাজকর্মগুলোকে চাকচিক্যময় বানিয়ে দেয়া হয়েছে।', 'And when affliction touches man, he calls upon Us, whether lying on his side or sitting or standing; but when We remove from him his affliction, he continues [in disobedience] as if he had never called upon Us to [remove] an affliction that touched him. Thus is made pleasing to the transgressors that which they have been doing', 'মানুষকে যখন দুঃখ ক্লেশ স্পর্শ করে, তখন তারা শুয়ে, বসে ও দাঁড়িয়ে আমাকে ডাকতে থাকে। অতঃপর যখন আমি তার দুঃখ ক্লেশ দূর করে দেই, তখন সে এমনভাবে চলে যায়, মনে হয় যেন তাকে দুঃখ-ক্লেশ স্পর্শ করার কারণে সে আমাকে কখনই ডাকেনি। এভাবেই যারা সীমালঙ্ঘন করে তাদের জন্য তাদের কাজকর্মগুলোকে চাকচিক্যময় বানিয়ে দেয়া হয়েছে।', 'And when affliction touches man, he calls upon Us, whether lying on his side or sitting or standing; but when We remove from him his affliction, he continues [in disobedience] as if he had never called upon Us to [remove] an affliction that touched him. Thus is made pleasing to the transgressors that which they have been doing', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/010012.mp3', now()),
  (10, 13, '', '[{"id":15282,"position":1,"text_uthmani":"وَلَقَدْ","transliteration":"walaqad","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15283,"position":2,"text_uthmani":"أَهْلَكْنَا","transliteration":"ahlaknā","translation_bn":"ধ্বংস করেছি আমরা","root":"هلك","lemma":"أَهْلَكَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15284,"position":3,"text_uthmani":"ٱلْقُرُونَ","transliteration":"l-qurūna","translation_bn":"বহু মানবগোষ্ঠীকে","root":"قرن","lemma":"قَرْن","grammar_bn":"শব্দ"},{"id":15285,"position":4,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকেও","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15286,"position":5,"text_uthmani":"قَبْلِكُمْ","transliteration":"qablikum","translation_bn":"পূর্ব তোমাদের","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":15287,"position":6,"text_uthmani":"لَمَّا","transliteration":"lammā","translation_bn":"যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"কালবাচক (Time)"},{"id":15288,"position":7,"text_uthmani":"ظَلَمُوا۟ ۙ","transliteration":"ẓalamū","translation_bn":"তারা অবিচার করেছিলো","root":"ظلم","lemma":"ظَلَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15290,"position":8,"text_uthmani":"وَجَآءَتْهُمْ","transliteration":"wajāathum","translation_bn":"ও কাছে এসেছিলো তাদের","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15291,"position":9,"text_uthmani":"رُسُلُهُم","transliteration":"rusuluhum","translation_bn":"রাসূলরা তাদের","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":15292,"position":10,"text_uthmani":"بِٱلْبَيِّنَـٰتِ","transliteration":"bil-bayināti","translation_bn":"সহ সুস্পষ্ট নিদর্শনগুলো","root":"بين","lemma":"بَيِّنَة","grammar_bn":"অব্যয় (Preposition)"},{"id":15293,"position":11,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15294,"position":12,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15295,"position":13,"text_uthmani":"لِيُؤْمِنُوا۟ ۚ","transliteration":"liyu''minū","translation_bn":"জন্যে ঈমান আনার","root":"امن","lemma":"ءَامَنَ","grammar_bn":"শব্দ"},{"id":15297,"position":14,"text_uthmani":"كَذَٰلِكَ","transliteration":"kadhālika","translation_bn":"এভাবে","root":"—","lemma":"ذَٰلِك","grammar_bn":"অব্যয় (Preposition)"},{"id":15298,"position":15,"text_uthmani":"نَجْزِى","transliteration":"najzī","translation_bn":"প্রতিফল দিই আমরা","root":"جزي","lemma":"جَزَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15299,"position":16,"text_uthmani":"ٱلْقَوْمَ","transliteration":"l-qawma","translation_bn":"সসম্প্রদায়কে","root":"قوم","lemma":"قَوْم","grammar_bn":"শব্দ"},{"id":15300,"position":17,"text_uthmani":"ٱلْمُجْرِمِينَ","transliteration":"l-muj''rimīna","translation_bn":"অপরাধী","root":"جرم","lemma":"مُجْرِم","grammar_bn":"শব্দ"},{"id":15301,"position":18,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'walaqad ahlaknā l-qurūna min qablikum lammā ẓalamū wajāathum rusuluhum bil-bayināti wamā kānū liyu''minū kadhālika najzī l-qawma l-muj''rimīna', 'তোমাদের পূর্বেকার বহু জনগোষ্ঠীকে আমি ধ্বংস করে দিয়েছি যখন তারা বাড়াবাড়িতে লিপ্ত হয়েছিল, তাদের কাছে রসূলগণ সুস্পষ্ট নিদর্শনসমূহ নিয়ে এসেছিল, কিন্তু তারা আদৌ ঈমান আনেনি। এভাবেই আমি অপরাধীদেরকে (পাপের) প্রতিদান দিয়ে থাকি।', 'And We had already destroyed generations before you when they wronged, and their messengers had come to them with clear proofs, but they were not to believe. Thus do We recompense the criminal people', 'তোমাদের পূর্বেকার বহু জনগোষ্ঠীকে আমি ধ্বংস করে দিয়েছি যখন তারা বাড়াবাড়িতে লিপ্ত হয়েছিল, তাদের কাছে রসূলগণ সুস্পষ্ট নিদর্শনসমূহ নিয়ে এসেছিল, কিন্তু তারা আদৌ ঈমান আনেনি। এভাবেই আমি অপরাধীদেরকে (পাপের) প্রতিদান দিয়ে থাকি।', 'And We had already destroyed generations before you when they wronged, and their messengers had come to them with clear proofs, but they were not to believe. Thus do We recompense the criminal people', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/010013.mp3', now()),
  (10, 14, '', '[{"id":16342,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16343,"position":2,"text_uthmani":"جَعَلْنَـٰكُمْ","transliteration":"jaʿalnākum","translation_bn":"আমরা বানালাম তোমাদেরকে","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16344,"position":3,"text_uthmani":"خَلَـٰٓئِفَ","transliteration":"khalāifa","translation_bn":"প্রতিনিধি","root":"خلف","lemma":"خَلِيفَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":16345,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16346,"position":5,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":16347,"position":6,"text_uthmani":"مِنۢ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16348,"position":7,"text_uthmani":"بَعْدِهِمْ","transliteration":"baʿdihim","translation_bn":"পর তাদের","root":"بعد","lemma":"بَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":16349,"position":8,"text_uthmani":"لِنَنظُرَ","transliteration":"linanẓura","translation_bn":"যেন দেখি আমরা","root":"نظر","lemma":"نَّظَرَ","grammar_bn":"শব্দ"},{"id":16350,"position":9,"text_uthmani":"كَيْفَ","transliteration":"kayfa","translation_bn":"কেমন","root":"كيف\r","lemma":"كَيْف","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":16351,"position":10,"text_uthmani":"تَعْمَلُونَ","transliteration":"taʿmalūna","translation_bn":"তোমরা কাজ করো","root":"عمل","lemma":"عَمِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16352,"position":11,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'thumma jaʿalnākum khalāifa fī l-arḍi min baʿdihim linanẓura kayfa taʿmalūna', 'অতঃপর তাদের পর আমি তোমাদেরকে পৃথিবীতে তাদের স্থলাভিষিক্ত করেছি এটা দেখার জন্য যে, তোমরা কী রকম ‘আমাল কর।', 'Then We made you successors in the land after them so that We may observe how you will do.', 'অতঃপর তাদের পর আমি তোমাদেরকে পৃথিবীতে তাদের স্থলাভিষিক্ত করেছি এটা দেখার জন্য যে, তোমরা কী রকম ‘আমাল কর।', 'Then We made you successors in the land after them so that We may observe how you will do.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/010014.mp3', now()),
  (10, 15, '', '[{"id":17502,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17503,"position":2,"text_uthmani":"تُتْلَىٰ","transliteration":"tut''lā","translation_bn":"তিলাওয়াত করা হয়","root":"تلو","lemma":"تَلَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17504,"position":3,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"নিকট তাদের","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17505,"position":4,"text_uthmani":"ءَايَاتُنَا","transliteration":"āyātunā","translation_bn":"আয়াতগুলোকে আমাদের","root":"ايي","lemma":"ءَايَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":17506,"position":5,"text_uthmani":"بَيِّنَـٰتٍۢ ۙ","transliteration":"bayyinātin","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"بَيِّنَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":17508,"position":6,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17509,"position":7,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":17510,"position":8,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":17511,"position":9,"text_uthmani":"يَرْجُونَ","transliteration":"yarjūna","translation_bn":"আশা রাখে","root":"رجو","lemma":"يَرْجُوا@","grammar_bn":"ক্রিয়া (Verb)"},{"id":17512,"position":10,"text_uthmani":"لِقَآءَنَا","transliteration":"liqāanā","translation_bn":"সাক্ষাতের আমাদের","root":"لقي","lemma":"لِقَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":17513,"position":11,"text_uthmani":"ٱئْتِ","transliteration":"i''ti","translation_bn":"\"আসো","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":17514,"position":12,"text_uthmani":"بِقُرْءَانٍ","transliteration":"biqur''ānin","tran